window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26657426"]={"book":{"id":26657426,"title":"高效能人士的7个习惯（人际关系篇）","author":"史蒂芬•柯维","translator":"","publisher":"湖南文艺出版社","pubdate":"2015-11","isbn":"9787540473617","tags":["人际关系","自我完善","成长","个人管理","管理","［美］史蒂芬柯维（Stephen","好书","值得一读","励志"],"memCount":11},"np":1,"pb":[35],"idx":[{"i":18178,"t":"影响圈和关注圈","l":"TF2-3","c":"杰哥5113","g":1,"p":1},{"i":17976,"t":"用怡情聆听的方式解决沟通中的情绪问题","l":"TF1-2","c":"刘尚明","g":1,"p":1},{"i":17910,"t":"责任型授权五步法","l":"TF2-2","c":"花想容MM","g":1,"p":1},{"i":17850,"t":"要事第一，人生由我掌控","l":"TF2-1","c":"月亮姐姐","g":1,"p":1},{"i":17665,"t":"学会倾听","l":"TF3-1","c":"雪菲","g":1,"p":1},{"i":17395,"t":"知彼解己，最重要的原则：移情聆听！ ","l":"TF1-2","c":"妃妃","g":1,"p":1},{"i":17300,"t":"如果生活让你感觉有点累，那么把”如果“换成“我可以，只要肯换角度，世界总有惊喜。","l":"TF2-4","c":"张静","g":1,"p":1},{"i":17025,"t":"区分关注圈和影响圈&扩大影响圈","l":"TF3-3","c":"ELIAUK","g":1,"p":1},{"i":16799,"t":"晋级","l":"TF1-1","c":"青松","g":1,"p":1},{"i":16792,"t":"今天这个拆页将从我们作为家庭教育者的角色切入，开启我们在家庭中作为孩子的第一任老师的职责，教给家庭成员充满力量的原则，并","l":"TF2-1","c":"徐琴娜","g":1,"p":1},{"i":16139,"t":"关注圈和影响圈","l":"TF3-2","c":"芊蓉","g":1,"p":1},{"i":16127,"t":"移情聆听","l":"TF3-1","c":"芊蓉","g":1,"p":1},{"i":15560,"t":"高效能人士的5+4法则","l":"TF2-4","c":"芷旭","g":1,"p":1},{"i":15017,"t":"消除烦恼的第一步","l":"TF1-1","c":"芷旭","g":1,"p":1},{"i":15004,"t":"要事第一","l":"TF2-1","c":"嘉璇","g":1,"p":1},{"i":14975,"t":"移情聆听","l":"TF1-2","c":"周梦梦","g":1,"p":1},{"i":11383,"t":"用“移情倾听”进行有效沟通","l":"TF2-3","c":"小妖灵灵","g":1,"p":1},{"i":10663,"t":"TF1-1过级","l":"TF1-1","c":"苔米","g":1,"p":1},{"i":10235,"t":"高效能人士的7个习惯","l":"TF3-1","c":"肖昀","g":1,"p":1},{"i":9662,"t":"区分关注圈和影响圈，做积极主动的人","l":"TF3-1","c":"罗赟","g":1,"p":1},{"i":9640,"t":"龙卷风TF3-1过级","l":"TF3-1","c":"龙卷风","g":1,"p":1},{"i":9628,"t":"聚焦影响圈，变消极为积极","l":"TF3-2","c":"江源媛","g":1,"p":1},{"i":8929,"t":"运用双赢四步法，寻求双方需求，达成一致目标","l":"TF3-2","c":"徐沈逸","g":1,"p":1},{"i":7681,"t":"双赢4步法实现共赢","l":"TF1-1","c":"刘犇","g":1,"p":1},{"i":7526,"t":"如何快速化消极为积极","l":"TF1-2","c":"悟空_长春分舵","g":1,"p":1},{"i":4644,"t":"深度倾听4步法","l":"TF2-1","c":"龚正伟","g":1,"p":1},{"i":4167,"t":"如何进行有效的沟通","l":"TF1-2","c":"齐艳","g":1,"p":1},{"i":3536,"t":"克服拖延","l":"TF1-1","c":"杨硕","g":1,"p":1},{"i":2781,"t":"高效能人士的7个习惯之要事第一","l":"TF3-2","c":"徐佳敏","g":1,"p":1},{"i":2224,"t":"学习设身处地倾听，避免陷入四种自传式的沟通不良的弊端当中","l":"TF2-3","c":"Joyce赵锦","g":1,"p":1},{"i":2092,"t":"责任型授权+","l":"TF3-3","c":"张臻凯","g":0,"p":1},{"i":1727,"t":"要事第一","l":"TF3-2","c":"张臻凯","g":1,"p":1},{"i":1223,"t":"由内而外改变自己","l":"TF2-2","c":"Lian","g":1,"p":1},{"i":1093,"t":"积极主动的言语自我对话，营造外在环境改变自己行事的态度","l":"TF2-1","c":"Lian","g":1,"p":1},{"i":737,"t":"3W1H+TVD法和3W1H+三“谈”法","l":"TF2-4","c":"陈健","g":0,"p":1}],"ms":[{"id":18178,"topic":"影响圈和关注圈","learn_goal":"","remark":"这本书的作者是大名鼎鼎的史蒂芬、柯维，主要讲述了高效能人士的七个习惯，自1989年出版以来，已成为一部经典著作，高居《纽约时报》畅销书排行榜长达30年，在全球140个国家以40种语言出版，在美国，这本书的影响力仅次于《圣经》，是美国公司员工、政府机关公务员、军队官兵装备书。","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"杰哥5113","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"\u003cp>【自我介绍】\u003cbr>【翻页】大家好，我是杰哥，我的标签有阅读达人（就是比较喜欢读书，每天都会都一会儿书）、鸡娃老父亲（家里有个女儿今年小升初）、“应试教育”的拆书家（先看技能点再去挑选拆页）。刚刚结束了十一长假，大家都还处于适应工作的过渡期中，今晚就由我来带着大家学习个轻松的内容。\u003cbr>【学习目标】\u003cbr>【翻页】今天我想和大家一起学习一个如何积极应对问题的方法，也就是关注“影响圈”内事项，并细化影响圈内的具体行动。希望完成本次线上学习后，大家未来碰到棘手问题时能专注于“影响圈”，去做自己能控制影响的事，从而让自己能变得更加的积极。\u003c/p>\u003cp>【FAB法介绍书籍】【翻页】今天我选的拆页来自《高效能人士的7个习惯》。\u003cstrong>【F】\u003c/strong>这本书的作者是大名鼎鼎的史蒂芬、柯维，这本书主要讲述了高效能人士的七个习惯，包含了个人领域成功的三个习惯“积极主动”、“以终为始”和“要事第一”，以及公众领域成功的三个习惯“双赢思维”、“知彼解己”和“统合综效”，再辅以“不断更新”来实现与时俱进的不断自我更迭。\u003cstrong>【A】\u003c/strong>这本书自1989年出版以来，已成为一部经典著作，高居《纽约时报》畅销书排行榜长达30年，在全球140个国家以40种语言出版，在美国，这本书的影响力仅次于《圣经》，是美国公司员工、政府机关公务员、军队官兵装备书。\u003cstrong>【B】\u003c/strong>如果你觉得陷入了职业发展的瓶颈，不知道如何再往前一步的时候，那试着翻翻这本书吧，通过学会这七个神奇的好习惯来提升自己的底层能力，让自己变得更优秀。\u003c/p>","ratings_count":1,"texts":[{"id":22443,"quote":"\u003cp>【翻页】接下来我们先花1-2分钟的时间来阅读一下拆页，好了的小伙伴请在留言框里打1：\u003cbr>R-阅读原文\u003c/p>\u003cp>片断来源：《高效能人士的7个习惯》第三章 习惯-积极主动 第208页\u003cbr>看一个人的时间和精力集中于哪些事物，也能大致判断他是否积极主动。每个人都有格外关注的问题，比如健康、子女、事业、工作、国债或核战争等等，这些都可以被归入“关注圈”( Circle of Concern)，以区别于自己没有兴趣或不愿理会的事物。\u003cbr>关注圈内的事物，有些可以被掌控，有些则超出个人能力范围，前者可以被圈成一个较小的“影响圈”( Circle of Influence)。观察一个人的时间和精力集中于哪个圈，就可以判断他是否积极主动。\u003cbr>\u003c/p>\u003cp>\u003cbr>积极主动的人专注于“影响圈”，他们专心做自己力所能及的事，他们的能量是积极的，能够使影响圈不断扩大。\u003cbr>反之，消极被动的人则全神贯注于“关注圈”，紧盯他人弱点、环境问题以及超出个人能力范围的事不放，结果越来越怨天尤人，一味把自己当作受害者，并不断为自己的消极行为寻找借口。错误的焦点产生了消极能量，再加上对力所能及之事的忽略，就造成了影响圈日益缩小。\u003cbr>\u003c/p>\u003cp>\u003cbr>只要我们的焦点在关注圈，就等于是允许自己受制于外界条件，自然就不会主动采取必要措施来推动积极变化。\u003c/p>","explains":"\u003cp>【翻页】好了，我看到不少小伙伴已经看完了，我先来谈谈自己对这个拆页的理解。\u003cbr>【what】\u003cbr>这个拆页为我们提供了一种判断自我和他人认知偏好的框架，具体来讲就是帮我们判断一个人在与外界互动时是积极乐观还是消极负面，这个拆页为我们解释了这种外在态度背后可能的内在原因，并且还建议我们怎样利用这个框架来调整和优化自己的认知偏好，从而让自己能更积极主动一些，更理性客观一些。\u003cbr>【why】\u003cbr>为什么“影响圈”这个框架可以帮我们判断一个人是乐观还是悲观呢？我们生活中常说一句话：“心态好的人就是遇事总往好的方面去想”，这个“好的方向”指的就是事物当中我们可以掌握、可以控制、可以主导的方面，大家看看是不是正好等于框架中的“影响圈”呢？反过来我们劝解别人的时候也经常说一句话“不可控的事情干嘛要去想”，这个不可控是不是又对应于“影响圈”之外的那部分“关注圈”呢？所以你看影响圈是不是就和我们平时的常识完美地契合起来了。\u003cbr>【how-行动步骤细化】 \u003cbr>那我们可以怎样使用“影响圈”来梳理思路，保持乐观呢？我们可以按照以下四个步来进行：\u003cbr>\u003cbr>1、寻找关注圈。找出那些我们关注的，但是却无法控制和影响的事项，比方说一些外界环境，天气，出身，运气等。\u003cbr>2、划定影响圈。找出那些我们能影响的事情，比方说自己的行动，态度，以及精力和金钱的分配方式。\u003cbr>3、细化影响圈内的行动。对于划定在影响圈的事情，去细化自己的行动方向和步骤，做自己能做的，放弃自己无法改变的事情。\u003cbr>4、思考怎样扩大自己的影响圈（这个是可选，非必选），在面对环境选择回应方式的同时，我们对于环境的影响力也能得到增强，这就像一个化学方程式，改变其中的某部分，其结果也会跟着改变，比如你现在职位很低无法影响公司未来的发展方向，但是随着你自己的不断进步，在公司影响力和话语权的增强，之后有一天，老板也会听从你的建议，于是影响公司未来发展方向这件事情就从关注圈变为了自己的影响圈。\u003cbr>\u003cbr>这里我教大家一个简便的细化操作方法，首先可以拿出一张纸，从中间对折一下，在纸的左边写上标题：我能影响和控制的；在右边写上标题：我关注但是无法影响的，然后在对折的地方画一条竖线，接着将我们脑子里和这件事情相关的事项分别写在两个标题下面，一件事项只能写在一个地方。接着，把我们右边那个写着无法控制的那半边撕下来，放在一边，然后关注左边那些我们能影响和控制的事情，看看怎么做好。过一段时间之后，可以再去看看自己之前放在一边的无法控制的事情是不是有机会变成能控制的了？从来实现影响圈的扩大。\u003cbr>【举例】\u003cbr>我自己身边就有个例子，我女儿班级里有个小朋友，绰号叫“皮大王”，这个皮大王的特点就是很皮，老师在上面上课，他在下面玩，老师批评他也没啥用。然后非常倒霉的是，他还是我女儿的同桌，这个皮大王自己上课玩也就算了，还喜欢影响旁边的同学，有的时候喜欢拉一下我女儿的手，或者推一下她，我女儿是个乖乖女，只知道一味的忍让，不去理睬他，但是皮大王就变本加厉的骚扰我女儿。\u003cbr>我女儿回家给外婆讲这个事，外婆就很焦虑，然后一会儿说是这个老师不好没有管教好里面的孩子，一会儿又说是我女儿不好，肯定是上课不认真听讲，才会让皮大王觉得和他是可以一起玩的人，又说是皮大王的父母不好，这么差的孩子都不知道去管教。但是她说的这些都没啥用，慢慢的我女儿越来越焦虑，越来越胆小，很消极，甚至一度都不想去上课了。\u003cbr>这个时候，要怎么帮女儿解决这个问题呢？我阅读了上面这段拆页，我采用如下的方式：\u003cbr>第一步，我先找哪些是我关注的但是我无法改变和影响的，放在关注圈里的是：老师怎样干预、对方父母怎样干预、皮大王自己怎样做。\u003cbr>第二步，我分析下哪些是我能去改变和影响的，放在影响圈里有：我的女儿可以怎么做，\u003cbr>第三步，针对我的影响圈内容，“我女儿可以怎么做”这个点，我就对我女儿说，下次皮大王碰你的时候，你就给我加倍的打回去，要打到他痛，但是不能打他的眼睛和打出血来，只要对方来招惹你，你就狠狠的报复回去，然后打完之后，自己就解气了，也就不要把这个事情放在心上了。\u003cbr>第四步，通过这种方式，我女儿就在处理皮大王的事情上越来越有技巧和心得，也知道怎么对付他的各种小伎俩，久而久之，皮大王发现碰到了一个硬茬，也就不敢再来招惹我女儿了，同时我女儿在其他小朋友面前也树立了威信，慢慢的也就能影响别的孩子怎么做了。\u003cbr>【where】\u003cbr>这个扩大影响圈的方法适用于那些的确通过你的努力可以影响一些事情结果的问题，有些问题如果你完全无计可施的，比方说买彩票，只能听天由命的那就不适用了。\u003c/p>","interaction":"\u003cp>【场景设计】\u003cbr>【翻页】下面我们来做一个学以致用的练习：在线的都是熟悉拆书过级的伙伴们，给大家2分钟的讨论时间，大家来扮演一位刚刚加入拆书帮不久的新人，你的师父跟你说希望你能在1年内成为三级拆书家，这位新人有点忐忑但又不想辜负师父的期待，想完成这个目标，那大家来讨论一下“在一年内成为三级拆书家”这个事里哪些是属于关注圈的，哪些是属于影响圈的，对于影响圈里的事情你可以通过怎么做，能让这件事情按照你的方向发展的。【如果有还没有加入拆书帮或者开始拆书过级的伙伴，可以选择一个自己即将参加的考试或考核来做上述的分析】。【只要有四个以上人+1个观察家，我就分两组】\u003cbr>好的，我看大家讨论的差不多了，我请XX来帮我们分享下。\u003cbr>【因为是线上拆，需要提前学习下腾讯分组的功能】\u003cbr>【步骤在PPT 里面列示清楚】\u003cbr>【拆为己用】\u003cbr>牛老师：我觉得我讲的主题是不是受欢迎，能不能得到学习者很好的互动属于关注圈的范畴，而找到一个容易被同情的话题，让互动更加容易一些这些则属于影响圈的范畴，因此我会在未来的拆书过程中更多的关注自己能做的那些事情，去选择一些好的话题，设计一些容易互动的场景，这些都是我会去做的。\u003cbr>结束语\u003c/p>\u003cp>【翻页】谢谢，今天的讨论非常热烈，通过短短的20多分钟的练习，相信大家已经初步感知到了聚焦“影响圈”的积极作用，通过掌握今天学到的模型，我们能够更好的处理面临的问题，并让自己变得更加积极主动 。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1728823297000,"updated_at":1730714280000,"ria":true},{"id":17976,"topic":"用怡情聆听的方式解决沟通中的情绪问题","learn_goal":"","remark":"掌握移情聆听的核心技巧","level":"TF1-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"刘尚明","city":"佛山市"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>各位老师和小伙伴们，大家晚上好，今天很高兴由我来给大家做TF1-2的拆书分享，感谢大家的支持！\u003c/p>\u003cp>我的三个标签是企业管理咨询师（在辅导企业解决当下经营管理问题的过程中帮助企业建立一套管理系统，培养与提升团队管理水平，帮助企业提升组织竞争能力。\u003c/p>\u003cp>）、健康推广大使（参与两家大健康公司的运营工作，日常分享健康知识与养生小技能。\u003c/p>\u003cp>）、拆书践行者（在三级拆书家的成长之路上）。\u003c/p>\u003cp>我今天的拆书是《高效能人士的七个习惯》中的一个片段。作者是史蒂芬·柯维博士，是美国著名的管理学大师， 《高效能人士的七个习惯》的核心观点是——我们可以通过培养良好的习惯和价值观，从内而外地改变自己的思维方式和行为方式，从而实现个人的成长和成功。\u003c/p>\u003cp>今天的拆页是“知己解彼”中重要的沟通场景。\u003c/p>\u003cp>今天我们需要分组学习，请俩俩一组分组讨论。大家请看原文片段，看完的小伙伴（发个信息）敲一下桌子发出声音示意。\u003c/p>","ratings_count":1,"texts":[{"id":22217,"quote":"\u003cp>移情聆听是指以理解为目的的聆听，要求听者站在说话者的角度理解他们的思维方式和感受。\u003c/p>\u003cp>移情聆听的本质不是要你赞同对方，而是要在情感和理智上充分而深入地理解对方。移情聆听不只是理解个别的词句而已。据专家估计，人际沟通仅有10%通过语言来进行，30%取决于语调与声音，其余60%则得靠肢体语言。所以在移情聆听的过程中，不仅要耳到，还要眼到、心到；用眼睛去观察，用心灵去体会。\u003c/p>\u003cp>正确的沟通方式也就是移情聆听，至少包括四个阶段。\u003c/p>\u003cp>第一阶段是\u003cstrong>复述语句，这至少能使人专心聆听。\u003c/strong>\u003c/p>\u003cp>子：“上学真是无聊透了！”\u003c/p>\u003cp>父：“你已受不了了，觉得上学太无聊。”\u003c/p>\u003cp>第二阶段\u003cstrong>加入解释，完全用自己的词句表达，但仍用左脑的逻辑思维去理解。\u003c/strong>\u003c/p>\u003cp>父：“你不想上学了。”\u003c/p>\u003cp>第三阶段\u003cstrong>掺入个人的感觉，右脑发挥作用。此时听者所注意的已不止于言语，也开始体会对方的心情。\u003c/strong>\u003c/p>\u003cp>父：“你觉得很有挫折感。”\u003c/p>\u003cp>第四阶段\u003cstrong>是既加以解释，又带有感情，左右脑并用。父：“你对上学有很深的挫折感。”\u003c/strong>\u003c/p>\u003cp>运用这四个阶段的方式沟通，不仅能了解对方，更能帮助对方认清自己，勇于表达。\u003c/p>","explains":"\u003cp>现在我来拆解上面的学习片段\u003c/p>\u003cp>【What】\u003c/p>\u003cp>沟通中听者站在自己的角度，不能理解对方想要表达的意图，甚至认为对方在胡说八道或扯歪理时，沟通就会不欢而散，甚至出现情感隔阂，这种情形相信很多人都遇到过。\u003c/p>\u003cp>移情聆听就是听者站在说话人的角度，用心去观察、体会对方的情绪、感受、意图，听懂对方的心声，相互了解，对方愿意深入交流，从而实现沟通双方的目的。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>如果沟通中不是用心去感受对方的语音、语调及肢体动作传达出来的信息，单纯的听很可能不能理解对方的心情，感受不到对方想表达的真正意图，最后的结果有可能就是无效沟通。\u003c/p>\u003cp>不管是家庭中想拥有良好的亲情关系或是生活、工作中与他人良好的合作，我们都需要因沟通而增进情感，而不要因沟通后反而导致关系出现裂痕，移情聆听让沟通双方感受到彼此的用心，结果一定是双方接受的。\u003c/p>\u003cp>【How】\u003c/p>\u003cp>移情聆听4个步骤：\u003c/p>\u003cp>\u003cstrong>复述：\u003c/strong>复述对方所说的话，让对方感受到你在专心聆听；\u003c/p>\u003cp>\u003cstrong>解释\u003c/strong>：以你的理解讲出对方未说的话；\u003c/p>\u003cp>\u003cstrong>感受\u003c/strong>：说出对方的感受，讲出对方内在的声音。\u003c/p>\u003cp>\u003cstrong>融合\u003c/strong>：将对方的话的理解与感受融合为一句话来表达。\u003c/p>\u003cp>【Where】\u003c/p>\u003cp>l 移情聆听适合工作、生活的沟通场景。\u003c/p>\u003cp>l 在某些专业的工作场合移情聆听则不适用，比如公检法收集证据及专业技术方面的沟通交流。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>举例子\u003cstrong>】\u003c/strong>我与女儿的一次失败沟通的例子\u003c/p>\u003cp>女儿：我们哪天去海边玩，吃各种各样的海鲜。\u003c/p>\u003cp>我：海边有点远，来回有点累。\u003c/p>\u003cp>我：看看你老妈什么时间方便，去吃顺德的特色菜。\u003c/p>\u003cp>女儿：你知道我最喜欢吃什么吗？\u003c/p>\u003cp>我：你没讲过，我哪里知道你最喜欢吃什么？\u003c/p>\u003cp>女儿：……\u003c/p>\u003cp>这是一段失败的沟通，我只顾着自己自说自话，没有聆听女儿的心声。\u003c/p>\u003cp>过了一段时间，女儿与我讲，她是很喜欢吃海鲜的，只是内地较贵，她想着去海边吃比较新鲜。而我从来没关注过她的想法与感受，只关注了自己关心的事情。在此之后，女儿想做什么我都尽量按她的意思去做。\u003c/p>","interaction":"\u003cp>请各位伙伴回忆下在过去，因为不注意听对方讲话，发生的一件让人感受不好的事儿。这个回忆希望有整件事的起因、经过、结果，时间、地点、人物。\u003c/p>\u003cp>下面用3分钟的时间，我们来进行小组讨论，稍后我们每个组邀请一个同学来分享。\u003c/p>\u003cp>刚才罗老师的分享确实是按照要求，有起因、经过、结果，还有时间、地点和人物，通过分享其实也对今天的拆书内容有更好地回顾和理解，让我们感受到聆听在沟通中的重要性。\u003c/p>\u003cp>\u003cstrong>【A2催化应用】2分钟\u003c/strong>\u003c/p>\u003cp>拆书帮倡导的就是拆为己用，学以致用，今天我们学会了“移情聆听”，我们来试着把它用起来。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>举例子\u003cstrong>】\u003c/strong>我与女儿的一次沟通\u003c/p>\u003cp>女儿：爸爸，我想学心理学\u003c/p>\u003cp>我：你想学心理学是吧！ \u003c/p>\u003cp>女儿：是的。\u003c/p>\u003cp>我：好像你在大学时有一门课是心理学吧。\u003c/p>\u003cp>女儿：那是不一样的，大学只是简单的了解。\u003c/p>\u003cp>我：你想深度学习心理学知识及运用，是吗？\u003c/p>\u003cp>女儿：是的，深层次的学习心理学对我的工作有帮助。\u003c/p>\u003cp>我：可以呀，学好心理学知识，掌握运用方法，可以帮助你护理工作与病人的沟通与交流，缓解对方的心理压力，病人恢复的快；同时可以提升医患关系。\u003c/p>\u003cp>理解对方，认同对方的观点与想法。接下来我与女儿就怎样学习与实践，怎样选择学校及老师做了详细交流，最后女儿按照我们沟通结果找到她理想的学校与老师。\u003c/p>\u003cp>请大家想一想，在接下来一个周或一个月里，你会遇到哪些情况，可以用这种方式去聆听呢？请大家用1分钟时间思考一下，在便签上写下你的可行性方案。\u003c/p>\u003cp>特别提醒：这里的方案不能仅仅是表决心，要写清楚事情发生的时间、地点、人物、起因、经过和结果，要有可衡量或可观测的预期结果。\u003c/p>\u003cp>补：杨老师写的便签，有目标，也有时间限制。希望各位伙伴能够在接下来的半个月时间里践行学习到的移情聆听的方法。（后续杨老师提交了便签图片）\u003c/p>\u003cp>最后我们来回顾一下，今天的拆书分享。\u003c/p>\u003cp>我们在《高效能人士的7个习惯》这本书里学到了一个能够帮助我们如何「移情聆听」，去感受对方的情绪、意图和需要的内容。\u003c/p>\u003cp>希望今天的“移情聆听”能对大家有所帮助，用移情聆听去看见对方，助力提升沟通效率。\u003c/p>\u003cp>本次拆书活动结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1723865974000,"updated_at":1728747076000,"ria":true},{"id":17910,"topic":"责任型授权五步法","learn_goal":"","remark":"实行责任型授权，为质量加码，为效率助力，让高效从此刻开始!","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"花想容MM","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>\u003cstrong>一、自我介绍及分组（0.5分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003ch3>大家好，我是花想容，如果你一时记不起我的名字，就想想李白的“云想衣裳花想容，春风拂槛露华浓，大概率就会想起来我叫花想容了。\u003c/h3>\u003ch3>我给自己的三个标签：\u003c/h3>\u003ch3>1、财税会计的工作者，是生存追求、活下来、求安全\u003c/h3>\u003ch3>2、拆书学习的践行者，是精神追求，去学习，求丰盈\u003c/h3>\u003ch3>3、间歇健身的爱好者，是健康追求，去锻炼，求美丽\u003c/h3>\u003ch3>\u003cstrong>【分组】\u003c/strong>\u003c/h3>\u003ch3>谢谢大家来到我的练级修罗场，我今天是2-2级。身边人就是有缘人，从某某开始，顺时针三人一组，剩余的两人或者三人一组，OK，分组完成。\u003c/h3>\u003cp>\u003cstrong>【图书介绍】（2分钟）【FAB】\u003c/strong>\u003c/p>\u003cp>今天要拆读的内容：责任型授权五步法摘自《高效能人士的七个习惯》\u003c/p>\u003cp>\u003cstrong>【F】特征（Feature），核心是“书”，用于满足好奇心\u003c/strong>\u003c/p>\u003cp>（展示图书）这本书无疑是一本红遍全球的经典畅销书，在美国， 这本书的影响力仅次于《圣经》，连普京总统都推荐这本书。它的作者史蒂芬·柯维博士，在书中主要介绍了个人领域、公众领域两大方向提升的高效能人士需要具备的七个习惯。\u003c/p>\u003cp>\u003cstrong>【A】优势（Advantage），重点是“比较”，用于建立安全感\u003c/strong>\u003c/p>\u003cp>作者在书中不仅总结了七个高效能习惯，并且详细的描述出其中的原理、行动步骤，大量的案例通俗且落地，让读者学以致用, 被广大职场人士推崇，更是被世界500强企业作为培训课程。\u003c/p>\u003cp>\u003cstrong>【B】利益（Benefit），强调的是“你（学习者）”，用于引发兴趣\u003c/strong>\u003c/p>\u003cp>B1（针对本书）如果你也想要通过建立高效能习惯，让自己的思想和行为得到进化。或者想要解决当下生活与工作迷茫低效、没有目标、焦虑悲观等问题。就可以翻开这本书学起来了。\u003c/p>\u003cp>B2（针对本拆页）如果你想高效的分配或者接受工作事务，那么学习今天的拆页，将是个非常好的选择。\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong> 学习者在跟随我完成本次RIA现场学习后，能够清楚地运用“责任授权五步法”授权，让被授权者清晰任务的结果及职责。\u003c/p>","ratings_count":2,"texts":[{"id":22153,"quote":"\u003cp>\u003cstrong>二、R原文片段（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>R责任型授权【P- 页】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>片段来自史蒂芬·柯维的《高效能人士的七个习惯》\u003c/strong>\u003c/p>\u003cp>责任型授权的关注重点是最终的结果。它给人们自由，允许自行选择做事的具体方法，并为最终的结果负责。起初，这种授权方式费时又费力，但却十分值得。通过责任型授权，可将杠杆的支点向右移动，提高杠杆的作用。\u003c/p>\u003cp>这种授权类型要求双方就以下五个方面达成清晰、坦诚的共识，并做出承诺。\u003c/p>\u003cp>预期成果双方都要明确并且完全理解最终想要的结果。要以“结果”，而不是以“方法”为中心。要投入时间， 耐心、详细地描述最终的结果，明确具体的日程安排及截止期限。\u003c/p>\u003cp>指导方针确认适用的评估标准，避免成为指令型授权，但是一定要有明确的限制性规定。不加约束的放任， 其最终结果只能是扼杀人们的能动性，让人们回到初级的指令型要求上：“告诉我你想要我做什么， 我照做就是了。”\u003c/p>\u003cp>可用资源 告诉他们可以使用哪些人力、财务、技术或者组织资源来取得所预期的成果。\u003c/p>\u003cp>责任归属制定业绩标准，并用这些标准来评估他们的成果。制订具体的时间表， 说明何时提交业绩报告，何时进行评估。\u003c/p>\u003cp>明确奖惩明确地告诉他们评估可能导致的结果——好的和不好的——包括财物奖励、精神奖励、职务调整以及该项工作对其所在组织使命的影响。\u003c/p>\u003cp>信任是促使人进步的最大动力，因为信任能够让人们表现出自己最好的一面。但这需要时间和耐心，而且还有可能需要对人员进行必要的培训，让他们拥有符合这种信任水平的能力。\u003c/p>\u003cp>我坚信，只要方法得当，这种责任型授权绝对能够让双方都受益，并且最终能够使善于分配工作的人用很少的时间做成很多事情。\u003c/p>","explains":"\u003cp>\u003cstrong>三、I拆书家讲解引导：【用自己的语言重述知识】（6分钟）\u003c/strong>\u003c/p>\u003ch3>\u003cstrong>【过渡语】\u003c/strong>请大家花一到两分钟阅读手中的原文拆页，阅读完抬头示意\u003c/h3>\u003cp> 我看大家的看得差不多了，没有看完的也不要紧，我们一起来解读。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>这个原文片段讲述的是：以结果为导向的责任型授权，是一种授权方式。在这种授权中，授权者给予被授权人以明确的任务和责任，并确保被授权者有足够的权力和资源来完成任务。从发展的眼光来看，这是最为合理的一种方法，也是高效的秘诀之一。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>当需要去完成某项工作或事务时，我们往往有两种选择：第一种自己亲力亲为；第二种授权全部或者部分工作给他人完成。如果选择第一种事必躬亲，耗时耗力未必在规定时间内保质保量完成任务；如果选择第二种交给他人却没有好方法，结果达不到预期，还容易让被授权者觉得不被信任。\u003c/p>\u003cp>\u003cstrong>&lt;反例&gt;\u003c/strong>周一上班板，老板交待了两件事，让我周四提交财务报告，以及安排重要客户到访事宜，两件事件时间上有冲突，于是我我就想到把财报分析交给同事小唐做。然而，等我忙完重要客户的事，再来准备提交财报的时候，小唐给我的财报效果并不理想，只能自己重新加工修改，而小唐也觉得我没交待清楚任务而委曲。\u003c/p>\u003cp>那么这种情况有没有好的办法呢？有，那就是我们今天要学习的责任型授权法，具体怎么做呢？\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong> （板书1结果2重点3资源4标准5奖惩）五步有点多，但别担心，我简单归纳分为两大方向五小步，方向一：\u003cstrong>要\u003c/strong>，要什么（1结果，2重点）；\u003cstrong>给\u003c/strong>，给什么（1资源、2标准、3奖惩）\u003c/p>\u003cp>第1步：预期成果：双方要对达成的目标认知一致，授权者必须确保接受者完全理解要达成的预期成果；\u003c/p>\u003cp>第2步：指导方针：理解有点难，但翻译成人话就是影响目标结果的几个至关重要的因素，做到这两点要的结果就大差不差了；\u003c/p>\u003cp>第3步：可用资源：告知对方做这项任务有哪些资源可以调用以获取支持，包括人力（培训），财力，物力等；\u003c/p>\u003cp>第4步：\u003cstrong>责\u003c/strong>任归属：制定任务考核标准，明确考核周期和任务提交时限；\u003c/p>\u003cp>第5步：明确奖惩：告知这项任务的价值和意义，以及未能如预期完成的可能不良后果，提升接受者的积极性。\u003c/p>\u003cp>“要”和“给”两大方向五小步骤呢有助于帮助我们在领导和管理的角色中，更明确更清晰更好的达成共识，并建立起信任和明确的责任分工，以实现良好的责任型授权。\u003c/p>\u003cp>\u003cstrong>&lt;反例变正例&gt;\u003c/strong>学习了责任型五步法，更清晰了方式交待任务的方法。再遇到这种情况我会这样授权：\u003c/p>\u003cp>小唐，你现在手上不忙的工作先停一停，首要任务是周五下班之前重新提交一份财务报告给我，目标要求报告里体现公司市场部、设计部、工程部的产值，费用、项目毛利，项目收付款项等\u003cstrong>（要结果）\u003c/strong>；重点是各个部门的数据准备不能交叉混乱，比如说销售部门只能归于销售部，设计部只能归于设计部\u003cstrong>（要重点）\u003c/strong>。另外我已经跟市场部、设计部、工程部总监沟通好，你可以联系三大部门助理协助你\u003cstrong>（给资源）\u003c/strong>，你把去年财报档案拿出来参考报告内容格式\u003cstrong>（给标准）\u003c/strong>；你把这财报弄懂了对你理解专业方面很有帮忙\u003cstrong>（给奖惩鼓励）。\u003c/strong>我说明白了吗？你有没有哪里不清楚的？如果有疑问或者不懂的可以随时找我沟通。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>可能大家咋一听，这种授权方式费时又费力，觉得麻烦。但请听我说，比起孩子来，你当然更有能力迅速把一间房子收拾干净整齐”，但你不能代替孩子成长也不能让他学会承担他相匹配的责任？比起新同事来说，你当然更有能力迅速把工作处理得更好。但是毕竟我们每个人的精力都是有限的，不可能兼顾所有的事情。\u003c/p>\u003cp>有的小伙伴可能会说，我就是一普通员工不是领导，没有什么可授权的。其实我们是可以\u003cstrong>反向授权的哈\u003c/strong>，如果发现领导分配任务不明确，不清晰，没有评估标准等，我们可以找领导明按责任授权五步法来梳理的，比如要资源，要支持等。。。。\u003c/p>\u003cp>虽然责任型授权在前期确实是费时费力，做好了，最终你会发现这样做是绝对值得的。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>这个方法的适用场景可以是职场上有效提高领导力，促进员工的自主性和创造力，提高团队协作；对于个人生活家务分工活动安排等也是非常有用的，但不适合用于一些需要紧急处理的任务，比如会议上领导临时要的文件让不会使用打印机的实习生小A去做等。\u003c/p>","interaction":"\u003cp>\u003cstrong>四、A2分步催化1（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书家提问设计】\u003c/strong>好，请思考1-两分钟，接下来一周的工作或者生活中，有没有可以授权或者被授权的事情呢？比如说和同事一起合作某项任务，你分配团队成员工作，或者领导交待你任务，又或者生活上像周末了分配家人采购物资，让家人或朋友负责周末放松活动的安排等。。。邀请一位小伙伴分享一下想到的场景。\u003c/p>\u003cp>\u003cstrong>李娜分享：\u003c/strong>出差前授权团队成员工作任务\u003c/p>\u003cp>\u003cstrong>五、A2分步催化2（7分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书家提问设计】\u003c/strong>\u003c/p>\u003cp>大家根据刚才组内想的场景，进行细化，大家怎样具体的去应用责任型授权五步法，把握“要”和“给”两大方向5小步哈\u003cstrong>——\u003c/strong>大家先讨论2分钟，稍后我们邀请一位小伙伴来进行分享一下。\u003c/p>\u003cp>\u003cstrong>李娜分享：\u003c/strong>出差前授权团队成员工作任务\u003c/p>\u003cp>\u003cstrong>一要\u003c/strong>\u003c/p>\u003cp>（1）\u003cstrong>结果：\u003c/strong>在我出差的这一周内，会要求团队成员能够完成月度分解至本周的绩效要求。这是我们整体工作推进的重要一环，关乎团队的工作效率和目标达成情况，确保每一个环节都不脱节，保障业务的顺畅进行。\u003c/p>\u003cp>（2）\u003cstrong>重点：\u003c/strong>重点在于务必按照既定的时间进度完成分配到的绩效。时间是关键因素，严格遵守时间安排能让我们的工作更有秩序，避免出现拖延和混乱的局面，保障各项工作有序推进，与其他部门的协作也能更加紧密、高效。\u003c/p>\u003cp>\u003cstrong>二给\u003c/strong>\u003c/p>\u003cp>（3）\u003cstrong>资源：\u003c/strong>让团队成员自行分析自己的业绩指标，对于成员提出的合理支持需求，会积极给予配合。这样可以充分调动成员的主观能动性，让他们对自己的工作有更清晰的认识，同时感受到团队的支持，增强自信心和责任感。\u003c/p>\u003cp>（4）\u003cstrong>标准：\u003c/strong>所有工作需按照以往的要求和规范完成指标。这些要求和规范是我们长期实践积累下来的宝贵财富，是保证工作质量的关键所在，严格遵循能有效避免错误，确保工作成果符合预期。\u003c/p>\u003cp>（5）\u003cstrong>奖惩：\u003c/strong>如果顺利完成任务，我将奖励大家喝奶茶，让大家在辛苦工作之余能感受到甜蜜的回报。反之，如果未能完成，大家的工作压力会增大，可能需要加班赶进度。希望通过这种方式激励大家积极对待工作，提高工作质量和效率。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1722324541000,"updated_at":1730209061000,"ria":true},{"id":17850,"topic":"要事第一，人生由我掌控","learn_goal":"","remark":"在生活中我们主动或者被动地承担看各种角色，同时角色也赋予了我们权利和义务，并且每个阶段角色在不同时期比重不同，如何在各种角色中游刃有余，丝滑切换并做到不顾此失彼呢，今天的自我管理四步法可以让我们轻松实现有效管理，达到各种角色的平衡。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"月亮姐姐","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>\u003cstrong>自我介绍：\u003c/strong>\u003c/p>\u003cp>嗨，各位小伙伴们大家好，我是刘月，留住月亮，大家可以称呼我为月亮姐姐，乐观开朗善解人意。\u003c/p>\u003cp>首先用三个标签来介绍下我自己：\u003c/p>\u003cp>1、人工智能科普培训老师\u003c/p>\u003cp>2、中年觉醒的宝妈\u003c/p>\u003cp>3、喜欢分享一切美好的事物，比如美文、美景、美服、美物等，有同好的朋友欢迎链接。\u003c/p>\u003cp>\u003cstrong>图书介绍：\u003c/strong>\u003c/p>\u003cp>今天我选的拆页来自于《高效能人士的七个习惯》，先通过FAB法来介绍一下这本书。\u003c/p>\u003cp>F 特征（核心是“书”，用于满足好奇心）：\u003c/p>\u003cp>这本书是由著名的领导力大师、人际关系专家史蒂芬·柯维博士撰写。他被誉为美国学界的“思想巨匠”；入选“影响美国历史进程的25位人物”；被《时代周刊》评为“人类潜能的导师”；\u003c/p>\u003cp>《高效能人士的七个习惯》它不仅是工作中的高效能工具，还是管理自己和让自己变得更优秀的有效方法。柯维博士教给我们：改变生活的关键是改变思维方式——我们每个人都有无穷的潜力。\u003c/p>\u003cp>A 优势（重点是“比较”，用于建立安全感）：\u003c/p>\u003cp>福布斯将《高效能人士的七个习惯》评为有史以来最具影响力的10大管理类书籍之一。在美国的影响力仅次于《圣经》，这本书在豆瓣的评分为8.4分，畅销30多年。被公认为不仅是企业、团体，更是个人获得提升的人生必修教材。\u003c/p>\u003cp>B 利益（强调的是“学习者”的利益，用于引发兴趣）\u003c/p>\u003cp>B1这本书提供了七个高效能习惯，而且详细说明了其中的原理与逻辑递进的关系，针对每一个习惯，有大量的案例、具体的行动建议，可以很好地引导读者学以致用。\u003c/p>\u003cp>B2今天学习的片段主题是“要事第一”，通过学习“自我管理的四步骤”能够让我们\u003c/p>\u003cp>针对日常忽视的“重要不紧急的事情”做好周计划，从而在时间管理领域以20%的付出取得80%的成果。\u003c/p>\u003cp>前言引导：\u003c/p>\u003cp>本片段涉及专业术语第二象项事务，第二象限事务是什么？大家可以看看白板上的四象限时间管理矩阵，第一象限是既紧急又重要的，第二象限是不紧急但重要的，第三是紧急不太重要的，第四则是既不紧急也不重要的。三四可以忽略，第一象限是既紧急又重要的，这类事务耗费大量的时间和精力，过分关注会占据超过80%的精力，让人每天都在忙于应付各种问题，疲于奔命。\u003cstrong>而第二象限事务包括建立人际关系、与个人使命相关、规划长期目标、防患于未然等等，这些属于要事\u003c/strong>，做好这些重要事情，我们的生活就会大大改观。。\u003c/p>","ratings_count":1,"texts":[{"id":22083,"quote":"\u003cp>\u003cstrong>自我管理四步骤\u003c/strong>\u003c/p>\u003cp>虽然我的工作主要是教授高效率的原则性问题，一般不讲授具体的实施计划，但我认为，如果能够以原则为基础，以第二象限事务为生活中心，对一个星期内的事务进行具体安排，将有助于更好地理解第四代时间管理方法的原则及其巨大潜能。\u003c/p>\u003cp>以第二象限事务为中心的日程安排需要以下四项关键步骤:\u003c/p>\u003cp>\u003cstrong>确认角色\u003c/strong> \u003cstrong>第一步就是要写出你自己的关键角色\u003c/strong>。作为一个个体，你有属于自己的各种角色。你可以先写下自己在家庭中的角色，然后再写下自己在工作中的角色，列举自己想要持续投入时间和精力去做的一些事情。\u003c/p>\u003cp>你不必想得太复杂，只要考虑自己下一周的角色和任务，记下这七天时间里需要专注的领域即可。\u003c/p>\u003cp>\u003cstrong>选择目标\u003c/strong> \u003cstrong>第二步就是思考下一个周计划中每一任务栏下你最想做的一两件要事\u003c/strong>，\u003cstrong>作为你选定的目标\u003c/strong>。\u003c/p>\u003cp>这些目标中一定要有几个第二象限事务，最好让这些短期目标与使命宣言中的长期目标相关联。即使你还没有撰写个人使命宣言，也可以根据自己的感觉来判断每个角色中哪些事情是比较重要的，并为每个角色确立一或两个目标。\u003c/p>\u003cp>\u003cstrong>安排进度\u003c/strong> \u003cstrong>第三步是为每一项目标安排具体的实施时间\u003c/strong>。如果你的目标是起草自己的个人使命宣言，那就不妨在星期天安排两个小时专门做这件事情。通常星期天是进行个人思考和制订个人成长计划的理想时间，因为这时候你有充足的时间思考、反省，寻求灵感，并根据各项原则和价值观来审视自己的生活。\u003c/p>\u003cp>确认角色并制定目标后，你就可以把每项任务分配到一个星期中某个具体的日子去做了。或者将它列为一项重要活动，或者列为一个特别约会。\u003c/p>\u003cp>\u003cstrong>每日调整\u003c/strong> 使用这种以第二象限事务为中心的周计划之后，你就会发现原来的每日计划变成了每日调整，\u003cstrong>即根据突发事件、人际关系的意外发展及崭新机会对每天的要务安排进行适当调整。\u003c/strong>\u003c/p>\u003cp>当你每天早晨审视自己一天的日程安排的时候，你会看到，由于内心的平衡，自己已经为角色和目标进行了合适的优先排序。这种日程安排是灵活的，是右脑运作的结果，是建立在自己对个人使命的认识的基础上的。\u003c/p>","explains":"\u003cp>\u003cstrong>这个片段说了什么？\u003c/strong>\u003c/p>\u003cp>What：这个拆页告诉我们每个人都处于多种不同的角色，我们需要根据关键角色以重要不紧急的要事为中心、制定具体进度、每日进行调整的四步法来安排一周的计划表。\u003c/p>\u003cp>\u003cstrong>为什么要用“自我管理四步法”？\u003c/strong>\u003c/p>\u003cp>Why：我们每天要处理的事情很多，重要和不重要都被安排在日程中，有时是被事情或者他人推着走，往往一天时间过去了，重要的事情还没做，被迫加班或者无限拖延。\u003c/p>\u003cp>运用“自我管理四步法”，可以让我们主次分明，以第二类象限事务为重心，游刃有余地完成一周的事物，即使中间出现意外需要调整，也能达到内心的平衡，因为我们已经为角色和目标进行了合理排序，重要的事项都在自己的掌控中，可以对抗不确定和风险。\u003c/p>\u003cp>\u003cstrong>【不这样做的坏处】\u003c/strong>\u003c/p>\u003cp>如果不运用自我管理的四步骤，我们大部分人都会眉毛胡子一把抓，西瓜皮滑到哪里是哪里，东一榔头西一棒槌，导致重要且紧急的事情占用了我们80%以上的时间，而重要不紧急的事情总被无限期延后，每天处于救火的紧张的状态，就很难按计划完成我们的任务和目标，并且经常会感觉啥都干了又好像啥也没干，充满疲惫和挫败感。\u003c/p>\u003cp> 【反面案例】\u003c/p>\u003cp>比如：我和老公平时都比较忙，要赚钱要学习要服务好客户要处理各种事情，时间大多给了工作而忽略了家人，去年一直说要带父母去体检，一直拖拖拉拉没有安排，直到今年5月份婆婆忽然发现身体不适到医院一检查就是大毛病，需要住院手术，导致我们措手不及，其他事情通通靠边，请假陪伴住院了半个月。这就是忽略自己在家庭中的角色，把原本重要不紧急的事情变成了重要又紧急的事情，怕小麻烦反而招来更大的麻烦。\u003c/p>\u003cp>How：\u003c/p>\u003cp>“自我管理四步法”可以很好解决这些问题，能让我们在不同角色之间做好平衡，安排好对应角色的重要事务。 \u003c/p>\u003cp>\u003cstrong>第一步：\u003c/strong>明确身份：写出自己在各种场景中的关键角色，比如自己是父母、是子女、是员工等身份。\u003c/p>\u003cp>\u003cstrong>第二步：\u003c/strong>选择目标：在每个角色身份后确定一两件重要事务作为下一周的目标。\u003c/p>\u003cp>\u003cstrong>第三步：\u003c/strong>安排进度：为各项目标安排具体的实施时间。\u003c/p>\u003cp>\u003cstrong>第四步：\u003c/strong>适时调整：根据突发事件和一些意外，对每周的具体行动计划进行适当调整。要注意不能因为调整而将原计划无限期延后。\u003c/p>\u003cp>通过学习“自我管理四步法”我也进行了调整。\u003c/p>\u003cp>第一：确定角色。我是妈妈、女儿、员工。\u003c/p>\u003cp>第二：选择目标。作为孩子的妈妈，需要跟孩子确定好暑假的学习和游玩计划；作为父母的女儿，需要关注他们的日常需求及定期体检；作为员工，我需要完成日常的重要工作。\u003c/p>\u003cp>第三：安排进度。作为妈妈，放假第一周周一傍晚跟孩子好好沟通一起共创确定每周的学习及玩耍计划，预约了3家教培机构进行试听。作为女儿，每周末跟父母沟通一次，了解他们的诉求和心情，并及时调解，带父母去做一次全身体检。作为员工，将每周的要事记录下来，按照时间节点严格执行。\u003c/p>\u003cp>第四：每日调整。比如跟爸爸沟通后他不太愿意去，怕花钱，就需要及时沟通做工作，时间可能会适度延迟，但不能取消。\u003c/p>\u003cp>通过以上调整给孩子找到了合适的培训机构也制定了他所愿意接受的学习计划，让学习不盲目打乱仗，父母的健康得到了保障，我们也可以更安心地工作了，即使出现小插曲也能游刃有余去处理。\u003c/p>\u003cp>\u003cstrong>使用边界\u003c/strong>\u003c/p>\u003cp>Where：\u003c/p>\u003cp>“自我管理四步法”对于想要掌控时间掌控自我人生正向发展的朋友非常适用，可以用它来指导我们对重要不紧急的事情也就是“要事”进行周计划表。而如果你目前状态很糟糕，情绪处于低谷，那就先不要逼迫自己，允许自己暂时躺平调整状态。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1显像提问：\u003c/strong>\u003c/p>\u003cp>好了，刚刚我们学习了这个片段，那请大家回想一下，最近是否经历过因为不够明确对自己最有价值的“要事”，而出现时间不够用，计划拖沓，被琐事牵着鼻子走无法改变现状的无力感和挫败感呢？\u003c/p>\u003cp>比如：工作中没有好好规划导致重要事件拖延，甚至整个计划都被打乱的状况；比如家庭关系由于疏于跟爱人沟通保持交流，导致夫妻冷漠，各忙各的；比如平时跟孩子交流太少，不了解他的学习状况，导致成绩下降请家长等让我们焦头烂额怀疑人生。\u003c/p>\u003cp>类似以上种种大家遇到过吗？请小伙伴们思考2分钟写下来，2分钟后，我将随机邀请一位小伙伴来分享。\u003c/p>\u003cp>好，时间到了，有哪位小伙伴愿意主动站上来分享一下自己的经历呢？有请三明治这位伙伴分享一下\u003c/p>\u003cp>三明治：自己有很多这方面的问题，同经济基础相关的没有引起重视，在各种社交活动花费的时间比较多，后续需要调整一下主次关系。\u003c/p>\u003cp>感谢小伙伴的分享。在实际工作生活中，我们有很多角色身份，需要同时面对很多事情。刚刚大家都写下了关于自己面对多头绪事务的经历。\u003c/p>\u003cp> \u003cstrong>A1+反思加工：\u003c/strong>\u003c/p>\u003cp>既然我们学习了自我管理四步骤，如果再给你一次机会，回到从前的场景，你又会怎么做呢？你会如何重新设计这一周的规划呢？你的角色是什么，你会制定什么样的目标，你会怎么安排进度。请大家在小组内做分享，2分钟后我会邀请小组代表来进行分享。\u003c/p>\u003cp>好，时间到了，有请叶雨小伙伴，看她是怎样通过“自我管理四步法”的原则和步骤，来制定周计划的。\u003c/p>\u003cp> 叶雨： 首先角色定位：学习者\u003c/p>\u003cp> 选择目标：一周看一本书。\u003c/p>\u003cp> 安排进度：将七天的计划安排好，做一个表格。\u003c/p>\u003cp> 每日调整：每天检查进度看是否有完成，并做调整。\u003c/p>\u003cp> 【结束语】\u003c/p>\u003cp>非常感谢叶雨的分享，按照学习步骤制定了周计划，今天大家一起学习了自我管理四步法：明确身份、选择目标、安排进度和适时调整，也学会了制定一份“要事第一”的周计划表，“凡事预则立，不预则废”，不忘初心方得始终，希望我们都能早日成为一名高效能人士，现自己的人生目标！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1721112937000,"updated_at":1722784618000,"ria":true},{"id":17665,"topic":"学会倾听","learn_goal":"","remark":"学习目标：与他人沟通时，大家能够使用（行为）“移情聆听法”去理解（澄清）他人 ，并能够用感受的词语来说出对方的感受（界定）。\n内容简介：跟随拆书家一起学习高效能认识的倾听方法","level":"TF3-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"雪菲","city":""},"club":{"name":"大连知行分舵","city":"大连"},"prologue":"\u003cp>开场：\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>非常感谢大家，在这么美好的晚上，来到拆书帮大连分舵的线上拆书练级活动，我是今天的拆书家金雪菲。\u003c/p>\u003cp>我有2个标签 (或者可以帮到大家的地方）：\u003c/p>\u003cp>专业的保险买手、保险经纪人，对整个市场上的保险产品和公司都很了解，帮助大家配置合适的保险，节省约一半的支出。\u003c/p>\u003cp>终身成长：成长是第一生产力，我个人经历漫长的职业迷茫、亲子关系的黑暗时期，所以阅读非常广泛，心理、历史、理财、管理等等，阅读与实践相结合，帮助我走出困境。欢迎爱读书的朋友过来和我交流。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>因为今天线上的伙伴不多，所以就不分组了。稍后的讨论大家可以直接开麦发言。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>今天的学习目标是，在跟随我完成本次RIA现场学习后，与他人沟通时，大家能够使用（行为）“移情聆听法”去理解（澄清）他人 ，并能够用感受的词语来说出对方的感受（界定）。\u003c/p>\u003cp>【事件场景】\u003c/p>\u003cp>女儿没有上过幼小衔接直接上小学，开始学习拼音的时候，她跟不上老师的节奏，上课提问她都不会。于是她跟我说：“妈妈，我不想上学了”。\u003c/p>\u003cp>我说：“上学确实不那么愉快，妈妈以前读书的时候也想过逃课，不过后来发现上课还是可以学到点东西的，你明天还是接着去上学吧，好不好。”\u003c/p>\u003cp>女儿说：“可是妈妈.....”女儿还想说什么，我因为晚上还要开会，也没空听她讲，就拉着她去写作业了。\u003c/p>\u003cp>【提问】\u003c/p>\u003cp>不知道大家是否也有过类似的经历，朋友、合作伙伴、家人或者孩子遇到挫折或者问题想要向我们倾诉、寻求帮助的时候，我们常常自以为是的联系我们自己的经历，贸然向对方提出建议或者以自己的经验提供忠告，着急回应，却根本没有真正理解对方真实的需求？\u003c/p>\u003cp>【影响】\u003c/p>\u003cp>当我们这样做的时候，其实并未真正理解对方，而只是为了做出回应。不利于双方之间信任的建立或者沟通的顺利进行。\u003c/p>\u003cp>如果别人感受不到被我们真正的理解，那即便我们说的话是有道理的，对方也不一定会听。\u003c/p>\u003cp> 【解决】\u003c/p>\u003cp>今天我们的分享的来自《高效能认识的7个习惯》中的“移情聆听”三步法，则是教会我们如何高质量地聆听他人，迅速理解对方的需求与感受，并建立信任，实现有效沟通。\u003c/p>","ratings_count":3,"texts":[{"id":21870,"quote":"\u003cp>【片段来源】： 《高效能人士的七个习惯》\u003c/p>\u003cp>【主题】：移情聆听\u003c/p>\u003cp>事实上，大部分人都是这么自以为是。我们的聆听通常有层次之分。一是充耳不闻，压根不听别人说话；二是装模作样，“是的”、“嗯”、“没错”；三是选择性地接收，只听一部分，通常学龄期儿童的喋喋不休会让我们采取这种方法；四是聚精会神，努力听到每个字。但是，很少有人会达到第五层次，即高层次的移情聆听。\u003c/p>\u003cp>主动型和回应型聆听是一种技巧，本质是以自我为中心，就算行为没有显露出来，动机已经不言而喻，会让说话的人有受辱的感觉。回应型聆听技巧的目的不过是要做出回应，操控对方。\u003c/p>\u003cp>移情聆听是指以理解为目的的聆听，要求听者站在说话者的角度理解他们的思维模式和感受。\u003c/p>\u003cp>移情不是同情，后者是一种认同和判断形式，更适合用来表达感情和做出回应，却容易养成对方的依赖性。移情聆听本质不是要你赞同对方，而是要在情感和理智上充分而深入地理解对方。\u003c/p>","explains":"\u003cp>WHAT:这个片段里提到了一个重要的概念：“移情聆听”。指一个人理解另一个人说话的真实意图以及所带的感情，并将他的理解反馈给说话人。它教我们在与人沟通时，如何通过“知彼解己”来精准的获取信息，理解对方，获取信任，让对方明白“我们懂他”，从而让对方敞开心扉，实现有效沟通，\u003c/p>\u003cp>WHY：\u003c/p>\u003cp>这样做的好处：通过“移情”，可以实现在情感和理智上深入地理解对方，在双方之间建立起信任的桥梁，让沟通更加顺畅。\u003c/p>\u003cp>不这样做的坏处：不理解对方就贸然给建议、提忠告或者判断对方行为对错，犹如医生未经诊断即给病人开药方，难以建立信任，相应的沟通也就是无效的。\u003c/p>\u003cp>【辨析概念间的适用边界】\u003c/p>\u003cp>这里特别强调，移情聆听不是简单的“认同对方”，而是从情感和理智上充分地理解对方。是以理解为目的的倾听，是站在倾诉者的角度，去理解他们的思维方式和感受。\u003c/p>\u003cp>整个聆听过程是围绕着倾诉者的，不断感知对方的感受和需要。\u003c/p>\u003cp>而同情，则是一种认同和判断形式。倾听的一方是站在自己的角度去感受和需要。\u003c/p>\u003cp>通常的表达方式是：“你的表达让我觉得如何如何”。\u003c/p>\u003cp>整个聆听过程其实是围绕着“我”展开的，你的说法让我觉得如何，或者听完我觉得应该要做点什么去安慰一下对方，等等。\u003c/p>\u003cp>为了让大家更好地理解移情和各种不同倾听方式的区别，我举3个例子。\u003c/p>\u003cp>1、在我开场的案例中，孩子告诉我：“妈妈，我明天不想上学”，于是我“巴拉巴拉，我也有过类似的经历，我的经验是.......” \u003c/p>\u003cp>这是移情聆听么？不是。\u003c/p>\u003cp>这是建议。在把别人的感受用自己的经历过滤，不是移情聆听，我并没有理解她此刻的感受和想法。如果是移情聆听，我可以先来陈述我听到的事实：“妈妈听到宝贝刚刚说明天不想上学了”，传达出我在全身心听你讲话的意思。\u003c/p>\u003cp>2、闺蜜和男朋友分手了，来找我倾诉，我和她一起大骂“你男朋友真是渣男”。\u003c/p>\u003cp> 这是移情聆听么？\u003c/p>\u003cp>不是，这是认同。是我自己的价值判断或者为了迎合闺蜜此刻的情绪，特定去认同她。闺蜜可能只是情绪伤心之下的一种语言发泄。事后她冷静下来可能也会不这么觉得。\u003c/p>\u003cp>这个时候，我们可以试着去体会她的感受并且反馈给她，说：“你是不是非常伤心？”\u003c/p>\u003cp>2、闺蜜跟我抱怨说，想换工作又觉得好难，不换工作又觉得实在是没时间陪小孩。我说：“天天想来想去又不行动，有这个功夫不如去投简历”。这是移情聆听吗？\u003c/p>\u003cp>不是。这是评判。\u003c/p>\u003cp>那如果是移情聆听，我们可以试着去询问对方的需要，比如：“你是不是希望可以工作和照顾小孩的一个平衡？”\u003c/p>\u003cp>【预防异议】你可能会觉得移情聆听这么麻烦，有时候简单直接的沟通效果会更好？\u003c/p>\u003cp>是的，移情聆听的主要的目的是让对方觉得“我懂你”，建立“我俩是站在一边的”这种信任感。是沟通的基础。当我们发现对方的问题不是信任的问题，需要用其他的方式让她采取行动，那么可以更加直接的方式处理。\u003c/p>\u003cp>【适用边界】：\u003c/p>\u003cp>移情聆听可以用于跟家人、朋友、同事、合作伙伴的沟通。当我们发现对方有比较严重的情绪或者合作中双方想要的东西不一样时，运用移情聆听来进行沟通，站在对方的立场去感同身受，沟通效果一定会更好。而一般性的沟通询问，随意的谈话闲聊就不适用这个方法。\u003c/p>\u003cp>【行动步骤】\u003c/p>\u003cp>根据刚才的讲解，我们可以总结出移情聆听的三个步骤。\u003c/p>\u003cp>第一步： 复述语句，陈述我们听到的事实。\u003c/p>\u003cp> 第二步： 掺入个人的感觉，体会对方的感受，并反馈给对方。\u003c/p>\u003cp>第三步：询问对方的需要。\u003c/p>\u003cp>理解他的处境和感受，并询问他的需要，他会感受到你的注意力一直在他身上，是真的想要理解他，也会觉得很安全，会更愿意打开话匣子，更愿意交流。\u003c/p>\u003cp>【解决问题】\u003c/p>\u003cp>回到开场时我距离的场景，用移情聆听法来应用一下，就是这样的：\u003c/p>\u003cp>孩子想我表达：“妈妈，我明天不想上学了”\u003c/p>\u003cp>我：“你说明天不想去上学了” （复述，用我们的语言表达听到的事实）\u003c/p>\u003cp>孩子：“是啊，老师提的拼音问题我都不会”\u003c/p>\u003cp>我：“老师提的问题，我们宝贝很多都不会回答，所以觉得很有压力，很沮丧，对吗？”（体会对方的感受，并反馈给她）\u003c/p>\u003cp>孩子：“是的，妈妈，我都不会，觉得太丢脸了”\u003c/p>\u003cp>我：“那妈妈明白了，我们宝贝现在需要的是，如何帮助你学会拼音，对吗？”\u003c/p>\u003cp>（询问对方的需要）\u003c/p>\u003cp>综上所述，我们知道，“移情聆听”是要以理解他人为目的，理解他人说话的真实意图以及所带的感情，并将我们的理解反馈给他人。\u003c/p>","interaction":"\u003cp>相信大家已经对移情聆听有了清晰的了解，为了更好的理解和应用今天所学，接下来请每位小伙伴编写一个小剧本，想象一下，未来一个月内，我们可能会遇到哪些场景可以用到移情聆听法呢，请大家设计一个剧本小故事，小故事中要用到我们今天所学移情聆听三步法，来理解对方，并将我们的理解反馈给对方。\u003c/p>\u003cp>编写要求：要设计出人物、情节变化（包括：起因、经过、结果），可采用对话形式，对话经过建议可以写关键词。我给大家准备一个框架模板，来辅助大家编写，现在发给大家，人手一份。\u003c/p>\u003cp>大家都已经拿到模板，给大家5分钟时间，之后我们邀请一位小伙伴来分享他的剧本。\u003c/p>\u003cp>编写要求\u003c/p>\u003cp>1、包含时间、地点、人物、经过、结果，对话经过标注关键词\u003c/p>\u003cp>2、对话经过应用“移情聆听三步法”\u003c/p>\u003cp>示范\u003c/p>\u003cp>用移情聆听法来应用一下，就是这样的：\u003c/p>\u003cp>（某天下午，在接孩子放学回家的路上）\u003c/p>\u003cp>孩子想我表达：“妈妈，我明天不想上学了”\u003c/p>\u003cp>我：“你说明天不想去上学了” （复述，用我们的语言表达听到的事实）\u003c/p>\u003cp>孩子：“是啊，老师提的拼音问题我都不会”\u003c/p>\u003cp>我：“老师提的问题，我们宝贝很多都不会回答，所以觉得很有压力，很沮丧，对吗？”（体会对方的感受，并反馈给她）\u003c/p>\u003cp>孩子：“是的，妈妈，我都不会，觉得太丢脸了”\u003c/p>\u003cp>我：“那妈妈明白了，我们宝贝现在需要的是，如何帮助你学会拼音，对吗？”\u003c/p>\u003cp>（询问对方的需要）\u003c/p>\u003cp>学习者的展示：\u003c/p>\u003cp>来自现场学习者（阅读知行）：\u003c/p>\u003cp>未来的时间：未来的一周某天\u003c/p>\u003cp>地点：小区\u003c/p>\u003cp>人物：我和一个业委会的邻居\u003c/p>\u003cp>事件（沟通的目的）：理解邻居的诉求：希望业委会能够接受让业主一起共同决策，同时也不要让业委会的成员寒心\u003c/p>\u003cp>对白及动作：\u003c/p>\u003cp>小区业主群里里进行如何开展绿化的讨论。有一个老业委会的人（也就是邻居）因为新业委会的一些做法（代替业主直接决策）引起了业主的投诉，就在群里发了一通脾气，非常生气。氛围很僵硬。\u003c/p>\u003cp>那么在这周，大家还会就这个问题进行探讨，学习者希望可以既理解邻居的诉求，同时希望协调双方的矛盾，不让做事情的人（业委会成员）寒心\u003c/p>\u003cp>那么这种场景下，如果用移情聆听方式来进行沟通：\u003c/p>\u003cp>我：你现在业委会的做法，引起了业委会和业主之间的冲突，对吧。（复述，表达事实）\u003c/p>\u003cp>邻居：是啊，你看，现在这么多人都在投诉业委会（觉得很生气）。\u003c/p>\u003cp>我：你是觉得现在业委会这样的做法让你感到得非常地难受，因为业委会代替大家做了决策。（体会对方的感受并反馈给他）\u003c/p>\u003cp>邻居：是的。（情绪稍微平静一点）\u003c/p>\u003cp>我：你是不是希望业委会参考一下老业委会的建议，今后遇到像这种关乎全体业主利益的决策的时候，先把相应的方案先发出来，让大家投票决定，是吗？\u003c/p>\u003cp>（询问对方的需求）\u003c/p>\u003cp>邻居：是的，如果是这样，就可以提前把做一些问题规避掉，不至于引起这么大范围的投诉。\u003c/p>\u003cp>我：你的顾虑很有道理，那我们可以去跟业主委员会来表达我们的诉求，一起探讨。\u003c/p>\u003cp>主讲人：好的，感谢悦读知行的精彩分享，她的这个剧本是一个非常典型的沟通场景。也包含了我们今天的移情聆听非常重要的三个步骤，表达我们听到的事实，体会对方的感受并反馈给她，询问对方的需要。非常棒的演示。\u003c/p>\u003cp>看来今天的分享大家都把握住了精髓，感谢大家的时间。也希望大家回去在我们的日常生活中把这个沟通技能用起来，让我们的生活更加美好。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1716877976000,"updated_at":1723216275000,"ria":true},{"id":17395,"topic":"知彼解己，最重要的原则：移情聆听！ ","learn_goal":"","remark":"我们接受更多的是偏向读写的训练，很少被教导如何去听，所以我们更倾向于从自己的主观意识去揣测他人意思，误解就这样产生的。知彼解己，最重要的原则：移情聆听！\n","level":"TF1-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"妃妃","city":"台州市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp> 大家好，我叫陈联妃，来自浙江台州，非常感谢各位老师来参加我这次1-2的过级。首先将用3个标签来介绍下自己：我是一名斜杠女青年，因为我同时在做很多跨行业的事...比如亲子教育、个人情绪管理、儿童社会情感能力学习；我的主职是一名保险代理人；同时我也爱好公益，也是一名自发的公益共读群群主，也开展过公益家长课堂。\u003c/p>\u003cp>今天为大家带来的片段来自美国作家、领导力大师史蒂芬·柯维博士的经典著作：《高效能人士的七个习惯》，这本书从个人领域的成功、公众领域的成功、自我提升和完善等方面阐述了七个习惯，本书在美国号称影响力仅次于《圣经》。\u003c/p>\u003cp> 今天我将为大家分享第264页的片段，第五个习惯知彼解已的移情聆听三步法\u003c/p>","ratings_count":2,"texts":[{"id":21579,"quote":"\u003cp> 《高效能人士的七个习惯》30周年纪念版 书本P264页\u003c/p>\u003cp> 有效的沟通-移情聆听\u003c/p>\u003cp>这个例子充分显示有效的沟通多么不易，了解他人又是多么重要。正确的沟通方式也就是移情聆听，至少包括四个阶段。\u003c/p>\u003cp>第一阶段是复述语句，这至少能使人专心聆听。\u003c/p>\u003cp> 子：“上学真是无聊透了！”\u003c/p>\u003cp>父：“你已受不了了，觉得上学太无聊。”\u003c/p>\u003cp> 第二阶段加入解释，完全用自己的词句表达，但仍用左脑的逻辑思维去理解。\u003c/p>\u003cp>父：“你不想上学了。”\u003c/p>\u003cp>第三阶段掺入个人的感觉，右脑发挥作用。此时听者所注意的已不止于言语，也开始体会对方的心情。\u003c/p>\u003cp>父：“你觉得很有挫折感。”\u003c/p>\u003cp> 第四阶段是既加以解释，又带有感情，左右脑并用。\u003c/p>\u003cp>父：“你对上学有很深的挫折感。”\u003c/p>\u003cp> 运用这四个阶段的方式沟通，不仅能了解对方，更能帮助对方认清自己，勇于表达。\u003c/p>","explains":"\u003cp>Why：\u003c/p>\u003cp> 沟通是生活中最重要的技能。但是，我们从小接受更多的是偏向读写的训练，很少有人教导我们如何去听，很多时候，我们听是为了说，为了给建议、为了“教育”，更倾向于从自己的主观意识去揣测他人言语背后的意思，误解就是这样产生的。所以 ，人与人之间的关系需要先倾听。\u003c/p>\u003cp> What：\u003c/p>\u003cp> 本拆页这个片段，一位父亲听到他的儿子说“上学真是太无聊了”时，并没有急于进行“教育”，而是站在儿子的角度，通过复述他表达的信息，理解并确认他的真实想法。而当儿子知道自己真正被理解和被倾听，双方就建立了信任安全的关系。所以通过移情聆听三步法，不仅让爸爸了解了自己的孩子，也帮助孩子认清了自己，让孩子勇于对爸爸表达自己内心真实的想法。\u003c/p>\u003cp>Where：移情聆听，以理解为目的，适用于比如在职场中同事沟通，朋友间的沟通、家庭亲密关系的沟通和亲子关系的沟通上。\u003c/p>\u003cp> How：我们来总结一下“移情聆听”的三步法\u003c/p>\u003cp> 第一步：复述——关注对方表达的内容，并复述出来\u003c/p>\u003cp> 第二步：理解——通过观察对方的情绪和肢体，尝试理解她背后的情绪和想法，用自己的语言表达出来。\u003c/p>\u003cp> 第三步：确认——通过左右脑并用，向对方确认你对他的真实想法和理解是否正确。此时，即使对方回答你理解错了也不要紧，你可以追问：“我很好奇，你的真实想法是什么？”\u003c/p>\u003cp> 为了帮助大家更好的理解这些步骤，我举个自己的亲身经历，下面是我和侄子的一段对话：\u003c/p>\u003cp>侄子：不想写作业了。\u003c/p>\u003cp>我：你已经受不了了，不想写作业了。← 复述\u003c/p>\u003cp>侄子：是\u003c/p>\u003cp>我：上学作业多，又难，所以你不想写。← 理解\u003c/p>\u003cp>侄子：是的，每天作业我都要写到11点多。\u003c/p>\u003cp>我：你觉得很辛苦，因为作业太多了。← 确认\u003c/p>\u003cp>侄子：我也想写好，可是太多了\u003c/p>\u003cp> 我：你因为作业多，有时候不会写，就有挫折感，才不想写作业的。 ← 确认\u003c/p>","interaction":"\u003cp>今天因为人数的关系，我们分成1组方便讨论。\u003c/p>\u003cp> 我们读过这个拆页，学习了移情聆听三步法，那么请大家回想一下，在刚刚过去的2月份里，在家庭中，你与孩子（或与你的爱人）、朋友及同事的沟通中，让你觉得你并没有好好的倾听过他/她的一件事？当时的你是怎么说的呢？你可以回想具体的时间，地点，人物和事情经过，请在小组内分享。\u003c/p>\u003cp> 3分钟后请一位老师再分享一下。\u003c/p>\u003cp>例：这周六在家里，看到我侄子写作业的场景\u003c/p>\u003cp>侄子：我不想写了，烦死了\u003c/p>\u003cp>我：才写多少就不想写了\u003c/p>\u003cp>侄子：我已经写了很久了\u003c/p>\u003cp>我：这不就是你应该做的吗？\u003c/p>\u003cp>其实看到他的行为和急躁的心情，我就在潜意识里开始判定他就是太懒了，不控制时间又拖延，所以我没有用到移情聆听就会导致两个人的关系很紧张。\u003c/p>\u003cp>Alice:昨天与儿子的对话，儿子接收到了一份礼物\u003c/p>\u003cp>儿子：朋友送的生日礼物，妈妈你觉得怎么样\u003c/p>\u003cp>妈妈：有点斯文\u003c/p>\u003cp>儿子：你是不是觉得不好，口气表情都很嫌气\u003c/p>\u003cp>妈妈：不是，只是觉得风格不同\u003c/p>\u003cp>在沟通当中，只是对话并没有去感受儿子的情绪和状态。\u003c/p>\u003cp> 现在请大家拿出一张白纸或便签，给大家3分钟时间，根据我们所学的移情聆听三步法，写一写你未来2周内你决定在与谁的沟通中践行使用移情聆听的规划呢？\u003c/p>\u003cp>我们在写这个规划时，记得一定要用确定的目标及行动计划，要有具体的做法，明确的时限，还要有可观测的预期结果。\u003c/p>\u003cp> 3分钟后请一位老师来分享一下。\u003c/p>\u003cp> 野人大叔：\u003c/p>\u003cp> 昨天晚上学校复读生起突破，虽已达成一致，还有相互不理解的地方，通过“移情聆听”的三步法帮助我了解以及他们双方互相了解感受，可以应用在今天这件事情上。\u003c/p>\u003cp> Alice\u003c/p>\u003cp> 对象是父母，希望了解他们的感受和需求，提升他们的幸福感\u003c/p>\u003cp> 1、日常的谈话内容抓住切入点\u003c/p>\u003cp> 2、利用“移情聆听”三步法\u003c/p>\u003cp> 3、识别他们的需求，采取行动，达成他们的心愿意\u003c/p>\u003cp> 今天的分享就到这里结束，非常感谢各位老师今天对我拆书的支持。\u003c/p>\u003cp>谢谢大家今天的聆听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1710431686000,"updated_at":1710920529000,"ria":true},{"id":17300,"topic":"如果生活让你感觉有点累，那么把”如果“换成“我可以，只要肯换角度，世界总有惊喜。","learn_goal":"","remark":"如果生活让你感觉有点累，那么把”如果“换成“我可以，只要肯换角度，世界总有惊喜。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"张静","city":"宁波市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>学习目标：\u003c/p>\u003cp>在学习完片段后，学习者在遇到难题时，学会区分影响圈和关注圈。并将一个问题拆解，区分类别（直接，间接，不可控），并找到影响圈。\u003c/p>\u003cp>分组：今天人比较少，，我们分一组。\u003c/p>\u003cp>自我介绍\u003c/p>\u003cp>首先我用三个标签简单的介绍一下我自己：\u003c/p>\u003cp>我的第一个标签是：拆书帮宁波分舵的活动组织者，你们如果需要过级可以与我链接。\u003c/p>\u003cp>第二个标签是：跨境电商店主。\u003c/p>\u003cp>第三个标签是：三年级孩子的妈妈。\u003c/p>\u003cp>图书介绍：\u003c/p>\u003cp>F:本书作者是史蒂芬·柯维，是一本成功励志，管理类的书籍，里面介绍的七个好习惯和方法，为我们带来超价值的自我提升体验。\u003c/p>\u003cp>A:豆瓣评分8.7，高居《纽约时报》最畅销书排行榜之首长达30年，总销量超过4000万册，在全球140多个国家以40种语言出版。常年稳居中国各大新华书店、当当、京东、亚马逊畅销排行榜前10名，风靡全球，影响力覆盖几亿人。\u003c/p>\u003cp>B:你有没有从早上忙到晚上，忙了一天好像什么也没做成的感觉？你有没有一直想学的一项技能，却一直挤不出时间，也不知道从哪下手？你在生活中会不会常常焦虑迷茫？这本书帮我从思维上的改变，用七个习惯，帮我我们从里到外的改变，指引我们更好的自律，更好的思考，更好的去创造价值。是一本值得放在床头，常常翻阅的&quot;人生效率手册&quot;。\u003c/p>","ratings_count":3,"texts":[{"id":21466,"quote":"\u003cp>兴关注圈与影响圈\u003c/p>\u003cp> 看一个人的时间和精力集中于哪些事物，也能大致判断他是否积极主动。每个人都有格外关注的问题，比如健康、子女、事业、工作、国债或核战争等等，这些都可以被归人“关注圈”，以区别于自己没有兴趣或不愿理会的事物。（见图3-3）\u003c/p>\u003cp>关注圈内的事物，有些可以被掌控，有些则超出个人能力范畴，前者可以被圈成一个较小的“影响圈”。（见图3-4）观察一个人的时间和精力集中于哪个圈子，就可以判断他是否积极主动。\u003c/p>\u003cp> 积极主动的人专注于“影响圈”，他们专心做自己力所能及的事，他们的能量是积极的，能够使影响圈不断扩大、扩张和成长。（见图3-5）\u003c/p>\u003cp>反之，消极被动的人则全神贯注于“关注圈”，紧盯他人弱点、环境问题以及超出个人能力范畴的事情不放，结果越来越怨天尤人，并不断为自己的消极行为寻找借口。错误的焦点产生了消极能量，再加上对力所能及的事情的忽略，就造成了影响圈日益缩小。（见图3-6）\u003c/p>\u003cp>只要我们的焦点在关注圈，就等于是允许自己受制于外界条件，自然就不会主动采取必要措施来推动积极变化。\u003c/p>\u003cp> 人与人的地位、财富、角色及人际关系不尽相同，因此在某些情况下，一个人的关注圈可能会小于影响圈。（见图3-7）这说明此人由于自身的缘故，在情感方面缺乏远见和判断力，消极而又自私，全部精力都放在关注圈内。\u003c/p>\u003cp>积极主动的人虽然更看重自己的影响力，但他们的关注圈往往不小于影响圈，这样才能有效发挥影响力。\u003c/p>\u003cp>直接控制、间接控制和无法控制\u003c/p>\u003cp>我们面对的问题可以分为三类：可直接控制的（问题与自身的行为有关），可间接控制的（问题与他人的行为有关）和无法控制的（我们无能为力的问题，例如我们的过去或现实的环境）。对于这三类问题，积极主动的人都是由影响圈着手，加以解决。\u003c/p>\u003cp>不论是能直接控制的、间接控制的还是无法控制的问题，解决的第一步都掌握在我们自己手里。我们可以改变习惯、手段和看法，而这些都属于影响圈范围。\u003c/p>","explains":"\u003cp>what：你们有没有常常会觉得生活中的事好多啊，忙的晕头转向的，也每做出什么成绩，还换来了一堆情绪上的问题，消耗自己。其实生活中的问题可以分成:可直接控制，间接控制和不可控制的。那么今天我们一起来学习如何区分这些困扰我们的问题，事件，找到我们的影响圈。\u003c/p>\u003cp>不这么做的坏处：\u003c/p>\u003cp>一：找出人们的通常做法：我们生活中会遇到很多问题，也时常被一些问题困扰，不知道从哪里做起，不知道怎么解决，感到无无能为力，就这么一直拖着。\u003c/p>\u003cp>二：通常做法有什么坏处：结果小问题拖成了大问题，问题产生问题，导致问题越来越多，生活越来越乱，越来越难。\u003c/p>\u003cp>三：举出了具体的反面例子：大概10月份的时候，我女儿有一次数学考了70分，我看到试卷第一时间就是生气，我在想，三年级的小朋友怎么能考出这个分数，那这么下去要完蛋了。我没骂她，但是我跟他说话的语气很不好，并且我用行动修理了她，不许看平板，要做校外试卷，可是我女儿也不是善茬，听到不能玩平板了，她就开始哭，她越哭，我越生气，越生气我就越越想收拾她，虽然忍住了，但是真的忍的好辛苦，我活生生的听她哭了两小时。我现在想想哪个场景还是害怕。\u003c/p>\u003cp>四：今天学习完这个片段，我想我可以这样做。\u003cstrong>（细分步骤）\u003c/strong>\u003c/p>\u003cp>第一：区分关注圈和影响圈：每个人都有格外关注的问题，比如健康，子女，事业，工作，国债，核战争等等，这些都可以被归入”关注圈“关注圈内的事物，有些可以被掌控，这一部分就是我们的”影响圈“，例如：孩子成绩好不好是我的关注圈，我怎么看待这个事情是我的影响圈。\u003c/p>\u003cp>第二：区分问题的类别：我们生活种遇到的问题可分为：直接控制的，间接控制的，不可控制的，那我就可以将问题细分一下，找到三个部分。\u003c/p>\u003cp>我直接控制的：我可以打电话问下数学老师，孩子在学校的学习情况。我可以选择用心平气和语气和孩子说：偶尔考差一次没事的，我小时候也有考砸的时候，你这次是因为试卷太难了，还是你做的时候有点粗心呢？\u003c/p>\u003cp>我间接控制的：我可以给孩子提供一些方法，比如说，看视频讲解，错题集，做试卷等。给孩子建议，让孩子多一些改进的方法可以选择。\u003c/p>\u003cp>无法控制的：天灾人祸，别人的思想行为，这些都是我们无法控制的。\u003c/p>\u003cp>在这个事件中，最终孩子的成绩考多少，我是无法控制的。\u003c/p>\u003cp>第三：关注影响圈，解决问题。\u003c/p>\u003cp>经过上面的反思：找到了我能做的部分：首先情绪上不焦虑，语气不暴燥，主动和老师了解情况，给孩子提供改进的方法，帮助孩子制定学习计划。\u003c/p>","interaction":"\u003cp>你过去的一个月有没有什么事情让你陷入关注圈，觉得无能为力的事？比如说：被老板安排加班，接到老师的投诉你可以回想一下类似事件，如果时间倒流，你重来一次，你会怎么做？\u003c/p>\u003cp>请大家花1-2分钟时间回忆一下，结合刚才学到的三个步骤，之后我邀请1-2位朋友分享一下你的经历。\u003c/p>\u003cp>学习者分享、\u003c/p>\u003cp>宁宁：拆书过级吧，一直想写稿，一直在写稿的路上，我一直拖着没有去做这个事情，导致已经过的级别也失效了。\u003c/p>\u003cp>张静：现在学习了这个片段，如果重来一次，你打算怎么做？\u003c/p>\u003cp>宁宁：我想想，第一步：区分影响圈和关注圈\u003c/p>\u003cp>这件事件中选拆页，\u003cstrong>写稿是我的影响圈。是否通过是我的关注圈。\u003c/strong>\u003c/p>\u003cp>\u003cbr>张静：然后哪些部分是你可以直接控制，间接控制的，哪些是不可控的？\u003c/p>\u003cp>宁宁：第二部分：\u003cstrong>区分类别：\u003c/strong>我能\u003cstrong>直接控制的部分\u003c/strong>就是选拆页，写稿。\u003c/p>\u003cp>\u003cstrong>间接控制的部分\u003c/strong>是约过级时间，比如要确认观察家和主持人的时间。\u003c/p>\u003cp>\u003cstrong>不可控的部分\u003c/strong>是做完这些，最终能不能通过。\u003c/p>\u003cp>张静：那你可以做什么？\u003c/p>\u003cp>宁宁：第三步：\u003cstrong>我关注我的影响圈，先选拆页，写稿，把我能做的部分做完，解决问题\u003c/strong>。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":21467,"quote":"\u003cp>关系说明：\u003c/p>\u003cp>今天两个片段，第二个片段是对第一个片段中关于“可直接控制问题”的补充，先通过聚焦影响圈改变态度，然后通过积极行为改变习惯。\u003c/p>\u003cp>学习目的：\u003c/p>\u003cp>通过所学片段，学习者遇到可间接控制的问题时，把“如果”换成“我可以”找到事件中我可以的部分，也就是影响圈的部分。\u003c/p>\u003cp>R原文片段二：\u003c/p>\u003cp>“如果”和“我可以”\u003c/p>\u003cp>一个人的关注圈与影响圈可以从他的言谈中看出端倪，与关注圈相关的语句多半带有假设性质。\u003c/p>\u003cp>“要是我的房屋贷款付清了，我就没这么烦心了。”\u003c/p>\u003cp>“如果我的老板不这么独断专行……”\u003c/p>\u003cp>“如果我学历更高……”\u003c/p>\u003cp>“如果我有更多属于自己的时间……”\u003c/p>\u003cp>而与影响圈相关的语句则多半体现了这个人的品德修养，例如“我可以更耐心、更明智、更体贴……”\u003c/p>\u003cp>把外在环境视作问题症结的想法本身就成问题，应该说是我们给了外部环境控制自己的权力，这种“由外而内”求变的思维方式就是以外在环境改变作为个人改变的先决条件。\u003c/p>\u003cp> 积极的做法应该是“由内而外”地改变，即先改变个人行为，让自己变得更充实，更具创造力，然后再去施加影响，改变环境。《旧约》里有段约瑟的故事。约瑟17岁就被兄弟卖到埃及，成为埃及法老的护卫长波提乏的奴隶。面对这样的遭遇，任何人都难免自怨自艾，并对出卖和奴役自己的人满腔怨愤，但是约瑟却能够积极处世，专心磨炼自己，不久便倍受信任，帮助主人打理家事，掌管财产。\u003c/p>\u003cp>后来他遭人诬陷，身陷囹圄达13年之久，皆因他坚持不肯出卖自己的良心。即便身处这样的困境，他积极的态度依然不改，他从自身做起，时刻想着“我可以”而不是“如果”，化悲愤为动力，没多久就掌管了整座监狱，后来又掌管了整个埃及，成为一人（法老）之下、万人之上的大人物。\u003c/p>","explains":"\u003cp>\u003cstrong>What：\u003c/strong>生活中常常会觉得如果对方怎么样怎么样就好了，如果丈夫多赚点钱就好了，如果孩子成绩好点就好了。如果房子再大点就好了，如果车子再好点就好了。你们有没有发现，这些如果都是向外求的，把期待放在外物上，这种情况就是把注意力放在了关注圈。把如果改成我可以，我自身出发，找到自己能做的，这就把关注点放在了影响圈，积极主动的人往往都会选择我可以，关注自己的影响圈。\u003c/p>\u003cp>\u003cstrong>HOW:\u003c/strong>\u003c/p>\u003cp>第一：转变思维。由内而外的改变，把”如果“换成”虽然.....但是我可以..........找到影响圈。\u003c/p>\u003cp>第二：改变行为。做我可以的部分，做计划。\u003c/p>\u003cp>第二：施加影响，改变环境。积极的想法带动积极的行为，积极主动的解决问题。\u003c/p>\u003cp>例如\u003c/p>\u003cp>原文片段的四个关于如果的问题：我们把”如果“换成”虽然.....但是我可以..........“\u003c/p>\u003cp>“虽然我的房屋贷款没有付清了，但是我可以努力学习，努力工作，提升技能，争取涨工资，减轻还贷压力。”\u003c/p>\u003cp>“虽然我的老板独断专行，但是我可以认真执行老板的决定，把自己能做的部分做到最好”\u003c/p>\u003cp>“虽然我学历不高，但是我可以通过日常的工作中多做，多学习，积极主动，积累经验，提升能力。”\u003c/p>\u003cp>“虽然我属于自己的时间不多，但是我可以学习时间管理，高效的利用属于自己的时间”\u003c/p>\u003cp>\u003cstrong>意译：\u003c/strong>\u003c/p>\u003cp>这两天特别火的董宇辉小作文事件，全网铺天盖地的言论，所有人都被骂，特别是俞敏洪，股票跌了几十个亿，大家都觉得这件事怎么做都不对，网友甚至说俞洪敏要开启他的第三次创业了。面对这样的局面，任何老板都会指责员工，甚至找临时工背锅。但是俞洪敏积极处理，快速做出应对方案：承认错误，公开道勤，开除小孙CEO职务，开直播澄清。\u003c/p>\u003cp> 可是后来网友依旧不买账啊，骂声并没有平息，股票该跌还是继续跌。即便身处这样的困境，他积极主动的态度依然不改，他从自身做起，时刻想着“我可以”而不是“如果。化危机为转机，开启第二次直播直播，邀请董宇辉参加，当着网友的面，直播中一个一个回复网友的问题，并且马上给出实际解决方案。安抚网友，安抚董宇辉，直面网友的质疑，一个个解决：给股份，为董宇辉开创新节目。稳定内部人员：带公司人员去滑雪，送最好的化学装备，通过一件一件他可以做的事，完全逆转了风向，后来各路网友黑转粉，稳定了股价，留住了董宇辉，股票也涨回来了。可以说是完美解决了这个大难题。\u003c/p>\u003cp>\u003cstrong>预防性讲解：\u003c/strong>\u003c/p>\u003cp>一：你或许会想，何必这么麻烦，这么简单的事，是人都懂。如果真的那么简单，就不会出现很多家长在辅导孩子作业的时候捶胸顿足了，也不会出现那么多抑郁症，分手，失恋，学习不好跳楼事件了。\u003c/p>\u003cp>二：也有人会说，说起来简单，做起来难。生活中的事情千丝万缕哪有这么好区分的。你说孩子挑食偏食，不爱吃饭，你很头疼，可是你可以找到你能做得到部分啊，你改善自己的厨艺，一个孩子再怎么挑食偏食，总有爱吃的东西，那就多准备爱吃的，补充蛋白质不一定事鸡蛋，也可以是牛奶。\u003c/p>","interaction":"\u003cp>A3:\u003c/p>\u003cp>那么请大家来设想一下这样一个场景，小王和男朋友因异地的关系，被男朋友提分手了，找朋友小李哭诉，请小李用今天学到的内容，向小王提问，帮小王理清事件，区分影响圈和关注圈，找到小李可以做的三个部分。用”虽然....但是我可以....“代替”如果“，找到我可以控制的部分。\u003c/p>\u003cp>给大家5-7分钟事件讨论，之后邀请两位学习者扮演小王和小李.\u003c/p>\u003cp>\u003cstrong>学习者分享：\u003c/strong>\u003c/p>\u003cp>\u003cbr>琴娜小王：我刚才有个电话。小林打来的和我分手。还说我们俩住那么远，住那么远，是今天的事情吗？\u003c/p>\u003cp>亚琴小李：我看你很愤怒，也很火，就是。那你怎么想的呀？\u003cbr>琴娜小王：我不想分啊，这么多年了，十年，人生能有几个十年？你跟你们家那位早就结婚了。\u003cbr>还有两个娃了呢，一个十年跟那两个人走了十年，我离开他，我能找谁，你说我能找谁？\u003cbr>如如果如果我当时听我妈的。看上他啥呀，人长得又矮又没钱。事业又没有发展前景，我看\u003cbr>上他啥对啊，\u003cbr>亚琴小王：这么不好就分呗。\u003c/p>\u003cp>琴娜：可是已经十年不投入了呀。你现在让我跟他分。我能找谁？你说我能找谁？\u003cbr>亚琴小李：你是想要怎么样？\u003c/p>\u003cp>琴娜小王：我不想分啊，我跟你说了呀，十年了。\u003cbr>亚琴小李：那你觉得哪部分你是可以做的？他什么态度，你可能你觉得你们刚才那个电话里面，他就想分\u003cbr>手，没有别的说法？\u003c/p>\u003cp>琴娜小王：我没有跟他吵架，我不需要和好，但是我不想跟他分手。\u003c/p>\u003cp>亚琴小李：就不分手吧，继续哈，哪部分是你能做的？\u003cbr>你可能关注刚才关注他。以前做的怎么样啊？现在怎么这样子？这个对你们不不分手有帮助\u003cbr>吗？那还有哪些是对你是有帮助的，你可以能掌控你能做的？\u003c/p>\u003cp>琴娜小王：我现在不要那么激动哦。啊，我太激动了，我觉得我太激动，\u003cbr>我有点失态了。所以我得控制一下自己，\u003cstrong>去管理一下，处理一下自己的情绪。\u003c/strong>\u003cbr>亚琴小李：嗯，非常好呃，\u003cstrong>这个是你能控制的是吗\u003c/strong>？\u003c/p>\u003cp>琴娜小李：嗯，\u003c/p>\u003cp>亚琴小王：特别好，还有吗？\u003c/p>\u003cp>琴娜小王：我觉得他也没那么好。如果他提出分手，我觉得也不是不能考虑，你说是吧，小林？可以理性的去考虑一下这段感\u003cbr>情，\u003cstrong>（控制自己的想法）\u003c/strong>\u003cbr>而且而且这么多年我们就一直是同事嘛，我也成长蛮多的，你觉得吗？也许他配不上我了，\u003cbr>对吧？\u003cbr>一个月咱们咱们才见一次面，也没没也没变帅，也没没有变，有钱都是那个老样子，我也不\u003cbr>知道他。\u003cbr>在江苏那边干嘛？对吧？对这个十年哈就人都会有变化，也要看看现在可能他也是这么想的\u003c/p>\u003cp>\u003cbr>状态，可能\u003cstrong>重新来评估一下我们的关系\u003c/strong>\u003c/p>\u003cp>\u003cbr>亚琴小李：还有吗？还有什么可以做的？还有可以做的，\u003c/p>\u003cp>琴娜小王：\u003cstrong>我觉得正好是一个机会啊，我来重新梳理一\u003c/strong>\u003cbr>\u003cstrong>下你们的关系哈。\u003c/strong>\u003cbr>亚琴小李：嗯，还有吗？\u003c/p>\u003cp>琴娜小王：\u003cstrong>也许我可以留意一下我们公司的其他同事，男同事嗯，\u003c/strong>\u003c/p>\u003cp>然后呢？\u003cbr>\u003cbr>琴娜小王：\u003cstrong>你了解我的对吧？如果如果他执意要分，反正我机会给到他，今天晚\u003c/strong>\u003cbr>\u003cstrong>上\u003c/strong> \u003cstrong>12\u003c/strong> \u003cstrong>点他执意要分第二个电话没打来的话，那就分呗，小李，你一定会支持我的，对吗？\u003c/strong>\u003c/p>\u003cp>亚琴小李：嗯，\u003cbr>琴娜小王：就是现在那你做什么选择我都支持你陪着我，就不怕我我我就给到他今天晚上 12 点。\u003c/p>\u003cp>亚琴小李：如果还有可能呢，大家坐下来聊一聊看看，因为两个人的事情，\u003cbr>\u003cbr>\u003cbr>琴娜小王：反正 12 点嘛。他如果电话打来，\u003cbr>咱们就沟通后续的沟通，，那如果大家有的聊就聊，如果没得聊的话\u003cstrong>，就明天开始。我要过我的新生活了哇\u003c/strong>，\u003c/p>\u003cp>亚琴小李：这个很好。\u003c/p>\u003cp>琴娜小王：哈哈哈。\u003c/p>\u003cp>A2:\u003c/p>\u003cp>请大家想一想，未来有什么想做但是有难度的，比如你想学习一门语言或者技能？想和家人或者朋友拉近关系，解开误会？学完这个方法，将问题拆分，找到我可以的部分，能在未来的一周或者一个月，把事情解决掉的？\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>亚琴：就是过级吧，就是有有点拖着，你看 2-2 都已经写完一\u003cbr>个月一个多月了吧，\u003cbr>然后都没空。然后2-2也放了很久了。\u003c/p>\u003cp>这部分自己能直接控制的：一个呢是\u003cstrong>自己的心态调整\u003c/strong>啊，\u003cstrong>自己的\u003cbr>目标这一部分\u003c/strong>吧，\u003cbr>为什么要做这个事儿，这一部分？也是自己可以控制的，包括的是可以怎么去把那个拆步骤去拆解，\u003cbr>包括技能点技能点就把一波波给拆解开来哈，这样会感觉会更轻松一点，更有行动力哈。\u003c/p>\u003cp>再有呢就是。关于找这个师父，师父什么时候修改啊，那这个是属于\u003cstrong>间接控制\u003c/strong>的。\u003c/p>\u003cp>嗯，还有能不能过的，这个是属于这个\u003cstrong>不可控的\u003c/strong>。\u003cbr>\u003c/p>\u003cp>\u003cstrong>结束语：\u003c/strong>\u003c/p>\u003cp>一件事情的发生，如果把他当成一个整体，或许会觉得很难，但是我们可以把他拆分一下，找到事件中我可以的部分。就像硬币也有两面。相信无论多难的事，里面总有一部分是我可以做的。\u003c/p>\u003cp>希望大家在今后的生活中，关注影响圈，积极主动的去生活，让生活变得越来越美好，越来越轻松。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1706859486000,"updated_at":1710083063000,"ria":true},{"id":17025,"topic":"区分关注圈和影响圈&扩大影响圈","learn_goal":"","remark":"遇到问题时，通过分析问题，让注意力聚焦在自己可以掌控的事情上，同时能够通过改变自己的语言，来影响自己的思维和行动，逐渐养成积极主动的习惯。","level":"TF3-3","duration":80,"status":29,"type":0,"chaishujia":{"username":"ELIAUK","city":"镇江市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp> 逐字稿：\u003cbr> \u003cstrong>一、自我介绍【1分钟】\u003c/strong>\u003cbr> 各位伙伴晚上好，我是今天的拆书家赵丽英。用三个标签介绍一下我自己。\u003cbr> 首先，我是一名基督徒\u003cbr> 第二，我是一名全职妈妈。\u003cbr> 第三，我是一名在升级打怪的拆书家\u003c/p>\u003cp> 【场景】\u003cbr> 上个礼拜一。在儿子的班级群里看到有20多位家长在请假。请假的原因是自己的孩子被诊断出甲流和支原体感染。看到这些信息的时候，心中就非常的焦虑。那就跟儿子说:“怎么突然有这么多孩子被感染？学校不做防护措施吗？比如有感冒的孩子不准到学校。既然有这么多孩子被感染，你肯定也逃不掉的。甲流比新冠还要难过，病程还要长。抗生素用的量也很大。这身子本来就柔弱，该怎么办？”当时非常的焦虑。\u003cbr> 【提问】\u003cbr> 不知道大家在工作或者生活当中遇到一些使自己很焦虑事的时候，是怎么处理的？是逃避？是彷徨？还是因着这些事情让你焦虑不已，寝食难安？\u003cbr> \u003cstrong>【影响】\u003c/strong>\u003cbr> 在问题面前，越是把主要的精力和时间放在自己不能掌控的事上。越是焦虑和恐惧产生不了动力，结果是不但对事情没有推进作用，反而让自己更加神经质，总是害怕这个，担忧那个，猜测那个，严重影响了生活、工作和心情。\u003cbr> \u003cstrong>【解决】\u003c/strong>\u003cbr> 今天要跟大家分享的这本书《高效能人士的七个习惯》。就是要告诉我们遇到事情如何调整自己的思维和行动，让自己聚焦到可以掌控的事情上。减少焦虑和恐惧，推进事情向前发展。进而改变我们情绪更好地投入到的生活和工作中。\u003cbr> \u003cstrong>【学习总目标】\u003c/strong>\u003cbr> 通过学习第一个拆页后，遇到焦虑的问题时，能够辨识（行动）出在这个问题里，哪些属于影响圈？哪些属于关注圈？（界定）并且能够运用聚焦影响圈四步法（澄清）来减少焦虑，推进事情发展。（界定）\u003cbr> 通过跟随我完成第二个拆页学习后，被动的人能够运用（运用）语言改变三步法（澄清）。通过改变自己的语言来影响自己的思维，改变自己的行为。让自己积极主动的行动起来。（界定）两个拆页为并列关系。\u003cbr> \u003cstrong>【分组】\u003c/strong>\u003cbr> 为了充分讨论，我们先分一下组。从我左手边起，丁舵，樊老师，丹丹老师为一组。金莲老师，陈芳老师，还有蒋老师。为一组\u003cbr> \u003cstrong>【过渡语】\u003c/strong>\u003cbr> 下面请大家阅读第一个片段，读完的伙伴请举手向我示意一下。时间 1分钟，现在开始。 \u003c/p>","ratings_count":4,"texts":[{"id":21167,"quote":"\u003cp>关注圈与影响圈\u003c/p>\u003cp>看一个人的时间和精力集中于哪些事物，也能大致判断他是否积极主动。每个人都有格外关注的问题，比如健康、子女、事业、工作、国债或核战争等等，这些都可以被归入“关注圈”（Circle ofConcern），以区别于自己没有兴趣或不愿理会的事物。 \u003c/p>\u003cp>关注圈内的事物，有些可以被掌控，有些则超出个人能力范围，前者可以被圈成一个较小的“影响圈”。观察一个人的时间和精力集中于哪个圈，就可以判断他是否积极主动。 \u003c/p>\u003cp>积极主动的人专注于“影响圈”，他们专心做自己力所能及的事，他们的能量是积极的，能够使影响圈不断扩大。 \u003c/p>\u003cp>反之，消极被动的人则全神贯注于“关注圈”，紧盯他人弱点、环境问题以超出个人能力范围的事不放，结果越来越怨天尤人，一味把自己当做受害者，并不断为自己的消极行为寻找借口。错误的焦点产生了消极能量，再加上对力所能及之事的忽略。就造成了影响圈日益缩小。 \u003c/p>\u003cp>只要我们的焦点在关注圈，就等于是允许自己受制于外界条件，自然就不会主动采取必要措施来推动积极变化。\u003c/p>","explains":"\u003cp>\u003cbr> 好的，感谢各位伙伴给我的反馈。我看到大多数伙伴已经读完了。没有读完也不要紧，我会详细讲解。\u003cbr> \u003cbr> \u003cstrong>【互动提问】\u003c/strong>\u003cbr> 1. 我先问一下各位伙伴啊，文片段中提到了两个圈儿，分别是什么？\u003cbr> 回答:关注圈和影响圈\u003cbr> 2. 那什么是关注圈？什么是影响圈呢？\u003cbr> 自己能掌控的是和自己不能掌控的事。\u003cbr> 对的，大家阅读原文都非常仔细认真哦。\u003cbr> 【What】\u003cbr> 在这个片段里，作者向我们介绍了两个圈。一个是关注圈，一个是影响圈。\u003cbr> 能够通过自己努力去影响和掌控的事。比如自己的习惯，做事情的方法和看法等称之为影响圈。\u003cbr> 反之，有些事情超出个人能力范围是我们无法改变的，比如外部的环境，他人的做法，我们成为关注圈。\u003cbr> 【\u003cstrong>概念讲解，对比强化\u003c/strong>】\u003cbr> 下面我举几个例子，大家来判断是属于关注圈还是影响圈\u003cbr> 1我下个月要进行3-3的过级。我很担心自己考核不通过非常焦虑。（关注圈 下个月之后的事情属于未知的事情，但又是无法改变的。）\u003cbr> 2我坚持读书，专注个人成长。（影响圈 自身成长是可以通过个人努力改变的。）\u003cbr> 3我总是沉迷于过去的错误，不停的责备自己。（关注圈 过去的事情已经发生没有办法改变。）\u003cbr> 4儿子这次考试不理想。事后他反思哪个知识点掌握的不牢，反复的掌握思考。（影响圈 事后查找原因。予以补足。）\u003cbr> 同样的害怕儿子被传染，非常的焦虑。（关注圈，属于外部环境。）\u003cbr> \u003cstrong>【Why】\u003c/strong>\u003cbr> 为什么我们要学习这个方法？工作、生话因我们没有认清自己在很多事情中的界定，经常把别人的事扛在自己的肩上，成为重担。而这些事情是我们无能为力的，这种情况下，我们整个人就会陷入负面情绪当中，身心俱疲。我们运用聚焦影响圈的方法将事情分类，可以找出相对应解决的办法。就会让我们从中获取成就感，是我们面对困难时更加正向积极。不然身心俱疲的状况仍然无法好转。\u003cbr> \u003cstrong>【How】\u003c/strong>\u003cbr> 那么，如何通过聚焦影响圈来界定事情吗？我结合书里的介绍总结出四个步骤。\u003cbr> \u003cstrong>1.思维转换\u003c/strong> \u003cstrong>遇到焦虑，恐惧等问题是可以问自己一个问题，除了我不能控制的事情，还有什么是我可以做的，是否还有更多的选择？\u003c/strong>\u003cbr> \u003cstrong>2.问题分类\u003c/strong> \u003cstrong>拿出一张白纸，分别画上两个圈。分别标上影响圈和关注圈。在两个圈内列出自己可控的事情和不可控的事情。\u003c/strong>\u003cbr> \u003cstrong>3接纳关注圈\u003c/strong> 对自己无能为力的事学会平静的接纳。比如自然规律，社会环境等。\u003cbr> \u003cstrong>4.扩大影响圈\u003c/strong> 需要你专注于影响圈，在自己力所能及的事情上开始做事。让自己掌控的事情越来越多，从而持续的向前推进事情。\u003cbr> \u003cstrong>【举例】\u003c/strong>回到刚才的场景中：\u003cbr> 我\u003cstrong>首先\u003c/strong>进行思维转换。需要询问自己，在当下流行病毒盛行的时候，还有什么是我能做的？\u003cbr> \u003cstrong>第二步:\u003c/strong>在两个圈中列出。我能掌控的事和我不能撑控的事。比如给他多补充蛋白质。和他一起锻炼身体。生活中加强他防护意识。是在我的影响圈。学校是否采取防护措施，在学校孩子是否合理使用口罩，是在我的关注圈。\u003cbr> \u003cstrong>第三步:\u003c/strong>接纳关注圈 也就是对其他孩子是否转阴之后入校？孩子在学校的防护措施是否到位？大环境当中病毒的传播保持接纳。\u003cbr> \u003cstrong>第四步：\u003c/strong>扩大影响圈。积极改变我能掌控的部分如下。饮食中提高蛋白质的摄入量。晚饭后和孩子一起保跑步提高身体素质。孩子在家时提醒他的洗手频率和出门时给到他戴口罩的提醒。\u003cbr> \u003cstrong>【Where】\u003c/strong>\u003cbr> 这个方法适用于需要发挥积极主动性去破局的问题。不适用于简单明了的状况。\u003cbr> 【\u003cstrong>预防意义\u003c/strong>】\u003cbr> 也许有的小伙伴儿会说我聚焦影响圈，也花费了好多的精力和时间，但是结果依然是不尽人意，我该怎么办呢？一个问题里既会有你能掌控的部分，也有你不能掌控的。拼尽全力是你的影响圈，但结果往往有很多你不能掌控的因素。它是属于我们的关注圈，我们只能微微一笑，坦然接受。\u003cbr> \u003c/p>","interaction":"\u003cp>相信大家已经对关注圈与影响圈的概念有了清晰的了解，为了更好的掌握这个知识点。接下来，请大家写一个小剧本。想象一下在未来的一周或半个月内可能发生的一次对话。\u003c/p>\u003cp>比如：1.孩子向你倾诉因即将到来的学科测验而忐忑不安，愁的连最爱的零食也不想吃了；2.好友告诉你她最近因为年末的述职报告如何写的出彩而焦虑难眠甚至不想参加任何聚会只想闭门写报告；。。。。。。\u003c/p>\u003cp>对话的部分要用到今天的聚焦影响圈四步法，写明这个剧本发生的时间、地点，人物，经过，结果等关键词。自己先预演一遍，等到真的实施时，就会更加得心应手了。\u003c/p>\u003cp>设计的时候，只要自己思考就可以了。设计完之后，可以在小组内相互分享一下。时间 3 分钟。3 分钟后我请一位伙伴跟大家分享了下。分享的时候，只要分享自己设想的案例，一个人预演一下设想的对话就可以了。\u003c/p>\u003cp>3分钟后邀请丹丹老师分享如下 \u003c/p>\u003cp>未来一周内孩子考试不及格\u003c/p>\u003cp>妈妈：先冷静，不能火冒。（思维转换）\u003c/p>\u003cp>说:儿子，虽然这次考的成绩不理想我们接纳。（接纳关注圈）我们可以来分析一下不及格的原因，看看那些是妈妈可以帮助你的，那些是你需要努力的。（事情分类）妈妈可以帮你查漏补缺，还可以给你报补习班。你要认真的学习，并配合安排。（各自的影响圈）\u003c/p>\u003cp>儿子：好的\u003c/p>\u003cp>妈妈：那下面我们先制定一下工作计划吧！今天就按着计划执行。（扩大影响圈）\u003c/p>\u003cp>谢谢丹丹老师的分享！在丹丹老师的分享当中恰当的运用了聚焦影响圈四步法。首先转换了思维，接着对不可控的事情选择接纳，分别出和儿子各自的影响圈。并且立刻采取行动。丹丹老师应用的非常棒！相信丹丹老师在以后的实际场景中也会应用的得心应手。掌声送给丹丹老师！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":21168,"quote":"\u003cp>【总结过渡】\u003c/p>\u003cp>刚才我们学习什么是关注圈影响圈以及如何聚焦影响圈去积极主动的行动。在本书中告诉我们，思维意识决定行为和态度。而一个人的行为和态度通常可以从他的语言模式中鉴定出来。消极被动的语言和积极主动的语言到底有什么区别呢？既然语言是思维的表现，又该如何通过改变一个人的语言，来改变一个人的行动呢？下面请大家跟随我一起学习第二个片段识别自己的语言。\u003c/p>\u003cp>【学习目标2】希望跟随我完成下面第二个片段学习后消极被动的人能够运用（行为）语言改变三步法，（澄清）通过改变自己的语言来影响自己的思维，改变自己的行为，让自己积极主动的行动起来。（界定）\u003c/p>\u003cp>【量表自测】\u003c/p>\u003cp>先在开始之前先请大家做一个简单的测试。这个测试能够帮助你快速的鉴定你是一个积极主动的人，还是消极被动的人。请仔细阅读下面表格中的每一个问题，然后根据自己的实际情况，按照1~6分的标准给自己打分。一分代表完全不符合，六分代表完全符合。打分完成后，将以上五项自测分数合计加总。分数的小伙伴儿可以举手示意。1分钟之后我们将解读这个自测量表。\u003c/p>\u003cp>【解释自测题】\u003c/p>\u003cp>好，我看到大家都已经做完了，请大家对照自己的分数，听我解读这个自测表。\u003c/p>\u003cp>得分在15分以下的小伙伴儿请举手，厉害啦，说明你们三位老师都是一个积极主动的人。在遇到困难时都会想办法去解决，而不是被困难吓倒，或者坐以待毙。\u003c/p>\u003cp> 得分在15~20分之间的小伙伴请举手。\u003cbr> 说明老师经常具备了积极主动的思维，但是行动上偶尔会消极被动，希望在完成今天学习后可以增加你的行动力。\u003cbr> 得分在25分以上的小伙伴儿请举手。\u003c/p>\u003cp>哦，没有哦，这说明咱们拆书帮的各位老师都是积极主动的人，为我们龙城分舵点赞。\u003cbr> 【原文片段】\u003cbr> 下面请大家阅读片段二。读完的伙伴请举手向我示意一下。时间 1分钟，现在开始。\u003cbr> 聆听自己的语言。\u003c/p>\u003cp>思维意识会决定行为和态度，如果有意识仔细检查，我们会发现这些都会在我们的人格地图上体现出来。比如我们的语言就是我们是否积极处事的真实写照。消极被动的人语言中往往终会暴露出推卸责任的意图，\u003c/p>\u003cp>例如“我就是这样做事的。”（我天生这样，这辈子改不掉了。）\u003c/p>\u003cp>“他把我气疯了。”（责任不在我，是外界因素控制了我的情绪。）\u003c/p>\u003cp>“我根本没时间做。”（又是外界因素——时间控制了我。）\u003c/p>\u003cp>“要是我妻子能更耐心一点就好了。”（别人的行为会影响我的效能。）\u003c/p>\u003cp>“我只能这样做。”（意味这受迫于环境或他人）\u003c/p>","explains":"\u003cp>好的，感谢各位伙伴给我的反馈。我看到大多数伙伴已经读完了。没有读完也不要紧，我会详细讲解。\u003c/p>\u003cp>我现在问大家几个问题。 \u003cbr> 1根据原文片段，我们知道一个人是否在积极处事，是可以通过什么体现出来？对的语言。大家回答的非常正确。\u003cbr> 2被动的人语言中会暴露出什么意图？ 推卸责任的意图。 大家回答，非常棒哦！\u003cbr> \u003cstrong>【What】\u003c/strong>\u003cbr> 在这个片段里，主要讲解了两种完全不同的语言模式。一个是消极被动的语言，另一个是积极主动的语言。消极被动的人语言中常常带有推卸责任的意图，把原因归结于他人和外在环境。积极主动的人在遇到困难时会说我能，我可以，然后从我做起去行动。\u003cbr> \u003cstrong>【Why】\u003c/strong>\u003cbr> 要想改变一个人，最根本的是改变这个人的思维，而语言是思维的外衣。如果没有刻意去调整自己的语言，那会使我们陷入更加负面的状况当中。如果刻意的捕捉自己平时的语言，把消极被动的语言改为积极主动的语言。然后“”做我所说”付出行动。就会变成一个积极主动的人。′\u003cbr> \u003cstrong>【How】听起来这个非常的不错。那么究竟该怎么做呢？我概括出三个步骤。\u003c/strong>\u003cbr> \u003cstrong>1觉察:\u003c/strong>要觉察到自己平时话语中的消极语言。比如说我没有办法，我不得不这么做。我就这样改不了。要是怎么样就好了。”这一类推卸责任的话，\u003cbr> \u003cstrong>2调整:\u003c/strong>把消极的语言换成积极主动的语言，比如说“”我可以，我选择，我能够。我尝试换一种方法去改变，当面对……情况的时候，我有更多的选择。” 等这里具有感\u003cu>控感\u003c/u>，灵活，有弹性的话，\u003cbr> \u003cstrong>3行动:\u003c/strong>也就是按照自己的语言模式持续行动起来，真正的让改变发生。\u003cbr> 【\u003cstrong>举例子\u003c/strong>】在开始准备3-3逐字稿的时候，我感觉超出了我自己能力范围很多。当遇到难点的时候，就会抱怨自己为什么以前没有好好的学习，提升自己的能力。当自己陷在消极里边的时候，就不愿意去启动。导致拖延。到最后的一段时间，家里又发生了很多事情。就会想到把过级的日期往后改。甚至当老师们询问我的时候，我还找到各样的借口作为托词。比如说“是因为我的能力有问题。是家里发生事情导致的。按照原计划过去肯定是不行的。”\u003cbr> 后来我察觉到:原来我只是陷入了消极被动的行为模式中。（第一步）这是我思维上发生了变化。不再是给自己找借口，而是给自己打气。我是有办法的。比如我的能力是不足，但我可以去学习以前老师过级的资料。时间是很紧张，白天没有时间，我可以利用晚上家人睡觉之后来准备。从那天开始，我就不断对自己说。你可以的。你还有很多的时间。加油加油！（第二步）于是我就上到拆书帮的官网，查找相关资料。阅读拆书手册。寻求其他老师的帮助。每天晚上利用孩子睡觉之后，安排自己晚睡两个小时。（第三步）\u003cbr> 【\u003cstrong>预防异议\u003c/strong>】\u003cbr> 有的小伙伴可能会说这种思维和行动转换并非人人都能做得到。毕竟不负责任是人的天性。让他人或外界条件做题最严更容易的多，是的道理没有错，但是人都应该对自己的人生负责。我们应该通过自己的努力调整改变事情，而不是坐等好运或噩运的降临。\u003cbr> \u003cstrong>【Where】\u003c/strong>\u003cbr> \u003cstrong>这个方法适用于我们遇到一些问题，需要跳出关注圈来解决时。而对于日常关注圈的事情，比如社会新闻股票涨跌自然灾害还是正常关注就好。\u003c/strong>\u003c/p>","interaction":"\u003cp>关于讲解部分，我们就先到这里，我想问问大家对刚才的内容有什么疑问或者不清楚的地方？好的没有是吗？我们还沿用刚才的分组，继续讨论。另外，我们请每组推选一位组长吧，麻烦组长帮忙协调下，让小组内的每位伙伴都能充分发言。\u003c/p>\u003cp>微行动学习步骤1\u003c/p>\u003cp>\u003cstrong>【拆书家提问】\u003c/strong>\u003c/p>\u003cp>好的，我看到各组都已经推选好组长了。一组丹丹老师为组长 二组金莲老师为组长那么，请大家回到我这里。\u003c/p>\u003cp>提问:通过上面两个片段的学习，大家了解到了如何聚焦影响圈并且通过改变自己的语言来改变自己的思维。进而改变行为，那么我想请问大家生活工作当中是否遇到过让自己经常消极被动的情景。比如说工作中一直很努力。但始终得不到老板的肯定，或者尽管上了婚姻辅导课，但是与丈夫一直相处不好。又或者孩子的学习，无论你怎样辅导都没有进展等等。\u003c/p>\u003cp>请大家回想一下自己的故事。然后每个人都在小组内分享一下。请组长帮忙关注下，务必让每位伙伴都分享一下自己的故事，每人 2 分钟左右。好的，现在开始。\u003c/p>\u003cp>【\u003cstrong>8 分钟后】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【邀请小组给案例归类，总结出性质相同的问题】\u003c/strong>\u003c/p>\u003cp>请问各位组长，您组内是不是每位伙伴都分享了自己的案例？\u003c/p>\u003cp>答：都分享了\u003c/p>\u003cp>好的，谢谢组长。\u003c/p>\u003cp>其实，不同的人发生的不同故事，可能是同一个性质的问题。下面请大家在小组里分析一下，各自的案例是不是有相似性？让各位伙伴困扰的问题，有没有相似性？\u003c/p>\u003cp>请概括出大家的案例里反映出的是哪些问题？然后用一两句话阐述一下这些问题。时间 2 分钟，现在开始。\u003c/p>\u003cp>请问各位组长，你们概况出不同案例反应出的相同问题了吗？\u003c/p>\u003cp>组长：概况出来了。\u003c/p>\u003cp>一组：因别人影响自己 二组：想改变孩子和老公\u003c/p>\u003cp>【明确问题】\u003c/p>\u003cp>\u003cu>现在大家了解了不同的问题。我们来选择一个最有普遍性的问题来详细讨论一下。\u003c/u>\u003c/p>\u003cp>好的，大家决定讨论“想改变孩子和老公”这个问题。陈芳老师，那就请您当我们这次讨论的案主吧。我先向您介绍一下，作为案主，我想请您帮忙做这样三件事：\u003c/p>\u003cp>1. 第一件事：阐述案例。给您的时间是 3 分钟，请您尽量详细地介绍一下。\u003c/p>\u003cp>2. 第二件事：在您介绍完毕后，接受大家的提问，并做详细回答。\u003c/p>\u003cp>3. 第三件事：最后我们给出一些解决方案，看能否对您的问题有所帮助。\u003c/p>\u003cp>好的，就是这三件事。第一，详细陈述案例；第二，澄清大家的疑问；第三，评估大家给出的建议。您看可以吗？\u003c/p>\u003cp>好的，那现在就有 3 分钟时间给您。请大家欢迎。那我们请陈芳老师给我们分享一下，掌声欢迎！ \u003c/p>\u003cp>陈芳老师的分享如下:\u003c/p>\u003cp>我陈芳老师的大女儿，今年13岁了。但他每一次吃饭的时候都会把他饭桌甚至饭桌底下衣服上吃的一塌糊涂。每次看到这种情景，我就非常的火冒。想去纠正他。可是旁边的老公总是阻止我。我很困惑，妹妹做事干净利索，为什么她就这样呢？就是在外边吃饭的时候，她会把可乐菜拌到一起吃。\u003c/p>\u003cp>\u003cstrong>【追问本质】\u003c/strong>\u003c/p>\u003cp>感谢 陈芳老师的分享。刚才提到了关于你女儿吃饭时，出现的状况想去纠正她老是被老公拦住的案例。\u003c/p>\u003cp>好的，各位伙伴，听完了 陈芳老师的介绍，各位伙伴是不是还有些细节想了解？有没有一些疑问想请 陈芳 老师进一步说明一下？\u003c/p>\u003cp>请大家向 陈芳提问。请 陈芳老师准备接收问题啊。大家提问时，请注意以下几点：\u003c/p>\u003cp>1. 请提出开放性的问题，这样才能收集到更多信息。\u003c/p>\u003cp>2. 请不要在这个环节给出建议。这个环节，我们尽量收集更多信息，更全面、深入地了解情况。接下来会有给出建议的环节。提问开始。\u003c/p>\u003cp>樊老师 :孩子从什么时候开始这样吃饭的？\u003c/p>\u003cp>陈芳老师:因为老公是徐州人，吃饭细节不注意。\u003c/p>\u003cp>丹丹老师:你心里是怪老公，还是怪孩子？\u003c/p>\u003cp>陈芳老师:老公对孩子的管教很松弛，而我比较主张严管。\u003c/p>\u003cp>金莲老师:有做的好的时候吗？做好的时候，你是如何跟孩子沟通的？\u003c/p>\u003cp>陈芳老师:肯定是有做的好的时候。做好时没有跟他沟通，认为是正常。\u003c/p>\u003cp>蒋老师:当孩子做的不好的时候，你当时的表现如何？\u003c/p>\u003cp>陈芳老师:我会有动作，言语上的提示，比如敲桌子指他的衣服。面部是带有怒气的。\u003c/p>\u003cp>丹丹老师:为什么特别在意这件事情？\u003c/p>\u003cp>陈芳老师:和小宝形成鲜明对比。拿他跟小宝比较。\u003c/p>\u003cp>丁舵:你是否有正向的给到孩子引导？是否让他有一定的奖惩。\u003c/p>\u003cp>陈芳老师:没有 给到他正向引导。出现这种状况之后也没有后果。\u003c/p>\u003cp>\u003cstrong>【明确本质】\u003c/strong>\u003c/p>\u003cp>好的，感谢各位伙伴的提问，感谢 陈芳老师的真诚回答。\u003c/p>\u003cp>我想，现在大家已经了解到了更全面的情况。现在，我请各位回到各自的小组里，在小组里讨论一下，陈芳老师刚才介绍的情况，原因有哪些？其中最根本的原因是什么？\u003c/p>\u003cp>一会儿我请小组内派出一名代表，跟大家分享一下组内讨论的情况。\u003c/p>\u003cp>【邀请分享】\u003c/p>\u003cp>请小组代表跟我们所有人分享一下你们讨论的成果。\u003c/p>\u003cp>二组的金莲老师: 1跟二宝有比较 2过分关注小孩子的这个方面。3跟小孩子的性格有关系。4妈妈的动作给到孩子负面的影响。根本问题是妈妈的关注圈。\u003c/p>\u003cp>一组丹丹老师表示，他们分析的问题根本与二组相同。\u003c/p>\u003cp>【目标设定】\u003c/p>\u003cp>大家已经讨论出一些原因，也明确了最根本的原因。那么大家觉得这个问题解决到什么程度是陈芳老师能接受的，也就是说咱们解决这个问题的目标是什么？\u003c/p>\u003cp>陈芳:立竿见影，立刻实施。\u003c/p>\u003cp>老师们对其的目标是什么？\u003c/p>\u003cp>答:陈芳老师不再为此而焦虑。\u003c/p>\u003cp>【方案共创】\u003c/p>\u003cp>现在请大家回到小组里，针对刚才讨论的情况。总结出可以达到目标的具体解决方案。时间为5分钟。一会儿我请小组代表给大家分享。\u003c/p>\u003cp>【方案分享】\u003c/p>\u003cp>一组樊老师: \u003c/p>\u003cp>1与老公达成共识。\u003c/p>\u003cp>2制定吃饭规则。\u003c/p>\u003cp>3与孩子说明制定原则的原因。\u003c/p>\u003cp>4设置奖惩\u003c/p>\u003cp>二组认同一组的解决方案。\u003c/p>\u003cp>好的，感谢樊老师的精彩分享。\u003c/p>\u003cp>生活不是考试，没有标准答案，只有精益求精，适用最好。\u003c/p>\u003cp>\u003cstrong>【询问案主】\u003c/strong>\u003c/p>\u003cp>那么，请问案主陈芳老师，您作为这个问题最典型案例的代表，接收到两个小组提出的解决方案，以及结合刚才的讨论情况，您有什么感受？答:非常不错。\u003c/p>\u003cp>那么，您觉得大家提出的建议，会对解决您的问题有所帮助吗？答:有帮忙。特别是蒋老师给到我很大的提醒，就是我要先进行思维上的改变。要先去跟老公达成共识。\u003c/p>\u003cp> 好的，感谢案主陈芳老师，感谢各位伙伴的积极参与。在大家的帮助下，咱们共同学习、共同解决了一个比较有好的普遍性的问题。请大家给自己的积极参与鼓掌！\u003c/p>\u003cp> \u003cstrong>【A2】催化应用【3 分钟】\u003c/strong>\u003cbr> 好的，今天我要分享的方法，都已经介绍完了。咱们也讨论解决了 陈芳老问题。\u003cbr> 有句老话是说教是最好的学，为了让大家更好的掌握今天的内容，我给大家布置一个小作业。回去在一周内找身边的小伙伴儿分享一下语言改变三步法。跟他聊一聊如何通过改变一个人的语言来改变一个人的行为。想想有哪些要点可以分享，你分享的要点越多，你掌握的内容就越牢。完成作业的小伙伴儿可以在11号之前把作业微信私发给我。\u003c/p>\u003cp>某老师的分享\u003c/p>\u003cp>礼拜一傍晚去接女儿放学。明显感觉到女儿的心情不好。于是询问女儿发生了什么事情。\u003c/p>\u003cp>妈:丫头今天发生什么事情了吗？\u003c/p>\u003cp>女:同学差别对待我，不帮助我反而去帮助别人。\u003c/p>\u003cp>妈:今天妈妈先教你一个魔法语言改变法，识别一下自己好不好？\u003c/p>\u003cp>女:可以听听。\u003c/p>\u003cp>妈:以前妈妈是不是教过你识别影响圈和关注圈呀？\u003c/p>\u003cp>女:对的。\u003c/p>\u003cp>妈:第一步先察觉自己的语言，是否在关注圈？就是是否把一切的责任都推给对方？\u003c/p>\u003cp>第二步，要调整自己的语言。尽管他不帮助我，我还能有什么办法达到最终的目标。第三步根据自己想到的办法，积极去行动。\u003c/p>\u003cp>你现在就尝试着用妈妈刚才跟你说的方法来重过一下你说的那件事情。\u003c/p>\u003cp>女:好的\u003c/p>\u003cp>\u003cstrong>总结【1 分钟】\u003c/strong>\u003cbr> 让我们回顾一下今天的内容，今天我们围绕着习惯一积极主动讲了关注圈与影响圈。分享了语言改变三步法，通过改变一个人的语言来改变一个人的行为。我相信只要你刻意的运用今天的方法，你的生活将发生不可思议的变化。\u003cbr> 非常感谢大家一个小时的积极参与与陪伴，今天我的分享到此结束，谢谢大家！\u003cbr> \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1702346257000,"updated_at":1702972375000,"ria":true},{"id":16799,"topic":"晋级","learn_goal":"","remark":"晋级","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"青松","city":"绍兴市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>大家好，我叫代松，名字源于“要知松高洁，待到雪化时”的诗句,我是一名电子工程师，同时也是附近一所高校的元培学院的的兼职讲师，美国项目管理协会（PMI）的培训讲师，主讲PMP项目管理。以及绍兴王阳明研究院师资班的学员。\u003c/p>\u003cp> 在工作期间，参与申请了300多项专利，设计多款电器平台，电磁炉，豆浆机，破壁机等。每年培训几百名项目经理，一个班的专业技术人员。IOTA智能物联标委会委员。\u003c/p>\u003cp>大家在项目管理，小电家选购，阳明心学方面的问题可以和我一起讨论，希望能和大家一起进步\u003c/p>","ratings_count":2,"texts":[{"id":20917,"quote":"\u003cp> \u003cstrong>R：《关注圈与影响圈》\u003c/strong>\u003c/p>\u003cp> 看一个人的时间和精力集中于哪些事物，也能大致判断他是否积极主动。每个人都有格外关注的问题，比如健康、子女、事业、工作、国债或核战争等等，这些都可以被归入“关注圈”( Circle of Concern，图3-3)，以区别于自己没有兴趣或不愿理会的事物。\u003c/p>\u003cp> 关注圈内的事物，有些可以被掌控，有些则超出个人能力范围，前者可以被圈成一个较小的“影响圈”( Circle of Influence，图3-4)。观察一个人的时间和精力集中于哪个圈，就可以判断他是否积极主动。\u003c/p>\u003cp> 积极主动的人专注于“\u003cstrong>影响圈\u003c/strong>”，他们专心\u003cstrong>做自己力所能及的事\u003c/strong>，他们的\u003cstrong>能量是积极的\u003c/strong>，\u003cstrong>能够使影响圈不断扩大\u003c/strong>。（见图3-5）\u003c/p>\u003cp> 反之，消极被动的人则全神贯注于“\u003cstrong>关注圈\u003c/strong>”，\u003cstrong>紧盯他人弱点、环境问题以及超出个人能力范围的事\u003c/strong>不放，结果越来越怨天尤人，一味把自己当作受害者，并不断为自己的消极行为寻找借口。错误的焦点\u003cstrong>产生了消极能量\u003c/strong>，再加上对力所能及之事的忽略，就造成了\u003cstrong>影响圈日益缩小\u003c/strong>。(见图3-6)\u003c/p>\u003cp> 只要我们的焦点在关注圈，就等于是允许自己受制于外界条件，自然就不会主动采取必要措施来推动积极变化。\u003c/p>\u003cp> 前面提到我有一个儿子在学校里遇到了麻烦，我和桑德拉都很担心，怕他因为那些弱点而被别人轻视。但这些都属于关注圈范围，结果错误的焦点不但没有解决问题，反而让我们自己倍感忧虑和无助，同时也加重了孩子的依赖性。后来我们聚焦于影响圈，着眼于自己的思维定式，结果真的有效。结论是我们不必担忧外界条件，只要先从自己做起，就可以化阻力为助力。\u003c/p>\u003cp>只有当我们在影响圈上下功夫，关注自己的思维模式时，我们才能获得改变自己的正能量，并最终也影响儿子。努力改变自己，而不是一味地担忧，我们就能改变现状。\u003c/p>","explains":"\u003cp>好，我看到大家已经看完拆页了，接下来我就分享一下我的理解和体会。\u003c/p>\u003cp>我们的精力是有限的，应该关注什么事情才能给我们最大的收益呢。常说“空谈误国，实干兴邦”。这个片段给我们提供一种简单直接的方法，让我们区分影响圈和和关注图，更好的防止精力多于扩展，从而提高效率。\u003c/p>\u003cp>精力要放在影响圈内才能提高效果，并不断的扩大影响圈。关注可控的范围，在这个范围内努力，不断的扩大影响圈。关注影响圈的人更积极主动，把自己能做的事情做好，不会把失败或停滞不前归于外因。关注关注圈的人更消极，更多的看到事情的限制，无法改变的部分，产生负面情绪。\u003c/p>\u003cp>首先，列出事物清单，在清单里区分出哪些事物是在关注圈哪些事情在影响圈。\u003c/p>\u003cp>其次，行动上少做关注圈的事，多做影响圈的事，扩大影响事。\u003c/p>\u003cp>最后，要清楚关注圈的事会被我们归结为外因，造成我们情绪低落。多在影响圈内行动，是积极的表现。\u003c/p>\u003cp>这个片段在生活或工作中，提高效率时使用，区分哪些是关注圈的事情，知道但无能为力。哪些是自己可控的事情，更多的积极行动。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>看完拆页的内容，我立即联想到发生在我身上的一个经历（故事）：\u003cbr> 疫情期间团队人员流动50%，我一直在抱怨公司的加薪政策不好，又因美国芯片限制要切换国产芯片，工作量剧增，造成的人员流失。\u003c/p>\u003cp>反思：\u003c/p>\u003cp>1） 公司政策，美国芯片制裁都是关注圈的事情，无法改变，把人员流动的原因归结在关注圈，不但问题没有解决，反而使自己和团队更加沮丧。\u003c/p>\u003cp>2） 没有把关注点放在影响圈内，想想自己能做的事情。薪酬和芯片制裁只是其中的一部分，自己有没有关注团队遇到困难时怎样提高效率，以及个人情绪的变化，个人成长的需求。\u003c/p>\u003cp>\u003cu>A2\u003c/u>\u003c/p>\u003cp>\u003cu>目标：\u003c/u>\u003cbr> 根据片段的启发，日常生活中，有很多我们不愿意做，又不得不做的事情，为提高自己的生活品质，更愉快的工作和生活，我将做以下行动。\u003c/p>\u003cp>\u003cbr> 这是一个转变我们积极面对能解决的问题的片段。根据片段原理，我将完成如下工作目标。\u003c/p>\u003cp>1）11月列出事物清单，区分哪些工作限制无法改变的，哪些是可以影响的\u003c/p>\u003cp> 1，梳理项目清单，找出最有价值的项目，排序项目重要度。\u003c/p>\u003cp> 2，不确定性高的项目，划入关注圈，减少投入。\u003c/p>\u003cp> 3，低价值又不确定性的项目，停止投入\u003c/p>\u003cp>2）分析影响圈内的事物，并列出行动方案。\u003c/p>\u003cp> 1，每周例会控制时间，挑有价值的事情讨论\u003c/p>\u003cp> 2，每月找关键工程师面谈，严格执行\u003c/p>\u003cp>3，放弃抱怨大环境不好\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1698549805000,"updated_at":1699788605000,"ria":true},{"id":16792,"topic":"今天这个拆页将从我们作为家庭教育者的角色切入，开启我们在家庭中作为孩子的第一任老师的职责，教给家庭成员充满力量的原则，并让其理解并遵循。","learn_goal":"","remark":"今天这个拆页将从我们作为家庭教育者的角色切入，开启我们在家庭中作为孩子的第一任老师的职责，教给家庭成员充满力量的原则，并让其理解并遵循","level":"TF2-1","duration":45,"status":30,"type":0,"chaishujia":{"username":"徐琴娜","city":"宁波市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>【学习目标】在跟随我完成本次RIA现场学习后，学习者能够参照了解家庭教育的4个建议实施积极教育影响。\u003c/p>\u003cp>亲爱的伙伴们：\u003c/p>\u003cp>大家晚上好！今天我要来大家来分享的是《高效能家庭的7个习惯》。\u003c/p>\u003cp>\u003cstrong>F 特征（核心是“书”，用于满足好奇心）：\u003c/strong>\u003c/p>\u003cp>《高效能家庭的7个习惯》是《高效能人士的七个习惯》的家庭版。作者是\u003ca href=\"https://baike.baidu.com/item/%E5%8F%B2%E8%92%82%E8%8A%AC%C2%B7%E6%9F%AF%E7%BB%B4/8826568?fromModule=lemma_inlink\">史蒂芬·柯维，国际著名领导学权威、家庭问题专家、教授和机构顾问。本书将七个习惯的力量注入家庭建设中，强调真正的高效能人士不仅要注重个人和公众领域的成功，更要寻求家庭方面的建树。\u003c/p>\u003cp>\u003cstrong>A 优势（重点是“比较”，用于建立安全感）：\u003c/strong>\u003c/p>\u003cp>这本书被誉为美国家庭圣经，《纽约时报》称这本畅销书为如何在动荡的世界中创立和维护一种强有力的家庭文化提供了宝贵经验。和同类书籍相比，作者是一位资深父亲，9个孩子的父亲，50个孙辈的祖父的履历让本书有大量的案例。行文流畅，易于阅读，并具有实际执行的步骤。\u003c/p>\u003cp>\u003cstrong>B 利益（强调的是“学习者”的利益，用于引发兴趣）\u003c/strong>\u003c/p>\u003cp>你希望拥有美好的家庭生活，但是现实是鸡飞狗跳、一地鸡毛？你想把家庭放在首位，用心经营，但是不知道从何入手？这本书能让你知道一步一步怎么做。若你想把家庭经营到风生水起，亲密关系、亲子关系以及与自我的关系等都能从这本书中得到一些启发……\u003c/p>\u003cp>今天这个拆页将从我们作为家庭教育者的角色切入，开启我们在家庭中作为孩子的第一任老师的职责，教给家庭成员充满力量的原则，并让其理解并遵循。\u003c/p>","ratings_count":2,"texts":[{"id":20909,"quote":"\u003cp>在教育方面，我有4 个建议：1.看清整个形势。如果一个人感到威胁，那么用戒律（或说教）来进行教育，只会造成这个人对教育者和教育本身更多的反感。最好等情形发生改变，这个人变得更加有安全感并且从心理上更愿意接受。在那样的时刻，你没有做出批评或纠正，这样会传达并教会他尊敬和理解。简单地说，如果你不能用戒律来进行教育，那么就可以用榜样来教育。榜样的教育作用会比戒律教育的作用更大更持久。这两者加起来也会让效果更明显。2.感觉你自己的精神和态度。如果你感觉愤怒或沮丧，不管你说了什么样的话，也不管你想教给别人什么样的价值观和原则，你都不可避免地会传递出那些负面的情绪。控制自己的情绪，跟他人保持距离。换一个时间进行教育，这个时候你应该感觉到爱心、尊敬和内在的安全。一个值得称道的好办法是：如果你在纠正或教育孩子时，轻轻抓住儿子女儿的手或手臂，如果你们彼此都觉得舒服，那么你就在发挥积极的影响。在愤怒的情绪下你是无法做到这些的。3.区分用来教育的时间和提高帮助支持的时间。在你的爱人或孩子筋疲力尽或处于极大压力之下时，如果你还是急于进行长篇大论的说教，就好像要教一个快要淹死的人游泳一样。他需要的是一条可以拉他上岸的绳子，而不是说教。4.记住，在很大程度上，我们总是在教授某种东西，因为我们总是在向外辐射出我们自己的样子。\u003c/p>","explains":"\u003cp>【what】\u003c/p>\u003cp>这个拆页是你在家庭中作为“教育者”身份时，施加教育影响时的4个注意点。它指导我们通过4个注意点对家庭成员尤其是孩子去实施有效影响，并时刻保持觉察。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>（通常做法）我们常常觉得，作为父母要时时处处以一个严肃教育者的身份面对孩子，不分场合地点，不顾及孩子周围的情形，直接指出孩子的问题，实施教育影响。\u003c/p>\u003cp>（坏处）但是这样做的很多情况下，孩子（尤其是青春期孩子）不“买单”，教育无效，甚至有可能造成关系紧张，而不利于家庭的氛围创建及家庭成员之间的沟通交流。\u003c/p>\u003cp>刚刚结束的超长寒假中，有一天三年级的弟弟8:30起床，拿着书从卧室走到餐厅，简单地扒拉几口饭后，仍然在看书。按约定这个时间是进行早读（出声朗读）的时间，几番提醒和催促后，我对他迟迟不进行早读有些急燥。\u003c/p>\u003cp>我：我和你说几遍了？\u003c/p>\u003cp>弟弟：知道了！\u003c/p>\u003cp>我：知道了还不做？早读是培养你的语感，15分钟的事情，每天都要拖上将近1小时。你说你还有看书的时间吗？【开始巴拉巴拉】\u003c/p>\u003cp>弟弟放下了书，看起来无力地瘫倒在沙发上。\u003c/p>\u003cp>既不看书，也不早读。\u003c/p>\u003cp>推推他，他说没力气。\u003c/p>\u003cp>我失望地看着他，想再说点什么，但是已然没有了说的欲望。\u003c/p>\u003cp>【how】如何在家庭里进行有效的教育呢？作者给了我们以下4个建议：\u003c/p>\u003cp>1.看清整个形势。对方变得有安全感并且从心理上更愿意接受时，施加教育才会更有效。榜样的作用会比戒律教育的作用更大更持久。\u003c/p>\u003cp>2.感觉自己的精神和态度。控制自己的情绪，跟他人保持距离。\u003c/p>\u003cp>3.区分用来教育的时间和提高帮助支持的时间。\u003c/p>\u003cp>4.记住，很大程度上，我们总是在向外辐射出我们自己的样子。\u003c/p>\u003cp>回到刚才我和弟弟互动的案例：\u003c/p>\u003cp>如果当弟弟出现这样状态的时候，我能重视我的感受，就能意识到弟弟的无力感与沮丧。参考四点建议，可以这样进行。\u003c/p>\u003cp>我走过去，坐在他的旁边，与孩子保持基本的连接。\u003c/p>\u003cp>“看得出来，你现在很不舒服。”弟弟不理我。\u003c/p>\u003cp>我没有走开，继续在旁边，此时我开始慢慢梳理自己的失望、担心与着急。过了一些时候，我觉得好多了。\u003c/p>\u003cp>慢慢地，弟弟也开口了“是的，很不舒服。”\u003c/p>\u003cp>“是因为我让你去早读吗？”\u003c/p>\u003cp>“我会早读的，但是我现在在看书，你就一直说。”\u003c/p>\u003cp>“对不起，我确实没有关注到你正在看一本感兴趣的书，是不是书里的内容吸引你了？”\u003c/p>\u003cp>“是啊，没有看完非常难受的。”\u003c/p>\u003cp>“可是，你不和我明说，我也没有猜到，咱们之间就有了误会了。让你难受，真是抱歉。”\u003c/p>\u003cp>如果你愿意，你可以继续看会书，我也在旁边看书。\u003c/p>\u003cp>早读开始了，需要我帮助的时候喊我！\u003c/p>\u003cp>（正确做法）在刚才的案例中，当孩子无力瘫倒的时候，我觉察到自己强烈的控制感和权力争夺（感觉自己的精神和态度），觉得：不早了，早读还不进行，不就影响今天一天的作业进度吗？时间拖拖拉拉那哪行啊？\u003c/p>\u003cp>慢慢让自己舒缓下来后发现，我并没有看到眼前这个人，没有尊重和理解。（看清整个形势。）我是希望孩子早读，并且抓紧时间，可是孩子也有自己的节奏与事务。当下这个时间可能是支持与服务时间，如果自己担心，只需要确定他早读的时间点即可，大可不必在旁边絮絮叨叨（区分用来教育的时间和提高帮助支持的时间）。你只要在，其实就是一种教育，孩子看到你，也知道你的教育观点与价值观，他知道自己应该干什么。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>我们的四条有效教育建议有其适用边界。\u003c/p>\u003cp>适用：我们自身有明确的使命宣言，有认为极其重要的原则与价值。并且通过爱的第一法则（诚实、正直、尊敬、责任和信任）建立起家庭成员间的关系，完成了家庭组织工作（有规律的一对一时间），遵循这四条有效教育的建议，家庭教育就会容易很多。当然这四个有效教育的建议比较多的应用在亲子关系上（家长对孩子，或者孩子对家长），也可以用在亲密关系上。在对配偶和青春期孩子施加教育影响时尤其需要这些建议。\u003c/p>\u003cp>不适用：家庭成员彼此良好关系并未建立的情况下，实施教育（或者影响、劝告、规诫）是作用不大的。这四条建议自然没有太大的用处。\u003c/p>","interaction":"\u003cp>请回顾一下最近一次和孩子互动时，你想实施教育影响，但是孩子根本不买帐的情况。我们都知道在家庭中，实施教育对孩子有积极影响并非易事，常常让我们有失望、无力的感觉。“好吧，你赢了，我对你没有办法。”现在想想最近有没有这样的感受？比如孩子撒谎了，你怎么做？作业拖着做很长时间，甚至影响睡眠时间，你怎么做？又或者，电子产品不离手，你又是怎么做的？\u003c/p>\u003cp>接下来，请大家设想一下，如果时光能够倒流，你再次经历那个场景，你会如何运用今天学到四个有效教育的建议呢？请大家在小组内分享，每人1分钟。【线上可以不分组】稍后我会请1个小伙伴分享。\u003c/p>\u003cp>陈琳：我虽然没有孩子，但是我见过很多案例，四点讲了同一回事，喜欢灌输自己的观点去教育孩子，最难的一关是情绪的问题，没有情绪后再沟通，才会是有用的。看清整个形势，每个孩子内心都是想要好的……\u003c/p>\u003cp>一江：女儿8岁了，这种情况真的很多，最近一次前些天我让他做数学题，二年级，应用题她理解困难，有时候很多遍都还不懂，我觉得孩子怎么那么笨。首先把自己跳脱出来，跳出这个现场，以第三者的眼光来看这个场面，认清自己的形势，体会孩子的情绪，你今天累了，下次再教你。其次是自己的精神和态度，来觉察一下，没有和孩子有同理心，想当然觉得很简单，孩子怎么会不明白。区分那个很晚的时间，是需要家长给到一些支持的，不能单方面进行灌输。有时候孩子的不好，其实是我们从他身上看到自己的那个讨厌的部分。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1698325285000,"updated_at":1698503207000,"ria":true},{"id":16139,"topic":"关注圈和影响圈","learn_goal":"","remark":"在《高效能人士的7个习惯》这本书中，书中提出了关注圈和影响圈的概念，帮助我们聚焦那些生活中值得关注的事情，进而开启高效能的人生。","level":"TF3-2","duration":35,"status":30,"type":0,"chaishujia":{"username":"芊蓉","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>大家好，我是芊蓉，三个标签介绍一下我自己：\u003c/p>\u003cp>结束北漂的广西人\u003c/p>\u003cp>正在研究爱情课题\u003c/p>\u003cp>正在研究人际关系\u003c/p>\u003cp>今天我拆解的片段，选自《高效能人士的7个习惯》 这本书。\u003c/p>\u003cp>下面我们从一个场景来感受这本书的魅力。\u003c/p>\u003cp>【事件场景】有一天我的工作室来了两个创业者，在他们看来，我是一个知识分子，于是一直在套我的话，其实我也认真的回答了他们的问题，但是他们总说我很滑，甚至很有心机，他们甚至像是来砸场的，结束后我整个人都是不开心的。\u003c/p>\u003cp>1个小时后我下楼，看到我妹妹，都觉得他们在议论我。\u003c/p>\u003cp>【提问】不知道伙伴们在现实生活当中有没有遇到过以上类似的情况，当遇到让你不舒服的事情的时候，你的注意力集中在哪里呢？你是集中在自己可以改变的事情上面，还是集中在了属于别人的事情上面呢？\u003c/p>\u003cp>【影响】生活中类似的事情有很多，它琐碎却又频繁，如果你把大量的时间精力放置在属于别人的事情上面，你的精神就会被消耗，你甚至都没有办法集中精力去做好你当下的事情，费心又费神。\u003c/p>\u003cp>【解决】这类问题的解决方法就在《高效能人士的7个习惯》这本书中，书中提出了关注圈和影响圈的概念，帮助我们聚焦那些生活中值得关注的事情，进而开启高效能的人生。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>今天的学习目标是，跟随我学习书中的拆页后，大家能够在现场运用（行为）聚焦影响圈的四个步骤（澄清），从影响圈入手去解决你的困惑（界定）。\u003c/p>\u003ch4>\u003cstrong>【A1】\u003c/strong>\u003c/h4>\u003cp>在开始阅读原文片段之前，请大家花一分钟的时间，做一个测试，看看目前你的时间精力主要分配在关注圈还是影响圈。以下6个题目，请按照1-6分的标准给自己打分，1代表非常不符合，6代表完全符合，请阅读下面的表格中的题目，为自己打分。\u003c/p>\u003cp>在这里我给大家3分钟的时间\u003c/p>\u003cp>现场互动：\u003c/p>\u003cp>看到大家的都出来了自己的最后得分，我看到最高分是22分，还有的21分，嗯嗯，看来大家都是非常的积极的呢。\u003c/p>\u003cp>我来解释一下自测题目。\u003c/p>\u003cp>测试得分25-36的小伙伴，恭喜你，你平常的思维习惯和精力主要集中在影响圈，遇事积极主动，离自己想要的成功越来越近。\u003c/p>\u003cp>如果得分在19-24分之间的小伙伴，说明你在某些时刻能够将精力集中在影响圈，而某些时刻集中在关注圈，你需要留意和觉察自己的思维习惯和精力，让自己变得更加积极主动，对自己的行为和习惯更有掌控感。\u003c/p>\u003cp>如果你的得分在6-18分之间，说明你的思维习惯和精力需要加以觉察和控制，那么今天的学习对你的帮助是最大的，一旦你能聚焦影响圈，变得积极主动，掌控自我，你将会享受到生活带给你的喜悦和快乐。\u003c/p>\u003cp>不管今天的测试你处于哪个状态或位置，今天的拆页都会让你有所收获。\u003c/p>\u003cp>这次拆解的原文片段来自于《高效能人士的7个习惯》，现在请各位用2分钟的时间阅读一下原文片段，阅读完成后示意我，或者评论区留言，现在开始阅读。\u003c/p>","ratings_count":1,"texts":[{"id":20226,"quote":"\u003cp>《高效能人士的7个习惯》\u003c/p>\u003cp>关注圈与影响圈\u003c/p>\u003cp>看一个人的时间和精力集中在哪些事物，也能大致判断他是否积极主动。每个人都有格外关注的问题，比如健康、子女、事业、工作、国债或核战争等等，这些都可被归入“关注圈”，以区别于自己有没有兴趣或不愿理会事物。\u003c/p>\u003cp>关注圈内的事物，有些可以被掌控，有些则超出个人能力范围，前者可以被圈成一个较小的“影响圈”。观察一个人的时间和精力集中在那个圈，就可以判断他是否积极主动。\u003c/p>\u003cp>\u003cstrong>积极主动的人专注于“影响圈”，他们专心做自己力所能及的事，他们的能量是积极的，能够使影响圈不断扩大。\u003c/strong>\u003c/p>\u003cp>反之，\u003cstrong>消极被动的人则全神贯注与“关注圈”，紧盯他人弱点、环境问题以及超出个人能力范围的事不放，结果越来越怨天尤人，一味把自己当作受害者，并不断为自己的消极行为寻找借口。\u003c/strong>\u003c/p>\u003cp>错误的焦点产生了消极能量，再加上对力所能及之事的忽略，就造成了影响圈日益缩小。\u003c/p>\u003cp>只要我们的焦点在关注圈，就等于是允许自己受制于外界条件，自然就不会主动采取必要措施来推动积极变化。\u003c/p>","explains":"\u003ch4>我看大家都读完了，\u003c/h4>\u003cp>\u003cstrong>【问题1】我问一下大家，我们刚才阅读的片段关键词是什么？\u003c/strong>\u003c/p>\u003cp>现场互动：\u003c/p>\u003cp>大家可以开你们的麦，也可以直接的在屏幕上打出来，好，我看到了有小伙伴说是关注圈和影响圈\u003c/p>\u003cp>没错，这段的关键词就是关注圈和影响圈\u003c/p>\u003cp>这个片段告诉我们，每个人都有两个圈子，他的时间和精力集中在哪些事物上，就能大致判断他是否积极主动，这两个圈就是影响圈和关注圈。\u003c/p>\u003cp>所谓\u003cstrong>影响圈\u003c/strong>，就是\u003cstrong>你可以改变的，你能够掌控的\u003c/strong>，例如：你的时间，你的选择，你的行为等等。\u003c/p>\u003cp>\u003cstrong>关注圈\u003c/strong>，就是那些\u003cstrong>你无法改变的，\u003c/strong>例如：没通过的成绩，过去的遗憾，既定的事实等等，这些都是你无法改变的。\u003c/p>\u003cp>好，这个是影响圈和关注圈的概念。\u003c/p>\u003cp>\u003cstrong>【问题2】那么接下来，我们结合概念一起来思考一下以下的清单，看一下他是属于影响圈还是关注圈？\u003c/strong>\u003c/p>\u003cp>1、我过去的错误——关注圈\u003c/p>\u003cp>2、我的选择——影响圈\u003c/p>\u003cp>3、航班晚点——关注圈\u003c/p>\u003cp>4、我的幸福——影响圈\u003c/p>\u003cp>5、别人的缺点——关注圈\u003c/p>\u003cp>6、别人如何对待我——关注圈\u003c/p>\u003cp>7、工作安全感——影响圈\u003c/p>\u003cp>8、下大雨影响出行——关注圈\u003c/p>\u003cp>很好，在区分的时候，我们一直在分析，哪些是可控的，哪些是不可控的，发现了吗，如果我们不去加以区分，我们就很容易掉入到关注圈里面，例如，我们会因为过去的错误不停的责备自己，会因为航班的晚点而不停的抱怨，明明改变不了，却不停的在这些改变不了的问题上面进行打转，对吧。\u003c/p>\u003cp>【问题3】第三个问题，当区分完影响圈和关注圈后，你们认为接下来还要做什么事情呀？\u003c/p>\u003cp>现场互动：\u003c/p>\u003cp>茉茉：接下来就是聚焦在影响圈上\u003c/p>\u003cp>拆书家：那你认为具体要怎么做呢？\u003c/p>\u003cp>茉茉：我也还没想好\u003c/p>\u003cp>拆书家：很好，刚刚茉茉很好的反应了大家的问题，就是都知道要聚焦在影响圈，可是聚焦在影响圈上之后呢，要做什么呀？在这里，我想到的就是——做计划，去行动。\u003c/p>\u003cp>你看，当我们区分完以后，基于影响圈的部分，去做计划，然后开启行动，只有行动起来，才算是转变了影响圈里面的内容，要不然，那些可控的事情就仅仅是看起来可控而已。\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003c/p>\u003cp>那么具体要怎么做呢？我把这个过程分为了4个步骤。\u003c/p>\u003cp>1、列清单：把自己关注的事物罗列出来；\u003c/p>\u003cp>2、做区分：结合我上面的分析，对清单中的事物逐一分析，按可控、不可控进行分类，可控的放入影响圈；不可控的放关注圈；\u003c/p>\u003cp>3、定方案：从你罗列的事件当中选出影响圈的部分。一一的写下你当下就可以去操作的行动方案，你的方案需要是一件具体的小事情；\u003c/p>\u003cp>4、去执行：针对第三步，按照重要紧急的情况去排序，这个排序，没有完全的对错，答案取决于你，然后按照排序展开行动。\u003c/p>\u003ch4>【案例】\u003c/h4>\u003cp>那接下来，我结合自己的案例来应用一下。\u003c/p>\u003cp>我先说一下背景：\u003c/p>\u003cp>【起因】前段时间，我的工作室来了两位我只见过一次的创业者，他们说上来坐坐，喝喝茶，但其实，我不喜欢这一类人，而且不太懂得怎么和这一类人打交道，我全程都在皱着眉头的听着，我按照我的习惯耐心的回答了他们的问题，结果对我各种挑刺，他们当面议论我，评判我的表达方式，我的性格，我的情感，语言当中带着许多的不允许与不尊重，我还被说成了是一个很狡猾、很心机的人，甚至被抨击说不真诚，在隐瞒，我的回答甚至让他们生气到直接下楼，我都能够觉察自己当时的面相已经很难看了。\u003c/p>\u003cp>我在我的工作室待了1个小时，脸色很沉重，下楼看到我妹妹的时候，我仿佛感觉他们在说我，甚至在晚上10点半骑车回去的时候，我觉察到我的神情依旧沉重。\u003c/p>\u003cp>【经过】在骑车的时候，我用关注影响圈的方法来解决这个问题：\u003c/p>\u003cp>\u003cstrong>第一：列清单\u003c/strong>\u003c/p>\u003cp>我感到不开心\u003c/p>\u003cp>我不知道怎么回复他们\u003c/p>\u003cp>对方不允许我按照我的方式表达\u003c/p>\u003cp>对方的性格太差了\u003c/p>\u003cp>\u003cstrong>第二：做区分\u003c/strong>\u003c/p>\u003cp>我感到不开心——影响圈（可控）\u003c/p>\u003cp>我不知道怎么回复他们——影响圈\u003c/p>\u003cp>对方不允许我按照我的方式表达——关注圈（不可控）\u003c/p>\u003cp>对方的性格太差了——关注圈\u003c/p>\u003cp>\u003cstrong>第三：定方案\u003c/strong>\u003c/p>\u003cp>我感到不开心——方案：用一句话来表扬自己：我已经很棒了，并且重复10次\u003c/p>\u003cp>我不知道怎么回复他们——方案：在知乎上面搜索关于如何面对他人挑衅的文章\u003c/p>\u003cp>\u003cstrong>第四：去执行\u003c/strong>\u003c/p>\u003cp>第1要做的事情：边骑车，边对自己说：我已经很棒了，重复10次\u003c/p>\u003cp>第2要做的事情：晚上回家看下知乎，找找方案\u003c/p>\u003cp>【结果】结果就是骑车不到10分钟的时候，我的心情就变好了很多，表情也柔和了许多，回家查阅了相关信息后，豁然开朗。\u003c/p>\u003cp>【适应边界】\u003c/p>\u003cp>当你因为外界的人、事、物而感到情绪低落的时候，就可以采用这个方法。\u003c/p>","interaction":"\u003ch4>【A3】\u003c/h4>\u003cp>为了帮助大家更好地掌握这个方法，接下来，我请大家进行场景演练。\u003c/p>\u003cp> 小红是一名课程设计老师，在北京工作了几年，公司一共6人，目前的这家公司属于她的很好的跳板，所以很认真的对待自己的工作，但是她经常要参与5个小时的会议，每次会议不仅仅很长，而且没有效率，其中\u003cstrong>有两个领导的思维是比较发散的，其他的同事有时候参与到会议当中\u003c/strong>，有时候不参与，每次开会都不聚焦，以至于\u003cstrong>小红感到很强烈的精神内耗\u003c/strong>。不过她也意识到自己的能力也不足，不仅仅是\u003cstrong>不善于引导\u003c/strong>，也没有解决方案。\u003c/p>\u003cp> 小丽是小红的朋友，正好学习了“关注圈与影响圈”，了解到小红的现状，打算跟小红来一次面谈，帮助她摆脱这种精神内耗…其中可以应用的方案有：\u003c/p>\u003cp>透过学习提升自己能力；\u003c/p>\u003cp>透过请教拆书帮的朋友获得引导的技巧；\u003c/p>\u003cp>透过和朋友倾诉可以缓解精神内耗。\u003c/p>\u003cp>接下来，我们会进行角色扮演，要求：\u003c/p>\u003cp>1、一人扮演小丽，一人扮演小红\u003c/p>\u003cp>2、对话内容要结合上文信息\u003c/p>\u003cp>3、对话中需要使用“关注圈和影响圈”的四步法\u003c/p>\u003cp>那么接下来我分一下小组，现在是5个人，那么我们就是一个大组，今天人不多，那茉茉来扮演小丽，曹原来扮演小红，接下来，你们先结合上面的信息，进行对话的框架的设置，需要先找到有哪些事件清单，然后区分影响圈和关注圈，需要注意哦，小丽要先把影响圈和关注圈的大致的概念告诉小红。\u003c/p>\u003cp>好，你们先写，同时可以在小组内进行讨论，5分钟后，你们再来进行演练。\u003c/p>\u003cp>【现场演绎】\u003c/p>\u003cp>小红：小丽，我最近好烦呀\u003c/p>\u003cp>小丽：怎么啦\u003c/p>\u003cp>小红：我经常要参与5个小时的会议，每次会议不仅仅很长，而且没有效率，其中\u003cstrong>有两个领导的思维是比较发散的，其他的同事有时候参与到会议当中\u003c/strong>，有时候不参与，每次开会都不聚焦，以至于我\u003cstrong>感到很强烈的精神内耗\u003c/strong>。不过我也意识到自己的能力也不足，不仅仅是\u003cstrong>不善于引导\u003c/strong>，也没有解决方案。\u003c/p>\u003cp>小丽：看起来你确实陷入到烦恼当中，这样，我最近学习了一个方法，叫做区分：影响圈、关注圈，所谓的影响圈就是可控的事情，关注圈就是不可控的事情，那现在我们先来梳理一下，你都有哪些烦恼\u003c/p>\u003cp>小红：（\u003cstrong>第一：列清单\u003c/strong>）\u003c/p>\u003cp>有两个领导的思维是比较发散的\u003c/p>\u003cp>其他的同事有时候参与到会议当中\u003c/p>\u003cp>每次开会都不聚焦\u003c/p>\u003cp>感到很强烈的精神内耗\u003c/p>\u003cp>不善于引导\u003c/p>\u003cp>小丽：非常好，我们一起来看看哪些是可控的，哪些是不可控的呢\u003c/p>\u003cp>小红：（\u003cstrong>第二：做区分）\u003c/strong>\u003c/p>\u003cp>有两个领导的思维是比较发散的——不可控\u003c/p>\u003cp>其他的同事有时候参与到会议当中——不可控\u003c/p>\u003cp>每次开会都不聚焦——不可控\u003c/p>\u003cp>感到很强烈的精神内耗——可控\u003c/p>\u003cp>不善于引导——可控\u003c/p>\u003cp>小丽：非常的好，我们把注意力放在可控的事情上面，然后我们一起来看看，有什么样的方法，可以解决这些问题呢？\u003c/p>\u003cp>小红：（\u003cstrong>第三：定方案）\u003c/strong>\u003c/p>\u003cp>透过和朋友倾诉可以缓解精神内耗：\u003c/p>\u003cp>透过学习提升自己引导的能力，透过请教拆书帮的朋友获得引导的技巧；\u003c/p>\u003cp>小丽：非常的好，那我们来看看哪件事更加重要，可以先去做的呢？\u003c/p>\u003cp>小红：我觉得倾诉这件事更重要，不过通过跟你分享，其实已经缓解了一半了，剩下的就是去学习引导能力，最后是找个时间，找一位引导能力比较好的拆书家对他进行请教。（\u003cstrong>第四：去执行\u003c/strong>）\u003c/p>\u003cp>小丽：非常的棒，你觉得你的问题得到解决了吗\u003c/p>\u003cp>小红：嗯嗯呢，确实已经解决了，谢谢你\u003c/p>\u003cp>小丽：不客气啦\u003c/p>\u003cp>\u003cstrong>【现场反馈】\u003c/strong>\u003c/p>\u003cp>很好，看来大家已经很好的掌握了我们的聚焦影响圈的方法。\u003c/p>\u003cp>而且茉茉引导得非常的好，曹原第一次听3-2的拆书，相信还有点懵，但是第一次听，还能够应对得这么好，已经很棒了，需要注意的是，在实际的对话当中，我们可能需要安静的去带领大家进行分析，可能不是那么快的做到，慢慢来会更好的上手。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>好，刚刚我们是借助我设计的场景进行的练习，接下来呢，我留个作业，请在一两天内，找机会跟人分享一下你今天学习到的聚焦影响圈的四个步骤，想想你会分享给谁呢？你又会如何进行分享呢？\u003c/p>\u003cp>这个是留给你们的作业，两天后，我找你们要你们的作业情况。\u003c/p>\u003cp>【学习者作业】\u003c/p>\u003cp>时间：下周二\u003c/p>\u003cp>人物：曹原、她同事\u003c/p>\u003cp>地点：公司\u003c/p>\u003cp>起因：\u003c/p>\u003cp>我的一个同事，经常会抱怨她的直属领导张总对她不公平，看不到她的成绩和努力，只会针对她，责备她，她也觉得很烦恼，甚至对自己的能力产生怀疑。\u003c/p>\u003cp>明天上班碰到她，我会在中午午休的时候，和她分享一下聚焦影响圈的办法，尝试帮助她摆脱困扰。\u003c/p>\u003cp>经过：\u003c/p>\u003cp>曹原：亲爱的，在忙吗？我看你最近的状态不太好\u003c/p>\u003cp>同事：是的，张总对我不公平，看不到我的成绩和努力，只会针对我，责备我\u003c/p>\u003cp>曹原：嗯嗯，那你一定很生气\u003c/p>\u003cp>同事：何止生气，我都要怀疑自己的能力了\u003c/p>\u003cp>曹原：我最近学到了一个提升自己能量的方法，我自己用了觉得特别有效，你想不想试一试？说不定能改变张总对你的看法。\u003c/p>\u003cp>同事：可以呀\u003c/p>\u003cp>曹原：我想要分享的内容呢，来自《高效能人士的7个习惯》这本书，里面呀，有两个名词：关注圈与影响圈，我们在平时的生活、工作当中，经常会把注意力集中在不同的事情上，这些事情呢，有的可控，有的不可控，那么，所谓的关注圈呢，就是指不可控的，而影响圈就是指可控的，这个概念我先简单的和你说一下。\u003c/p>\u003cp>那么接下来呢，我们可以基于你最近烦恼的事情去罗列一个清单，你看看最近的烦心事有哪些？（列清单）\u003c/p>\u003cp>同事：\u003c/p>\u003cp>张总对我的评价让我不舒服\u003c/p>\u003cp>张总布置的任务太多了\u003c/p>\u003cp>我开始怀疑自己的能力\u003c/p>\u003cp>我的情绪受到了严重的影响\u003c/p>\u003cp>曹原：嗯嗯，很好，那接下来我们一起来区分一下，你罗列的这些事情当中，哪些是影响圈的，哪些是关注圈的（做区分）\u003c/p>\u003cp>同事：好的\u003c/p>\u003cp>张总对我的评价让我不舒服——我不可控——关注圈\u003c/p>\u003cp>张总布置的任务太多了——我不可控——关注圈\u003c/p>\u003cp>我开始怀疑自己的能力——我可控——影响圈\u003c/p>\u003cp>我的情绪受到了严重的影响——我可控——影响圈\u003c/p>\u003cp>曹原：很好哈，相信你在区分的时候也意识到了，有些事情是你无法控制的，只有自己的事情呢，才是自己可以控制的，那么接下来，我们就聚焦在影响圈圈上\u003c/p>\u003cp>同事：嗯嗯，那就是：我的能力、我的情绪属于影响圈的\u003c/p>\u003cp>曹原：那接下来，我们来基于影响圈的事情呢，来制定方案，你可以思考一下，要做些什么事情，才能改善你自己的情况呢？可以具体到一些小事情上面（定方案）\u003c/p>\u003cp>同事：\u003c/p>\u003cp>我的能力——我需要对当前的事情进行复盘，找到需要改进的地方\u003c/p>\u003cp>我的情绪——在周末的时候，去水上乐园玩，去释放情绪\u003c/p>\u003cp>曹原：很好，接下来，你可以排一下序，然后一起看看，你要先做哪个，并且立即行动起来（去执行）\u003c/p>\u003cp>同事：嗯嗯，那就是：\u003c/p>\u003cp>第一件事：一会我就可以看看水上乐园的周末的票，然后约上几个伙伴和我一起\u003c/p>\u003cp>第二件事：今天回家后就拿出本子来进行复盘\u003c/p>\u003cp>曹原：非常的棒，那么你现在关于孙总的这个事情，你有没有好一点呀。\u003c/p>\u003cp>同事：好太多了，谢谢你。\u003c/p>\u003cp>曹原：不客气。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>今天我们学习了影响圈和关注圈的两个概念，并且学会如何区分以及如何聚焦影响圈，简单的回顾一下具体的步骤：\u003c/p>\u003cp>\u003cstrong>第一：列清单\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二：做区分\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三：定方案\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第四：去执行\u003c/strong>\u003c/p>\u003cp>最后我想说，你的注意力在哪里，你的结果就在哪里！\u003c/p>\u003cp>那么希望大家未来也可以多多的使用，今天的分享就到这里。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1688193396000,"updated_at":1688829656000,"ria":true},{"id":16127,"topic":"移情聆听","learn_goal":"","remark":"本书《高效能人士的7个习惯》提供了一个有效的倾听方式——移情聆听，帮助你在倾听的时候，不仅能够给对方建立安全感，也让你在不会回应的时候提供一些有效的方法。","level":"TF3-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"芊蓉","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是芊蓉，三个标签介绍一下我自己：\u003c/p>\u003cp>三级心理咨询师\u003c/p>\u003cp>觉察力日记的践行者\u003c/p>\u003cp>课程设计老师\u003c/p>\u003cp>今天我拆解的片段，选自《高效能人士的7个习惯》 这本书。\u003c/p>\u003cp>\u003cstrong>【场景介绍法】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【事件场景】\u003c/strong>\u003c/p>\u003cp> 开始分享本书的内容之前，我先说一个案例：\u003c/p>\u003cp>有一次，我舍友想向我倾述她在感情当中的烦恼，我当时手头有点工作，只是偶尔停下来和她对话，我当时有感受到她很难过，但是我不知道要怎么回应，我甚至觉得有点尴尬，于是我想转移一下话题，结合她的内容分享了自己的心得，结果讲着讲着，对方突然嚎啕大哭了起来，我瞬间不知道怎么办才好。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>\u003c/p>\u003cp>大家在大脑当中回顾一下，在过去的半年时间里，你有没有遇到过，不懂得如何回应他人倾诉的问题的情况？又或者有朋友向你倾诉，结果你的回应不仅没有帮助到对方，还让对方不愿意继续向你倾诉的情况？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003c/p>\u003cp>当倾诉的人心情不好，甚至无比痛苦时，如果我们直接告诉他该怎么做，或者直接指出来他的问题，甚至忽略对方的感受，这样不但起不到安慰的效果，还可能会导致对方的排斥，严重的还会导致关系的破裂。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003c/p>\u003cp>那么要如何有效的倾听呢？本书《高效能人士的7个习惯》提供了一个有效的倾听方式——移情聆听，帮助你在倾听的时候，不仅能够给对方建立安全感，也让你在不会回应的时候提供一些有效的方法。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在完成本片段的学习后，学习者能够辨别（行为）移情聆听的具体表现，并在活动现场运用移情聆听3步法（澄清）从情感、理智去体会对方，理解对方（界定）。\u003c/p>","ratings_count":1,"texts":[{"id":20220,"quote":"\u003cp>\u003cstrong>移情聆听\u003c/strong>\u003c/p>\u003cp> 事实上，大部分人都是这么自以为是。我们的聆听通常有层次之分。一是充耳不闻，压根不听别人说话；二是装模作样，“是的”、“嗯”、“没错”；三是选择性地接收，只听一部分，通常学龄期儿童的喋喋不休会让我们采取这种方法；四是聚精会神，努力听到每个字。但是，很少有人会达到第五层次，即高层次的移情聆听。\u003c/p>\u003cp> 主动型和回应型聆听是一种技巧，本质是以自我为中心，就算行为没有显露出来，动机已经不言而喻，会让说话的人有受辱的感觉。回应型聆听技巧的目的不过是要做出回应，操控对方。\u003c/p>\u003cp> \u003cstrong>移情聆听是指以理解为目的的聆听，要求听者站在说话者的角度理解他们的思维模式和感受。\u003c/strong>\u003c/p>\u003cp> 移情不是同情，后者是一种认同和判断形式，更适合用来表达感情和做出回应，却容易养成对方的依赖性。\u003cstrong>移情聆听本质不是要你赞同对方，而是要在情感和理智上充分而深入地理解对方。\u003c/strong>\u003c/p>","explains":"\u003cp>【what】\u003c/p>\u003cp>这个片段分享了一个很重要的概念：移情聆听。\u003c/p>\u003cp>什么是移情聆听呢？\u003c/p>\u003cp>原文当中是指以理解为目的的聆听，要求你站在对方的角度去理解他们的思维模式和感受。\u003c/p>\u003cp>这句话的关键词有哪些？\u003c/p>\u003cp>对方的角度、理解、思维模式、感受\u003c/p>\u003cp>首先我们来看：对方的角度，这就意味着，我们不能以自我为中心，去评价呀、去给建议呀，都不行\u003c/p>\u003cp>理解：就是去体会，去感受，去允许对方，但是大多数时候这个过程我们都是在大脑当中完成的，那么为了更好的呈现出我们有去理解对方的动作，最好的方式就是去复述对方的话语；\u003c/p>\u003cp>思维模式、感受：也就是不仅仅要体会对方的感受，还要去理解对方的想法，这样才是一个完整的移情聆听。\u003c/p>\u003cp>【概念辨析】讲解技能之案例与概念相互参照\u003c/p>\u003cp>好，为了更好的理解“移情聆听”，我们一起来看一下下面的案例：\u003c/p>\u003cp>好，在这里我邀请一位伙伴来扮演一下我的朋友，来，茉茉吧，你来念朋友这句话。\u003c/p>\u003cp>\u003cstrong>对话一：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>朋友：我那么努力的准备这次考试，结果没赶上考试\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我：不会吧，你点也太背了\u003c/strong>\u003c/p>\u003cp>互动：\u003c/p>\u003cp>拆书家：大家觉得这是移情聆听吗？\u003c/p>\u003cp>学习者：不是\u003c/p>\u003cp>拆书家：大家都很棒，这个不属于移情聆听，它不是站在对方的角度上面去思考问题，而是站在自己的角度去体会，去评价。\u003c/p>\u003cp>\u003cstrong>对话二：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>朋友：我那么努力的准备这次考试，结果没赶上考试\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我：你努力的准备考试，结果没赶上考试呀\u003c/strong>\u003c/p>\u003cp>互动：\u003c/p>\u003cp>拆书家：大家觉得这是移情聆听吗？\u003c/p>\u003cp>拆书家：大家都很棒，这个不属于移情聆听，它只符合了一个要点：就是去复述对方的话语，其他的没有。\u003c/p>\u003cp>\u003cstrong>对话三：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>朋友：我那么努力的准备这次考试，结果没赶上。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我：你努力的准备考试，结果没赶上考试呀\u003c/strong>\u003c/p>\u003cp>\u003cstrong>朋友：是啊，气死我了，我也是点背，当天手机闹钟坏了，起晚了，还堵车，堵了一个小时\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我：你当时一定很生气\u003c/strong>\u003c/p>\u003cp>互动：\u003c/p>\u003cp>拆书家：这是移情聆听吗？\u003c/p>\u003cp>学习者：不是\u003c/p>\u003cp>拆书家：太棒了，在这个对话中，我有复述、我还有理解对方的感受，但是还少了理解对方的想法。\u003c/p>\u003cp>\u003cstrong>对话四：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>朋友：我那么努力的准备这次考试，结果没赶上。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我：你努力的准备考试，结果没赶上考试呀\u003c/strong>\u003c/p>\u003cp>\u003cstrong>朋友：是啊，气死我了，我也是点背，当天手机闹钟坏了，起晚了，还堵车，堵了一个小时\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我：你当时一定很生气\u003c/strong>\u003c/p>\u003cp>\u003cstrong>朋友：是呀，我当天晚上真的都调好闹钟了，结果都没有响\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我：我想你当时调闹钟的时候一定也很担心第二天起不来\u003c/strong>\u003c/p>\u003cp>\u003cstrong>朋友：是呀，就是因为担心第二天起不来，结果发现是调错了\u003c/strong>\u003c/p>\u003cp>\u003cstrong> \u003c/strong>\u003c/p>\u003cp>互动：\u003c/p>\u003cp>拆书家：这是移情聆听吗？\u003c/p>\u003cp>学习者：是的\u003c/p>\u003cp>拆书家：太棒了，在整个对话中，我不仅是站在对方的角度，还有复述，有理解思维方式和感受。那么，一个完整的移情聆听下来，就会感到很舒服。\u003c/p>\u003cp>当然，在实际的对话当中，有时候需要反复循环的去跟对方沟通，倾听，才能真正的理解和体会对方，今天由于时间有限，我们的对话就设置得比较少。\u003c/p>\u003ch4>\u003cstrong>【How】\u003c/strong>\u003c/h4>\u003cp>具体怎么做呢？在这里，我将移情聆听分为了3个步骤。\u003c/p>\u003cp>\u003cstrong>1、复述信息\u003c/strong>\u003c/p>\u003cp>用你自己的语言去重复一小部分对方刚刚讲的话语。\u003c/p>\u003cp>例如：你努力的准备考试，结果没赶上考试呀\u003c/p>\u003cp>\u003cstrong>2、体会感受（右脑）\u003c/strong>\u003c/p>\u003cp>去体会对方在讲他的那些内容的时候的感受，并表达出来。\u003c/p>\u003cp>注意，是去体会对方的感受，而不是你自己的感受，这就意味着你要去关注、体会对方的情绪。\u003c/p>\u003cp>例如：你当时一定很生气\u003c/p>\u003cp>\u003cstrong>3、验证理解（左脑）\u003c/strong>\u003c/p>\u003cp>去理解当对方在描述那些信息的时候，他当时是怎么做的，怎么想的，把你想到的内容进行表达，从而验证你的理解。\u003c/p>\u003cp>例如：我想你当时调闹钟的时候一定也很担心第二天起不来\u003c/p>\u003cp>好，这就是一个完整的移情聆听。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>当你的朋友、爱人、家人这些关系比较亲近的人或者你关注的人（学员、同事、小朋友......），在\u003cstrong>情绪低落\u003c/strong>的向你倾诉，同时，\u003cstrong>你也愿意倾听\u003c/strong>的时候，就可以使用这个方法了。\u003c/p>\u003cp>注意哦，当你本身有很大的情绪的时候，这个方法就不适合了。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>【人物】我、小朋友\u003c/p>\u003cp>【起因】上个月，店里来了一个顾客，这个顾客带着一位拿着玩具但是有点忧伤的5岁的小朋友，为了让顾客能够安心的试衣服，于是我和这个小朋友交流了起来。\u003c/p>\u003cp>经过简单的交流，发现这个小朋友正在因为学校里面的一个小朋友而不开心。\u003c/p>\u003cp>他说：我想跟小红一起玩，但是她不理我，我把我的玩具分享给她了，但是她就是不和我玩。\u003c/p>\u003cp>【经过】于是我应用了移情聆听：\u003c/p>\u003cp>我：（复述信息）嗯嗯，你想跟小红一起玩，但是她不理你\u003c/p>\u003cp>小朋友：是的\u003c/p>\u003cp>我：（体会感受）你一定很难过吧\u003c/p>\u003cp>小朋友：是的，我的玩具那么好玩，但是她不要\u003c/p>\u003cp>我：（验证理解）你是不是很想把自己好玩的玩具分享给你喜欢的小朋友，希望她也能够和你一样开心呀？\u003c/p>\u003cp>小朋友：嗯嗯，这个玩具真的很好玩，我很喜欢这个玩具\u003c/p>\u003cp>【结果】经过我的一番对话之后，小朋友给我介绍了他的玩具，瞬间开心了起来。\u003c/p>\u003cp>这，就是移情聆听的魅力，可以说生活当中，经常会有这样的场景。\u003c/p>\u003cp>那么接下来，我们进入到互动的环节。\u003c/p>","interaction":"\u003ch4>【A2】\u003c/h4>\u003cp>其实，刚刚的那个案例，是我自己编的，\u003cstrong>是结合我的真实生活场景展开的\u003c/strong>，我的真实生活场景当中遇到过有的顾客带着小朋友来店里买衣服的场景，而且有的小朋友手里拿着玩具，那么我就是借助这样的生活场景，进行展开设计，并且应用了今天提到的“移情聆听”3步法，设计了整个剧本。\u003c/p>\u003cp>那么，接下来请大家设想一下，在未来的2周内，可能会发生一次需要进行移情聆听的对话，例如：你的闺蜜找你倾诉她的烦恼，或者你的孩子倾诉她的不开心........基于你选择的对话场景，进行编剧，并且把这个对话编写成一个剧本，剧本有两个角色，你可以是其中一个角色，也可以不是，将这些对话场景运用叙述六要素的方式，编写成一个剧本。\u003c/p>\u003cp>请注意：\u003c/p>\u003cp>①剧本需要包含时间，地点，人物，起因，经过，结果。（可以参考我刚刚分享的案例）\u003c/p>\u003cp>②剧本要使用移情聆听的三步法。\u003c/p>\u003cp>③剧本最终呈现出来的要是对话的形式。\u003c/p>\u003cp>今天人不多，那么我们就是一个大组，大家可以先自己写一下剧本的框架，然后把具体的行动步骤，用几个关键词来进行简要的描述，可以先在脑海中进行构思，那如果有问题，可以直接开麦进行讨论，5分钟后，我将邀请一位伙伴来分享你的剧本。\u003c/p>\u003cp>【伙伴分享】\u003c/p>\u003cp>分享者：茉茉\u003c/p>\u003cp>时间：下周二\u003c/p>\u003cp>地点：下班路上\u003c/p>\u003cp>人物：我、同事\u003c/p>\u003cp>起因：我们公司的某个产品升级，然后升级完了之后也没有什么大的变化，然后我同事就跟我吐槽。因为他对于产品比较有期待，然后又没有什么变化，就是他会感觉下半年的工作不太好做，然后我们就会有一个简单的交流。\u003c/p>\u003cp>经过：\u003c/p>\u003cp>朋友：这个东西升级的什么玩意，最后也没有什么变化。\u003c/p>\u003cp>茉茉：嗯嗯，确实没有什么变化。（复述信息）\u003c/p>\u003cp>朋友：这个东西没什么太大变化，对于一些老客户可能不是很好介绍，就是我们销售这个产品的时候会有一些困难\u003c/p>\u003cp>茉茉：那你一定很生气（体会感受）\u003c/p>\u003cp>朋友：对呀，本来销售就不好做！\u003c/p>\u003cp>茉茉：我想你一定是想把这个东西给我们的客户用起来，希望我们真的能够去帮助我们的客户？（验证理解）\u003c/p>\u003cp>朋友：对的呀，想想，这也是公司的事情，我只需要把自己的事情做好就行。\u003c/p>\u003cp>结果：朋友的情绪得到了缓解\u003c/p>\u003cp>【反馈】\u003c/p>\u003cp>好的，非常的棒，刚刚茉茉很好的举了自己的例子，同时我们会发现，在真实的互动当中，其实是需要进行多个对话的，并且呢，不管是重复信息，还是体会感受等等，在实际的应用的时候，当我们对具体的行动步骤了然于胸了，才能更好的应用。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>今天，我们学习“移情聆听”的3步法：复述信息、体会感受、验证理解，相信这个方法在未来能够很好的帮助到你，今天的分享就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1688037275000,"updated_at":1688211319000,"ria":true},{"id":15560,"topic":"高效能人士的5+4法则","learn_goal":"","remark":"线上过级","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"芷旭","city":""},"club":{"name":"昆明春城分舵","city":"昆明"},"prologue":"\u003cp>\u003cstrong>【分组】1分钟\u003c/strong>\u003cbr>我们这次拆书至少有60分钟，会有分享和讨论的环节，想先请问一下有多少伙伴是可以全程参与的？可以在聊天区敲1。由于时间比较长，所以到了实际分享和讨论的环节，我也会再次根据实际情况来进行调整。\u003cbr>(人数不足6人，自成一组)\u003cbr>\u003cbr>\u003cstrong>【开场】1分钟\u003c/strong>\u003cbr>大家好，我是芷旭，目前生活在德国，我的三个标签是：\u003cbr>快乐妻子成长教练，我希望可以带领更多妻子一起成长，真实做自己，快乐做妻子，轻松做妈妈；\u003cbr>拆书爱好者，自从结识拆书帮，我就深深爱上了这个神奇的地方，我本身也很爱读书，所以真的是一拍即合；\u003cbr>追求平衡的终身成长者，我本身是一个目标导向很明确的人，但一个人走不远，所以我希望可以和小伙伴们一起成长，因此我要学习更多考虑人，而非事，需要平衡目标与过程。\u003cbr>\u003cbr>\u003cstrong>【图书介绍】 1.5分钟\u003c/strong>\u003cbr>【Feature特征】：\u003cbr>今天我要和大家介绍的这本书是《高效能人士的七个习惯》，这本书在美国的地位仅次于《圣经》。作者史蒂芬·柯维博士，也入选了“影响美国历史进程的25位人物”，在世界500强企业里，这本书备受推崇。\u003cbr>【Advantage优势】：与其他同类书籍相比，这本书不仅仅讲到职场上的高效能，更是从个人成长的角度全方位阐述如何从个人独立成熟到人际关系成熟，成为高效能人士，可谓将个人成长的途径解释得淋漓尽致。\u003cbr>【Benefit利益、好处】：\u003cbr>这本书通过七个原则来帮助人们建立高效能的工作和生活习惯，可以称得上是是个人全方位成长的宝典。\u003cbr>今天我们聚焦在责任型授权，通过今天的学习，可以帮助你在需要将任务分配给他人时，能知道怎么做才是真正的授权和放手，从而提高你的效能。\u003cbr>\u003cbr>\u003cstrong>【第一个拆页的学习目标】0.5分钟\u003c/strong>\u003cbr>第一个拆页学习之后，学习者能够通过反思，运用责任型授权五步法，将任务分配给别人。\u003c/p>","ratings_count":1,"texts":[{"id":19616,"quote":"\u003cp>\u003cstrong>【R】阅读原书拆页 3分钟\u003c/strong>\u003cbr>现在就请大家花三分钟时间一起来阅读这一段原文拆页，读完的小伙伴可以在聊天区敲1示意以下，到最后30秒时我会提醒大家。\u003cbr>\u003cbr>主题书籍《高效能人士的七个习惯 》三十周年纪念版 页码：P186-187\u003cbr>拆页原文：\u003cbr>仍以我家为例。有一年，我们开家庭会议，讨论共同的生活目标以及家务分配。会议结果不问可知，因为孩子还小，我与妻子分担了大部分工作。当时7岁的史蒂芬已懂事，自愿负责照顾庭院，于是我认真指导他如何做个好园丁。\u003cbr>我指着邻居的院子对他说:“这就是我们希望的院子---绿油油而又整洁。除了上油漆外，你可以自己想办法，用水桶、水管或喷壶浇水都行。”\u003cbr>为了把我所期望的整洁程度具体化，我俩当场清理了半边的院子，好给他留下深刻的印象。\u003cbr>经过两星期的训练，史蒂芬终于完全接下了这个任务。我们协议一切由他作主，我只在有空时从旁协助。此外，每周两次，他必须带我巡视整个院子，说明工作成果，并自己为表现打分。\u003cbr>当时并未谈到零用钱的问题，不过我很乐意付这笔钱，我想，7岁大的孩子应该已有责任感，足以负担这个任务。\u003cbr>那一天是星期六，一连过了3天，史蒂芬毫无动静。星期六才做的决定，我不奢望他立即行动，星期天也不是工作日，可是星期一他依然故我，到星期二，我有些按捺不住。今人气恼的是，院内脏乱依旧，史蒂芬却在对街的公园里玩。\u003cbr>我感到极度失望，忍不住想要唤他过来整理院子。这么做可收立竿见影之效，却会给孩子推卸责任的借口。于是我勉为其难忍耐到晚餐用毕，才对他说：“照前几天的约定，你现在带我到院子里，看看工作成绩，好不好?” \u003cbr>才出门他就低下头，过不多久便抽噎起来。 \u003cbr>“爸，这好难哟!”\u003cbr>很难？我心里想：你根本什么都没做。不过我也明白，难的是自动自发，于是我说:“需不需要我帮忙呢?”\u003cbr>&quot;你肯吗?爸!”\u003cbr>&quot;我答应过什么?&quot;\u003cbr>&quot;你说有空的时候会帮我。”\u003cbr>“现在我就有空。”\u003cbr>他跑进屋去拿来两个大袋子，一人一个，然后指着一堆垃圾说:&quot;请把那些捡起来好不好?&quot;\u003cbr>我乐于从命，因为他已开始负起照顾这片园地的责任。\u003cbr>那年暑假我总共又帮了两三次忙，之后他就完全独立作业，悉心照顾一切。甚至哥哥姐姐乱丢纸屑，立刻就会受到指责。他做得比我还好。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导 12分钟\u003c/strong>\u003cbr>既然大家都读完了原文的案例，接下来我们就来拆解一下。\u003cbr>\u003cstrong>【What】（这是一个什么概念）\u003c/strong>\u003cbr>第一个拆页分享的这个概念叫做“责任型授权”，它是一种关注结果的授权方式，是给人自由，允许被授权者自行选择做事的具体方法，并为最终的结果负责。\u003cbr>\u003cstrong>【Why】（为什么要这么做，这么做有什么好处，不这么做有什么坏处）\u003c/strong>\u003cbr>为什么我们要来学习这个责任型授权呢？\u003cbr>其实分配任务是我们在生活和工作中常会遇见的事，因为我们毕竟个人时间有限，不可能什么事都自己做。但是，你觉得分配任务给别人容易吗？觉得容易的可以扣1，觉得不容易的可以扣2\u003cbr>你有没有经历过，把一件事情交给别人去做，发现比自己做还累，不交吧，实在没时间亲自做，交吧，最后可能还要自己收拾烂摊子，非常纠结。\u003cbr>如果我们真的每件事都亲自去做，那会怎么样？那肯定是不可能的，会把自己累死，到最后可能也会很有怨气，但如果我们随意把任务分配给本人，那对方接不住，势必最后我们就是必须收拾烂摊子。\u003cbr>所以我们必须学会如何正确地分配任务给其他人。\u003cbr>而我们今天要学习的这个责任型授权，就是教我们如何把责任正确地授权给其他人，让我们可以真正放手，从而大幅提升我们的效能。\u003cbr>\u003cbr>\u003cstrong>【意译案例】\u003c/strong>\u003cbr>比如我就想到我曾经经历过的一件事：\u003cbr>当时我们小组来了一位新的实习生，组长让我带她，分配一些任务给他，当时我正在预备两周后一个公司内部的软件培训，正好需要帮手，跟她沟通之后，决定把培训的投影片制作交给她。\u003cbr>我把我已经做完的文字资料共享给她，又亲自演示了一遍软件的操作，我跟她说：“这是文字资料，你可以根据刚才我的演示，将文字稿里的重点提炼到PPT，这里有一个培训投影的模板，你最终要呈现出来的PPT就是这个样子。”\u003cbr>交接好之后，我跟她说：“一周后你需要出初稿，期间如果有任何不明白的地方，都要来找我沟通。”\u003cbr>之后一周的时间，她就在埋头苦干，也没有来找我询问任何事，我虽然有些奇怪，但由于我们说好了如果有问题，她要来找我，所以我就没有去追她，而是选择信任。\u003cbr>到了约好的时间，她向我展示了她做出的投影片初稿，我发现，由于她对这个软件还不太熟悉，所以在投影的设计上，重点不够突出，还有一些是她理解不到位的地方，我给她一一指出来，让她去修改。\u003cbr>然后我问她：“为什么过程中没有来找我询问？”\u003cbr>她说：“不好意思来找你，怕打扰你。”\u003cbr>我说：“我说过你有问题可以随时来找我沟通，如果你不想打扰我，也可以约好每天15分钟，这样你如果有问题，也可以问，不用担心打扰我。”\u003cbr>她说：“好的，那我们就每天9点，用15分钟来沟通一下，有问题我就提。”\u003cbr>我答应了，因为她开始主动为此负责了。\u003cbr>之后我们每天用15分钟沟通，把一些还不完善的地方指出来，让她继续去进行优化，三天后我们就定稿了。\u003cbr>拿到组长那边去过稿的时候，组长很满意，于是我们利用接下来的几天时间，预备好了培训的其他设计，之后在公司内部做了一场很成功的培训，得到了一致好评。\u003cbr>而这位实习生之后也成了我很好的合作伙伴，我们还合作了一些其他的项目，彼此都很愉快。\u003cbr>\u003cbr>\u003cstrong>【Where适用边界】\u003c/strong>\u003cbr>就像这个例子一样，责任型授权其实不仅适用于上司对下属或者父母对孩子，也很适合平级之间的任务分配，让彼此都明确责任边界，合作起来也更加愉快。需要注意的是，被授权的对象一定是要愿意接受这个责任的，如果对方并不愿意接受，那么这个责任型授权就无法继续使用了。\u003cbr>\u003cbr>\u003cstrong>【异议预防】\u003c/strong>\u003cbr>可能有些小伙伴会说，这也太麻烦了吧？我真的觉得自己做还是更快更好吧？这样麻烦，真的能提高我的效能吗？\u003cbr>确实，责任型授权在初期是很费时费力的。\u003cbr>比起实习生，你自己做投影可能一个小时就做完了；比起孩子，你当然更有能力迅速把一间房间收拾得干净整齐；比起老公，你照顾孩子确实游刃有余。但你要想想，如果你总是自己做，那你得多累？而且一个人的时间有限，真的不可能什么都亲历亲为。\u003cbr>但如果用这个责任型授权，虽然初期花的时间和精力比较大，但一旦对方掌握了技能并且承担了责任，这件事就再也不需要你操心了，等于你投资了一段比较集中的时间，换来了以后的“一劳永逸”，这是不是很香呢？\u003cbr>(反例)\u003cbr>上周我盆友来跟我吐槽老公不帮忙带孩子，让她精疲力尽的时候，我跟她分享了责任型授权，让她试着在老公休息的时候，让老公有机会来学习一下怎么带娃。\u003cbr>结果周一就打电话跟我说没法用，我仔细问了过程发现，原来她只是把孩子交给老公，让他带一个下午，就直接出去了，回来的时候发现家里一团乱，孩子在旁边哇哇哭，老公已经快疯了。\u003cbr>那其实，责任型授权究竟该如何做呢？\u003cbr>\u003c/p>\u003cp>\u003cstrong> 【How】（具体怎么做呢-细化步骤）\u003c/strong>\u003cbr>我总结出了以下五个步骤：\u003cbr>第一步：预期结\u003cstrong>果（国）\u003c/strong>\u003cbr>责任型授权注重结果，所以一开始就要把预期的结果明确下来，让对方可以清楚知道自己要拿到什么结果。（我给实习生最终需要呈现的示例，让她看到最终结果应该长什么样子，并且约定一周后出初稿）\u003cbr>第二步：指导\u003cstrong>标\u003c/strong>准\u003cstrong>（标）\u003c/strong>\u003cbr>责任型授权注重被授权者的主观能动性，所以会给出评估的标准，但不会告诉对方具体的步骤，这部分要给对方自由发挥的空间。（我给实习生文字资料，让她知道要把这里的重点放到投影片里，但我并未划出重点，而是给她演示了一遍软件操作，让她自行筛选重要信息）\u003cbr>第三步：可用资\u003cstrong>源（圆）\u003c/strong>\u003cbr>既是授权，就一定有资源可用，所以告诉对方有什么资源可用，让对方担负责任的同时也得到支持。（我告诉实习生，有任何不明白的地方都可以来找我询问）\u003cbr>第四步：责任\u003cstrong>归\u003c/strong>属\u003cstrong>（规）\u003c/strong>\u003cbr>既然前面三步都已经明确，那么属于对方责任范围的内容已经明确，所以我们就不再随意插手。（比如我们约好了一周之后，也说好她有问题可以随时来问，那即使她不来，我也不再过问，而是去信任，因为责任在她）\u003cbr>第五步：明确\u003cstrong>奖\u003c/strong>惩\u003cstrong>（奖）\u003c/strong>\u003cbr>明确告知评估后的结果，让对方知道自己所担负的责任会引发什么后果，以及对他个人是否有什么奖惩措施，这里需要注意，有时候不是一定有额外的奖励或惩罚，事情成功或失败的自然后果也可以成为奖励或惩罚。（比如我们都知道两周后就要做培训，作为实习生，如果无法好好完成任务，势必会影响到考核成绩）\u003cbr>\u003c/p>\u003cp>（反例加工正例）\u003cbr>按照这五个步骤，前面盆友的例子，她其实可以这么做：\u003cbr>先跟老公说好目标是独立带娃4小时（一个下午），把娃平时下午要做的事告知老公：12点半午饭，1点出去饭后活动，2点到3点午休，3点到3点半吃点心，3点半开始，可以读一下绘本或者玩一下玩具，.很快妈妈就回来了。\u003cbr>这个部分就是结果约定和指导标准，具体如何吃，如何睡，如何玩，这些都交给老公自由发挥。\u003cbr>接下来很重要的是，资源方面要给足老公支持，比如午餐和点心都可以先准备好，让老公有资源可用，包括绘本或游戏，也可以让老公先挑好自己会的，减少重新学习的压力。最重要的是告诉老公，如果实在搞不定，可以得到自己什么支持，比如可以打电话给自己请教，这样的资源在一开始的时候是能大大降低难度的。\u003cbr>这些都交代好之后，朋友就可以出去做自己的事了，如果老公没有打电话求救，就不要去干涉，相信老公的能力，然后回来之后，按照之前说好的奖惩来实施即可。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】 学习者拆为己用 8分钟\u003c/strong>\u003cbr>\u003cstrong>【显像提问】\u003c/strong>\u003cbr>接下来，请大家认真想一想，在你过去，有没有发生过这些情况：\u003cbr>你晚上要加班，请老公辅导孩子作业，带孩子去睡，结果回来发现孩子作业没写完，正在看电视；\u003cbr>你把洗碗的工作交给孩子做，结果孩子碗洗不干净，还把水池弄得一团糟；\u003cbr>你因为忙不过来，把一个报告的工作分配给同事，结果报告写出来完全不合要求，你不得不周末加班自己做；\u003cbr>请大家思考30秒，当时是发生了什么事？你是怎么把任务分配出去的？结果如何？\u003cbr>然后我们来分享，每个人分享1-2分钟。\u003cbr>好了，接下来我们请X位伙伴来分享。\u003cbr>\u003cbr>\u003cstrong>【学习者分享】\u003c/strong>\u003cbr>黄老师：2月份有一个项目，里面有一些外购的电器件，其规格书还没有确定下来。当时给研发工程师一个期限，2月15日这些规格书要确定下来。但到了时间，发现结果不理想，连50%都不到。\u003cbr>\u003cbr>\u003cstrong>【A1+】（反思加工） 6分钟\u003c/strong>\u003cbr>既然我们今天学习了责任型授权五步法，那我们接下来就要学以致用了。\u003cbr>假如时间能倒流，再给你一次机会，你会如何应用责任型授权五步法，也就是国标圆规奖（预期结\u003cstrong>果\u003c/strong>-指导\u003cstrong>标\u003c/strong>准-可用资\u003cstrong>源\u003c/strong>-责任\u003cstrong>归\u003c/strong>属-明确\u003cstrong>奖\u003c/strong>惩）这五步来进行任务的分配呢？\u003cbr>给各位2分钟来思考一下，你可以按这五步来把关键词记下来，等一下我们请X位小伙伴来分享一下。\u003cbr>好，时间到，接下来我请X位伙伴来一一分享一下。\u003cbr>\u003cbr>\u003cstrong>【学习者分享】\u003c/strong>\u003cbr>预期结果：2月15日可以完成25项外购件规格书的审核确认\u003cbr>指导标准：公司有外购件规格书的模板，每一个外购件也有研发的需求规格\u003cbr>可用资源：研发团队相关的结构和硬件工程师，还有质量、采购包括供应商，如果需要组织会议的话，随时可以组织大家来开会，如果需要我帮忙组织会议，都可以叫我帮忙\u003cbr>责任归属：这25项外购件的规格书都由对方确定，如果搞不定就来找我，如果不找我，我就默认为对方能搞得定\u003cbr>明确奖惩：把这个工作作为季度重要工作，会把工作结果反馈到对方部门经理那里，作为一个绩效反馈\u003cbr>\u003cstrong>【回应反馈】\u003c/strong>\u003cbr>感谢黄老师的分享，可以在这么短的时间内可以把这五步做到这么好，在我看来，这五步都是蛮符合标准的，真的非常棒。\u003cbr>\u003cbr>\u003cbr>\u003cbr>\u003cstrong>【两个拆页之间的关系】1.5分钟-此处根据观察家意见进行了修改\u003c/strong>\u003cbr>通过第一个片段的学习，我们知道了如何把一个任务完整地授权出去，让对方可以得到清晰的任务目标、资源和奖惩。\u003cbr>但在实际情况中，有些被授权者可能很快可以胜任，但有些被授权者也许会遭遇困难和挫败，那么他们就会产生负面情绪，想要退缩，甚至撂挑子不干。\u003cbr>这个时候，授权者是否能够移情聆听，是否能够不去指责对方，而是处理好对方的情绪，鼓励对方继续承担责任，就非常影响到授权的结果。\u003cbr>所以，第二个拆页和第一个拆页是正反并列关系，当遇到被授权者不能胜任而产生负面情绪时，我们可以应用第二个拆页来进行移情聆听。\u003cbr>\u003cbr>\u003cstrong>【第二个片段学习目标】0.5分钟\u003c/strong>\u003cbr>那接下来我们要来通过第二个片段的学习，可以在有人带着负面情绪来与我们沟通时，使用移情聆听四步法，迅速与对方建立共情，达到有效沟通。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":19617,"quote":"\u003cp>\u003cstrong>【R】阅读原书拆页 2分钟\u003c/strong>\u003cbr>现在就请大家花两分钟时间一起来阅读这一段原文拆页，读完的小伙伴可以在聊天区敲1示意以下，剩30秒时我会提醒大家。\u003cbr>\u003cbr>主题书籍《高效能人士的七个习惯 》三十周年纪念版 页码：P264\u003cbr>拆页原文：\u003cbr>有效的沟通这个例子充分显示有效的沟通多么不易，了解他人又是多么重要。正确的沟通方式也就是移情聆听，至少包括四个阶段。\u003cbr>第一阶段是复述语句，这至少能使人专心聆听。\u003cbr>子:“上学真是无聊透了!”\u003cbr>父:“你已受不了了，觉得上学太无聊。”\u003cbr>第二阶段加入解释，完全用自己的词句表达，但仍用左脑的逻辑思维去理解。\u003cbr>父:“你不想上学了。”\u003cbr>第三阶段掺入个人的感觉，右脑发挥作用。此时听者所注意的已不止于言语，也开始体会对方的心情。\u003cbr>父:“你觉得很有挫折感。”\u003cbr>第四阶段是既加以解释，又带有感情，左右脑并用。\u003cbr>父:“你对上学有很深的挫折感。”\u003cbr>运用这四个阶段的方式沟通，不仅能了解对方，更能帮助对方认清自己，勇于表达。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导 8分钟\u003c/strong>\u003cbr>\u003cbr>好，接下来我就分享一下我对这个拆页的理解和体会。\u003cbr>\u003cstrong>【What】（这是一个什么概念）\u003c/strong>\u003cbr>拆页告诉用我们，移情聆听是正确的沟通方式，它至少包括复述语句、加入理解、加入情感、理性与情感结合这四个阶段。\u003cbr>\u003cbr>\u003cstrong>【Why】（为什么要这么做，这么做有什么好处，不这么做有什么坏处）\u003c/strong>\u003cbr>沟通是日常生活中最常见的行为，不管是在职场还是家庭中，我们都免不了需要与人沟通。\u003cbr>很多时候，对方和我们沟通的时候可能会带着一些负面情绪，这时我们可能会很容易急着纠正对方，急着澄清或防御，或者急着安慰对方，这就很容易让我们无法正确理解对方的意思，导致鸡同鸭讲，沟而不通，甚至到最后不欢而散。\u003cbr>\u003cbr>\u003cstrong> 【How】（细化步骤）\u003c/strong>\u003cbr>具体该如何做，可以让我们和别人迅速达到共情，让双方可以真正彼此理解，作出有效沟通呢？\u003cbr>接下来我们就一起来看看移情聆听的四步骤究竟具体是怎么做的：\u003cbr> 1. 复述语句（复）\u003cbr>重复对方的话，让对方感觉你把他的话听进去了。这一点很重要，因为我们往往急着辩驳或安慰，其实很多时候我们都没听明白对方在说什么。\u003cbr> 2. 加入理解（理）\u003cbr>加入了个人的理解去表达对方的意思，运用理性思维，将对方说的这句话进行理解，并表达出来。比如原文中的，孩子说上学真是无聊透了，父亲理解之后，说孩子不想上学了，看到了孩子这句话背后的想法。\u003cbr> 3. 加入情感（情）\u003cbr>加入个人感觉，情绪右脑开始发挥作用，体会\u003cstrong>对方\u003c/strong>心情，注意这里是要说出对方的情绪，去体会到对方在说这句话的时候，背后是什么情绪，比如孩子说上学无聊透了，父亲感受到孩子在上学这件事上有挫败感。\u003cbr> 4. 情理结合（合）\u003cbr>最后这个阶段就是既有理性的解释，也有带着感情，其实就是把前面的话结合起来，重复我们对对方话语本身和对背后情绪的理解。\u003cbr>\u003cbr>\u003cstrong>【案例说明】\u003c/strong>\u003cbr>我们家三岁八个月的哥哥，有时候不想去幼儿园，由于我们夫妻平时都赶着上班，早上没太多精力顾及他的情绪，一般都会直接说：“你必须去，爸爸妈妈都要上班。”然后硬是把他送去。但往往我们这么做之后，孩子都会哭得无法控制，即使我们狠心离开，我们自己心里也非常难受。\u003cbr>当我学习了这个方法后，我就想，这个方法可以试一试，于是我决定下次在遇到哥哥不想去幼儿园的情况，我就会使用移情聆听四步骤来跟哥哥共情。\u003cbr>我会这样跟哥哥说：\u003cbr>“你不想去幼儿园”（复述语句：表示我看到了他的想法）\u003cbr>“你不想和妈妈分开”（加入理解：暗示对方我理解他不想去的原因）\u003cbr>“你觉得很难过”（加入情感：体会到哥哥的心情）\u003cbr>&quot;去幼儿园会让你觉得很难过。“（理性与情感结合：将哥哥的情绪和造成这个情绪的原因都点明了）\u003cbr>后来果然有一天，哥哥又不愿意去幼儿园了，我就按照上述的计划跟哥哥说了这四句话，结果当我这么说的时候，哥哥就一直点头，因为他的情绪和需要被看到被理解了，所以他反而不哭闹了，和我黏一黏之后也愿意去幼儿园了，而且到了幼儿园之后也还是挺开心的，愿意跟着老师进去。\u003cbr>所以，可以看到，这个简单的方法在小孩子的身上都是很有效的，最重要的就是因为他的情绪和需要被看到了。\u003cbr>\u003cbr>\u003cstrong>【异议预防】\u003c/strong>\u003cbr>也许有小伙伴会说，这个对话看起来很简单啊，真的能够解决问题吗？\u003cbr>我一开始也是这么想的，就这个四个简单的步骤，能解决什么问题？\u003cbr>但我后来明白了，有一句话说：“先解决心情，再解决事情。”意思就是要先解决情绪，才能好好来解决事情。而这个移情聆听四步骤就是解决心情的这一个关键步骤，通过这一步，带有负面情绪的一方感受到了被理解和被接纳，他就愿意好好来沟通，并且愿意听你怎么说，那么你说的话才会有效。\u003cbr>\u003cbr>\u003cstrong>【Where适用边界】\u003c/strong>\u003cbr>所以，这个有效沟通的四步骤，非常适用于当别人有负面情绪的时候，可以帮助你迅速和对方建立起沟通的基础，不仅可以让你了解对方的想法，更能够帮助对方去认清自己，勇敢表达。\u003cbr>【不适用】但如果对方现在就是拿着一件客观的事实来和你讨论时，这个四步骤就不太适用，因为这个时候可以就事论事就好，不需要用到这四步骤。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】角色扮演\u003c/strong> \u003cstrong> 12分钟\u003c/strong>\u003cbr>接下来，为了促使大家更好的应用，我想请大家进行一次现场实战演练，练习一下我们刚刚学习的移情聆听四步骤。\u003cbr>\u003cstrong>【场景设计】\u003c/strong>\u003cbr>请设想这样一个场景：\u003cbr>最近由于你晚上要加班，辅导孩子写作业和洗漱睡觉的事都交给了配偶负责，你已经按照责任型授权五步法，把一切该交代的都交代清楚了。\u003cbr>过了三天，你晚上下班回来，发现孩子已经睡了，但配偶黑着脸坐在客厅，看到你之后，开口就跟你抱怨孩子真是太难搞了。\u003cbr>\u003cstrong>【给出清晰指令】\u003c/strong>\u003cbr>现在请大家针对上面的这个场景认真思考一下，当你遇到这个情况，你会如何回应呢？请大家按照今天学习的这个移情聆听四步骤来进行回应，并且，我们这个对话要进行三轮，也就是说，配偶抱怨，你回应，配偶继续还有一些抱怨，你继续回应，最后配偶还是有些负面情绪，你继续回应，并且鼓励配偶继续把这个责任坚持下去。\u003cbr>现在给大家8分钟时间，大家在这里进行思考和讨论，如何可以结合我刚才分享的“复理情合“的移情聆听四步骤来安抚配偶，并且鼓励对方继续，帮助他真正承担起这个责任来。\u003cbr>最后我会邀请两位小伙伴，来进行这个对话的一个角色扮演。\u003cbr>\u003cbr>\u003cstrong>【学习者演练记录】：\u003c/strong>\u003cbr>\u003cstrong>妻子：\u003c/strong>孩子太难搞了\u003cbr>\u003cstrong>丈夫的移情聆听：\u003c/strong>\u003cbr>你刚刚说孩子太难搞了，对吗？\u003cbr>你觉得在辅导学习的时候，他们总是来麻烦你，所以你觉得很麻烦或很痛苦，对吗？\u003cbr>是的，我也有体会，辅导孩子作业的时候，我总是会被无奈和无助包围，孩子真的太难搞了，你也是这样的吗？\u003cbr>要不这样吧，下周我申请早点下班，我来给孩子辅导，让你可以有一个缓和的时间，可以吗？\u003cbr>\u003cstrong>【回应反馈】\u003c/strong>\u003cbr>很棒的演练，我在刚才的演练中可以看得出来，丈夫很想安抚妻子的情绪，做了共情，最后也想了一个解决办法，真的是很好的丈夫。\u003cbr>那我们其实按照移情聆听四步骤，这个对话其实没有那么复杂。\u003cbr>比如说，当妻子说：孩子真是太难搞了。\u003cbr>那么丈夫首先复述对方的话就是说：“哦，你觉得孩子太难搞了，对吗？”这是表示我们听见了对方说的这句话。\u003cbr>理解部分：“你觉得带他们很不容易，你觉得辅导他们很辛苦，对吗？“\u003cbr>情感部分：“你觉得辅导他们的过程中，会有一些挫败感吗？或者会有一些焦躁吗？或者会觉得很累，很不耐烦吗？“\u003cbr>情理结合：“因为你觉得辅导孩子的过程中，他们总是来问你，你觉得很辛苦、很累，所以你就会感觉到非常焦躁和不耐烦，是这样的吗？”\u003cbr>我们停留在这里就可以了，不需要去寻找解决问题的方案，因为当对方有情绪的时候，我们所要说的和做的就是去鼓励她。\u003cbr>\u003cbr>\u003cbr>\u003cbr>\u003cstrong>【A2】催化应用(分步催化1) \u003c/strong> \u003cstrong> 6 分钟\u003c/strong>\u003cbr>【拆书家提问】\u003cbr>接下来，为了促使大家更好的应用移情聆听四步骤，大家可以试着想象一下，未来的一周或一个月内，你会不会遇到身边有人带着负面情绪来找你说话的场景？比如：\u003cbr>孩子跟你抱怨：“我那个班主任真是好讨厌！”\u003cbr>配偶下班回来，跟你说：“我真的不想去上班了！”\u003cbr>朋友来跟你抱怨：“我又被家里催婚了，太烦了！”\u003cbr>大家可以试着想象一下，未来的一周或一个月内，你可能会遇到的负面沟通的场景，这个场景是怎么样的？也许这个场景是你一直反复遇到的，将来还可能会再发生，你也可以写下这个场景，试着在便签上写下关键词，30秒之后请三位小伙伴分享一下。大家请留意，只需要分享这个场景就可以，暂时还不需要分享你会如何做。\u003cbr>\u003cstrong>【学习者案例记录】：\u003c/strong>\u003cbr>黄老师的案例：\u003cbr>小朋友回来气鼓鼓地说：”我再也不要和xxx玩了，他太讨厌了！”\u003cbr>\u003cbr>\u003cstrong>【回应反馈】\u003c/strong>\u003cbr>这真的是一个很常见的场景，很棒的生活化场景。\u003cbr>\u003cbr>\u003cstrong>【A2】催化应用(分步催化2) 5分钟\u003c/strong>\u003cbr>好的，刚才小伙伴们都已经分享了自己想象的将来会遇到的负面沟通的场景。接下来，大家可以根据刚刚自己写下的那个具体场景，设想一下，如何运用今天学到的“移情聆听四步骤：复述语句、加入理解、加入情感、理性与情感结合”的方法来回应对方，让对方感受到被你听见和理解呢？\u003cbr>给大家1分钟时间思考和预备一下，想一想在那个场景中，你会如何回应对方呢？就像我之前所举的例子一样，我就预先把自己到时候要对哥哥说的话想好了，等又遇到这个情况时，就照着说。大家也可以写下关键词语或整个句子，稍后我们请X位小伙伴来为我们分享一下。\u003cbr>\u003cbr>\u003cstrong>【学习者案例记录】：\u003c/strong>\u003cbr>\u003cstrong>复：\u003c/strong>“你不想和xx一起玩了，他太讨厌了，对吗？”孩子应该会点头同意\u003cbr>\u003cstrong>理：\u003c/strong>“你觉得他说话伤害了你，或者透露你的秘密给其他人，或者踢了你一脚，是有这样的情况吗？”孩子可能会说是的，然后透露一个情况\u003cbr>\u003cstrong>情：\u003c/strong>“你觉得他伤害到了你，也没有尊重你，所以你感到很生气，很伤心难过，对吗？”这句话可能会抱着他来说。\u003cbr>\u003cstrong>合：\u003c/strong>“因为他做了伤害你的事，所以你觉得很难过，爸爸也能体会到这种心情，来，我们抱一抱。”\u003cbr>\u003cstrong>【回应反馈】\u003c/strong>\u003cbr>哇，好棒好棒！给黄老师鼓掌，这个应用真的很棒！我相信小朋友被你这样问，最后还有抱抱的时候，他心里一定会非常柔软，感觉到被爸爸看见了，而且爸爸接纳了他的这个情绪，而且也听明白了他的意思，并没有去责备或者说教。\u003cbr>那个感觉真的是很不一样，我都很感动了，真的要特别给黄老师点赞。\u003cbr>\u003cbr>\u003cstrong>【结束语】1分钟\u003c/strong>\u003cbr>今天我们学习了责任型授权五步法，这是我们每个人都会遇到，并且若想要提高效能，我们必须学会这个方法，将一个责任真正授权出去。\u003cbr>但这个方法初期是费时费力的，其中很主要的费力就是对方可能会产生负面情绪，需要我们的鼓励，于是我们的移情聆听四步骤就很重要，它可以帮助对方感受到我们和他是一条战线，去面对眼前的挑战。\u003c/p>\u003cp>\u003cstrong>所以，掌握责任型授权五步骤，再加上移情聆听四步法，这个5+4组合，就可以助你脱离凡事亲力亲为的困境，朝着高效能人士迈出一大步！\u003c/strong>\u003cbr>感谢大家今天的聆听和参与，今天的拆书就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1681198883000,"updated_at":1681569701000,"ria":true},{"id":15017,"topic":"消除烦恼的第一步","learn_goal":"","remark":"线上过级","level":"TF1-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"芷旭","city":""},"club":{"name":"昆明春城分舵","city":"昆明"},"prologue":"\u003cp>大家好，我是来自德国的汪芷旭，汪洋大海的汪，草字头加停止的芷，旭日东升的旭。我的名字左边很多水，右边很多阳光，中间是草。这三个字也代表着我的三个标签：\u003cbr>首先，我很有韧劲儿，正如水滴石穿，我也是一个坚持和不放弃人；\u003cbr>其次，我很有能量，好像旭日一样有朝气;\u003cbr>最后，我注重追求平衡，水和阳光是青草生长的必需品，但如果太多了，草也会停止生长的，所以我也不断在学习平衡成长，因此，我的拆书方向主要也是自我成长和自我管理。 \u003c/p>\u003cp>接下来给大家介绍一下拆书帮。\u003cbr>拆书帮是一个非营利组织，由帮主赵周老师创立，拆书帮的使命就是培养拆书家。\u003cbr>拆书家是一群学习促进者，通过赵周帮主独创的便签法，将书籍中的知识拆为己用，同时也引导和促进一群人把知识拆为己用。\u003cbr>拆书法是一种以解决问题为目标的成人学习法，以学习者为中心，通过RIA便签法让学习者真正做到把知识变成解决问题的可执行方案。\u003cbr>这个RIA便签法，就是从书中选择一个拆页进行阅读，解释这个知识点，激活学习者的经验和反思，再催化学习者制订行动方案，这样就可以帮助一个人快速地把书中的这个知识掌握和应用。\u003cbr>我在2022年12月便签训练营毕业之后拜入范范姐门下，进入了昆明春城分舵继续学习，希望能够不断将书中的知识拆为己用，和小伙伴共同成长。\u003c/p>","ratings_count":1,"texts":[{"id":19022,"quote":"\u003cp>那现在就由我来带领大家拆解一下今天的片段，今天我选择的片段是《高效能人士的七个习惯 》三十周年纪念版中的一段，页码是101-102页。\u003cbr>下面我们花1分半的时间看一下原文片段，如果你阅读完毕，请在聊天区敲1。\u003cbr>现在我们开始安静阅读，还剩30秒的时候，我会提醒一下。\u003c/p>\u003cp>拆页原文：\u003c/p>\u003cp>直接控制、间接控制和无法控制\u003c/p>\u003cp>我们面对的问题可以分为三类:可直接控制的(问题与自身的行为有关)，可间接控制的(问题与他人的行为有关)和无法控制的(我们无能为力的问题，例如我们的过去或现实的环境)。对于这三类问题，积极主动的人都是由影响圈着手，加以解决。\u003c/p>\u003cp>可直接控制的问题:可以通过培养正确习惯来解决，这显然在影响圈范围内，本书第二部分“个人领域的成功”中讨论到的习惯一、二、三即属于这一类。\u003c/p>\u003cp>可间接控制的问题:可以通过改进施加影响的方法来解决，例如采取移情方式而不是针锋相对，以身作则而不是口头游说。这在第三部分“公众领域的成功”的习四、五、六中有所论述。\u003c/p>\u003cp>无法控制的问题:我们要做的就是改变面部曲线，以微笑、真诚与平和来接受现实。纵使有再多不满，也要学着泰然处之，这样才不至于被问题左右。匿名戒酒组织鼓励成员的祷词是这样的:\u003c/p>\u003cp>上帝啊，请赐我平静的心去接受我无法改变的，请赐我勇敢的心去改变我能够改变的，请赐我智慧的心去辨别它们。\u003c/p>\u003cp>不论是能直接控制的、间接控制的还是无法控制的问题，解决的第一步都掌握在我们自己手里。我们可以改变习惯、手段和看法，而这些都属于影响圈范围。 \u003c/p>","explains":"\u003cp>好的，我们读完了这一段拆页，接下来我就来简单说说这段拆页都讲了什么： \u003c/p>\u003cp>我们每个人的生活中都会面对大大小小的问题，而这个拆页就给我们介绍了一个对这些问题进行分类的方法，按照不同的维度可以把问题分成可直接控制的，可间接控制的和无法控制的三类。\u003c/p>\u003cp>如果我们使用这个方法，就可以把目前引发我们心烦或者压力的问题进行梳理，然后根据分类去采用合适的应对方法，而不是被诸多问题缠绕，因为无能为力而产生沮丧感，从而意志消沉，连自己原本能够控制的影响圈也放弃了。\u003c/p>\u003cp>这个方法其实就是把问题按照可控程度进行分类：\u003c/p>\u003cp>第一类：可直接控制。\u003c/p>\u003cp>这一类的问题与我们自身的行为有关，只要我改变我的行为，养成正确的习惯，就可以解决，比如说我的情绪，我可以通过学习提升自己的情绪管理能力来解决。\u003c/p>\u003cp>第二类：可间接控制。\u003c/p>\u003cp>这一类的问题与他人的行为有关，我无法仅通过改变自己来解决，而是要通过改进施加影响力的方式来解决，比如说，对方惹我生气，我无法改变对方，但我可以通过正确的表达方式来影响对方。\u003c/p>\u003cp>第三类：无法控制的。\u003c/p>\u003cp>这一类的问题是我们无能为力的问题，我做什么都改变不了，比如说我无法决定我的出身，我也无法改变当下的yq。这一类的问题，我能做的就是以平静的心去接受现实，学着泰然处之，做到不被问题影响我。\u003c/p>\u003cp>因此，这个方法非常适用于当我们感觉到心烦意乱的时候，或者觉得生活中一团乱麻、无从下手的时候，用来梳理这些问题，找到自己可以做的事。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>好，这个拆页具体如何应用到我们的生活中去呢？\u003c/p>\u003cp>我来跟大家分享一个我最近的经历。\u003c/p>\u003cp>最近我在做我人生中的第一个课程，进入12月的时候，我突然感觉到非常焦虑。\u003c/p>\u003cp>按照原定计划，我需要在12月初开始着手去打磨课程大纲，搜集素材，在12月10日就要出课纲了。我当时突然感觉到很大的压力，快要把我打垮了，我觉得课纲好难，我的素材太多了，我不知道怎么整理；另外一方面，我也很担心，我的这些知识有人想听吗？别人会不会觉得都是学过的，没什么意思？我要怎么做，才能让每个人都觉得有收获？越想越觉得自己的东西拿不出手。\u003c/p>\u003cp>这些问题困扰着我，让我裹足不前，每天都在内耗，到了12月10日该出大纲的时候，我什么也没有，然后我因此更加沮丧，因为我该做的事也没做好。\u003c/p>\u003cp>12月18日，我终于安静下来，使用了这个片段里的分类法，把我当下困扰的问题一一梳理和分类。我当时是这么做的：\u003c/p>\u003cp>我当时觉得很难的问题中：\u003c/p>\u003cp>我自己能够控制的，就是去把我所有从课程和书籍里的来的素材进行整理和归类，然后总结知识点，先把课纲的初稿列出来。\u003c/p>\u003cp>我还能控制的是，每天花2个小时来专门做这件事。\u003c/p>\u003cp>这两件事，我需要好好预留时间，专心去做，只要每天花时间做，就可以出结果。\u003c/p>\u003cp>我能够影响的事，在当时是没有的，因为我不需要跟任何人去沟通和合力。\u003c/p>\u003cp>至于其他我所担心的那些问题，别人会如何看待我的课程等等，这些都是没有出课程之前，我控制不了的事，我把它们归类到我在写大纲阶段无能为力的事，所以我得学着先把这些忧虑放下，让自己不被它们影响到。\u003c/p>\u003cp>当时整理完毕之后，我就开始专心每天花2小时来进行知识点的整理，结果20日那天我就把我的课纲初稿给写好了。\u003c/p>\u003cp>反思：\u003c/p>\u003cp>当时使用这个方法，帮助我理清了思路和当下该做的事，专心在自己力所能及的事上，积极主动，结果两天时间就完成了该做的事。\u003c/p>\u003cp>这个方法很有效地帮助我迅速区分出当下可以做的事，让我可以减少焦虑，专心在自己的专注圈。\u003c/p>\u003cp>这个方法非常有效，所以在以后的实际生活中要提前运用，减少无谓的内耗\u003c/p>\u003cp>A2：\u003c/p>\u003cp>生活中的问题每天都有，现在我的课程海报已经做好了，也开始发售了，但新的问题又出现了：\u003cbr>我该怎么来每天在朋友圈去发售？\u003cbr>我的课程逐字稿要如何完成？\u003cbr>我的训练营最终设计要如何？\u003cbr>我最后能招到多少学员？\u003cbr>来报名的人会从这个课程里得到收获吗？\u003cbr>她们会喜欢吗？\u003cbr>我要如何服务好她们？\u003cbr>训练营后续还能提供什么服务，好让这些学员愿意继续和我一起成长呢？\u003cbr>我能做得成这件事吗？\u003cbr>那这些问题是我过去这一周想得比较多的，它们也带给我一些压力，但我不希望又陷入沮丧和焦虑中去，于是我决定再次使用这个分类法来帮助自己聚焦影响圈。\u003cbr>我的目标是：在月底之前整理好这些问题，把它们分类，然后根据不同的类别采取不同的措施方法，专注影响圈，做好自己力所能及的事。\u003cbr>我的具体计划是：\u003cbr> 1. 今天晚上9点-10点，把上面列出的这些事情进行分类，然后把“我无法控制的“找出来，把它们暂时清理出我的大脑。\u003cbr> 2. 明天上午10点-11点，把所列出来的“我可以直接控制的”和”我可以间接控制的“两大类，根据这个方法制定出我接下来6天的待办事项和时间计划，然后打印出来，按进度完成。\u003cbr> 3. 1月3日招生结束后复盘自己这次的进步 \u003cbr> \u003cbr>\u003cbr>那这个就是我接下来的具体计划，最后我来总结一下今天的拆书：\u003cbr>我们今天学习了一个将生活中的问题进行分类的方法，这个分类可以帮助我们迅速定位关注圈和影响圈，把问题进行划分之后，我们可以用正确的态度去面对各种问题，专注在影响圈，通过积极表达扩大影响力，以及笑对那些我们无力改变的事，接纳它们，放过自己。\u003cbr>好了，我今天的分享就到此结束了，希望这个片段会对各位小伙伴有帮助。\u003cbr>谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1673203968000,"updated_at":1673350006000,"ria":true},{"id":15004,"topic":"要事第一","learn_goal":"","remark":"【学习目标】\n学会如何以“重要不紧急”事物为中心的日程安排，避免周而复始的陷入不重要的琐事","level":"TF2-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"嘉璇","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家晚上好，我是李嘉璇，在北京土生土长，曾经在互联网公司工作15年，工作内容基本与互联网广告运营相关，去年年底集齐BAT（百度，阿里，腾讯）就退出互联网江湖，跨入抗衰老领域自主创业。很开心今年7月份正式加入宇宙中心分舵，作为一个新手拆书家，愿意和分舵的小伙伴们一起精进成长。\u003c/p>\u003cp>\u003cstrong>【书籍简介】\u003c/strong>\u003c/p>\u003cp>今天为大家分享的片段来自于《高效能人士的七个习惯》\u003c/p>\u003cp>F:《高效能人士的七个习惯》是全球知名管理大师史蒂芬·柯维的企业管理著作，该书讲述了品行修养，为人处事的技巧。高效能人士中的七个习惯是个整体，相辅相成，是一个人“从依赖到独立，又从独立到互赖”的心灵成长历程。\u003cbr>\u003cbr>A:\u003cstrong> \u003c/strong>此书是“20世纪最具影响力的经济类书籍”，在全球70个国家以32种语言畅销发行出版30年，可以说是商界、管理界最著名的教材之一，影响了数以万计的政治家、企业家、以及各行各业的优秀人士，稳居各大书店最畅销书籍排行榜。\u003cbr>这本书与同类管理类书籍相比，强调了两个重要的关键词，一个是「效能」，一个是「习惯」，书中不仅阐述了正确的观念意识和思维方式，更提供了详细可操作的方法和工具，这七个习惯，也可以说是提升我们人生效率的最重要的原则。\u003cbr>\u003cbr>B1:有时候我们总会感慨，为什么别人能够进步飞速，而自己总是原地踏步，或者是觉得生活没有目标和方向，整天浑浑噩噩。这本书就帮我们总结出那些高效能人士最核心的七个行为习惯，从个人确立目标，进行个人修炼，实现“个人领域成功”。到通过建立共赢，换位沟通，集思广益等，促进团队沟通与合作,实现“公众领域的成功”，可以说适合每一个对现状不满意，想要突破和成长的个人和团队。\u003cbr>\u003cbr>B2: 对于时间管理大家都不陌生，但也经常会觉得每天周而复始的忙碌，做事效率却很低，想做的事情做的不理想或者完全没有做，久而久之，就容易焦虑茫然甚至EMO。今天我们所分享的内容来自于这本书的第三个习惯《要事第一》，这个原则可以让我们对时间、对自己进行有效的管理，出一个脚印的完成自己设定的目标。\u003cbr>\u003cbr>【学习目标】\u003c/p>\u003cp>通过今天线上拆书分享，希望能让大家在繁忙的生活和工作中，找到现阶段“重要的事”，并根据4个步骤制定具体的“行动周计划”\u003c/p>","ratings_count":1,"texts":[{"id":19007,"quote":"\u003cp>《高效能人士的七个习惯》P105\u003cbr>\u003cbr> 虽然我的工作主要是教授高效率的原则性问题，一般不讲授具体的实施计划，但我认为，如果能够以原则为基础，以第二类事物为生活中心，对一个星期内的事务进行具体安排，将有助于更好地理解第四代时间管理方法的原则及其巨大潜能。\u003cbr>以第二类事物为中心的日程安排，需要以下四个关键步骤：\u003cbr>\u003cbr> \u003cu>\u003cstrong>确认角色 第一步就是写出你自己的关键角色\u003c/strong>\u003c/u>，作为一个个体，你有属于自己的各种角色，你可以先写下自己在家庭中的角色，然后再写下自己在工作中的角色，列举自己想要了持续投入时间和精力去做的一些事情。你不必想得太复杂，只要考虑自己下一周的角色和任务，记下这七天时间里需要专注的领域即可。\u003cbr> \u003cu>\u003cstrong> 选择目标 第二步就是思考下一个周计划中每一任务栏下你最想做的一两件要事，作为你选定的目标 \u003c/strong>\u003c/u>这些目标中一定要有几个第二类事务，最好让这些短期目与使命宣言中的长期目标相关联。即使你还没有撰写个人使命言，也可以根据自己的感觉来判断每个角色中哪些事情是比较要的，并为每个角色确立一或两个目标。\u003cbr> \u003cu>\u003cstrong>安排进度 第三步是为每一项目标安排具体的实施时间。\u003c/strong>\u003c/u>如果你的目标是起草自己的个人使命宣言，那就不妨在星期天安排两个小时专门做这件事情。通常星期天是进行个人思考和制订个人成长计划的理想时间，因为这时候你有充足的时间思考，反省，寻求灵感，并根据各项原则和价值观来审视自己的生活。\u003cbr>确认角色并制定目标后，你就可以把每项任务分配到一个星期中某个具体的日子去做了。或者将它列为一项重要活动，或者列为一个特别约会。\u003cbr> \u003cu>\u003cstrong>每日调整 使用这种以第二类事务为中心的周计划以后，你就会发现原来的每日计划变成了每日调整\u003c/strong>\u003c/u>，即根据突发事件，人际关系的意外发展及崭新机会对每天的要务安排进行适当调整，当你每天早晨审视自己一天的日程安排的时候，你会看到由于内心的平衡，自己已经为角色的目标和进行了合适的优先排序，这种日常安排是灵活的，是右脑运作的结果，是建立在自己对个人使命的认知的基础上的。\u003c/p>","explains":"\u003cp>在开始拆解片段之前，我们先来看一段小视频（播放“重要的事”小视频）\u003c/p>\u003cp>今天给大家分享的片段来自于7个好习惯的第3个习惯——要事第一\u003c/p>\u003cp>顾名思义，就是优先去做重要的事，那到底什么才是重要的事呢？我给家里交电费是么？处理一个公司客户投诉？在家刷剧刷视频？\u003c/p>\u003cp>［反例]我先来给大家分享个我自己的例子，对于直播这件事，我一直觉得作为一个自主创业的人，非常需要通过互联网去传播很多的信息，并且要打造个人的IP。但之前我习惯用清单的方式，列一列最近要做的事。到最后总被各种各样的琐事占用了时间，计划也赶不上变化，直播的事情就一拖再拖，不了了之。有时看到别人直播，就会有些懊恼和自责，这明明是我从去年就应该开始做了事情，却到现在都一直没有开始。\u003c/p>\u003cp>［通常行为＋不这样做的坏处］\u003c/p>\u003cp>很多人都知道的时间管理四象限，也懂得应该先做重要的事，但还是习惯先处理紧急的事情和琐碎的事情，觉得这些都处理好了，才能理清思绪静下心来认真开始做重要的事。紧急的事情迫在眉睫，不得不处理，这样的事情多了就感觉每天就是在扑火，而且临时抱佛脚又很容易忙中出错，影响最终结果。琐事又怎么也忙不完，每天疲于奔命，只能借助不重要不紧急的事情逃避现实，放松自己。把大多时间花在不重要的琐碎事情上，就会觉得忙活了半天似乎什么都没干，很容易产生焦虑的情绪。还总说“我没时间”。\u003c/p>\u003cp>所以大家最容易忽略的其实就是重要且不紧急的第二象限，虽然非常重要，但是因为没有迫在眉睫，所以总是避重就轻，无限拖延，我们常说deadline是第一生产力。平时没有安排足够的时间去做重要不紧急的事情，拖来拖去，到最后就会把事情发展成紧急重要的事情。\u003c/p>\u003cp>［WHAT＋HOW+正例]\u003c/p>\u003cp>这里的“要事”指的是重要不紧急，是在中长期能够显现效果的但短期看起来不紧急也似乎没有什么成果的事，比如:健身读书，考前一个月的复习，给家人的陪伴等。我们平时需要安排好足够的时间去做重要不紧急的事情。\u003c/p>\u003cp>懂得要是第一的观念，那我们最需要去做的就是付出行动，先从自我管理开始。我们可以按照以下四个关键步骤，对重要的事情进行周计划。\u003c/p>\u003cp>在学习了这个方法以后，我12月初给自己定了一周的计划，把直播这个重要任务加入到其中。\u003c/p>\u003cp>1.确认角色——在生活和工作中，我们扮演着不同的角色，可以是负责督促孩子学习的妈妈，可以是项目负责人，也可以是活动组织者。拿我自己来说，我就有如下角色。\u003c/p>\u003cp>2.选择目标——接下来的一周，每一个角色的任务里最想做的一两件重要不紧急的事情，最好是可以跟中长期目标相结合。\u003c/p>\u003cp>3.安排进度——为选好的每件要事安排具体的时间。根据自己日常的时间规律，尽量安排在可以自由支配时间的时间段。首先列出每天三件重要的事情，然后细分小时粒度，安排这些重要事情的具体时间段。\u003c/p>\u003cp>4.每日调整——在实际的执行过程中，会有一些突发事件和特殊情况要进行调整。可以每天早晨再把当天的日程安排下，有一个核心思路就是，还是要在这周内来既定的任务完成。比如12月5日的录制小视频，因为团队的临时电话会，从11点调整到了14点。\u003c/p>\u003cp>以上是我们要事第一周计划，除此以外，建议等这个星期结束的时候再进行一次复盘。回顾一下各个角色下这周的任务是否都有完成。为下一周计划做准备。\u003c/p>\u003cp>我们今天分享的主要是针对于个人管理，如果是运用到团队领域的话，还涉及到任务的分配以及授权。如果大家有兴趣，可以从这本书里面去看更多的方法，我们今天在这里就不展开来讲。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>请大家想一想，有什么事情是能够让你的个人生活或者工作有所改观，比如家庭关系、身体健康、工作效率等，但是你一直没有去做的？(尤其是那种是你长时间觉得应该做，但是一直没有开始或坚持了不久，就会在内心非常的纠结，甚至会有自责的情绪) 当时你是用什么方式计划的，之后又是什么原因没有完成？\u003c/p>\u003cp>\u003cstrong>A1+：\u003c/strong>对于刚才想到的那些重要的事情，如何用今天学到的4个步骤制定一个周计划？立刻就开始“要事第一”\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>学员——杰瑞姐姐:\u003c/p>\u003cp>重要的事情：一直觉得健身（瑜伽 冥想 八段锦）是对身体健康非常重要的事，目前除了瑜伽跟着老师可以一周坚持五天，冥想和八段锦都没有坚持，找不到合适的时间，也怕自己练练不好走火入魔。平时也有安排在日程里，但是到时间就胡思乱想，就没有执行。\u003c/p>\u003cp>1.确认角色——自己健康的第一负责人\u003c/p>\u003cp>2.选择目标——坚持健身（瑜伽 冥想 八段锦）\u003c/p>\u003cp>3.安排进度——每日要务都有健身，希望形成一个习惯。工作日安排在8:00-9:00\u003c/p>\u003cp>4.每日调整——孩子周末去培训班，有可能需要调整。调整到晚上8:00\u003c/p>\u003cp>反馈：每日调整一般是突发事件，如果是比较有规律的，建议避开这些时间，安排在可以自由支配的时间。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>同样公平的没人每天24小时，有人进步神速，有人原地踏步，有人可以遇到更好的自己，有人却日迷茫焦虑。最大的差别就是我们是否能够每天花时间在中长期有价值的重要的事情上。希望大家通过今天的分享学习，能够立刻行动，做好下周的“要事”执行计划。明确自己的角色和下周重要任务，安排好具体的日期和时间去做，并根据时间情况，每天早晨对当日计划进行适当调整。\u003c/p>\u003cp>养成“要事第一”的好习惯，我们就在“个人成功”上跨进了一大步。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1673059588000,"updated_at":1673502422000,"ria":true},{"id":14975,"topic":"移情聆听","learn_goal":"","remark":"移情聆听是一种有效的沟通工具，是以尊重对方为前提的聆听，在情感和理智上都可以充分的理解和尊重对方，使对方能打消顾虑，畅所欲言，从而达到沟通的效果。","level":"TF1-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"周梦梦","city":"郑州市"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp> 爱学习的小伙伴们平安,感谢大家来参加我的线上练级活动我是新手拆书家梦儿。\u003c/p>\u003cp>\u003cbr> 用三个标签介绍一下我自己：家庭教育指导师，终身学习践行者，新手拆书家。\u003cbr> 在教培行业深耕8年,擅长培训机构的运营和管理工作,2023年最重要的目标就是成为三级拆书家,欢迎小伙伴们监督我完成目标’\u003c/p>\u003cp>\u003cbr>\u003cstrong>【分组】\u003c/strong>本次分享将有分组讨论环节，大家将分为2组，届时会邀请大家进组，欢迎大家到时候积极参与。\u003cbr> \u003cstrong>\u003cem>\u003cu>【技能点2：对现场学习者进行了分组。】线下\u003c/u>\u003c/em>\u003c/strong>\u003cbr> \u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>【技能点2：用会议软件对学习者进行分组，并加入各小组讨论。】线上\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp> 今天我给大家分享的片段来自《高效能人士的七个习惯》。\u003cbr> 作者是史蒂芬•柯维,是美国学界的”思想巨匠”,被《时代周刊》评为”人类潜能的导师”.\u003cbr> 书中介绍了”高效能人士的七个习惯”的行动建议和实践方案,以帮助读者加深对这”七个习惯”的理解和掌握.使这”七个习惯”成为每个人自己的行动指南.\u003c/p>\u003cp> \u003cstrong>\u003cem>\u003cu>【技能点3：选择图书是实用类或理论类图书。】\u003c/u>\u003c/em>\u003c/strong>\u003cbr> \u003c/p>\u003cp>\u003cstrong>\u003cem>接下来，我们用一分钟的时间来阅读一下原文片段，阅读完的小伙伴在聊天区回复1给我示意一下。\u003c/em>\u003c/strong>\u003cbr> \u003c/p>","ratings_count":3,"texts":[{"id":18976,"quote":"\u003cp> 《高效能人士的七个习惯》P266\u003cbr> 有效的沟通\u003c/p>\u003cp>\u003cbr> 正确的沟通方式也就是移情聆听,至少包括四个阶段’\u003cbr> \u003cstrong>第一阶段是复述语句,这至少能使人专心聆听.\u003c/strong>’\u003cbr> 子:”上学真是无聊透了!”\u003cbr> 父:”你已经受不了了,觉得上学太无聊.”\u003cbr> \u003cstrong>第二阶段加入解释,完全用自己的语句表达,但仍然用左脑的逻辑思维去理解.\u003c/strong>\u003cbr> 父:你不想上学了.\u003cbr> \u003cstrong>第三阶段掺入个人的感觉,右脑发挥作用.此时听着注意的已不止于言语,也开始体会对方的心情.\u003c/strong>\u003cbr> 父:”你觉得很有挫败感.”\u003cbr> \u003cstrong>第四阶段是既加以解释,又带有感情,左右脑并用.\u003c/strong>\u003cbr> 父:”你对上学有很深的挫败感.”\u003c/p>\u003cp>\u003cbr> 运用这四个阶段的方式沟通,不仅能了解对方,更能帮助对方认清自己,勇于表达\u003c/p>\u003cp> \u003cstrong>\u003cem>\u003cu>【技能点4：所选拆页包含有具体行动或做法。】\u003c/u>\u003c/em>\u003c/strong>\u003cbr> \u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>【技能点5：拆页内容未超过 2 页图书内页。】\u003c/u>\u003c/em>\u003c/strong>\u003cbr> \u003c/p>","explains":"\u003cp>\u003cstrong>\u003cem>我看大家都读完了，感谢大家的反馈，下面谈一谈我对这个片段的理解。\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>WHAT:\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cu>这个片段讲述了一种有效沟通的方法,也就是-----移情聆听,是指以理解对方为目的的聆听，要在情感和理智上都可以充分而深入地理解对方。\u003c/u>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>Why\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cu>移情聆听可以满足个人被看见、被理解、被尊重的心里需求，能让对方打消顾虑，勇于表达自己的真实想法。\u003c/u>\u003c/p>\u003cp>\u003cu>不懂得移情聆听的人在沟通的过程中急于打断对方的陈述，热衷于给出自己的意见，对方觉得不被认可，容易闭口不谈，使谈话陷入僵局，从而导致谈话的失败。\u003c/u>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>移情聆听的具体做法是什么呢，我们一起来学习一下吧！\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>How\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一阶段：复述对方的原话。\u003c/strong>\u003c/p>\u003cp>认真聆听，找到对方的关键词或者句子进行复述。\u003c/p>\u003cp>\u003cstrong>第二阶段：加入解释。\u003c/strong>\u003c/p>\u003cp>用自己的语言表达对方的语言。\u003c/p>\u003cp>\u003cstrong>第三阶段：体会心情。\u003c/strong>\u003c/p>\u003cp>带入对方的角色，体会对方的心情。\u003c/p>\u003cp>\u003cstrong>第四阶段：综合陈述。\u003c/strong>\u003c/p>\u003cp>带入感情地诠释对方的心情和感受。\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>Where\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cu>移情聆听适用于各种关系的改善与增强。当有人向你抱怨或吐槽时，可以用移情聆听的方式让对方畅所欲言，表达出自己的真实想法。移情聆听是属于两个人之间的私密谈话，人多的话就无法进行移情聆听。\u003c/u>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>案例\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cu>去年6月份，孩子们中午放学的时候，我的一个学生看见我，一头扎进我的怀里就哭了起来，看她伤心的样子，特别心疼，把她带到了我的办公室，看看她到底是怎么了。\u003c/u>\u003c/p>\u003cp>\u003cu>我：你怎么了？发生什么事了？\u003c/u>\u003c/p>\u003cp>\u003cu>她;梦梦老师，同学们冤枉我，我不想去上学了。\u003c/u>\u003c/p>\u003cp>\u003cu>我：同学们冤枉你了，所以你不想去上学了。→复述对方的原话\u003c/u>\u003c/p>\u003cp>\u003cu>我：同学们冤枉你这件事情，让你很崩溃。→加入解释。\u003c/u>\u003c/p>\u003cp>\u003cu>我：你现在感觉很伤心，因为同学们冤枉了你。→体会心情。\u003c/u>\u003c/p>\u003cp>\u003cu>我：你现在很伤心，因为同学们冤枉你这件事，让你觉得很崩溃，所以不想去上学了。→综合陈述。\u003c/u>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>经过反复的沟通，她终于说出了自己伤心的原因：她最近学习很努力，这次数学考了第一名，同学们不信任她，在班里起哄，数学老师却没有批评那些学生，让她感觉既伤心又委屈。\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>当她感受到我的真诚和尊重，放下了自己的情绪，愿意把内心的想法分享出来，就已经完成了移情聆听。\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>【技能点6：拆书家讲解引导中包括了：1）行动建议步骤；2）与行动各步骤对应的案例。】\u003c/u>\u003c/em>\u003c/strong>\u003c/p>","interaction":"\u003cp>我们刚刚学习了移情聆听的四个步骤，那么听完了我的案例，现在请大家回忆一下，在你过往的经历中，有没有遇到过类似的场景--比如：朋友跟你说不想工作了，孩子跟你说不想上学、不想上兴趣班等类似的场景\u003c/p>\u003cp>下面我给大家分成两个组，大家用3分钟的时间分享，3分钟后请1位代表来进行分享。注意咱们这个环节，只分享过去的经历即可，成功或失败的经历都可以分享，不需要谈论之后如何做的部分，下面把时间交给大家。\u003c/p>\u003cp>好的，时间到。看大家刚才讨论的都很热烈，下面我们就用1分钟时间，请一位小伙伴分享一下。\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>【技能点7：【A1】指令清晰。学习者在小组内分享了自己的经验，并有一位代表分享了本组的一个经验。】\u003c/u>\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录\u003c/strong>\u003c/p>\u003cp>分享者：程子同学\u003c/p>\u003cp>女儿想看电视，说好的只能看20分钟，时间到了，爸爸关掉了电视，但是女儿很不能接受这件事，一直哭闹。\u003c/p>\u003cp>程子：你现在是不是有点伤心？\u003c/p>\u003cp>女儿：是的，我现在很伤心。\u003c/p>\u003cp>程子：那你为什么很伤心呢？\u003c/p>\u003cp>女儿：爸爸不让我看电视，我就特别伤心。\u003c/p>\u003cp>程子：那你现在可以听妈妈给你说几句吗?\u003c/p>\u003cp>我们以前说活每天看电视只能看25分钟，看的时间久了，会伤害你的眼睛，你今天已经看了25分钟了，爸爸比较担心你再看的话会对你的眼睛不好，所以就不让你看了。我们去做别的事情吧。\u003c/p>\u003cp> \u003cstrong>\u003cem>好，谢谢程子的分享，让我们感受到了移情聆听在沟通中的重要性。\u003c/em>\u003c/strong>\u003cbr> \u003c/p>\u003cp>下面请大家试想一下，在未来的一个月内，你准备如何运用移情聆听这个方法。\u003c/p>\u003cp>下面给大家2分钟时间，请大家在便签上写出接下来一个月可能会出现的一个具体的场景，按照我们讲到的四个步骤，规划一次移情聆听的实际应用。\u003c/p>\u003cp>注意要有具体的做法、明确的时间、要有可以衡量或者可以观测的预期结果。\u003c/p>\u003cp> \u003cstrong>学习者案例记录\u003c/strong>\u003cbr> 学习者：欢欢\u003cbr> 我朋友前天给我抱怨过她不想工作了，当时我不知道该怎么开导她，经过今天的学习，我决定明天晚上给她打电话聊一聊关于她不想上班这件事情。\u003cbr> \u003cbr> 场景：因为疫情原因，闺蜜的公司降薪30%，闺蜜接受不了降薪，想辞职。\u003cbr> \u003cbr> \u003c/p>\u003cp>我;因为降薪这件事情，你现在不想上班了，降薪这件事情，让你感觉很不公平，你感觉非常气愤，因为公司降薪这件事，让你觉得自己的劳动价值被打了折扣。\u003c/p>\u003cp>经过反复沟通，闺蜜觉得疫情原因确实对公司的业务影响很大，她不想辜负公司对她的栽培，决定继续在公司工作，和公司一起度过难关。\u003c/p>\u003cp>好，时间到。通过今天的学习，我们知道了移情聆听的四个步骤。希望大家在以后的生活中可以灵活运用，今天的分享到此结束，谢谢大家！\u003c/p>\u003cp>\u003cstrong>\u003cem>\u003cu>【技能点8：指令清晰。提醒每个学习者都写下了一个包含具体做法，其中包含具体的行动方案，有明确时限和可衡量或可观测预期结果的便签。】\u003c/u>\u003c/em>\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1672653412000,"updated_at":1673441602000,"ria":true},{"id":11383,"topic":"用“移情倾听”进行有效沟通","learn_goal":"","remark":"高效能人士的7个习惯","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"小妖灵灵","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp> \u003cstrong>【分组】\u003c/strong> \u003c/p>\u003cp>嗨~大家好，我是小妖灵灵。今天我将用25分钟左右的时间进行分享。等一下会有分享讨论环节，我们先来分一下组，大家就近两两一组。谢谢\u003c/p>\u003cp> \u003cstrong>【学习目标】\u003c/strong> \u003c/p>\u003cp>希望大家在跟随我完成本次RIA现场学习后，能够学会使用“移情倾听”进行有效沟通，站在说话者的角度理解他们的思维模式和感受。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【F】\u003c/strong>现在我手里拿的这本书叫《高效能人士的7个习惯》，它的作者是50个孩子的祖父、柯维领导中心的创始人——史蒂芬·柯维。柯维在书里讲了帮助他成功的7个习惯，它们分别是：积极主动、以终为始、要事第一、双赢思维、知己知彼、统合综效和不断更新。\u003c/p>\u003cp>\u003cstrong>【A】\u003c/strong>在美国，这本书的影响力仅次于《圣经》，《纽约时报》《福布斯》《财富》等全球知名杂志鼎力推荐。不同于那些夸大其辞、泛泛而谈的成功学书籍，这本书能从深层分析你身上存在的问题的根源，然后帮助你找到问题的解决的方案。\u003c/p>\u003cp>\u003cstrong>【B】\u003c/strong>书中“七个习惯”是柯维精选出的最核心思想和方法，实用又不流于技巧。用最少的时间，为诸多忙碌人士带去超价值的自我提升体验。但也正如柯维所说，书里的内容都是简单易行的办法，至于如何能够很好地达成，还是要靠我们自己持之以恒的自我修炼。\u003c/p>","ratings_count":1,"texts":[{"id":15309,"quote":"\u003cp>\u003cstrong>今天我选用的片段就是书中的方法之一。如果你想提升自己的沟通能力，做一个好的倾听者，不妨就来阅读下这部分内容，阅读时间为3分钟，阅读完的伙伴可以举手示意我，谢谢。\u003c/strong>\u003c/p>\u003cp>选自《高效能人士的7个习惯》P270-271\u003c/p>\u003cp>正确的沟通方式也就是移情聆听，至少包括四个阶段。\u003c/p>\u003cp>\u003cstrong>【第一阶段是复述语句，这至少能使人专心聆听】\u003c/strong>\u003c/p>\u003cp>子：“上学真是无聊透了!”\u003c/p>\u003cp>父：“你已受不了了，觉得上学太无聊。”\u003c/p>\u003cp>\u003cstrong>【第二阶段加入解释，完全用自己的词句表达，但仍用左脑的逻辑思维去理解】\u003c/strong>\u003c/p>\u003cp>父：“你不想上学了。”\u003c/p>\u003cp>\u003cstrong>【第三阶段掺入个人的感觉，右脑发挥作用。此时听者所注意的已不止于言语，也开始体会对方的心情】\u003c/strong>\u003c/p>\u003cp>父：“你觉得很有挫折感。”\u003c/p>\u003cp>\u003cstrong>【第四阶段是既加以解释，又带有感情，左右脑并用】\u003c/strong>\u003c/p>\u003cp>父：“你对上学有很深的挫折感。”\u003c/p>\u003cp>\u003cstrong>运用这四个阶段的方式沟通，不仅能了解对方，更能帮助对方认清自己，勇于表达。再以前面的例子说明：\u003c/strong>\u003c/p>\u003cp>子：“上学真是无聊透了!”← 我想引起注意，与人谈谈心事。\u003c/p>\u003cp>父：“你对上学有很深的挫折感。”← 对，这正是我的感觉。\u003c/p>\u003cp>子：“没错，学校的东西根本不实用。”\u003c/p>\u003cp>父：“你觉得读书对你没什么用。”← 想想看，我是那么说的吗？\u003c/p>\u003cp>子：“对，学校的不一定对我有用。你看乔伊，他现在修车技术一流，这才实用。”\u003c/p>\u003cp>父：“你觉得他的选择正确。”← 嗯……\u003c/p>\u003cp>子：“嗯，从某个角度看确实如此。现在他收入不错，可是几年后，或许会后悔。”\u003c/p>\u003cp>父：“你认为将来他会觉得当年做错了决定。”\u003c/p>\u003cp>子：“一定会的，现在的社会里，教育程度不高会吃亏的。”\u003c/p>\u003cp>父：“教育很重要。”\u003c/p>\u003cp>子：“对，如果高中都没毕业，一定找不到工作，也上不了大学。有件事——我真的很担心，你不会告诉妈吧？”\u003c/p>\u003cp>父：“你不想让你妈知道？”\u003c/p>\u003cp>子：“不是啦!跟她说也无妨，反正她迟早会知道的。今天学校进行阅读能力测验，结果我只有小学程度，可是我已经高二了！”\u003c/p>\u003cp>儿子终于吐露真言，原来他担心阅读程度不如人。此时才是父亲发挥影响力，提供意见的时刻。不过在开导过程中，依然要注意孩子言谈间所传达的信息。若是合理的反应不妨顺其自然，但情绪性反应出现时，必须仔细聆听。\u003c/p>\u003cp>父：“我有个构想，也许你可以上补习班加强阅读能力。”\u003c/p>\u003cp>子：“我已经打听过了，可是每星期要耗掉好几个晚上!”\u003c/p>\u003cp>父亲意识到这是情绪性反应，又恢复移情聆听。\u003c/p>\u003cp>父：“补习的代价太高了。”\u003c/p>\u003cp>子：“而且我答应同学，晚上另有节目。”\u003c/p>\u003cp>父：“你不想食言。”\u003c/p>\u003cp>子：“不过补习如果真的有效，我可以想办法跟同学改时间。”\u003c/p>\u003cp>父：“你其实很想多下点功夫，又担心补习没用。”\u003c/p>\u003cp>子：“你觉得会有效吗？”\u003c/p>\u003cp>孩子又恢复了理性，父亲则再次扮演导师的角色。\u003c/p>","explains":"\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>好啦，时间到。沟通是人一生中最重要的技能，然而我们从小接受太多读写训练，却没有关于听说的课程。毫不夸张地说，大多数人不会“听话”，更不会“好好说话”。\u003c/p>\u003cul>\u003cli>“听”时，要么充耳不闻、装模作样，要么选择性接收，只有少数人能聚精会神。\u003c/li>\u003cli>“说”时，要么热衷评价、自以为是，要么好为人师、追根究底。\u003c/li>\u003c/ul>\u003cp>这么看来，真的只有极少数人能做到移情聆听、有效沟通。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>那到底如何才能做到“移情倾听”呢？原文片段中讲到了它的4个阶段：\u003c/p>\u003cp>\u003cstrong>1、重述对方的话\u003c/strong>\u003c/p>\u003cp>用自己的语言重新复述对方的话，重点是对方的感受，让对方感觉到我在试图理解他。\u003c/p>\u003cp>\u003cstrong>2、加入自己理性的理解（细化步骤）\u003c/strong>\u003c/p>\u003cp>用自己的逻辑解释对方的话，表达我的想法，避免自以为是的片面评价。具体可以这样做：\u003c/p>\u003col>\u003cli>根据内心的直觉，第一时间判断对方说话的意思。这一流程由本能控制，常常会很片面。\u003c/li>\u003cli>对直觉得出的结论，不停地在自己脑中进行追问——自己这一结论在哪些方面考虑不足，对哪些方面认识不足，这会让自己一下子找到与对方信息不对等的地方。\u003c/li>\u003cli>针对信息不对等的地方，向对方提问并沟通。\u003c/li>\u003c/ol>\u003cp>\u003cstrong>3、用感性体会对方的感受（细化步骤）\u003c/strong>\u003c/p>\u003cp>谈谈所聊事情，自己观察到什么、感受如何。尝试用同理心去体会对方的情绪，尽可能地安抚对方情绪。具体可以这样做：\u003c/p>\u003col>\u003cli>停下自己正在做的事，时不时点头，或是说“我了解”、“我知道你意思”、“这不能怪你”等表示理解的话，让对方知道你在认真听他说话。\u003c/li>\u003cli>第一时间换位思考，站在对方的角度想一想：“如果我是他，我会不会也这样想呢？我会有怎样的感受呢？”\u003c/li>\u003cli>向对方准确、清晰、具体地表达自己的感受，让对方觉得自己的情绪被理解。\u003c/li>\u003c/ol>\u003cp>\u003cstrong>4、理性感性并用\u003c/strong>\u003c/p>\u003cp>在安抚对方情绪的基础上，找准真正的问题所在，给出引导性的建议。\u003c/p>\u003cp>需要指出的是，以上这四个阶段，在沟通中可以不按顺序。\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>刚才大家阅读的拆页内容，为我们提供了一个父子间使用“移情倾听”进行有效沟通的模板。下面，我举一个夫妻间使用“移情倾听”进行有效沟通的例子。\u003c/p>\u003cp>\u003cstrong>【EXAMPLE】（意译案例）\u003c/strong>\u003c/p>\u003cp>最近家里因为“孩子该读哪所幼儿园”而争论不休。丈夫一直玩游戏想逃避这个问题，妻子一把夺过丈夫手里的手机，迫使丈夫面对这个问题。\u003c/p>\u003cp>妻子：“你能不能别玩手机了！我一直在想孩子该上哪所幼儿园，有时候我甚至觉得他还小。”\u003c/p>\u003cp>处于第1阶段的丈夫会【重述对方话】：“你不希望我玩手机，你想我和你讨论孩子上幼儿园的问题，但你又觉得孩子太小。”\u003c/p>\u003cp>处于第2阶段的丈夫会【加入自己理性的理解】：“你很重视孩子教育问题，怕他输在起跑线上，但又觉得他年龄尚小。”\u003c/p>\u003cp>处于第3阶段的丈夫会【用感性体会妻子的感受】：“你很担心他。”\u003c/p>\u003cp>处于第4阶段的丈夫会【理性感性并用】，这样回答：“你一方面关心孩子教育，一方面又担心他还没做好心理准备，是吗？”\u003c/p>\u003cp>运用这4个阶段的不同沟通方式，我们接着看看丈夫和妻子能否取得有效沟通。\u003cstrong>（这里我想邀请1位伙伴和我对话）\u003c/strong>\u003c/p>\u003cp>【妻子】：“你能不能别玩手机了！我一直在想孩子该上哪所幼儿园，有时候我甚至觉得他还小。”← 我（妻子）想引起注意，与丈夫谈谈心事。\u003c/p>\u003cp>【丈夫】：“你一方面关心孩子教育，一方面又担心他还没做好心理准备，是吗？”←对，这正是我（妻子）的感觉。\u003c/p>\u003cp>【妻子】：“是的，你看每个幼儿园的学费、环境、教学理念都不一样。”\u003c/p>\u003cp>【丈夫】：“你觉得幼儿园花样太多，让你应接不暇？”← 想想看，我（妻子）是那么说的吗？\u003c/p>\u003cp>【妻子】：“没错，每个学校的教育资源都不一样。你看王姐家孩子，她给孩子选了所双语国际贵族幼儿园，从小耳濡目染地接受语言训练。”\u003c/p>\u003cp>【丈夫】：“你觉得她的选择正确。”← 嗯……\u003c/p>\u003cp>【妻子】：“嗯，某方面看的确如此。现在她孩子外语说得特别厉害，可我听说那个幼儿园的家长们非富即贵，不太待见王姐这样的家庭。”\u003c/p>\u003cp>【丈夫】：“你很担心孩子在这所幼儿园里也被欺负、被排挤。”\u003c/p>\u003cp>【妻子】：“对！这样的话，孩子成长会受到影响，反而得不偿失了。但我又怕其他幼儿园不靠谱，万一幼儿园再扎小孩什么的，我简直不敢送他去上幼儿园。”\u003c/p>\u003cp>妻子终于吐露真言，原来她担心选到没有师德的幼儿园，孩子被欺负。此时才是丈夫发挥影响力，给出自己意见的时刻。\u003c/p>\u003cp>【丈夫】：“我有个想法，我们可以联系幼儿园，先让孩子试学一段时间。”\u003c/p>\u003cp>【妻子】：“我已经打听过了，幼儿园只能让孩子试学1个星期。”\u003c/p>\u003cp>在开导妻子的过程中，丈夫依然要使用“移情倾听”，不可大男子主义，全然不顾妻子的情绪反应。\u003c/p>\u003cp>【丈夫】：“你其实很想试试看，但又怕1周时间看不出什么东西？”\u003c/p>\u003cp>【妻子】：“部分原因是这样，我还怕他还没做好离开父母的准备。当然，我也不希望他太依赖我们。”\u003c/p>\u003cp>【丈夫】：“是啊，做这个决定对你我、孩子都不容易。如果我们想今年送他上幼儿园，一定要选择一个适合他的地方才行。”\u003c/p>\u003cp>【妻子】：“你的意思是，只有找到一个他喜欢的幼儿园，才会放心让他这么小上幼儿园吗？”\u003c/p>\u003cp>【丈夫】：“是的，我们可以试一试。”\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>这个方法适用于他人对某个问题与我们有不同的看法、或者不理解的地方，需要我们做出回应的时候。需要注意的是：如果对方说话带着情绪，需要先安抚好对方的情绪。\u003c/p>","interaction":"\u003cp>\u003cstrong>【场景设计】\u003c/strong>\u003c/p>\u003cp>通过以上的讲解，相信大家都清楚了解了“移情倾听”的沟通方法，现在我们来做一个演练，场景是这样的：\u003c/p>\u003cp>一次线下拆书分享后，你讲解的内容受到了学习者的质疑。在你与学习者互动征集反馈意见时，这时，有个人举起了手，他说：“你说的这些内容简直就是断章取义、刻意曲解原文。”\u003c/p>\u003cp>\u003cstrong>【小组讨论】\u003c/strong>\u003c/p>\u003cp>现在请大家在小组内讨论：应该如何用“移情倾听”沟通呢？请大家两两一组进行演练：一个扮演拆书家，一个扮演学习者，合编一段对话写到拆页后面。\u003c/p>\u003cp>另外提醒大家注意：我们演练的目的是练习今天学到的用“移情倾听”沟通，所以扮演拆书家的伙伴一定要用“移情倾听”。\u003c/p>\u003cp>现在开始，时间为10分钟，等一会儿我会邀请2组小伙伴上来分享。\u003c/p>\u003cp>\u003cstrong>【角色扮演——学习者案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cbr>【第1组分享】\u003c/p>\u003cp>学习者：你说的这些内容简直就是断章取义、刻意曲解原文。\u003c/p>\u003cp>拆书家：你觉得我说的这些内容断章取义、曲解了原文的意思？\u003c/p>\u003cp>学习者：是的。\u003c/p>\u003cp>拆书家：原来你是这么认为的。那我想问一下，你是如何看待原文内容的呢？\u003c/p>\u003cp>学习者：我觉得你的观点与原文不符合，你随意挑选了原文的某个点，曲解了原文。\u003c/p>\u003cp>拆书家：哦~你的意思是我对原文的认识是片面的。我其实有时候自己读书也会这样，当我发现自己的观点和对方不一致时，也会有类似的感受，我很能理解你的意思。我之后也会用多角度去重看原文，让我的观点更加全面些，希望你下一次能继续来参加我的线下分享，看看我是否有所长进，可以吗？\u003c/p>\u003cp>学习者：好的。\u003c/p>\u003cp>【第2组分享】\u003cbr>\u003c/p>\u003cp>学习者：你说的这些内容简直就是断章取义、刻意曲解原文。\u003c/p>\u003cp>拆书家：你是希望我完全按原文的意思来讲吗？\u003c/p>\u003cp>学习者：对。比如你刚才说的方法，它就是新瓶旧酒而已，并没有对事件本身有什么实质影响。\u003c/p>\u003cp>拆书家：我没有特别明白您的意思是？\u003c/p>\u003cp>学习者：就比如你刚才说“把不得不换成我选择做”，但这并没有改变我要去做这件事的事实。\u003c/p>\u003cp>拆书家：你的意思是觉得这个方法对你没有太大帮助对吗？\u003c/p>\u003cp>学习者：对啊。\u003c/p>\u003cp>拆书家：是这样的，可能我没说明白。当面对你不得不做的事情时，你首先要做的是转变态度，你不是被逼的，而是自己选择的。你可以转变态度接着做，也可以放弃不做。这样的话，你再去做事时，心态会不会有相应的变化？\u003c/p>\u003cp>学习者：哦~原来如此，我试试看。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>掌声感谢两组小伙伴的分享！我的分享也到此结束，祝愿大家都能够学会移情倾听，构建和谐友爱的人际关系。请所有的小伙伴把写好的便签交给我一下，感谢各位的配合和聆听，我的分享完毕，有请主持人!\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1618736880000,"updated_at":1618742327000,"ria":true},{"id":10663,"topic":"TF1-1过级","learn_goal":"","remark":"TF1-1","level":"TF1-1","duration":13,"status":30,"type":0,"chaishujia":{"username":"苔米","city":"昆明市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>TF1-1拆书预备表 \u003c/strong>提交人：葛娟\u003c/p>\u003cp>\u003cstrong>【拆书帮介绍】 2分钟 \u003c/strong>\u003c/p>\u003cp>在开始内容之前先介绍下什么是“拆书帮”。\u003c/p>\u003cp>首先，什么是拆书？\u003c/p>\u003cp>拆书是一种学习方法论，适用于旨在提升个人能力并解决问题的学习方法，强调把图书的知识页转化为学习者的能力，把知识关联学习者的过往经验、规划具体的运用。\u003c/p>\u003cp>分为个人学习的拆书法和组织学习的拆书法：个人学习的应用是便签法，让人读一本书就能达到有所输出的效果；组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为已用，从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训教练。\u003c/p>\u003cp>拆书帮是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书帮俱乐部）。拆书帮分舵是公益性的青年自组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>下面进入到今天分享的主体内容部分。\u003c/p>\u003cp>\u003cstrong>【R】阅读原书拆页 2分钟 \u003c/strong>\u003c/p>\u003cp>[主题]：自我管理四步骤\u003c/p>\u003cp>[片段来源]：拆解片段来自《高效人士的七个习惯》P.133\u003c/p>\u003cp>自我管理的四步骤虽然我的工作主要是教授高效率的原则性问题，一般不讲授具体的实施计划，但我认为如果能够以原则为基础，以第二象限事物为生活中心，对一个星期内的事务进行具体安排，将有助于更多地理解第四代时间管理方法的原则及其巨大的潜能。以第二象限事物为中心的日程安排需要以下四项关键步骤。\u003c/p>\u003cp>\u003cstrong>确认角色，\u003c/strong>第一步就是要写出你自己的关键角色。作为一个个体，你有属于自己的各种方式啊，各种角色，你可以先写下自己在家庭中的角色，然后再写下自己在工作中的角色，列举自己想要持续投入时间和精力去做的一些事情。\u003c/p>\u003cp> 你不必想的太复杂，只要考虑自己下一周的角色和任务记下这7天时间里需要专注的领域即可。\u003cstrong>选择目标，\u003c/strong>第2步就是思考，下一个周计划中每一任务栏下你最想做的一两件事，作为你选定的目标，这些目标中一定要有几个第二象限事物，最好让这些短期目标与使命宣言中的长期目标相关联，即使你还没有撰写个人使命宣言，也可以根据自己的感觉来判断每一个角色中哪些事情是比较重要的，并且为每个角色确定1或两个标准。\u003c/p>\u003cp>\u003cstrong>安排进度，\u003c/strong>为每一项目标安排具体的实施时间，如果你的目标是起草自己的个人使命宣言，那就不妨在星期天安排两个小时专门做这件事情，通常星期天是进行个人思考和制定个人成长计划的理想时间，因为这时候你有充足的时间思考反省寻求灵感，并根据各项原则和价值观来审视自己的时间和生活，确认角色并制定目标后，你就可以把每项任务分配到一个星期中某个具体的时间去做了，或者将它列为一项重要活动或者列为一个特别的约会。\u003c/p>\u003cp>\u003cstrong>每日调整，\u003c/strong>使用这种以第二象限十五为中心的周计划之后，你就会发现原来的每周计划变成了每日调整，即根据突发事件人际关系的意外发展及转型的机会，对每天的要务安排进行适当调整，但你每天早晨审视自己一天的日程安排的时候，你会看到由于内心的平衡，自己已经为角色和目标进行了合适的优先排序，这种日程安排是灵活的，是右脑运作的结果是建立在自己个人对使命的认识基础上的。\u003c/p>\u003cp>\u003cstrong>【分享I便签】 2.5分钟 \u003c/strong>\u003c/p>\u003cp>【What】(这是一个什么概念)\u003c/p>\u003cp>自我管理是高效率工作的重要部分，以效率原则为基础，对一段时间内的事物进行具体安排，具体可以有四个重要的步骤。\u003c/p>\u003cp>【Why】(为什么要这么做，这么做有什么好处，不这么做有什么坏处)\u003c/p>\u003cp>当自我管理有章可循时，我们的工作效率会更高，自我认识会更强。如果一旦偏离步骤，则没办法在短期内提升工作效率，也无法在多个角色中看到自己内心的平衡。\u003c/p>\u003cp>【How】(具体怎么做呢)\u003c/p>\u003cp>自我管理的四项重要步骤如下：\u003c/p>\u003cp>１.角色定位——整理并写下自己在未来一周内需要担任的角色，并把这些角色即将要承担的重要任务列出清单；\u003c/p>\u003cp>２确定目标——将责任清单中的任务按轻重缓级的顺序排列，并将最重要的前几项任务区别开来\u003c/p>\u003cp>３.规划时间——给每项目标任务规划完成时间表，把任务以天为单位规划好每个任务的时间；\u003c/p>\u003cp>４.即时调整——每天结合临时的工作任务及当天规划好的任务时间及要求进行具体调整。\u003c/p>\u003cp>\u003cstrong>【A1】（激活过去经验） 2分钟 \u003c/strong>\u003c/p>\u003cp>今年8月份报考了经济师的考试，在备考期间，没有制定学习计划，按见缝插针的形式进行学习，直到现在，课本内容还没有完成至少一遍的学习。现在离考试只有两个星期的时间啦，要想在考前掌握课本的全部内容，时间紧张，以至于非常焦虑。\u003c/p>\u003cp>【反思】\u003c/p>\u003cp>用自我管理的四项重要步骤来看，我的经济师学习做了整体的规划，考虑了工作、家庭、学习等方面的因素，但没能确定具体的学习目标，没能把学习计划分解至每周甚至每日上去，也没能将重要的章节圈划出来进行反复学习直至理解，针对临时的事情的冲突没能做好即时的调整，导致遇到即时发生的事情就搁置了原有的学习计划。\u003c/p>\u003cp>\u003cstrong>【A2】 \u003c/strong>（规划未来应用）\u003cstrong>1.5分钟 \u003c/strong>\u003c/p>\u003cp>目标：本周日晚饭后，制定出下周的行动实施计划，安排好下周工作和生活。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>１、本周日计划下周需要做的事情，包括生活类、亲子类、工作类、家庭类的所有与自己相关需要在下周完成的事情，并形成清单。\u003c/p>\u003cp>2、将下周需要完成事项清单的轻重缓急进行排序，时时提醒自己投入精力的方向与目标。\u003c/p>\u003cp>3、根据轻重缓的的排序进行具体实施时间与要求的进度安排；\u003c/p>\u003cp>4、每天开始，了解当天需完成的计划事项，如有临时事项冲突，即时调整当天的事项计划，以确保当天事项计划的完成。。\u003c/p>\u003cp>做到奖励看一部电影，做不到跑5公里\u003c/p>\u003cp>\u003cstrong>结束语\u003c/strong>\u003c/p>\u003cp>自我管理就是一个平衡人生的过程\u003c/p>\u003cp>在资讯发达，社会发展越来越多元化的今天，也对人们提出了更为苛刻的要求，让人们觉得日子更加紧迫和心力交瘁。尽管我们付也了很多，尽量有效地利用时间，努力工作，积极进取，并利用现代科技不断提高效率，然而让人不解的是，我们越来越陷于一些鸡毛蒜皮的小事上不能自拔，而把健康、家庭、品德以及其他许多重要的事情放在了工作之后，舍本逐末，我们不能把问题归咎于工作，或社会的得杂和变迁，而在于我们的流行文化提倡：“早出、晚走、高效，从现在起就要懂得牺牲”——可事实上，心灵的平和宁静远非这些技巧所能企及，它取决于人们是否明白什么是最重要的事情，是否懂得轻重缓急，并能抓住生活的重点，客观地面对。\u003c/p>\u003cp>我今天的分享就到这里了，感谢大家！\u003c/p>","ratings_count":1,"texts":[{"id":14529,"quote":"\u003cp>\u003cstrong>【R】阅读原书拆页 2分钟 \u003c/strong>\u003c/p>\u003cp>[主题]：自我管理四步骤\u003c/p>\u003cp>[片段来源]：拆解片段来自《高效人士的七个习惯》P.133\u003c/p>\u003cp>自我管理的四步骤虽然我的工作主要是教授高效率的原则性问题，一般不讲授具体的实施计划，但我认为如果能够以原则为基础，以第二象限事物为生活中心，对一个星期内的事务进行具体安排，将有助于更多地理解第四代时间管理方法的原则及其巨大的潜能。以第二象限事物为中心的日程安排需要以下四项关键步骤。\u003c/p>\u003cp>\u003cstrong>确认角色，\u003c/strong>第一步就是要写出你自己的关键角色。作为一个个体，你有属于自己的各种方式啊，各种角色，你可以先写下自己在家庭中的角色，然后再写下自己在工作中的角色，列举自己想要持续投入时间和精力去做的一些事情。\u003c/p>\u003cp> 你不必想的太复杂，只要考虑自己下一周的角色和任务记下这7天时间里需要专注的领域即可。\u003cstrong>选择目标，\u003c/strong>第2步就是思考，下一个周计划中每一任务栏下你最想做的一两件事，作为你选定的目标，这些目标中一定要有几个第二象限事物，最好让这些短期目标与使命宣言中的长期目标相关联，即使你还没有撰写个人使命宣言，也可以根据自己的感觉来判断每一个角色中哪些事情是比较重要的，并且为每个角色确定1或两个标准。\u003c/p>\u003cp>\u003cstrong>安排进度，\u003c/strong>为每一项目标安排具体的实施时间，如果你的目标是起草自己的个人使命宣言，那就不妨在星期天安排两个小时专门做这件事情，通常星期天是进行个人思考和制定个人成长计划的理想时间，因为这时候你有充足的时间思考反省寻求灵感，并根据各项原则和价值观来审视自己的时间和生活，确认角色并制定目标后，你就可以把每项任务分配到一个星期中某个具体的时间去做了，或者将它列为一项重要活动或者列为一个特别的约会。\u003c/p>\u003cp>\u003cstrong>每日调整，\u003c/strong>使用这种以第二象限十五为中心的周计划之后，你就会发现原来的每周计划变成了每日调整，即根据突发事件人际关系的意外发展及转型的机会，对每天的要务安排进行适当调整，但你每天早晨审视自己一天的日程安排的时候，你会看到由于内心的平衡，自己已经为角色和目标进行了合适的优先排序，这种日程安排是灵活的，是右脑运作的结果是建立在自己个人对使命的认识基础上的。\u003c/p>","explains":"\u003cp>\u003cstrong>【分享I便签】 2.5分钟 \u003c/strong>\u003c/p>\u003cp>【What】(这是一个什么概念)\u003c/p>\u003cp>自我管理是高效率工作的重要部分，以效率原则为基础，对一段时间内的事物进行具体安排，具体可以有四个重要的步骤。\u003c/p>\u003cp>【Why】(为什么要这么做，这么做有什么好处，不这么做有什么坏处)\u003c/p>\u003cp>当自我管理有章可循时，我们的工作效率会更高，自我认识会更强。如果一旦偏离步骤，则没办法在短期内提升工作效率，也无法在多个角色中看到自己内心的平衡。\u003c/p>\u003cp>【How】(具体怎么做呢)\u003c/p>\u003cp>自我管理的四项重要步骤如下：\u003c/p>\u003cp>１.角色定位——整理并写下自己在未来一周内需要担任的角色，并把这些角色即将要承担的重要任务列出清单；\u003c/p>\u003cp>２确定目标——将责任清单中的任务按轻重缓级的顺序排列，并将最重要的前几项任务区别开来\u003c/p>\u003cp>３.规划时间——给每项目标任务规划完成时间表，把任务以天为单位规划好每个任务的时间；\u003c/p>\u003cp>４.即时调整——每天结合临时的工作任务及当天规划好的任务时间及要求进行具体调整。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】（激活过去经验） 2分钟 \u003c/strong>\u003c/p>\u003cp>今年8月份报考了经济师的考试，在备考期间，没有制定学习计划，按见缝插针的形式进行学习，直到现在，课本内容还没有完成至少一遍的学习。现在离考试只有两个星期的时间啦，要想在考前掌握课本的全部内容，时间紧张，以至于非常焦虑。\u003c/p>\u003cp>【反思】\u003c/p>\u003cp>用自我管理的四项重要步骤来看，我的经济师学习做了整体的规划，考虑了工作、家庭、学习等方面的因素，但没能确定具体的学习目标，没能把学习计划分解至每周甚至每日上去，也没能将重要的章节圈划出来进行反复学习直至理解，针对临时的事情的冲突没能做好即时的调整，导致遇到即时发生的事情就搁置了原有的学习计划。\u003c/p>\u003cp>\u003cstrong>【A2】 \u003c/strong>（规划未来应用）\u003cstrong>1.5分钟 \u003c/strong>\u003c/p>\u003cp>目标：本周日晚饭后，制定出下周的行动实施计划，安排好下周工作和生活。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>１、本周日计划下周需要做的事情，包括生活类、亲子类、工作类、家庭类的所有与自己相关需要在下周完成的事情，并形成清单。\u003c/p>\u003cp>2、将下周需要完成事项清单的轻重缓急进行排序，时时提醒自己投入精力的方向与目标。\u003c/p>\u003cp>3、根据轻重缓的的排序进行具体实施时间与要求的进度安排；\u003c/p>\u003cp>4、每天开始，了解当天需完成的计划事项，如有临时事项冲突，即时调整当天的事项计划，以确保当天事项计划的完成。。\u003c/p>\u003cp>做到奖励看一部电影，做不到跑5公里\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1606047306000,"updated_at":1606656685000,"ria":true},{"id":10235,"topic":"高效能人士的7个习惯","learn_goal":"","remark":"高效能人士的7个习惯","level":"TF3-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"肖昀","city":"银川"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>【自我介绍】大家好，我是肖昀。我是一个二级拆书家，今天我分享的主题是：如何让对方觉得被理解。\u003c/p>\u003cp>\u003cstrong>【介绍图书】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【事件场景】\u003c/strong>我们每个人身边都有亲密的人，某些父母，孩子，爱人，朋友等等，我们希望能与他们保持良好的关系，走进他们的内心，爱他们，了解他们\u003cstrong>。\u003c/strong>可是，现实就像傍晚，我弟弟跟我视频，说他最近工作很多，很烦。我就很担心，仔细盘问他具体是什么事情遇到了困难，想着给他出主意，可是他没说几句就很不耐烦的说，说了你也不懂。我又追问了几句，他又找了个借口把电话挂了。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>\u003c/p>\u003cp>这让我很郁闷，也很纳闷，话没有说完就停了，而且我明明是为了她好，她还一副不领情的样子，不知道大家有没有遇到过这样的情景？\u003c/p>\u003cp>我们很多人都会遇到这样的情景。那想不想问题出在哪里，并且解决这样的问题呢？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003c/p>\u003cp>为什么呢？因为，在，与关系亲密的人沟通时，双方的内心有两个预先的设定，倾诉的人想，爱我的人，一定是能够理解我的人。聆听的人想：我都是为了你好。因为有了这样的时间表，所以关系亲密的人之间的沟通，比普通人的沟通更容易出现偏差，，也更容易伤人。我们想象一下，当不被自己身边的人理解的时候，我们想的是什么？连你都不理解我！对不对？\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003c/p>\u003cp>如何解决这个问题，更好的理解我们爱的人，走进他们的心，让他们意识到爱和支持，从而使我们之间的关系更近呢？《高效能人士的七个习惯》这本书中提出了解决方案。今天的片段来自于第五个习惯，知彼解己，我们的主题就是：\u003cstrong>如何更好的理解我爱的人？\u003c/strong>\u003c/p>","ratings_count":3,"texts":[{"id":14072,"quote":"\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>通过现场学习，学习者能够辨别（动作）出什么是移情聆听，并且能够运用移情聆听四步法（透明）与爱的人沟通，让对方觉得被理解，沟通能够顺利进行（界定）\u003c/p>\u003cp>现在，请伙伴们看今天片段，可以划出关键字，时间是1分钟。\u003c/p>\u003cp>摘自《高效能人士的七个习惯》 p182页\u003c/p>\u003cp>而作为聆听的最高层次，移情聆听是指以理解为目的的聆听，要求听者站立说话者的角度理解他们的思维模式和感受。移情聆听的本质不是要你相对对方，而是要在情感和理智上充分而深入的理解对方。\u003c/p>\u003cp>移情聆听不只是理解个别的句子而已，在移情聆听的过程中，既要用眼晴去观察，还要用心灵去体会。\u003c/p>\u003cp>如此聆听效果显着，它能为你的行动提供最准确的信息。你不必以己度人，也不必费心猜测，你所要了解的是对方的心灵世界。聆听是为了理解，是心和心的深刻交流。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】\u003c/strong>\u003c/p>\u003cp>看到伙伴们都已经看完了片段，进入我们的I两次，拆书家讲解。\u003c/p>\u003cp>Wh y：刚才我们说到，如何更好的理解我爱的人？理解的基础是沟通，我们没有办法做到单方面的了解别人。那在沟通当中，聆听的作用就非常重要了。通过听，达到才能走进对方内心的目的。可是，并不是所有的听都是聆听，的我们当中片段说移情聆听的英文聆听的最高层次，那我们能不能说一说，还有哪些低层次的聆听呢？\u003c/p>\u003cp>学习者记录：\u003c/p>\u003cp>孟佳。我听你说，倾听。\u003c/p>\u003cp>九月：你讲你的，我干我的。\u003c/p>\u003cp>考拉：以我的经验给你建议。\u003c/p>\u003cp>是的，刚才大家说了很多，这些听的层次，都无法达到更好的理解对方的目的。\u003c/p>\u003cp>什么：而移情聆听，以理解为目的的聆听，要求我们站在说话者的角度理解他们的思维模式和感受，在情感和理智上充分而深入的理解对方。\u003c/p>\u003cp>\u003cstrong>【概念辨析】\u003c/strong>\u003c/p>\u003cp>为了让大家对移情聆听更多的了解，我们举几个例子\u003c/p>\u003cp>有一天，你上小学一年级的儿子垂头丧气的看着一张图片，眼泪都快流出来了，你问他怎么了，他说看图写话好难，我不会写。你说：“哎呀，真的挺难的，怎么样这么小的孩子写这些，来先休息一会，乖。”这是不是移情聆听？（关键点1）\u003c/p>\u003cp>学习者记录：\u003c/p>\u003cp>淑霞：不叫。\u003c/p>\u003cp>孟佳：我觉得这个虽然不是移情聆听，但至少听的人会舒服一些。\u003c/p>\u003cp>对，这不是，虽然这里有对对方情感的回应，而是是同情，移情聆听要站在说话者的角度理解他们，而不是同情他们。\u003c/p>\u003cp>最近，你的妈妈跟你念叨了好几次，自己什么都记不住了。你说：“记不住东西真的很让人心烦，我有时侯也记不住，你可以写个便签，或者用手机备忘录。”这是不是移情？\u003c/p>\u003cp>理解双重要听到对方的意思，感受对方的心情，更要用心去体会背后的需求，实现心与心的交流。（关键点2）\u003c/p>\u003cp>学习者记录：\u003c/p>\u003cp>大家一起：这个不算。\u003c/p>\u003cp>这个大家比较有共识。妈妈说自己记不住了，其实重点不在于想要知道记东西的方法，而是对于自己年华逝去，身体慢慢虚弱等等的一种担心和感慨，或者是想让别人多一些关注的期待。\u003c/p>\u003cp>你的好朋友跟你吐槽老公，说他成天在外面忙，陪自己陪的不够。你说：“我知道你需要人陪伴，不过男人就是要干事业的啊，他要是一分钱都挣不不回来，你肯定更烦。”这是不是移情聆听？\u003c/p>\u003cp>学习者记录：\u003c/p>\u003cp>孟佳：不算。\u003c/p>\u003cp>九月：我觉得这个算。\u003c/p>\u003cp>我发现大家有分歧，有人觉得算，有人觉得不算，我们来看一下。虽然你发现了她需要人陪伴，但是你并没有理解她的感受，或者把自己的观点和感受加了上去。是你认为男人就需要干事业，不挣钱会使你心烦，而不是闺蜜，对吗？（关键点3）\u003c/p>\u003cp>经过上面的三个例子，我们发现移情聆听的三个关键点：1。站在对方的角度去理解，而不是同情。2。用心体验，理解对方真正要表达的内容。3。不把自己的感受和观点强加给别人。\u003c/p>\u003cp>我认为最难的点是，不把自己的感受和观点强加给别人，我们真的很难做到不把自己代入 进去。那如何才能做到移情聆听？\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>明确\u003cstrong>步骤】\u003c/strong>根据原文片段，我总结了一个3 + 1的步骤\u003c/p>\u003cp>1.复述语言：复述对方的话\u003c/p>\u003cp>2.表达感受：表达对方的感受\u003c/p>\u003cp>3.理解确认：说出你的理解并询问对方，进行确认。\u003c/p>\u003cp>+1。给予支持：询问对方是否需要自己做些什么。\u003c/p>\u003cp>很多时候对方向我们倾诉，其实只是需要得到关注，理解，所以一般进行完第三步就已经达到目的了。你可以根据情况，选择要不要询问第四步，为自己爱的人提供行动上的支持，某种需要你提供建议吗？还可以问对方打算做些什，从中判断自己能够给予支持。\u003c/p>\u003cp>一开始建议您按照步骤顺序使用，避免自己忘记某些步骤，当您熟悉了之后，就可以按照当时的实际情况灵活运用。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>你可能会说，这太麻烦了。我承认，移情聆听需要足够的耐心。但它能极大的改善你和身边的人的关系，让你们更加亲密，让彼此都能意识到爱与支持，你将会认为它麻烦吗？你会不愿意为了你爱的人付出一些时间和能量吗？\u003c/p>\u003cp> 为了让大家更加的清晰这四步骤，我们用之前我自己的故事来看看如何使用。\u003c/p>\u003cp>弟弟：最近我工作很烦，很累。\u003c/p>\u003cp>我：怎么了，给姐说说。\u003c/p>\u003cp>弟弟：嗯，我们领导把防疫的事情都安排给我，我还有我自己的工作，都有些干不过来了。\u003c/p>\u003cp>我：你现在同时干着自己的职责内部的工作，还要承担单位的防疫工作吗？\u003cstrong>（复述语言）\u003c/strong>\u003c/p>\u003cp>弟弟：是的，有那么多东西要采购，那么多事情和人要安排，又累又烦。\u003c/p>\u003cp>我：听起来真的让人头大，你肯定觉得累，也很心烦。\u003cstrong>（\u003c/strong>表达感受\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>弟弟：就是，我昨晚三点才睡。\u003c/p>\u003cp>我：你是觉得自己没有办法负担这种工作量或强度对吗？\u003cstrong>（理解确认）\u003c/strong>\u003c/p>\u003cp>弟弟：那倒不是，我以前也不是没这样加过班。\u003c/p>\u003cp>我：你是觉得领导安排工作不够合理吗？\u003cstrong>（理解确认）\u003c/strong>\u003c/p>\u003cp>弟弟：是，他好像他特别重视这事，但是又不给我足够的资源。\u003c/p>\u003cp>我：那你接下来打算做些什么吗？\u003cstrong>（给予支持）\u003c/strong>\u003c/p>\u003cp>弟弟：我跟他谈一谈，我至少需要两个人一起做这个事。\u003c/p>\u003cp>对话到此结束，大家感受一下，如果你是我的弟弟，这样的对话可以让您意识到支持和理解吗？\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp> 最后我想问问大家，如果有这样一种情况，比如说你的闺蜜失恋了，喝醉了酒，情绪激动的哭着说她不想活了，在房间里面砸东西，这种情况下适合使用移情聆听吗？对，大家都会认为不适合。移情聆听虽然是一种应用比较广泛的沟通方法，但是它不适合突发紧急情况下，不适合对方或者你自己情绪激动的时候。这一点需要大家在应用的时候注意。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2学习者拆为己用：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【编剧本】\u003c/strong>\u003c/p>\u003cp>有一个关于学习的研究成果，在大脑中过一遍，等于实际应用一遍。\u003c/p>\u003cp>接下来我们一起来做一个模拟演练。今天的演练是各位小伙伴编写一个剧本，想象一下，未来一个月，这样的场景下你需要移情聆听？可能是父母和你唠叨，孩子和你闹腾，朋友和你诉苦。用你想到的场景编写一个小剧本。剧本要有故事六要素（时间，地点，人物，角色，起因经过结果），要有对话。是未来的场景，用到我们今天学习的移情聆听四步法。\u003c/p>\u003cp>时间是5分钟，等一下会请一个伙伴来分享。\u003c/p>\u003cp>有伙伴可能会说，这剧本到底怎么编？其实你只要想到案例，就可以编出剧本，我把我刚才自己的案例编成了一个剧本做范例，大家可以参考一下。\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>陈章：我有一个同事姐姐，经常跟我说起自己孩子的事情，最近他在纠结给孩子报班的事情，经常跟我倾诉。假设我未来一周要上班，同事姐姐又跟我说相关的事情。\u003c/p>\u003cp>同事：我还是想给儿子报班……儿子还是不高兴，怎么办。\u003c/p>\u003cp>我：你是怎么想的呢？\u003c/p>\u003cp>同事：现在的家长都是各种安排，给孩子不报，我觉得孩子不学习不行。但是我儿子性格内向，写作业什么的很慢，我给他报太多了孩子又压力大。\u003c/p>\u003cp>我：（复述语言）你之前也说，你儿子自己平常思考的比较多，喜欢跟自己玩。他写作业比较慢，你报班他会觉得压力大，是这个意思吗。\u003c/p>\u003cp>同事：是啊，但是不报也不行啊。\u003c/p>\u003cp>我：（理解确认+表达感受）你是觉得给孩子报班孩子压力大，不报又觉得怕孩子输在了起跑线上。是因为你们的感受冲突了，所以你不开心，觉得担心对吗。\u003c/p>\u003cp>同事：是啊。\u003c/p>\u003cp>陈章：剧本就到这里。因为我也没有相关的经验，所以他也知道我给不出什么建议可能只是想跟我说说，我就用上这些步骤，好好的倾听就可以了。所以我也没有用第四步，给与支持。\u003c/p>\u003cp>好的，谢谢陈章的分享，我们给她鼓掌吧！\u003c/p>\u003cp>\u003cstrong>【有力总结】\u003c/strong>\u003c/p>\u003cp>今天我们分享的内容是如何移情聆听。希望大家把复述内容，表达感受，理解确认，给予支持这四个步骤用到自己爱的人当中去，用到自己的工作和生活中去，更好的理解对方，真正实现心与心的交流。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1596771249000,"updated_at":1601266342000,"ria":true},{"id":9662,"topic":"区分关注圈和影响圈，做积极主动的人","learn_goal":"能区分关注圈和影响圈，聚焦影响圈积极行动","remark":"我们总有时候会觉得不如意，学生时代，觉得大学读的专业不好就业，工作后觉得老板好小气，同事不给力，甲方公司要求真过分，经济大环境好差啊，在家里觉得另一半不理解你，小孩不听你的话，父母脾气倔不听劝……哎呀，人生好难啊，但是好像又不知道怎么改变，对人生似乎失去了掌控感。\r\n\r\n其实，掌控自己人生的秘诀就是先要区分关注圈和影响圈，做一个积极主动的人。","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"罗赟","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>\u003cstrong>学习目标\u003c/strong>：现场学习后，学习者能够在遇到不如意的事情时，能够通过列清单、做区分、聚焦积极行动三步骤（澄清）找到（行为）可控因素并列出（行为）改变的行动计划（界定）。 \u003c/p>\u003cp>\u003cstrong>开场\u003c/strong> \u003c/p>\u003cp>各位小伙伴大家好，我是罗赟。我们先分下组，2人一组。\u003c/p>\u003cp>我今天分享的主题是区分关注圈和影响圈，做自己人生的主人。\u003c/p>\u003cp>片段来自经典书籍《高效能人士的7个习惯》三十周年纪念版。 \u003c/p>\u003cp>\u003cstrong>图书介绍\u003c/strong> \u003c/p>\u003cp>事件场景：平时大家有没有遇到事情不如你意的时候？比如，学生时代，觉得大学读的专业不好就业，工作后觉得老板好小气，同事不给力，甲方公司要求真过分，经济大环境好差啊，在家里觉得另一半不理解你，小孩不听你的话，父母脾气倔不听劝……哎呀，人生好难啊，但是好像又不知道怎么改变。 \u003c/p>\u003cp>提问：小伙伴们有遇到过类似的经历吗？（有）这时候会忍不住想抱怨几句，发发牢骚对吧？ 那么除了抱怨我们还能做些什么呢？影响：人生不如意事十之八九，如果都消极对待，把原因都归咎到外界，就会觉得自己是一个受害者，我们可能就会失去对人生的主动权，严重影响人生的幸福感。 \u003c/p>\u003cp>解决：《高效能人士的7个习惯》中所介绍的7个习惯组成一个方向盘，让我们牢牢把握人生主动权。我今天分享如何区分关注圈和影响圈，更是能帮助我们把注意力集中到我们力所能及的事情上并开始积极行动改变不如意的现状。 \u003c/p>\u003cp>那我们先来读一下这个片段。看完的小伙伴请示意我。\u003c/p>","ratings_count":2,"texts":[{"id":13498,"quote":"\u003cp>\u003cstrong>R \u003c/strong>《高效能人士的7个习惯（三十周年纪念版）》史蒂芬·柯维 p115-116\u003c/p>\u003cp> 关注圈和影响圈\u003c/p>\u003cp>看一个人的时间和精力集中于哪些事物，也能大致判断他是否积极主动。每个人都有格外关注的问题，比如健康、子女、事业、工作、国债和核战争等等，这些都可以被归入“关注圈”（Circle of Concern），以区别于自己没有兴趣或不理会的事物。（见图3-3）\u003c/p>\u003cp>关注圈内的事物，有些可以被掌控，有些则超出个人能力范围，前者可以被圈成一个较小的“影响圈”（Circle of Influence，见图3-4）。观察一个人的时间和精力集中于哪个圈，就可以判断他是否是积极主动。\u003c/p>\u003cp>积极主动的人专注于“影响圈”，他们专心做自己力所能及的事，他们的能量是积极的，能够使影响圈不断扩大。（见图3-5）\u003c/p>\u003cp> 反之，消极被动的人则全神贯注于“关注圈”，紧盯他人弱点、环境问题以及超出个人能力范围的事不放，结果越来越怨天尤人，一味把自己当作受害者，并不断为自己的消极行为寻找借口。错误的焦点产生了消极能量，再加上对力所能及之事的忽略，就造成了影响圈日益缩小。（见图3-6）\u003c/p>\u003cp>只要我们的焦点在关注圈，就等于是允许自己受制于外界条件，自然就不会主动采取必要措施来推动积极变化。 \u003c/p>","explains":"\u003cp>\u003cstrong>I 促进引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>［what对比概念］\u003c/strong>\u003c/p>\u003cp>拆书家：这个片段中有两个关键词是什么呢？\u003c/p>\u003cp>学习者：关注圈和影响圈。\u003c/p>\u003cp>拆书家：好的，那我们通过例子来分析下如何区分关注圈和影响圈。\u003c/p>\u003cp>\u003cstrong>[例子]\u003c/strong>你的飞机航班因为大雾延误2个小时，大雾属于关注圈还是影响圈的因素呢？\u003c/p>\u003cp>学习者：关注圈\u003c/p>\u003cp>拆书家：对，因为大雾是一种天气现象，天气是一种外部环境因素，是你无法控制的，所以属于关注圈。\u003c/p>\u003cp>\u003cstrong>[例子]\u003c/strong>航班是你同事定的，那同事定航班这件事属于关注圈还是影响圈呢？ \u003c/p>\u003cp>学习者：影响圈\u003c/p>\u003cp>拆书家：好的，小伙伴有别的想法吗？\u003c/p>\u003cp>学习者：关注圈\u003c/p>\u003cp>拆书家：好的，我看到大家对这个有不同的理解了，有的觉得同事的行为是外部因素，是不可控的，是关注圈，有的觉得是我可以不让同事定，我自己定，这个我就可以控制了，好像又属于影响圈。嗯，其实区分的关键点在于这个事情或者行为是否是我们完全可控的。同事行为我们不完全可控，所以属于关注圈，但是订票这件事情是否交给同事来做，是我们可控的，所以属于影响圈。我这样说明大家理解吗？\u003c/p>\u003cp>学习者：理解。\u003c/p>\u003cp>拆书家：\u003cstrong>[例子]\u003c/strong>你等待的过程中，你的行为和心态属于关注圈还是影响圈呢？\u003c/p>\u003cp>学习者：影响圈。\u003c/p>\u003cp>拆书家：是的，因为我们自己行动和心态是我们自己可以控制的。所以，区分关注圈和影响圈的关键点是什么呢？\u003c/p>\u003cp>学习者：外在还是内在。\u003c/p>\u003cp>学习者：是否在自己可控范围内。\u003cstrong>（关键点1）\u003c/strong>\u003c/p>\u003cp>拆书家：是的，那么外部环境、他人和自己分别属于关注圈还是影响圈呢？\u003c/p>\u003cp>学习者：环境和他人属于关注圈，因为不可控，自己属于影响圈。\u003cstrong>（关键点2）\u003c/strong>\u003c/p>\u003cp>拆书家：非常好。那么我们刚才通过列举一件事情的影响因素，并对各种因素进行了分类，来区分是属于关注圈还是影响圈。\u003cstrong>（对应步骤1和步骤2）\u003c/strong>但我们最终是希望积极心态或行动应对不如意的事情，对吧？\u003c/p>\u003cp>学习者：是的。\u003c/p>\u003cp>拆书家：好的，那么接下来的行动应该聚焦到关注圈的事情还是影响圈内的事情呢？\u003c/p>\u003cp>学习者：聚焦影响圈。\u003cstrong>（对应步骤3）\u003c/strong>\u003c/p>\u003cp>拆书家：是的。 \u003c/p>\u003cp>\u003cstrong> [例子]\u003c/strong>比如等待飞机的过程中，我们可以聚焦到影响圈内我们的行为和心态，我们可以选择心平气和把这个当做一次难得的充电时光，打开书本一边学习一边等待，心态也可以摆脱抱怨。\u003c/p>\u003cp>\u003cstrong>［How-行动步骤］\u003c/strong>\u003c/p>\u003cp>拆书家：现在，我们已经总结出来，当我们面对一件不如意的事情时，我们怎么积极主动聚焦到力所能及的事情上：\u003c/p>\u003cp>1、\u003cstrong>列清单\u003c/strong>\u003c/p>\u003cp>结合你面对的事情，列出所有影响这件事的环境因素、他人、以及你对事情的看法和可以采取的行为。\u003c/p>\u003cp>\u003cstrong>2、做区分\u003c/strong>\u003c/p>\u003cp>根据是否完全可控的关键点来区分出所有事件或因素分别是属于关注圈还是影响圈。\u003c/p>\u003cp>\u003cstrong>3、聚集积极行动\u003c/strong>\u003c/p>\u003cp>聚集到影响圈内力所能及的1-2件事情，制定行动计划并付诸行动。\u003c/p>\u003cp>【举例】讲一个我自己的小故事。一年前我经常埋怨老公不学习新的育儿理念，更不谈参与科学育儿，以致于夫妻关系是很糟糕的。那么如果用今天的方法来分析，第一步，列清单，这个事件中，涉及到老公的想法和行为，涉及到其他家人的想法和行为，涉及到他的工作环境等，涉及到我自己的想法、态度和做法，第二步，做区分。工作环境、老公的想法和行为、家人的想法和行为不是我完全可控的，所以属于关注圈，而我自己的想法和行为才是可控的，属于影响圈。第三步，聚焦积极行动，调整自己的心态，反求诸己，我自己做到科学育儿了吗？我后来加入了一个家庭教育社群，学习并制定一些家庭教育计划和实践，比如家庭英语启蒙计划，每周会有绘本阅读，英语小游戏，慢慢的，老公看到了小孩的表现有进步，2岁会说一些简单的英语单词。老公也逐渐被我影响而加入到科学育儿和英语启蒙中来。我的影响圈真的扩大了。 \u003c/p>\u003cp>\u003cstrong>［预防异议］\u003c/strong>\u003c/p>\u003cp>拆书家：可能有小伙伴会问关注圈的事情我们确实无法完全可控，难道就无能为力了吗？不是的。无法完全掌控不等于我们什么事都不能做。比如天气无法控制，但是我可以调整我对天气的态度；同事工作效率低，不是我能控制的事情，但我们可以善意的给同事提工作更高效的建议帮助他改善效率。\u003c/p>\u003cp>\u003cstrong>［where--适用边界+Why--好处］\u003c/strong>那么这个方法适用范围很广，尤其是面对不如意的事情时，区分关注圈和影响圈，并在影响圈内积极行动，我们就会摆脱受害者心态，重新掌控自己的人生。比如当你开始抱怨家人的不良习惯，或者你的朋友向你抱怨文件又出现了纰漏等，而你就可以用今天学到区分关注圈和影响圈的方法来做自我对话或跟朋友对话，帮助采取积极心态和积极行动。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2 编写剧本\u003c/strong>\u003c/p>\u003cp> 现在我们来做个小练习，请大家编写一个小故事，使用我们今天所学的三个步骤，区分关注圈和影响圈的方法，设计一个对话剧本，剧本要有人物对话和情节变化（起因、经过和预期结果）二、三百字即可，请大家现场应用，把设计的剧本摘要写在纸上，5分钟后，我会邀请1组小伙伴跟大家分享。\u003c/p>\u003cp>\u003cstrong>学习者A2小剧本\u003c/strong>\u003cbr>\u003c/p>\u003cp>地点： 百读书社 人物：蘅蒹和三宝 时间：今晚\u003c/p>\u003cp>背景：三宝的老公和儿子吵架，三宝找蘅蒹抱怨\u003c/p>\u003cp>对话内容：\u003c/p>\u003cp>蘅蒹：你在烦啥？\u003c/p>\u003cp>三宝：我老公和儿子吵架了，我好烦。\u003c/p>\u003cp>蘅蒹：这件事你能控制吗？\u003c/p>\u003cp>三宝：不可控啊。\u003c/p>\u003cp>蘅蒹：那你烦啥呢？又不可控，对吧。\u003c/p>\u003cp>三宝：那我现在能做啥呢？\u003c/p>\u003cp>蘅蒹：那你想想你现在能做啥？\u003c/p>\u003cp>三宝：我给他们做好吃的，给他们营造一个沟通的环境。\u003c/p>\u003cp>【向学习者反馈】：好的，感谢蘅蒹的剧本分享。这个是对话形式的，其实对话中就贯穿了聚焦影响圈积极行动的三个步骤。比如“你在烦啥？”三宝会说出来一些事情，这其实就是在\u003cstrong>列举\u003c/strong>事件因素了。接下来问她“这个事情你可控吗？”，三宝说他人吵架的事情，不可控的，帮助她\u003cstrong>区分\u003c/strong>出来他人吵架属于关注圈。接着问“你能做啥？”其实就是在帮助三宝聚集影响圈，\u003cstrong>聚焦\u003c/strong>到自己能做的事情上，三宝说“我给他们做好吃的，给他们营造一个沟通的环境。”这就是在列\u003cstrong>行动计划\u003c/strong>了。\u003c/p>\u003cp>结语：感谢两位的分享，今天我们一起学习了区分关注圈和影响圈并积极行动的方法：列清单，做区分，和聚焦积极行动。希望大家能有收获，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1579186848000,"updated_at":1593439309000,"ria":true},{"id":9640,"topic":"龙卷风TF3-1过级","learn_goal":"各位能够通过制定“统合综效”的第三种方案，解决在认识、行动等","remark":"《高效能人士的7个习惯","level":"TF3-1","duration":30,"status":29,"type":0,"chaishujia":{"username":"龙卷风","city":"昆明"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>各位小伙伴，大家好！我是龙卷风，很高兴能和大家一起进行拆书训练！\u003c/p>\u003cp>为了便于拆书活动的开展，今天的小伙伴我们编成一个小组，待会讨论、交流、分享的时候就以小组为单位进行。\u003c/p>\u003cp>\u003cstrong>学习目标 \u003c/strong>\u003cbr>\u003c/p>\u003cp>今天拆页的主题是：“统合综效”创造性合作；拆解片段来自《高效能人士的7个习惯》 P287。 \u003cbr>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，各位能够通过制定“统合综效”的方案，解决在认识、行动等方面的冲突和分歧，实现互惠共赢。\u003c/p>\u003cp>\u003cstrong>图书介绍\u003c/strong> \u003cbr>\u003c/p>\u003cp>下面给大家介绍下这本书：\u003c/p>\u003cp>【场景】各位小伙伴都可能面对着计划被紧急事情干扰、工作分歧这样的情况吧，比如，年初你定下了一个年度小目标：暑假时陪家人到国外去旅游，你做好了计划，安排了时间，随着时间临近，你憧憬着在海边和家人嗨！“叮铃铃”，老板电话来了，“情况紧急，提升工作方案提前了，你本周拿出来”，“海边度假不要去了”；你好好计划的出国旅游就要被其他紧急事情冲掉，老板和你就是否去度假产生了分歧，你心急如焚，感觉自己计划被打乱了，不知道如何下手。\u003c/p>\u003cp>【提问】各位小伙伴，你面对计划被其他事情干扰的时候你是怎么做的？你是如何来预防这种情况出现的？你在与家人或同事有选择、方案有分歧的时候，你是如何来解决的？ \u003cbr>\u003c/p>\u003cp>【影响】其实在工作和生活中，我们经常会面对突发情况、计划外的事情，这些事情往往会干扰原来的计划，处理不当原有计划完成不了、突发事情也处理不好，导致自己长期处于瞎忙低效的状态中，看起来很忙，看起来做了大量的事情，目标没有实现，压力依然很大。分歧和差别无处不在，我们经常委屈求全、折中妥协、非此即彼，双方感觉都不爽。 \u003cbr>\u003c/p>\u003cp>【解决】怎么解决呢？《高效能人士的7个习惯》这本书将从思维上入手，坚持价值目标导向、要事第一、积极主动，以始为终，不断更新，让你聚焦自身价值目标，将时间精力等关键资源聚焦于有助于目标实现的关键事，积极主动完成有利于价值实现、目标完成的关键事情和重点工作；让你应用第4代时间管理方法，关注有价值、不紧急的要事，提前计划、主动解决，团结协作合理授权，有效避免计划外事情干扰和带来的压力，实现价值的最大化和时间效率的最高化，成为高效能人士，掌控工作和生活。\u003c/p>\u003cp>面对分歧，其让你在相互理解、相互尊重、互惠共赢的的基础上，尊重差异，移情沟通，应用“统合综效”方法，创造性解决分歧和差异，实现共赢。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":13473,"quote":"\u003cp>接下来，让我们走进今天的拆页，请大家花1-2分钟阅读下原文拆页。看完的小伙伴，给举手示意一下。\u003c/p>\u003cp>\u003cstrong>[主题]\u003c/strong>：统合综效——创造性合作的原则\u003c/p>\u003cp>\u003cstrong>[片段来源]\u003c/strong>：拆解片段来自《高效能人士的7个习惯》P286\u003c/p>\u003cp>\u003cstrong>【R：阅读原文】\u003c/strong>\u003c/p>\u003cp>一位父亲想利用假期带全家去露营钓鱼。他策划许久，做好一切安排，两个儿子也兴奋地期待着。然而妻子却打算利用难得的假期，陪伴久病不愈的母亲。一场家庭争端一触即发。\u003c/p>\u003cp>丈夫说：“我们已经盼望了一年，而且孩子们到外婆家无所事事，一定吵翻天更何况她老人家病情并没有那么严重，又有你妹妹就近照顾。”\u003c/p>\u003cp>妻子说：“她也是我的母亲，不知道在世上还有多少日子，我要陪在她身边。”\u003c/p>\u003cp>“你可以每晚打电话，反正我们会跟她一起过圣诞节。”\u003c/p>\u003cp>“那还有好几个月，不知那时她是否还在人世。母亲总比钓鱼更重要。”。\u003c/p>\u003cp>“大夫和孩子比母亲更重要。”\u003c/p>\u003cp>这样争执下去，最后或许会有折中的安排，也许是妻子独自去探望母亲，丈夫带着孩子去度假。可是夫妻俩都会有内疚感，心情不可能愉快，孩子也会察觉到，也不会玩得尽兴。\u003c/p>\u003cp>或者，先生妥协，但心不甘情不愿，有意无意地就想证明如此决定何其错误。反之，妻子顺从先生的心意，却毫无玩兴。倘若母亲不幸在此时病危或撒手人衰，妻子不会原谅丈夫，丈夫也难以原谅自己。\u003c/p>\u003cp>不论是哪一种妥协，都会成为夫妻间挥之不去的阴影。两个人会相互指责对方的无情，不负责任和当初的错误决定。即使多年以后，这件事还可能会是他们的争论焦点，甚至可能导致整个家庭的破裂。很多家庭都是一开始的时候幸福美满，你侬我侬，最后却因为一点小事火药味十足。\u003c/p>\u003cp>通过沟通，丈夫深刻而真实地感觉到妻子陪伴母亲的愿望，知道妻子原是想减轻妹妹常年照顾母亲的负担，也的确不知道母亲还能在世多长时间，而且母亲确实比钓鱼重要得多。\u003c/p>\u003cp>而妻子理解了丈夫想让家人团聚在一起和让孩子们开心的苦心，知道他此还花心思去上培训班和购买装备，相信为家人留下一个美好的回忆十分重要。\u003c/p>\u003cp>于是他们试着寻找第三条可行之道。\u003c/p>\u003cp>先生说：“也许在这个月找一周，家务请人代劳，其他由我负责，你就可去看母亲。要不然，到距离母亲较近的地点去度假钓鱼也不错，甚至邀请附近的亲友一起度假，更有意思。”\u003c/p>\u003cp>他们有商有量，指导找出双方都满意的解决方案，而且比原来的方案和妥协的办法都好得多。\u003c/p>\u003cp>这不是一种交易，而是变革，两个人都得偿所愿，也是彼此感情更上一层楼。\u003c/p>","explains":"\u003cp>好，小伙伴们都已经阅读完了，下面我们来具体解析下。\u003c/p>\u003cp>\u003cstrong>【强化讲解\u003c/strong>\u003cstrong>概念\u003c/strong>\u003cstrong>】\u003c/strong>\u003cstrong>WHY\u003c/strong>\u003c/p>\u003cp>上面拆页通过介绍夫妻双方在假期安排分歧上处理的案例，告诉我们“统合综效”的基本概念和重要性。\u003c/p>\u003cp>什么是“统合综效”？我给大家举几个例子介绍一下：\u003c/p>\u003cp>比如说，双方在解决分歧和冲突中，一方提出：“我的方案考虑非常全面、非常适合，效果最好，按我的来”。这是不是“统合综效”？不是的，因为这个方案是唯我独尊，没有考虑并尊重对方提出的差异，是非此即彼的选择。\u003c/p>\u003cp>“用你的方案，我的不完善，就不用了”，是不是“统合综效”？这也可能不是，因为这里面感到更多的是妥协、委屈求全。\u003c/p>\u003cp>“我们把方案中共识的部分整合成一个方案”，这是不是“统合综效”？这不一定，因为虽然形成了共识但很有可能没有形成1+1大于2的效果，也就不是统合综效。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>WAHT\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>我们可以看出，“统合综效”不是非此即彼、妥协折中、简单的部分相加，它需具备尊重差异、互惠共赢、整体大于部分之和的协作等条件和要素。所以，“统合综效”就是判断和尊重差异，相互取长补短，实现互惠共赢；就是尊重并整合各方，实现整体大于部分之和，即1+1大于2；各个部分是整体的一个组成部分，但又不仅仅是一个组成部分，而是最具激发、分配、整合和激励作用的部分。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>案例\u003c/strong>\u003cstrong>讲解\u003c/strong>\u003cstrong>概念\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>拿拆页案例中来说，“到距离母亲较近的地点去度假钓鱼也不错，甚至邀请附近的亲友一起度假”就是双方真诚沟通后得到了“统合综效”的第三条道路。\u003c/p>\u003cp>首先，它是双方都尊重理解差异的，丈夫深刻而真实地感觉到妻子陪伴母亲的愿望，妻子理解了丈夫想让家人团聚在一起和让孩子们开心的苦心，没有非此即彼，二选一；\u003c/p>\u003cp>其次，它是互惠共赢的，妻子丈夫都没有妥协、折中，大家实现了自己的愿望，没有因此而委屈；\u003c/p>\u003cp>再者，它是协同的，协同使整体大于部分之和的；最终方法不是两人方案简单的叠加，也不是两人的共同点之和，而是大于两人原有计划之和，其更好地满足妻子、丈夫的需求，还带来额外的幸福感。\u003c/p>\u003cp>\u003cstrong>【How引出具体步骤】\u003c/strong>\u003c/p>\u003cp>“统合综效”这么重要，哪我们如何寻找到“统合综效”的第三条道路啦？我结合上下归纳总结出五个步骤，来寻找“统合综效”的创造性解决方法：\u003c/p>\u003cp>1.详细说明问题或机遇。这是对当前面临的情况进行基于事实的、客观详细地表述和说明，使双方能够客观地看待当前存在的问题、机遇和挑战。\u003c/p>\u003cp>2.倾听别人的意见。在尊重对方差异的前提下，不带任何偏见地听取对方意见和建议想法，深入了解其需求，感受其情绪，更加深入理解对方。\u003c/p>\u003cp>3.表达你自己的意见。真诚表达自己的意见和需求，让对方深入了解和理解自己。\u003c/p>\u003cp>4.大家一起开动脑筋，集思广益。双方结合客观事实，在相互尊重差异、理解需求的基础上，应用多种方法如头脑风暴等，寻找解决问题、满足需求、实现共赢互惠的办法。\u003c/p>\u003cp>5.共同找到最佳方案。双方共同确定实现互惠共赢的最佳方案，实现1+1大于2。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>我们拿一个具体的事例来看看如何“统合综效”：现在正在进行的中美贸易摩擦，停停打打，谈谈停停又谈，现在要签署第一阶段的协议。\u003c/p>\u003cp>我们粗略分析一下这个过程。第一步：详细说明问题或机遇，双方各自表述自己的看法，有的拿数据报告，有的找权威组织，有时候还通过直接对话，各自发表声明、关键人物谈话等方式说明；\u003c/p>\u003cp>第二步、第三步：相互倾听、表达，会谈中，各自介绍自己的立场，需求，不断明确底线，有和有斗，但双方都表明是在坦诚的气氛中进行沟通表明愿意进行下一轮沟通谈判，互信坦诚是双方相互倾听理解的基础；\u003c/p>\u003cp>第四步、第五步就是集思广益、寻找最佳方案，中间经历停停谈谈，甚至出现倒美方指责中方倒退的情况，但经过努力最终达成了第一阶段的协议。\u003c/p>\u003cp>具体来看，第一步、第二步、第三步是真诚沟通、尊重差异的过程，中间两个国家不断博弈、调整，最终为实现共赢打好基础，是一个相互理解、尊重、相互认同的过程；第四步、第五步是实现共赢的过程，创造性解决问题的过程，考验的是智慧。\u003c/p>\u003cp>从这个事例来看，互惠共赢、“统合综效”是多么不容易，相互尊重、相互理解不容易，找到共同目标即使是阶段性的目标也不容易，找到“统合综效”的互惠共赢的方案也不容易。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>步骤难点讲解\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>请问一下小伙伴：这5个步骤，哪一步最难？最容易疏忽的是哪一步？最容易出问题的是哪一步？\u003c/p>\u003cp>（小伙伴回答：第一步容易疏忽，大家上来就讲；第二步倾听容易出问题，相互尊重难以坚持，第五步找到方案比较难）\u003c/p>\u003cp>对的，正如小伙伴所说，第一步最容易被忽略，大家直接上来就表达、倾听，没有对事实和机遇进行客观表述，形成一个基础；第三步、第三步最容易走偏，大家往往没能始终坚持共赢互惠、客观的想法，不自觉中将自己的情感带入，导致需求没有真诚表达；第四步最难，考验智慧和灵活性，往往会觉得没有这个“统合综效”的办法。\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处】\u003c/strong>\u003c/p>\u003cp>解决分歧和差异，如果我们不按照“统合综效”的步骤来做，我们往往就片面强调自身利益，不能充分尊重他人，不能始终坚持互惠共赢，也就不会产生双赢的解决办法，要不强势要要求他人人接受，或折中妥协，或委屈求全，导致至少有一方是输的，自然不会长久和形成合力、双方效能不会最大化，最终产生分离甚至是对抗和冲突。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>或许有人一开始觉得很难，而且认为1~5个办法走步骤走完也不一定会寻找到“统合综效”的方案，效果也是不好的。其实我们因为尊重差异、真诚沟通，积极为对方着想，努力寻找互惠共赢方案，在这个过程中增加了信任和了解，在某种程度上就已经实现了一个共赢。另一方面，“统合综效”的道路，一般情况下是存在的，只要坚持双赢模式、尊重差异，确实愿意理解对方，你就能找到一种让每一个人都受益更多的方案，这也是一个不断提升、循序渐进的过程。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>适用于双方都有合作共赢模式、尊重差异的思维观念，需要在相互信任的环节下进行真诚沟通，没有这种观念、环境，就无法充分沟通和理解，也就无法实现“统合综效”。\u003cbr>\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>&nbsp;\u003c/p>\u003cp>1.拆书帮提倡“大脑中过一遍，等于实际应用了一遍”，下面请各位小伙伴编一段小故事，设计出主题、人物、情景变化（包括起因、经过、结果）和当时双方的对话、动作等，编写出小剧本；剧本中要有角色使用“统合综效”的步骤来解决分歧和差异，对应前面学到的技能内容。我准备了一个简单的剧本格式供大家参考，如下：\u003c/p>\u003cp>&nbsp;&nbsp;\u003cstrong>时间：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>地点：\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;\u003cstrong>人物：\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;\u003cstrong>内容：\u003c/strong>（事件过程，含角色行为的顺序，及具体的表情动作描述）\u003c/p>\u003cp>&nbsp;&nbsp;\u003cstrong>对白：\u003c/strong>（事件中对话的具体内容）\u003c/p>\u003cp>&nbsp;&nbsp;\u003cstrong>旁白：\u003c/strong>（可选）（用来介绍背景、人物关系、人物的内心想法等）\u003c/p>\u003cp>2.&nbsp;下面给大家5分钟的时间，请各位小伙伴编写出小剧本，等会我们邀请小伙伴来给我们分享下。注意，剧本中有角色要体现“统合综效”的5个步骤。\u003c/p>\u003cp>（小伙伴们编写剧本）\u003c/p>\u003cp>3.好，时间到，下面我们请一位伙伴给大家分享一下；请范范给大家分享应用“统合综效”的小剧本，大家掌声欢迎！\u003c/p>\u003cp>\u003cstrong>学习者案例记录：现场记录\u003c/strong>\u003c/p>\u003cp>范范：我给大家分享一下我的小剧本。\u003c/p>\u003cp>\u003cstrong>时间：\u003c/strong>晚上21:00\u003c/p>\u003cp>\u003cstrong>地点：\u003c/strong>家里客厅\u003c/p>\u003cp>&nbsp;&nbsp;\u003cstrong>人物：\u003c/strong>丈夫，妻子\u003c/p>\u003cp>&nbsp;&nbsp;\u003cstrong>内容：\u003c/strong>夫妻双方就春节假期安排分歧进行讨论，利用“统合综效”找出合适的方案。\u003c/p>\u003cp>&nbsp;&nbsp;\u003cstrong>对白如下：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>丈夫：\u003c/strong>老婆，你有时间吗？我们坐下来一起商量一下今年春节怎么安排吧。（丈夫一边说一边站起来，把老婆拉到沙发上坐下，并将咖啡递给老婆）\u003c/p>\u003cp>\u003cstrong>妻子：\u003c/strong>好，我们好好商量一下，不然老是心里面添堵。（老婆接过咖啡，喝了一口）\u003c/p>\u003cp>\u003cstrong>丈夫：\u003c/strong>现在距离春节还有2个周，我们都要放假了，小孩补习班也马上要放假了，一家人难得有空，还凑在一起；但我两在春节安排上有不同意见，我相信我们只要好好合计一下就能把这个事情安排好。（说完，停了停，身体向前倾）你是怎么想的，能告诉我吗？\u003c/p>\u003cp>\u003cstrong>妻子：\u003c/strong>我们平时陪我父母时间本来就少，这一年都没有回去过，而且我算了一下：我们有三年没和他们一起过年了（同时比了一个3的手势）；因此我想想今年春节我们和小孩一起回去陪父母过年；我已经提前打电话给他们说了，他们也准备了年货，屋子也收拾好了，等着我们回去；如果春节不回去，就没有时间陪他们，一家人也难得团聚，他们会很失望的。\u003c/p>\u003cp>\u003cstrong>丈夫：\u003c/strong>你主要是想陪陪父母，一家人团聚一下，是吗？\u003c/p>\u003cp>\u003cstrong>妻子：\u003c/strong>是的，平时没时间，春节假期难得有时间，要陪陪他们。\u003c/p>\u003cp>\u003cstrong>丈夫：\u003c/strong>我理解你的想法；我说说一下我的想法：咱们小孩平时学习压力大，一年来老是做作业、上兴趣课，都没有出去走走、见见世面；我想春节假期游客相对少，带孩子出去走走，放松一下，增长增长见识；我前几天还咨询了朋友、上网找了攻略，拟定了线路，就想我们一起去旅游，过一个不一样的春节。\u003c/p>\u003cp>\u003cstrong>妻子：\u003c/strong>难怪上次我说回家陪老人过年，你就跟我急。我以为你不想回去过年，原来你想带小孩去旅游，长见识，还做了准备工作了，看样子我错怪你了。\u003c/p>\u003cp>\u003cstrong>丈夫：\u003c/strong>上次谈这事，我有点急，没有说清楚，也怪我，道个歉！（说着，拱手道歉）\u003c/p>\u003cp>\u003cstrong>妻子：\u003c/strong>这道歉，我们诚意有点不足啊（说完，两人会心一笑）\u003c/p>\u003cp>\u003cstrong>丈夫：\u003c/strong>陪老人过年一家人团聚、陪小孩旅游去长见识。我俩看看有什么办法能“鱼与熊掌兼得”，大家赶快想想。\u003c/p>\u003cp>\u003cstrong>妻子：\u003c/strong>要不我们回去过节时提前点或晚点回来，空出来的时间去旅游；\u003c/p>\u003cp>\u003cstrong>丈夫：\u003c/strong>好办法，我们还可以在地点上调整一下，把旅游点安排在回老家的中间点，或者返回路线的附近，这样顺路还节省时间。\u003c/p>\u003cp>\u003cstrong>妻子：\u003c/strong>是啊，这个下时间、地点都能兼顾了。（妻子露出了开心的笑容）\u003c/p>\u003cp>\u003cstrong>丈夫：\u003c/strong>还有啊，要不过年后我们带着爸妈一起去旅游，这样也能多陪陪父母。\u003c/p>\u003cp>\u003cstrong>妻子：\u003c/strong>这个主意太棒了！（妻子拍着手说）\u003c/p>\u003cp>\u003cstrong>丈夫：\u003c/strong>那我们这个春节这样安排：我们一起回老家陪父母过年，提前2天走，顺路去名胜点转转；假期结束后带着父母返程，在回来的路上用3天时间去中途或附近的风景点旅游，然后和父母一起回来。这样行不行？\u003c/p>\u003cp>\u003cstrong>妻子：\u003c/strong>这个方法好，陪父母过年，团聚的时间也比原来长；小孩也去了2个不同的地方旅游，增长了见识。\u003c/p>\u003cp>\u003cstrong>丈夫\u003c/strong>：那就这样了，我去查攻略、定路线；你给爸妈打电话。（丈夫笑着站起来准备去查资料、妻子则兴奋地给父母打电话）\u003c/p>\u003cp>&nbsp;&nbsp;\u003cstrong>旁白：\u003c/strong>（丈夫应用“统合综效”5个步骤，解决了春节假期安排的分歧，家庭更加和谐）\u003c/p>\u003cp>&nbsp; 分享完毕，谢谢大家！\u003c/p>\u003cp>\u003cstrong>【拆书家总结】\u003c/strong>\u003c/p>\u003cp>太棒了！掌声送给范范！！通过刚才的小剧本，我们可以看到丈夫应用“统合综效”5个步骤，也就是：详细说明问题或机遇、倾听别人、表达自己、集思广益、寻找最佳方案，找到了调整出行时间、旅游地点、和父母一起旅游、接父母团聚的方案，实现了陪父母、陪小孩旅游目的，实现了互惠共赢。\u003cbr>\u003c/p>\u003cp>通过今天的学习，小伙伴们深入了解“统合综效”概念要点、边界，学习了应用5个步骤来找到有效的第三条道路、实现共赢互惠的方法。\u003c/p>\u003cp>期待“统合综效”的方法能给各位在处理冲突、实现共赢互惠方面所帮助。\u003c/p>\u003cp>今天的分享就到这里，谢谢各位~！~\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1578836951000,"updated_at":1578837491000,"ria":true},{"id":9628,"topic":"聚焦影响圈，变消极为积极","learn_goal":"4招教你变消极为积极的心态调整","remark":"","level":"TF3-2","duration":25,"status":29,"type":0,"chaishujia":{"username":"江源媛","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;【自我介绍】大家好，我是丫丫，我的三个标签是：\r\n演讲——我是锦英头马培训师俱乐部的教育副主席；拆书——我是蜀汉分舵的组织运营副长老；\r\n成长——一年前我还是一个娇生惯养的啃老族，自从接触了像拆书帮这样的社群，认识了上进的伙伴们，让我找到了新的奋进动力。也希望大家和我一起在拆书帮持续成长。开始前我们根据座位两人一组，大家积极参与哦。 &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>在跟随我完成本次RIA现场学习后，学习者能够使用（\u003cstrong>行为\u003c/strong>）聚焦影响圈的四个步骤：列举因素、区分圈层、聚焦影响、实施行动（\u003cstrong>澄清\u003c/strong>），完成一次协助他人聚焦影响圈的沟通演练，从而帮助我们从消极心态调整到积极乐观心态（\u003cstrong>界定\u003c/strong>）。\u003c/p>\u003cp>\u003cstrong>场景\u003c/strong>：眨眼间又要过春节了，又到了要花钱如流水入不敷出的时候了。想想自己2019年年初定的存款3W的经济目标，根本就没有实现，心里很不是滋味，于是得出：老板太抠了，明明挣钱了就是不给我们发。心里也不太舒服。\u003c/p>\u003cp>\u003cstrong>提问\u003c/strong>：大家有没有类似的经历，一个既定目标，当你由于各种原因没有完成时，你心里是怎么想的？你的关注点在哪里？你的关注点在哪里，才能让自己更好的改进？ &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003cbr>\u003cstrong>影响\u003c/strong>：如果关注点没有落到正确的地方，就很难用一个正确的心态看待当下的问题，个人进步效率会很低下；长远来看，不利于我们自身更好地成长，很难成就一番大事。 &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003cbr>\u003cstrong>解决\u003c/strong>：针对这样的情况，怎么办？别怕！给你推荐一本书，叫《高效能人士的7个习惯》，这本书从观念和行为上讲到如何通过塑造好习惯成为高效能人士。\u003c/p>\u003cp>拆页告诉我们什么是影响圈和关注圈，帮助我们思考如何调整自我提供依据，提高人生效率。\u003c/p>\u003cp>\u003cstrong>【A1自测】\u003c/strong>我们先做一个简单的小测试，来了解一下自己做事过程中善于聚焦于积极方面的程度。\u003c/p>\u003cp>给大家1分钟时间，完成以下6个题目，请按照1-6分的标准给自己打分，1代表完全不符合，6代表非常符合。\u003c/p>\u003cp>小测验\u003c/p>\u003cp>请仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分（1代表完全不符合，6代表非常符合）。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1.比起谈天说地，聊八卦绯闻，我喜欢把精力放在自己应该做的事情上。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2.如果工作上出现失误，我会优先思考自己在此过程中出现的问题。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3.我能尽自己最大努力去做好一件我认为必要的事情。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4.当出现了外在因素阻碍了当前我在做的事时，我不会怨声载道。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5.在多个因素共同决定的事项中，我能知道当中哪些因素我自己可以把控。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>6.我总能心无旁骛很快把注意力集中在自己要做的事上。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>总分\u003c/p>\u003c/td>\u003ctd>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>解释自测\u003c/strong>\u003cstrong>】\u003c/strong>好了，时间到，大家的结果都出来了吧。\u003c/p>\u003cp>30分以上 &nbsp;说明你做事能够很好的聚焦于积极方面。\u003c/p>\u003cp>20-30分 &nbsp;&nbsp;说明你做事有一定的自我调整意识，往积极方面聚焦。\u003c/p>\u003cp>20分以下 &nbsp;说明你做事态度不是很积极，通过今天的学习，可以好好聚焦调整一下。\u003c/p>\u003cp>不论测试结果如何，通过今天的学习，我们将学会调整自我的方法，聚焦积极态度。\u003c/p>","ratings_count":1,"texts":[{"id":13459,"quote":"\u003cp>\u003cstrong>【R阅读原文】\u003c/strong>下面给大家1分钟的时间阅读拆页，读完后请举手示意我，谢谢！\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>看一个人的时间和精力集中于哪些事物，也能大致判断他是否积极主动。\u003c/p>\u003cp>每个人都有格外关注的问题，比如健康、子女、事业、工作、国债或核战争等等，这些都可以被归入“关注圈”( Circle of Concer)，以区别于自己没有兴趣或不愿理会的事物。(见图3-3)。\u003c/p>\u003cp>关注圈内的事物，有些可以被掌控，有些则超出个人能力范围，前者可以圈成一个较小的“影响圈”( Circle of Influence，见图3-4)。观察一个人的时间和精力集中于哪个圈，就可以判断他是否积极主动。\u003c/p>\u003cp>积极主动的人专注于“影响圈”，他们专心做自己力所能及的事，他们的能量是积极的，能够使影响圈不断扩大。(见图3-5)\u003c/p>\u003cp>反之，消极被动的人则全神贯注于“关注圈”，紧盯他人弱点、环境问题以及超出个人能力范国的事不放，结果越来越怨天尤人，一味把自己当作受害者，并不断为自己的消极行为寻找借口。错误的焦点产生了消极能量，再加上对力所能及之事的忽略，就造成了影响圈日益缩小。(见图3-6)\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp;&nbsp;只要我们的焦点在关注圈，就等于是允许自己受制于外界条件，自然就不会主动采取必要措施来推动积极变化。\u003c/p>","explains":"\u003cp>\u003cstrong>WHAT\u003c/strong>：\u003cstrong>【现场学员互动】\u003c/strong>\u003c/p>\u003cp>提问：拆页提出了两个注意力的圈，是哪两个圈呢？\u003c/p>\u003cp>回答：关注圈和影响圈。\u003c/p>\u003cp>反馈：很好。我们来看看拆页中是分别怎么定义这两个概念的呢？关注圈是每个人都有格外关注的问题。（健康、子女、事业、工作、国债或核战争等等），影响圈是可以被掌控的（做自己所能及的事）。\u003c/p>\u003cp>提问：正如刚刚的自测题，如果平时总喜欢谈天说地，闲聊八卦，导致当下任务延迟推后，这是聚焦影响圈吗？\u003c/p>\u003cp>回答：不是。\u003c/p>\u003cp>提问：如果当出现了外在因素阻碍了当前我在做的事时，我怨声载道，这是聚焦影响圈吗？\u003c/p>\u003cp>回答：不是。\u003c/p>\u003cp>提问：在多个因素共同决定的事项中，我能知道当中哪些因素我自己可以把控。这是聚焦影响圈吗？\u003c/p>\u003cp>回答：是的。\u003c/p>\u003cp>\u003cstrong>（拆书家反馈）\u003c/strong>很棒！说明大家现在基本能够明确什么是关注圈，什么是影响圈了。你们认为在刚刚自测题的三个例子中，在聚焦“关注圈”时，感觉自己是积极还是消极的心态？\u003c/p>\u003cp>回答：消极。\u003c/p>\u003cp>\u003cstrong>WHY\u003c/strong>: 是的，只有当我们在影响圈上下功夫，关注自己的思维模式时，才能具备更积极的状态做好事情，对吧？但是在生活中我们容易当局者迷，尤其是身处一个会有诸多因素影响的事物中，要意识到自己是在关注圈还是影响圈，要加以判别归类，并实施行动就非常重要了。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>\u003cstrong>HOW\u003c/strong>：我们具体该怎么做呢？我给大家整理了以下4个步骤，帮助我们聚焦于影响圈，养成积极态度：\u003c/p>\u003cp>1.&nbsp;\u003cstrong>列举因素\u003c/strong>：把影响特定事件的具体要点列举出来。“为什么不能做好”“哪些因素导致的？”\u003c/p>\u003cp>2.&nbsp;\u003cstrong>区分圈层\u003c/strong>：明确该影响因素是属于影响圈还是关注圈，进行分类。 “这些因素分别属于影响圈还是关注圈？”\u003c/p>\u003cp>3.&nbsp;\u003cstrong>聚焦影响\u003c/strong>：聚焦影响圈，制定计划。“接下来我重点突破哪一项因素？”\u003c/p>\u003cp>4.&nbsp;\u003cstrong>实施行动\u003c/strong>：根据影响圈中的事项开始行动。“我打算何时开始行动”“如何做？” &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003cbr>\u003cstrong>&lt;举例&gt;\u003c/strong>上半年我们公司新来一个教学主管，基层教学老师小王因为与其意见向左觉得相处起来很不舒服，那段时间上课状态也不是很好，在近期的满意度调查中，评分不是很理想。于是我协助小王分析：\u003c/p>\u003cp>（列举因素）&nbsp;当下的工作任务是把课上好，让学员满意，影响的因素有：课程设计、备课演练、服务沟通、学员感受等\u003c/p>\u003cp>（区分圈层）&nbsp;让小王做个圈层分类：课程设计大纲、备课演练评分规则是教学主管决定，属于关注圈，学员感受是学员自己的，属于关注圈，而课程设计具体方案、备课演练形式、服务沟通是自己的，属于影响圈。\u003c/p>\u003cp>（聚焦影响）因此接下来需要他把关注重点放在自己的影响圈，提升备课能力、服务沟通能力。\u003c/p>\u003cp>（实施行动）&nbsp;于是接下来我们又开始了备课演练，精进服务沟通技巧。通过相互探讨和演练，小王的教学满意度在半年后提升了5%。 &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003cbr>\u003cstrong>WHERE\u003c/strong>：聚焦影响圈是为了让我们的心态从消极调整为积极，并不是说在日常生活中我们一点都不关注身外之事，毕竟知己知彼百战不殆。所以使用的时候注意聚焦影响圈的使用目的。\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A3促动参与\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>案例介绍完毕，接下来，我们就要拆为己用了。\u003c/p>\u003cp>我给大家设计了一个这样的场景：公司销售部门，你是小张，而你的平级同事小王最近销售业绩不佳，他找你吐槽，说最近都是因为公司产品涨价导致的，请你用扩大影响圈的4步法帮助他聚焦到自己的影响圈，给大家8分钟时间，之后请一组伙伴来角色扮演。\u003c/p>\u003cp>\u003cstrong>【学习者分享：尧磊（小王）&amp;张宁（小张）】\u003c/strong>\u003c/p>\u003cp>小王：好烦啊，最近业绩不好，就是公司产品涨价了，好难做。\u003c/p>\u003cp>小张：你觉得业绩不好，除了涨价，还有哪些因素？（列举因素）\u003c/p>\u003cp>小王：除了我们涨价，还有竞争对手太厉害，市场行情不好，和客户沟通也没有效果，主要就是这些。\u003c/p>\u003cp>小张：你觉得这几个影响因素是你自己可以掌控解决的？哪些不能？（区分圈层）\u003c/p>\u003cp>小王：市场行情我控制不了，老板决定要涨价我也没办法，我可以去做的就是：多去了解相应信息和行情做出决断，加强和客户沟通联系，让客户获知我们产品的最新优势。\u003c/p>\u003cp>小张：你打算重点去关注哪一点呢？（聚焦影响）\u003c/p>\u003cp>小王：优先挖掘自己产品的优势。这个最重要。\u003c/p>\u003cp>小张：打算具体怎么做呢？（实施行动）\u003c/p>\u003cp>小王：我打算下周一和产品部沟通详细了解产品新增优势，然后找采购部了解清楚一下具体材料涨价点在哪里。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>好的，如果小王能再后面把了解到的信息记录在一张表上整理就更完善了！同时给小张一点建议：除了按照步骤提问，在每一步小王回答后给一些回应，如“很好，很棒！”不然觉得一直在“灵魂拷问”哦~\u003c/p>\u003cp>非常感谢伙伴的分享，表现得都非常棒，看来是基本掌握了这4个步骤。\u003c/p>\u003cp>\u003cstrong>【A2特定任务】\u003c/strong>: 学习一定要做到知行合一，所以接下来请大家回去思考，自己未来一个月内在工作上或生活上有哪件事情把注意力放在了关注圈产生了消极被动的心态，请运用上今天讲的4个步骤让自己把关注圈聚焦到影响圈。三天后私信我分享一下你怎么做的和你的感受。 \u003c/p>\u003cp>&nbsp;\u003cstrong>【学习者分享：洪洪】\u003c/strong>&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>要到期末了，我们美术学校要计划开始安排缺课学生从下周一开始来补课了。我看到其他老师一打电话，孩子们都答应说能来，而我缺课的学生比较多，我一打电话，很多学生都不能来，让我很难过，心理变得很消极。\u003c/p>\u003cp>我想到了你讲的“把关注圈聚焦到影响圈”的方法，让自己从消极心态调整到积极乐观心态。&nbsp;\u003c/p>\u003cp>到底是什么原因导致我补课学生出勤率比同事低呢？我的学生年龄比较大，期末时间紧张；我主要教的素描课单次时间很长；我没有用积分奖励制度吸引孩子来补课；素描课堂比较枯燥不有趣。（列举因素）\u003c/p>\u003cp>哪些是我自己可以把控的因素，哪些不是呢？ 素描时长是学校规定，老师工资也是这样算的，不能随意修改；学生年龄段大所以时间紧张我也没法掌控；而积分制度我自己可以设置奖励，提升素描课堂趣味性我也可以下一番功夫。（区分圈层）\u003c/p>\u003cp>接下来我重点突破哪个问题呢？我认为核心还是提升素描课堂趣味性，增强对孩子的吸引力，让他们想来补课。（聚焦影响）\u003c/p>\u003cp>要如何做呢？从之后的素描课开始，除了单纯教学，还要给学生讲一些学习素描对生活或者学习的好处，给他们看看中央美院的作品，展望一下未来美术应用的可能性。同时，每次上课多表扬学生，让孩子们有成就感。（实施行动）\u003c/p>\u003cp>感受：这样即使出勤率不理想，自己确实把关注点集中到可以掌控的因素上了，心态变积极不少，并且很有开始执行的动力了。 &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>今天我们两个圈，是什么？对，影响圈和关注圈。也知道了如何区别这两个圈。并学习了聚焦影响圈的方法：列举因素、区分圈层、聚焦影响、实施行动，把消极心态转化成积极心态。希望大家把这个方法真正应用在生活中，帮助我们用更积极的状态做事，成为高效能人士！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1578639902000,"updated_at":1579100611000,"ria":true},{"id":8929,"topic":"运用双赢四步法，寻求双方需求，达成一致目标","learn_goal":"见实录","remark":"","level":"TF3-2","duration":25,"status":29,"type":0,"chaishujia":{"username":"徐沈逸","city":"上海市"},"club":{"name":"上海申展分舵","city":"上海市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好！欢迎来到TF3-2的拆书现场，我是今天的拆书家徐沈逸。我的三个标签是笔记侠，科普作家，二级拆书家。我先给大家分个组，左手边小伙伴为一组，右手边小伙伴为一组。\u003c/p>\u003cp>【学习目标】\r\n在跟随我完成本次RIA现场学习后，学习者能够在与他人出现利益分歧时，可以使用（行为）双赢四步法（澄清），实现双方都能接受的结果（界定）。\r\n【图书介绍】2min\r\n我今天要拆解的图书是《高效能人士的7个习惯》。\r\n【事件场景】或许你碰到过这样的场景：盼星星盼月亮好不容易盼来了周末，工作了一周非常疲惫，你只想宅在家里好好休息一下，而你的孩子却希望你带TA出去玩……\r\n【提问】\r\n大家是否遇到过类似情况呢？\r\n你当时是怎么做的呢？效果怎样？\r\n还可以怎样做呢？\r\n是不是没想到还有更好的方案？\r\n【影响】当我们与孩子总达不成一致意见，你说孩子不听话，但孩子却说你并不理解他，亲子关系也会越来越疏离。 这说明其实这类事情的影响很大，如果处理不好的话，后果很严重，影响我们的幸福程度。\r\n【解决】\r\n《高效能人士的七个习惯》一书中提到的第四个习惯——双赢思维恰好能帮助我们解决这类问题。周末和孩子想做不同事情的时候，它可以帮你和孩子明确双方的需求，找到一个孩子和你都能接受的结果，避免冲突发生。\r\n双赢思维促使我们不断地在所有的人际交往中寻求双边利益。读这本书，还可以使你参透高效能人士持续成功的秘诀，通过改变自己的思维方式从而改变你的人生。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":12661,"quote":"\u003cp>赢/输的方法不可能带来双赢的结果。你总不能要求别人：“不管你是不是喜欢，都要以双赢为目标。”问题是怎样找到双赢的解决方案。\u003c/p>\u003cp>哈佛法学院的教授罗杰·费舍和威廉·尤利曾合作出版的《走向共识》建议在谈判中坚持“原则”，而不是“立场”。虽然他们并没有使用“双赢”一词，但是倡导的精神和本书不谋而合。\u003c/p>\u003cp>他们认为原性谈判的关键是要将人同问题区分开来，要注意利益而不是立场，要创造出能够让双方都获利的方法，但不违背双方认同的一些原则或标准。\u003c/p>\u003cp>我建议不同的人和机构采用以下四个步骤完成双赢过程：\u003c/p>\u003cp>首先，从对方的角度看问题。真正理解对方的想法、需要和顾虑，有时甚至比对方理解得更透彻。\u003c/p>\u003cp>其次，认清主要问题和顾虑（而非立场）。\u003c/p>\u003cp>再次，确认大家都能接受的结果。\u003c/p>\u003cp>最后，找到实现这种结果的各种可能途径。\u003c/p>\u003cp>习惯五和六直接说明了如何处理其中两点，后两个章节里将详细探讨。\u003c/p>\u003cp>需要指出的是，双赢过程同双赢结果密不可分，只有经由双赢过程才能实现双赢结果，这里的目的和手段是一致的。\u003c/p>\u003cp>双赢并非性格魅力的技巧，而是人类交往的一种模式。\u003c/p>","explains":"\u003cp>【A1请大家自测】\u003c/p>\u003cp>在开始阅读之前，首先请大家做一个简单的测试。以下共5个题目，请与自己平时的行为或态度进行对照，然后给自己打分。1分代表完全不符合，6分代表非常符合，请大家仔细阅读表格里面的每句话，根据自己的实际情况来给自己打分，时间1分钟。打完分以后请大家计算一下自己获得的总分。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1.有利益分歧时，我愿意去了解对方的需求。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2.别人出言不逊时，我总是能保持清醒，不针锋相对。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3.我从不认为一方输了，另一方就一定赢了。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4.我总是试图了解清楚双方想要达到的目标。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5.与人合作时，我总是努力寻找达成一致意见的解决方案。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>【I解释自测题】\u003c/strong>\u003c/p>\u003cp>大家都做完了吗？之所以让大家做这个自测题，是想通过这些题目让大家检验一下自己的双赢思维。这5个题目总分30分，有没有哪一位小伙伴是20分以上的？请举一下手！这个题的得分越高，表示你的双赢思维越强。\u003c/p>\u003cp>大家可以关注一下自己最终总的得分：\u003c/p>\u003cp>如果得分在20分以上，说明你在人际沟通中做到了双赢思维；\u003c/p>\u003cp>如果得分在10~20分，说明勉强能够做到双赢思维；\u003c/p>\u003cp>如果得分不到10分，那么希望你能在接下来的环节中比其他小伙伴投入更多的注意力。\u003c/p>\u003cp>请大家用1分钟的时间，阅读一下原文片段，阅读完成以后可以向我示意一下。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>现在进入拆书讲解的环节。\u003c/strong>\u003c/p>\u003cp>【学习目标】学习完这个片段，我们能够在与他人出现利益分歧时，使用（行为）双赢四步法（澄清），实现大家都能接受的结果（界定）。\u003c/p>\u003cp>【简短互动】我想请问一下大家，在日常工作和生活中，你和他人在利益上出现分歧时，一般你是怎么做的呢？是互不让步？还是沟通后折中解决？\u003c/p>\u003cp>如果你和他人有利益分歧时，都互不让步，有没有可能形成一致意见？\u003c/p>\u003cp>不但达不成一致意见，有时还会产生严重的后果。你们认为可能会产生什么后果呢？\u003c/p>\u003cp>【不这么做的坏处】长远来看，不是双赢，就一定是两败俱伤。因为一方赢了，对方的态度、情感和双方之间的关系一定会受到影响。\u003c/p>\u003cp>你认为什么是双赢呢？\u003c/p>\u003cp>【what】小结一下，通过刚才的提问，大家对“双赢”这个概念有了初步的了解。“双赢”就是双方有福同享，皆大欢喜。\u003c/p>\u003cp>【WHY】这种人际交往结果往往能促使所与人都愿意接受决定，完成计划。双赢可以使双方互相学习、互相影响、双方获利。\u003c/p>\u003cp>【HOW】那怎么样才能实现双赢呢？\u003c/p>\u003cp>首先，换位思考\u003c/p>\u003cp>第二，明确问题\u003c/p>\u003cp>第三，找共同点，确定一个双方都能接受的结果\u003c/p>\u003cp>最后，实现途径，找到实现这种结果的各种可能途径。\u003c/p>\u003cp>【举例】给大家举个我自己的例子。我不喜欢吃辣，但是我的老公很喜欢吃辣。所以，如果我们要一起出去吃饭，该怎么办呢？吃辣的话，我老公舒服，可是对不起我的舌头；吃不辣的话，我喜欢吃，可是我老公却觉得淡而无味。那么如果我们用双赢的四个步骤，如何达到我们想要的结果呢？\u003c/p>\u003cp>1、换位思考，我理解到我老公的需要，在家里我的婆婆做的饭菜都很清淡，所以他想如果出去吃饭的话最好能换换口味。\u003c/p>\u003cp>2、明确问题，我的目标是吃不辣的，我的顾虑是如果都是辣的，我肯定吃不了几口；老公的目标是想吃辣，他的顾虑是如果吃不辣的，那和在家里没有什么区别。\u003c/p>\u003cp>3、找共同点，双方能接受的结果是他吃他的辣，我吃我的不辣。\u003c/p>\u003cp>4、实现途径，找到双方都满意的方法。比如说鸳鸯火锅，一边是辣的汤底，一边是清汤汤底。\u003c/p>\u003cp>就这样，我们双方都满足了自己的需求。\u003c/p>\u003cp>【预防异议】有的小伙伴说，我喜欢舍己为人，我每次都让对方赢也能够让我们的人际关系很和谐。我想说的是，也许一次两次还能忍受，可是总有一天你会受不了。平静的关系下面涌动着的是压抑的情感，被践踏的价值和隐藏的埋怨，最终将导致两败俱伤。\u003c/p>\u003cp>【适用边界】当然，不只是日常生活中和亲朋好友之间需要使用双赢思维，在工作场合同样适用。\u003c/p>","interaction":"\u003cp>【A3促动参与】10min\u003c/p>\u003cp>经过我刚才的一番讲解，大家应该都能够理解什么是双赢四步法了吧？不过，别太得意哦！理解不代表能记住，更不代表会应用。大量的新知识会因为你习惯用旧知识去解决而被你遗忘，学而不用是学习的大忌。所以，为了学以致用，我们现在一起做一个演练！\u003c/p>\u003cp>请大家认真听一下要演练的场景：在给孩子报兴趣班的问题上，小王和TA的另一半有了不同的看法。一个希望让她学跳舞，培养良好的气质；另一个则不希望学跳舞，因为担心跳舞的训练太苦，甚至会造成脚趾的畸形。\u003c/p>\u003cp>面对这样的情况，小王应该如何运用今天学习的双赢四步法促使TA和TA的另一半达成双赢的结果呢？\u003c/p>\u003cp>现在，请两个人一组，进行讨论演练。5分钟后，我会请一对小伙伴以角色扮演的方式和大家分享。\u003c/p>\u003cp>\u003cstrong>学习者案例\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小王：我们应该要问问看孩子喜欢什么，不是说跳舞好就让她去跳舞。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小红：我知道你的顾虑，作为父亲，你想保护孩子，不想让她太累。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小王：你也是喜欢培养孩子的艺术感觉。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小红：那么我们现在明确一下问题是什么？你并不是反对孩子学跳舞，你只是反对孩子学习她不感兴趣的东西。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小王：只要她感兴趣，学跳舞也没有关系。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小红：所以，我们来找一个大家都能接受的结果。如果她对跳舞感兴趣，那就让她上。如果她对跳舞不感兴趣，那就找其他的方法培养她在艺术方面的修养。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小王：上其他的兴趣班也可以。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小红：实现途径的话，我觉得是我们先沟通，然后再跟孩子沟通。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小王：可以带孩子上各种体验课，了解孩子的兴趣所在。\u003c/strong>\u003c/p>【A2催化应用】1min\u003cp>好，刚才大家在我给定的情景下运用双赢四步法进行了现场演练，相信大家对这个知识点有了更清晰的认识。\u003c/p>\u003cp>为加深大家对这个知识点的理解，现在我给大家布置一个任务，回去后再来应用一下今天所学的知识。你回去后不妨邀请你最信任和亲密的家人，一同回忆你们上一次吵架（出现分歧），在平静的状态下探讨用双赢四步法应当怎样处理。然后将运用的情况，在微信上发给我，好吗？\u003c/p>\u003cp>（现在可以在便签上把你的A2写下来，打算邀请谁什么时间什么地点说的主题是关于什么场景的）\u003c/p>\u003cp>\u003cstrong>学习者案例\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间：明天晚上\u003c/strong>\u003c/p>\u003cp>\u003cstrong>地点：我家\u003c/strong>\u003c/p>\u003cp>\u003cstrong>主题：和男朋友探讨该不该喝酒\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步&nbsp;换位思考（他不是真的想喝酒，可能只是为了应酬。）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步&nbsp;&nbsp;明确问题（其实，我担心的是他借着喝酒之名做出其他背叛我的事情）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步&nbsp;&nbsp;找共同点（完全不喝酒不想行，毕竟是人际交往的需要。可以喝一点酒，但是不能过量，过量了会伤身体）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第四步&nbsp;&nbsp;实现途径（喝酒之前，拍个视频给我看，我就知道和什么人一起喝酒，大概要喝多少酒）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1569286075000,"updated_at":1569303290000,"ria":true},{"id":7681,"topic":"双赢4步法实现共赢","learn_goal":"3-2","remark":"当你与他人出现利益分歧时，可以运用（行为）双赢四步法（澄清），实现共同双赢的结果（界定）。","level":"TF1-1","duration":25,"status":30,"type":0,"chaishujia":{"username":"刘犇","city":"邯郸"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>【开场】各位小伙伴大家好，我是邯郸回车巷筹备分舵的二级拆书家刘犇，让我们一起拆书赋能、终身成长！\r\n【学习目标】在跟随我完成本次分享后，学习者在有要事在身恰遇朋友求助时（where），使用拒绝干扰三步法（澄清），理清自己的要务目标与时间精力（行为），委婉的拒绝朋友的求助（界定），从而让我们排除干扰，专注完成自己的要事。\r\n学习者场景法介绍图书\r\n【场景】各位伙伴一起来想一个这样的场景，在你有非常重要的事情要做时，你的一位好友前来请你帮忙，虽然请求帮忙的那件事儿确实是你擅长的，可是这事儿要占用你不少精力，你是拒绝呢？还是碍于面子勉强答应呢？\r\n【提问】大家经历过这样的场景吗？那时你是怎样做的？我们在要事在身时，又该如何处理别人的求助呢？\r\n【影响】拒绝朋友你可能会感到不好意思，甚至会认为朋友会从此耿耿于怀，影响你们的关系。而碍于面子勉强答应，很可能因为精力不够，朋友的忙没有帮好，自己的事儿也受到了影响，致使鸡飞蛋打、两败俱伤。\r\n【解决】史蒂芬.柯维在《高效能人士的七个习惯》第三个习惯“要事第一”中告诉我们，要时刻把最重要的事放在第一位来做，而在自己有要事在身却遇到别人求助时，理清自己的要务目标与时间精力，委婉的拒绝朋友的求助，从而让我们排除干扰，专注完成自己的要事。\r\n &nbsp;\u003c/p>\u003cp>测试\u003c/p>\u003cp>1、朋友请我帮忙时，我总是一口答应。\u003c/p>\u003cp>2、朋友向我求助时，我总是忽略自己当下要做事情的重要性。\u003c/p>\u003cp>3、我总是会迫于面子或者压力等，答应我本不想做的事情。\u003c/p>\u003cp>4、我有要事在身，不想答应朋友的请求时，不知道如何拒绝。\u003c/p>\u003cp>【A1：请大家自测】\u003c/p>\u003cp>在今天的分享片段之前，我请大家先拿出我刚才发给大家的量表做个自测，每项分值1-6分，认为该项完全符合的给6分，完全不符合给1分，不十分符合的按符合程度酌情给分2--5分。时间1分钟。\u003c/p>\u003cp>【I：解释量表】\u003c/p>\u003cp>好，刚才给到大家的量表自测，是想了解大家在生活中，在自己有要务在身，能否懂得拒绝影响你要务目标的求助，分值4-11分的伙伴举手示意一下，说明您比较懂得拒绝；分值12-18分的伙伴挥挥手，这个分值说明您有拒绝的意识，但不太懂得如何拒绝；而分值在19--24分的伙伴，说明您很不擅长在自己有事时处理朋友突然的求助，您更适合来听今天的分享：专注要务目标，三步委婉拒绝。\u003c/p>","ratings_count":1,"texts":[{"id":11174,"quote":"\u003cp>刚才我已经把原文拆页发给大家了，现在请各位用2分钟的时间阅读一下原文片段，阅读完毕请举手示意一下。\u003c/p>\u003cp>原文片段：\u003c/p>\u003cp>人各有志，各有优先要务。必要时，应该不卑不亢地拒绝别人，在紧急与重要之间，知道取舍。\u003c/p>\u003cp>我妻子曾经受邀担任一个社区主席。其实有很多别的重要事务等她完成，但是迫于压力她最终还是接受了邀请。\u003c/p>\u003cp>之后她打电话给一位闺蜜，询问对方是否愿意参加委员会。对方认真听了很久后说，“桑德拉，这个计划听起来很不错，确实值得一试。我非常感谢你让我参与，但是我现在确实不能参加，我想让你知道我真的非常感谢你邀请我。”\u003c/p>\u003cp>桑德拉本已做好了一切准备，但只欠一个礼貌的拒绝。她告诉我她真希望自己当时也能拒绝。\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导 \u003c/p>\u003cp>【互动】\u003c/p>\u003cp>我：好，片段大家已经看完了，在这个案例中，桑德拉遇到了一个什么问题呢？\u003c/p>\u003cp>亚丽：朋友邀请她去做社区主席。\u003c/p>\u003cp>我：去做社区主席是一个问题吗？为什么这是一个问题。\u003c/p>\u003cp>常乐：因为她有很多别的重要事务要做。\u003c/p>\u003cp>我：没错，在自己有重要的事务要做时，朋友来邀请她做社区主席，这才是一个问题，那她答应了吗？\u003c/p>\u003cp>亚丽：她答应了\u003c/p>\u003cp>我：那她邀请闺蜜时，她的闺蜜怎么做的？\u003c/p>\u003cp>常乐：她拒绝了，她听完桑德拉的话，对她的计划表示支持，随后感谢了桑德拉，然后拒绝了她。\u003c/p>\u003cp>我：您读的非常认真，大家掌声鼓励。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>这个片段告诉我们，若要专注于自己重要的事儿，就得排除次要事务的牵绊。而朋友向我们求助，就有可能成为我们的牵绊，这时我们需要迅速理清自己的目标和拥有的时间精力等状况，从而像影响我们完成目标的求助说“不”，专注完成自己的要务。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>从片段中我们可以看出，当我们有要事在身时，朋友向我们求助，我们可以用三步来理清自己的目标与现状的时间、精力情况，排除次要事物的牵绊：\u003cstrong>1、耐心听清请求。\u003c/strong>耐心听完求助者的请求是对求助者的尊重，同时也为自己理清目标与现状提供了信息，留出了时间。\u003cstrong>2、理清目标与现状。\u003c/strong>快速梳理自己的目标是什么？自己当前有多少时间和精力，并根据求助者的请求信息，确定自己能否在不耽误自己要务目标的情况下，很好的向求助者提供帮助。比如向朋友提供帮助只需要5分钟，而你在保证完成要务的前提下，能有1个小时的时间精力，那么你自然可以答应朋友的求助，反之，你则应该拒绝，这时就要用到最重要的第三步。\u003cstrong>3、礼貌的拒绝。\u003c/strong>礼貌的拒绝需要我们首先对求助者要做的事情给予充分肯定，之后对其表示感谢，感谢他对你的认可与信任，最后说明情况不能帮忙。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>为什么要这样做呢？因为如果没有这么做，就很有可能答应一件特别占用你时间、精力，严重影响你当下要做的重要事儿，最后很可能是朋友的忙没帮好，自己的重要的事儿也受到了影响，可谓是鸡飞蛋打、两败俱伤。而运用三步法，可以让我们在有要务在身时，理清自己的要务目标和时间精力，对影响我们完成目标的求助勇于说“不”，礼貌的拒绝。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>有的伙伴可能会说，虽然理清了自己，礼貌的进行了拒绝，可朋友还是会觉得你没有帮到他啊。我想提醒大家的是，我们不提供帮助，朋友还可以找其他人，我们没有必须接受朋友求助的义务，不要有这个心理负担。同时，当我们通过理清，知道自己有更重要的事情去做时，会更加笃定、更加真诚地去礼貌拒绝，相信真心为你考虑的朋友会理解的。\u003c/p>\u003cp>【举个例子】\u003c/p>\u003cp>去年9月我报考了国家二级企业人力资源管理师，当时距离考试仅剩下一个月的时间。正当我集中精力进行复习时，乒乓球俱乐部的一位朋友找到我说：“10月中旬有一个市级乒乓球俱乐部比赛，但是俱乐部由于少一个人不能参加，所以想请你来参加，我们得每天在一块练练，拿个前三名不成问题。”我一边耐心的听朋友的请求，一边迅速梳理我的要务目标和时间精力，距离考试还有一个来月的时间，就我目前掌握的情况来看，要想顺利通过考试，自己每天要从下班后的3小时空余中，抽出最少2个小时的时间用于学习，而如果我答应参加这次乒乓球俱乐部比赛，我就得每天去练2个小时的球，这样回家后，即使我把剩余的时间都用上，也不能保证我学习的时间，而要想打好球，回家还得看一些比赛视频，思考思考战术，这就更加没有时间精力了，这样下去，我哪个也做不好。所以，待朋友说完请求后，我对他说：“这次市乒协举办乒乓球俱乐部比赛真是一个不错的活动，大家也非常有希望进前三（肯定意义），感谢对我的信任与认可啊（表示感谢），但是我真的不能去参加这次比赛，实在抱歉（说明情况礼貌拒绝）”。最终朋友理解了我，并找到了另一位朋友加入俱乐部。\u003c/p>\u003cp>（观察点6：【I】环节拆书家有进行简短互动，并能精确控场。）\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>这个片段的方法适用于，当有要事在身朋友向你请求帮助时，用来理清自己的要务目标、时间精力等，并对于影响自己要务目标的求助礼貌的拒绝。\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp;【A3现场演练】\u003c/p>\u003cp>下面请我们大家做个演练，朋友小李成立了一家亲子活动俱乐部，她知道你在亲子教育方面颇有心得，就邀请你做他的顾问，这需要你每天到她的俱乐部组织活动，可是你现在刚刚报名了全国RIA联合训练营，并给自己定下目标，要6个月内成长为三级拆书家。\u003c/p>\u003cp>作为小李的朋友，这时你该如何处理呢？下面请运用我们今天片段上所学的三个步骤，设计一段你与小李的对话，你的回答中要体现所学的三个步骤，现在请大家在小组内开始演练，一会儿我们选出一到两人给大家分享。\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>常乐扮演被求助者，亚丽扮演小李。\u003c/p>\u003cp>亚丽：常乐姐，我知道你在亲子教育方面特别有经验，正好我成立了一家亲子活动俱乐部，我想请你来做我们俱乐部的顾问。\u003c/p>\u003cp>常乐：哦，亲子活动俱乐部特别好啊，特别有意义，这个顾问是怎么做呢？\u003c/p>\u003cp>亚丽：需要你帮我们组织一下活动，前期每天需要1到2个小时的时间的引导，当然我们会给你顾问费用。\u003c/p>\u003cp>常乐：需要每天吗？\u003c/p>\u003cp>亚丽：对的\u003c/p>\u003cp>常乐：我特别感谢你信任我，我也特别愿意参加这样的活动，因为如果现在的家长们如果真的都能懂得亲子教育的话，受益的是那些孩子们，家长也会和孩子一起成长，这是特别棒的一件事，这也是我的一个心愿，不过我刚报了全国RIA训练营，需要连续21天，我也有朋友是拆书家，他说这个受益很大，我也参加过他们的拆书活动，感觉特别受益，我也想加入他们，所以我就报了这个21天训练营，每天做作业需要两个小时，所以我现在精力真的不够，并且我还准备用4—6个月时间尽快成为三级拆书家，到那时我在亲子教育方面也会更加专业，但是目前这段时间真的不行，特别不好意思。\u003c/p>\u003cp>亚丽：没事，也怪我没有早点通知你，也期待以后更优秀的你加入我们。\u003c/p>\u003cp>我：两位伙伴的演练很棒，给她们一个掌声。【号召鼓掌】刚才在常乐姐和亚丽的演练中，常乐姐很好的应用到了三步法，首先她在与小李的对话中，耐心的听清了小李的请求，然后她在这个过程中，理清了自己要做的重要的事儿，就是参加全国RIA训练营，并逐渐成长为拆书家，明确了自己现有的时间精力不足以帮助小李，最后是肯定、感谢小李，并对小李礼貌的拒绝，很好的应用了今天所学的三步法。【摘要点评】&nbsp;\u003c/p>\u003cp>【A2布置任务】\u003c/p>\u003cp>&nbsp;各位伙伴，今天大家学会了拒绝干扰三步法，请大家在三天内，找机会跟别人分享一下你今天的收获，最好是找一个需要这个方法的朋友，并给出她怎么做会更好的建议，请你将这一过程记录下来并反馈给我，你像别人分享的越深入，你对这个方法的掌握也就更好。【找人分享的A2】\u003c/p>\u003cp>&nbsp;好，今天的分享就到这里了，希望大家学以致用，拆为己用，谢谢大家。\u003c/p>\u003cp>学习者作业：\u003c/p>\u003cp>小青：我学到了拒绝干扰三步法后，有很大的收获，因为我以前就是一个自己有重要的事还没做起，却不太会拒绝别人的人。这次学完回去后，我就把这个方法分享给了的一个闺蜜，下面是我和她的对话。\u003c/p>\u003cp>小青：燕子（化名），我看你整天这么忙，我都替你觉得累，很是心疼你，你可得照顾好自己啊。\u003c/p>\u003cp>燕子：谢谢姐的关心，可是有什么办法啊，就这么多活儿，总不能不干吧。\u003c/p>\u003cp>小青：我知道你工作不少，可是总不至于这么忙啊，你这么忙就没有其他原因吗？\u003c/p>\u003cp>燕子：其他原因，你指的是什么？\u003c/p>\u003cp>小青：你昨天下班了，还在做文件排版，那是你的工作本职吗？\u003c/p>\u003cp>燕子：哦，你是说这个啊，是朋友找我帮忙，我因为还有我的工作没做完，所以做着做着就就到下班时间了，我也只能做完在走啊。\u003c/p>\u003cp>小青：你就是和我一样，不懂得在自己忙碌的时候，去拒绝那些影响你工作的求助，所以单位里老看着你忙，自己的事也没有做太好……\u003c/p>\u003cp>燕子：有时顺口就答应了，有时我也不想答应，可一想拒绝却不知道怎么开口。\u003c/p>\u003cp>小青：你找我啊，我前两天刚学会一个拒绝干扰三步法，对你肯定有用，在你自己的事没弄完，却有人请你帮忙时，用好这三步即可。首先，朋友向你求助的时候，你得耐心仔细的听他把话说完，这不仅是对朋友的尊重，也给你留出一个缓冲的时间。然后，你在朋友向你请求这段时间，要迅速想想自己有那些重要的事儿还没做？帮助朋友会不会影响到自己重要的事？如果真的影响到你自己重要的事儿，那你就应该礼貌的拒绝。\u003c/p>\u003cp>燕子：哦，我好像明白了，那怎样礼貌的拒绝呢？\u003c/p>\u003cp>小青：礼貌的拒绝包括要对朋友要做的事表示一个认可，然后你得感谢朋友在他周围这么多人理选择了让你帮忙，这是对你的信任，然后像对方诚恳的表示拒绝。这样既保障了自己重要的工作不受打搅，又不伤害朋友的感情……\u003c/p>\u003cp>燕子：哦，原来可以这么做啊，我要早知道，不就轻松多了，谢谢姐的提醒。\u003c/p>\u003cp>小青：不客气，我以前和你一样，所以一看到你这么辛苦，就想帮帮你。\u003c/p>\u003cp>燕子：谢谢青姐，我以后知道怎么做了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1555863121000,"updated_at":1555863585000,"ria":true},{"id":7526,"topic":"如何快速化消极为积极","learn_goal":"调整消极情绪到积极情绪","remark":"如果你想有效的识别自己的消极情绪，并想把消极情绪转化为积极情绪，那么就来拆书吧，哈哈。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"悟空_长春分舵","city":"长春"},"club":{"name":"长春阅微分舵","city":"长春"},"prologue":"大家好！我是0级拆书家悟空，今天是我的TF1-2过级训练。\r\n 关于分组，我们依然保持上轮的分组情况。\r\n我先着重介绍一下今天我们要拆解的图书和主题。\r\n今天带来的书是《高效能人士的七个习惯》，想必大家都听说过或者读过、甚至是拆过，作者是世界著名的大师史蒂夫柯维。这本书将告诉我们，如何通过七大准则，帮助我们顺利通过“从依赖到独立、从独立到互赖”的心灵成长过程，从而达到事业、家庭、人际关系、个人成长等方面圆融和谐、实现人生全面的成功。\r\n积极主动是七个习惯中第一个，也是其他六个习惯的基础，这个习惯是非常重要的，那积极主动可以划分为积极和主动两种小习惯，我们今天就来通过书中的片段拆解一下，如何通过语言，自我调节快速的达到积极的状态。","ratings_count":1,"texts":[{"id":11001,"quote":"\u003cp>接下来给大家2分钟时间阅读下手中的片段，读完的小伙伴可以给我眼神示意下我，谢谢。\u003c/p>\u003cp>R&nbsp;原文片段\u003c/p>\u003cp>拆书片段来自：《高效能人士的七个习惯》P.62&nbsp;\u003c/p>\u003cp>不要说“我办不到”\u003c/p>\u003cp>我们可以利用自我意识检讨自身的观念，以言语为例，它颇能真切反映一个人对环境的态度。\u003c/p>\u003cp>习惯于消极被动的人，言语中就会流露出推卸责任的个性。例如：\u003c/p>\u003cp>“我就是这样。”仿佛是说：这辈子注定改不了。\u003c/p>\u003cp>“他使我怒不可遏!”意味着：责任不在我，是外力控制了我的情绪。\u003c/p>\u003cp>“办不到，我根本没时间。”又是外力控制了我。\u003c/p>\u003cp>“要是某人的脾气好一点”，意思是：别人的行为会影响我的效率。\u003c/p>\u003cp>“我不得不如此。”意味着：迫于环境或他人。\u003c/p>\u003cp>言语态度对照表：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>消极被动\u003c/p>\u003c/td>\u003ctd>\u003cp>积极主动\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>●我已无能为力\u003c/p>\u003c/td>\u003ctd>\u003cp>●试试看有没有其他可能性\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>●我就是这样一个人\u003c/p>\u003c/td>\u003ctd>\u003cp>●我可以选择不同的作风\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>●他使我怒不可遏\u003c/p>\u003c/td>\u003ctd>\u003cp>●我可以控制自己的情绪\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>●他们不会接受的\u003c/p>\u003c/td>\u003ctd>\u003cp>●我可以想出有效的表达方式\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>●我被迫……\u003c/p>\u003c/td>\u003ctd>\u003cp>●我能选择恰当的回应\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>●我不能\u003c/p>\u003c/td>\u003ctd>\u003cp>●我选择\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>●我必须\u003c/p>\u003c/td>\u003ctd>\u003cp>●我情愿\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>●如果\u003c/p>\u003c/td>\u003ctd>\u003cp>●我打算……\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>好，我看到大家都读完了，接下来我就讲一下我对于这个片段的理解。\u003c/p>\u003cp>\u003cstrong>【why】大家都知道积极是一个褒义词，是一个赞美的词，大多数都想成为一个积极的人，积极的去工作、积极的去生活，对吧？那大家有没有想过积极到底是个什么东西呢？我在新华字典上查询“积极”，给出的定义是“肯定的、正面的；进取的，热心的”，是不是有点抽象。具体点来说，我觉得积极它可能是一个念头、是一种情绪、是一种态度、一种观念等等，总之它会给我们带来正面的力量、促进行动的力量。\u003c/strong>\u003c/p>\u003cp>我们都想拥有这种积极的力量，但是有一个科学实验表明，绝大多数人在生活中，每天产生的消极情绪要远多于积极的情绪，我们可能不知不觉中就会收到外界的影响而变得消极。那没有什么方法，能够让我们快速发现我们自己已经变得消极，然后自我调节，变得积极起来呢？\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>我今天带来的片段R，就能很好的解决这个问题。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>那么根据片段信息，我们应该怎么做呢？\u003c/p>\u003cp>我来详细介绍下：\u003c/p>\u003cp>第一步，通过自我审视，进行消极情绪识别。我们平时照镜子，这是自我观察，看外在的部分，比如衣着，容貌是。自我审视，是对内的观察，观察你的想法、你的情绪以及你的语言，来观察它是处在积极的状态还是消极的状态。当你发现你犹豫不定、患得患失、害怕、暴躁、觉得做了也没用的时候，都是别人不好，或者你跟别人说“我不行，我不能，我被迫”这样的话时，你现在就很可能处在消极的状态。这个过程就是自我审视，需要你在工作、生活中及时的去观察你自己。\u003c/p>\u003cp>第二步，通过语言调节，转换消极为积极。为什么语言能够调节？因为，内心的想法会决定你的行为，同时你的语言也同样会刺激和影响你的想法。我们表达什么样的语言才能进行调节？要表达自己想要对自己、对他人、对事情负责人的语言。\u003c/p>\u003cp>比如“我试试、我可以、我选择、我选择、我情愿、我打算”，大家平时的时候也可以根据片段中的对照表看看自己是否发表了消极的语言，如果是的话，建议换成积极的表达方式。\u003c/p>\u003cp>这就是第二步，语言调节。\u003c/p>\u003cp>通过以上两步，我们就能有效的识别消极，快速积极了。\u003c/p>\u003cp>为了便于大家理解，我举个我自己的例子。我妈妈每天早上给我做早餐，但是有时起来较晚或者不饿，就不吃了，我妈妈就会唠叨几句，我不喜欢唠叨，一听唠叨，就有点烦，就说“就是不吃了”，我和我妈妈的心情就不爽了，这就进入消极状态了。那我昨天类似的情况，当要“烦”的时候，意识到消极了，转变语言说“那我晚上吃”，心情马上轻松起来。\u003c/p>\u003cp>【where】每个方法都有自己的适用范围，这个方法比较适合自我暗示，或者与其他人沟通时使用。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】\u003c/strong>刚刚我们读过这个拆页，我也为大家详细介绍了具体的内容，为了能让大家感同身受一番，下面我就带领大家完成激活经验和催化应用的练习，那么请各位现在就想一想，在生活中，是不是也会遇到消极的自己，请选取一件你印象比较深刻的让你消极的事件，或者让你消极的时刻，\u003c/p>\u003cp>1、&nbsp; 可不可以给我们讲一下关于你消极的小故事？\u003c/p>\u003cp>2、&nbsp; 那你回想一下，你有没有发现你消极了，比如通过你的想法、你的情绪、你的语言？\u003c/p>\u003cp>如果你当时没有发现你消极了，你现在能否通过回忆做一下自我审视。我希望大家能够把自己想到的事和你的反思，&nbsp;&nbsp;&nbsp;&nbsp;请大家讨论一下。3分钟后我将邀请小伙伴分享自己的问题。\u003c/p>\u003cp>参与者（侯君）发言：\u003c/p>\u003cp>高中的时候，有一个老师特别严厉，你犯点小错误，他也会当着大家的面批评你，刚开始我觉得没必要，小错误，私底下说下一年就行了，他当着这么多人的面说出了我的缺点，这么多人知道了，也促使我改正缺点，并且脸皮也越来越厚了，也挺好的。\u003c/p>\u003cp>（拆除家点评）：这个过程，实际上侯君也应用了这个方法，先是识别到自己消极，然后相当于自己和自己说，“没事，我以后会更好”，就转化为积极状态。\u003c/p>\u003cp>\u003cstrong>【A2】\u003c/strong>方法大家已经掌握的差不多了，今天活动结束之后，一定还是会遇见消极情绪出现的状况，那你应该具体做些什么才能运用今天学到的方法发现你的情绪，并运用语言转换的把消极情绪转变成积极情绪呢？\u003c/p>\u003cp>参与者发言(黄佳)： 自己是一个时而独立，时而迷茫的人，有时候生活安排的很充实，旅游啊，徒步啊等等，有时候就不知道自己该干什么，该往哪方面发展，有时候就会非常的消极。\u003c/p>\u003cp>那今天学会这个方法，目标是在后面21天里使用这个方法，让自己出现消极状况的时候，通过语言自我激励变得积极。\u003c/p>\u003cp>行动：每天中午和晚上，回顾一下白天是否有消极的状态出现，比如想法、情绪或者语言方面；如果回顾一下当时是否说了一些消极的语言，如果说了，按照片段R中积极、消极语言对照表的例子，转化一下语言方式，说积极的话。即时但是没说消极的话，现在对自己说些积极的话，比如我选择、我可以、我情愿等语言方式让自己更积极。\u003c/p>\u003cp>【结束语】希望大家之后能根据自己写的方法，发现自己消极的状况，并快速的调整自己，让自己更加积极。好！今天我的过级活动就到这里。感谢各位的配合和参与，不足之处还请多多指教，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1554643706000,"updated_at":1554643706000,"ria":true},{"id":4644,"topic":"深度倾听4步法","learn_goal":"深度倾听4步法","remark":"","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"龚正伟","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"各位伙伴上午好， 我叫龚正伟，一句话就可以记住我，一个正直而伟大的老龚！","ratings_count":1,"texts":[{"id":7684,"quote":"\u003cp>\u003cstrong>（F\u003c/strong>\u003cstrong>）\u003c/strong>今天给大家带来的书叫《高效能人士的七个习惯》，作者叫史蒂芬柯维，是美国学界的“思想巨匠”，被时代周刊评为“人类潜能的导师”。这本书一共讲了7个行为习惯：积极主动、以终为始、要事第一、双赢思维、知己知彼、统合综效和不断更新，帮助你走向成功。\u003c/p>\u003cp>\u003cstrong>（A）\u003c/strong>这本书在美国的影响力仅仅次于，美国每个家庭里必有的一本书《圣经》，《福布斯》杂志说它是“有史以来最具影响力的10大管理类书籍”之一。比起同类书籍，做到很牛的一点是，它是世界500强企业必备的培训课程和教材。\u003c/p>\u003cp>\u003cstrong>（B）\u003c/strong>你是不是觉得自己很渴望成功，但又不知道从何下手？这边书从思维、到方法再到工具，指引你从个人成功到团队成功。你又是不是希望在与人协作过程中更加有效和顺畅？这本书的双赢合作可以帮你轻松做到。如果你想提升自己的沟通能力，特别是做一个好的倾听者，这本书的移情沟通法和深度倾听法可以教你简单做到。\u003c/p>\u003cp>\u003cstrong>（学习目标）\u003c/strong>在跟着我完成本次学习之后，你就能在倾听的时候，使用深度倾听4步法，设计出一句话回应对方，让对方愿意把话继续说下去。\u003c/p>\u003cp>\u003cstrong>（分组）\u003c/strong>好，为了帮助大家更好地互动与学习，现在咱们进行分组。\u003c/p>\u003cp>今天我带来的片段就是深度倾听4步法，我已经把片段发到1、2群了，现在大家花2分钟左右的时间读一下，读完之后，抬头示意就可以了。\u003c/p>","explains":"\u003cp>好，相信大家也读的差不多了，没读完的也没关系，接下来我们一起来学习下这个片段。\u003c/p>\u003cp>\u003cstrong>（what\u003c/strong>\u003cstrong>）\u003c/strong>这个片段就是教我们如何用深度倾听4步法做一个好的倾听者。不管在工作还是生活当中，我们都需要有效沟通，而关键是有一个好的倾听者，也就是以对方为中心，能够真正理解对方的意思和感受。\u003c/p>\u003cp>\u003cstrong>（how\u003c/strong>\u003cstrong>）\u003c/strong>那我们具体要怎么做呢？片段的方法，我管它叫，深度倾听4步法：\u003c/p>\u003cp>1、&nbsp; 抓住重点。也就是找出对方言语中的重点。比如，片段例子中抓住的重点就是：无聊。\u003c/p>\u003cp>2、&nbsp; 推理逻辑。也就是根据重点推出背后的逻辑。重点无聊背后的逻辑就是：不想上学了。\u003c/p>\u003cp>3、&nbsp; 观察心情。也就是观察对方的动作、表情等肢体语言，体会对方的心情。上学无聊的心情就是：有挫折感。\u003c/p>\u003cp>4、&nbsp; 总结回应。也就是用一句话总结出前面三步的重点、逻辑和心情，然后回应。片段总结出的一句话就是：你对上学有很深的挫折感？\u003c/p>\u003cp>举个例子，我老婆上周又给我抱怨她们公司那些事儿，说：我们公司的人好烦？以前的我都是这么说：怎么会烦啊，你们大公司大企业的，挺好的啊！她紧接着就说：你懂什么嘛，一点都理解我！我说：我怎么就不理解你了呢，你说说！她有点愤怒的跟我说：算了，懒得跟你说！然后我就无语了！\u003c/p>\u003cp>我心里就想如果还是像以前那样说会怎么样，肯定还是那样甚至是更糟糕！所以我就用了深度倾听4步法：\u003c/p>\u003cp>第一步，抓住重点，她的重点应该是：好烦。\u003c/p>\u003cp>第二步，推理逻辑，好烦背后的逻辑应该是：某个人做了什么事情让她好烦。\u003c/p>\u003cp>第三步，观察心情，当时她肢体语言所表达的心情是：讨厌，甚至愤怒。\u003c/p>\u003cp>第四步，总结回应，我就总结出一句话回应说：老婆，你的意思是说，有个同事做了什么事情，让你觉得很讨厌甚至是愤怒，是吗？\u003c/p>\u003cp>结果，她很诧异的说：你怎么知道？就是的……然后就滔滔不绝说了很多，关于她们同事具体做了什么，是怎么怎么过分，一点不为她着想等等，一聊就是1个小时，感觉根本停不下来。最后她还抱着我说，老公今天你好像有点不一样耶，特别懂我！\u003c/p>\u003cp>\u003cstrong>（不做的坏处）\u003c/strong>所以在我们沟通中如果做不到深度倾听的话，我们很多时候就会以自己为中心，不能很好的理解对方想要表达的意思和感受，更有可能造成不必要的误解，甚至是冲突。很容易像我之前那样沟通，结果直接把天聊死，长期这样的话就会影响到人与人之间的关系！\u003c/p>","interaction":"\u003cp>\u003cstrong>（A1\u003c/strong>\u003cstrong>显像提问）\u003c/strong>好，我刚讲了一个我自己的例子，现在大家回想一下，自己在过去一个月内，有没有经历过，有人找你倾诉、促膝长谈的场景，比如有个闺蜜想跟你好好倾诉下生活的苦闷，或是你的爱人想跟你好好说说他的困扰，又或者是你的同事打算跟你抱怨老板的不好等等。选一个你经历过，印象比较深刻的写下来，如果没有，你可以写下：有人打算跟你倾诉的类似场景。用30秒回想一下，并在小组内分享具体是什么事情，什么时候发生的，经过和结果怎么样？时间控制在3-4分钟。我待会会请一位同学简单分享一下。\u003c/p>\u003cp>\u003cstrong>（学习者案例）\u003c/strong>她老公给说，去那个地方的机票没有了。她回答说那这样不是很好吗，可以不用去了的啊！结果老公就无语了，把天聊死了。\u003c/p>\u003cp>\u003cstrong>（A1+\u003c/strong>\u003cstrong>方法运用）\u003c/strong>好，刚刚你们都分享了自己遇到的有人找你倾诉的场景，现在想想如果你再次遇到了同样的情况，你用刚学的深度倾听4步法设计出一句话回应对方，让对方愿意把话继续说下去！写下你应用的4个步骤，关键是那一句回应的话，然后在小组内分享，时间控制在6-7分钟。同样待会如果时间允许的话，我会请一位同学简单分享一下。\u003c/p>\u003cp>\u003cstrong>（学习者案例）\u003c/strong>她用了深度倾听4步法这样设计：\u003c/p>\u003cp>1、&nbsp; 重点是没有机票了\u003c/p>\u003cp>2、&nbsp; 逻辑是不能去旅游了\u003c/p>\u003cp>3、&nbsp; 心情是感到很失落\u003c/p>\u003cp>4、总结设计的一句话是：老公，你是说买不到机票，不能去旅游了，你感到很失落，是吗？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1517985350000,"updated_at":1517985350000,"ria":true},{"id":4167,"topic":"如何进行有效的沟通","learn_goal":"大家在工作、生活中按有效沟通四个阶段，实现真正有效的沟通","remark":"宣传介绍：“尬聊”、“鸡同鸭讲”大家在沟通时完全不在一个频道。这样无效的沟通是不是常常出现在你的生活中，来我们的拆书帮吧！让我们从新学会有效沟通！\r\n","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"齐艳","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"大家好，我先自我介绍下，我叫齐艳，网名叫喜鹊，从事书法教育推广。\r\n 【图书介绍】\r\n 时间：0.5分钟\r\n 今天我给大家带的拆页来自于《高效能人士的7个习惯》，本书是美国的史蒂芬.柯维博士撰写的。此书在美国的影响力仅次于《圣经》这本书是中国商界最著名，最经典的培训教程，是世界500强企业培训必备教材，也是我们个人自我提升和自我完善不可不读的一本著作。\r\n以上是我对本书的简介。","ratings_count":0,"texts":[{"id":7147,"quote":"\u003cp>【R\u003cstrong>阅读原书拆页\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>时间：\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>分钟\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 我已经把拆页发到珞珈分舵群里，请小伙伴们用1分钟的时间阅读下，看完的小伙伴抬头示意下我。\u003c/p>\u003cp>\u003cstrong>有效沟通\u003c/strong>\u003c/p>\u003cp>这个例子充分显示有效的沟通多么不易，了解他人又是多么重要。正确的沟通方式也就是移情聆听，至少包括四个阶段。\u003c/p>\u003cp>第一阶段是复述句，这至少能使人专心聆听。\u003c/p>\u003cp>子：“上学真是无聊透了”\u003c/p>\u003cp>父：“你已经受不了了，觉得上学太无聊”\u003c/p>\u003cp>第二阶段加入解释，完全用自己的语句表达，但仍用左脑的逻辑去理解。\u003c/p>\u003cp>父：“你不想上学啦”\u003c/p>\u003cp>第三阶段渗入个人感觉，右脑发挥作用。此时听者所注意的已不止于言语，也开始体会对方的心情。\u003c/p>\u003cp>父：“你觉得很有挫折感”\u003c/p>\u003cp>第四阶段是即加以解释，又带有感情，左右脑并用。\u003c/p>\u003cp>父：“你对上学有很深的挫败感”\u003c/p>\u003cp>运用第四个阶段的方式沟通，不仅能了解对方，更能帮助对方认清自己，勇于表达自己\u003c/p>","explains":"\u003cp>\u003cstrong>、\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书家讲解引导】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间：\u003c/strong>\u003cstrong>3\u003c/strong>\u003cstrong>分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>大家是沟通过程中是不是发生过“鸡同鸭”讲的尴尬状况呢？和你的家人，朋友，同事，甚至是领导。给你说一件事或讲一段话，半天你没有理解对方的意思，这时候对方很无奈，着急甚至有点抓狂。这种沟通就是无效沟通，这就是“聆听”出现问题。我们大部分人聆听时并不想理解对方，而是在对方讲诉完后匆匆忙忙下结论，给以“善意”的建议。因为大部分人喜欢用自己在思维过滤一切，用自己的经历理解别人在生活。\u003c/p>\u003cp>而正确的沟通方式从“移情聆听”开始。什么是移情聆听呢？以理解对方为目的聆听，站在说话者的角度理解他们思维模式和感受。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; \u003cstrong>做到有效沟通要做到以下四个阶段：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>第1. \u003c/strong>\u003cstrong>核主题\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>第2. \u003c/strong>\u003cstrong>抓重点。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>第3. \u003c/strong>\u003cstrong>挖情绪。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>第4. \u003c/strong>\u003cstrong>表达重点和情绪\u003c/strong>\u003c/p>\u003cp>如果能熟练运用第四个阶段，不仅能了解对方，更能帮助对方认清自己，用于表达自己。才能达到有效沟通。\u003c/p>\u003cp>例如我的闺蜜她打电话说“亲爱的，我觉得在学校上班无聊极了，每天机械重复做一件事情 ，我快奔溃啦。从现在可以看到我退休。”如果我按有效沟通四个阶段我会这样回应她\u003c/p>\u003cp>\u003cstrong>&nbsp;第1. \u003c/strong>\u003cstrong>核主题。“你在学校上班很无聊是吗？”（这是她的主题）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>第2. \u003c/strong>\u003cstrong>抓要点。“你不想上班啦？”（这段话背后客观核心表达）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>第3. \u003c/strong>\u003cstrong>挖情绪。“你上班感觉很有挫败感。”（谈话所带的情绪）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;第4. \u003c/strong>\u003cstrong>表达要点和情绪。“亲爱的，你不想上班啦，感觉很有挫败感，是吗？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>对方的感觉是不是会觉得我很善解人意呢？会觉得与我沟通很通畅呢？并易认清自己，勇于表达自己。有效沟通会让我们闺蜜的聊天更愉快，感情更好。\u003c/p>\u003cp>这就是有效沟通四个阶段，以上是我对拆页的分享。\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A1\u003c/strong>\u003cstrong>激活经验\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;时间：\u003c/strong>\u003cstrong>5\u003c/strong>\u003cstrong>分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>现在请大家回忆下。最近一段时间有没有因为没有移情聆听产生无效沟通的场景呢？比如家人的抱怨、同事工作部署，交接、朋友相互倾诉等，当时发生的具体情景和最后结果？\u003c/p>\u003cp>请描述起因经过结果，看看无效沟通是如何发生的？分享给你在小组成员。讨论时间（5）分钟。最后请一位小伙伴分享给大家。现在大家可以小组里讨论啦。\u003c/p>\u003cp>&nbsp;[小伙伴分享案例]：\u003c/p>\u003cp>小伙伴和老公在同一家公司，她是采购部主管，老公是销售部。因为采购部的人员频繁调动，影响销售部同事对客户承诺交货时间，影响销售人员的诚信，公司口碑，让销售人员身处尴尬处境。\u003c/p>\u003cp>于是有这样的对话： &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>“你们采购部怎么搞的，天天人员变动，询价时说一周交货，现在又说不行，我怎么给客户交代啊？”老公打电话质问老婆。\u003c/p>\u003cp>“我知道啦，这个现在不说，回家我和你说具体情况，你的问题会帮你搞定的。”老婆觉得很委屈，又不想在办公室解释显得尴尬急于挂电话。\u003c/p>\u003cp>“什么回家说，我现在要解决问题。”老公啦没有说完老婆把电话挂。\u003c/p>\u003cp>无效沟通就是发泄情绪还制造出新矛盾。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>催化应用】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;时间：\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>OK！各小组讨论都很热烈，我聆听发现各小组的小伙伴们都出现过“尬”聊的现象。请大家想象一下未来一周里同事，或父母，或朋友会找你聊天沟通，按有效沟通四个阶段，你可以怎样用移情聆听的方式去回应他呢？请把预想的对话语句表达写到的签纸上。些完以后请交给我，时间2分钟。\u003c/p>\u003cp>今天分享的拆页是“有效沟通四个阶段”希望大家学以致用，能熟练运用到工作生活中去，做到学以致用。\u003c/p>\u003cp>&nbsp;[小伙伴分享案例]：\u003c/p>\u003cp>小伙伴和老公在同一家公司，她是采购部主管，老公是销售部。因为采购部的人员频繁调动，影响销售部同事对客户承诺交货时间，影响销售人员的诚信，公司口碑，让销售人员身处尴尬处境。\u003c/p>\u003cp>老公打电话质问老婆。“你们采购部怎么搞的，天天人员变动，询价时说一周交货，现在又说不行，我怎么给客户交代啊？” \u003c/p>\u003cp>用有效沟通四步骤：\u003c/p>\u003cp>1．核主题。“你们销售部没有办法给客户交代吗？”\u003c/p>\u003cp>2. 抓重点。“你们在客户那边很为难，是吗？”\u003c/p>\u003cp>3．挖情绪。“你现在很愤怒，也很着急，对吗？”\u003c/p>\u003cp>4. 表达重点和情绪。“你们在客户那边很为难，你现在很愤怒也着急。我们看看现在怎么处理能帮你解决问题好吗？”\u003c/p>\u003cp>如果这样沟通既可以解决现有问题，也不会有新矛盾出现。大家心情是不是都很好呢？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1512374029000,"updated_at":1512374303000,"ria":true},{"id":3536,"topic":"克服拖延","learn_goal":"4个小方法克服拖延","remark":"拖延症已经成为很多人生活中的极大困扰。为什么会拖延？如何克服拖延？只需掌握这4个小方法。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"杨硕","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"大家好，我是杨硕。简单的用三个标签介绍下自己，我第一个标签是爱旅行，希望可以在5年内去够20个国家；第二个标签是爱运动，新晋的羽毛球爱好者；第三个标签是爱读书，希望今年可以读100本书，现在已经读了60多本。","ratings_count":0,"texts":[{"id":6419,"quote":"\u003cp>介绍拆书和拆书帮：\u003c/p>\u003cp>&nbsp; &nbsp; 我平常读书也算是比较多的，我想应该算是掌握了很多素材，但是有时候写文章想到一个点，死活也找不到在哪看到的。于是我就很疑惑，我平常看书也不只是看看而已，也会拿笔划线，在空白处写笔记什么的，为什么还是用不上？难道是我记笔记的方法不对？赵周老师曾经说过，记笔记的方法没有好坏，它只是学习思路的外显化。当我在读书划线记笔记的时候，实际上是在进行以书为中心的学习，而拆书法注重的是以学习者为中心的学习。具体体现是RIA便签读书法，R是当我们看书时触动我们的段落，I是把那些内容用自己的话重述下来，而不是摘抄和总结，A1是要联系自己过往的相关经历，A2是提出有利于解决我们实际问题的下一步行动计划。通过这样一个过程，以往看到的书中的知识就很容易被调用，从学习知识转变为提升能力。便签法让我们从学习书中的知识，到让知识为我所用，做到真正的拆为己用。\u003c/p>\u003cp>&nbsp; &nbsp; 拆书帮是基于拆书法的学习爱好者社群，会以各个分舵为单位，由拆书家带领大家现场学习，引导促进学习者理解、运用书中的知识。拆书帮使命是帮助更多的学习爱好者成长为拆书家。\u003c/p>\u003cp>R原文片段：\u003c/p>\u003cp>&nbsp; &nbsp; 我们为什么要拖沓？换句话说，我们为什么通常将至关重要的事排在无关紧要的事之后？可能最普遍的原因是某项特定的重任让人不愉快，一些人很讨厌平衡收入支出以及安排充实的生活，例如填写每月清单、缴税、结识新朋友、发言讲话、答复邮件、倒垃圾、看牙医、锻炼。高效、成功、健康，通常需要我们离开安逸区。对于不愉快的任务，我们通常会推迟。但是，如果我们推迟它们，让事件控制我们，我们的效率会降低，从而自尊心也降低。避免这种降低趋势的唯一途径是控制我们生活中的事件，即使他们有些令人不愉快。\u003c/p>\u003cp>&nbsp; &nbsp; 以下是一些克服拖沓的建议：\u003c/p>\u003cul>\u003cli>\u003cp>设立最后期限，这会带来本没有的紧迫感\u003c/p>\u003c/li>\u003cli>\u003cp>先做不愉快的事儿，这样做，你便会期待更舒适的任务，并每日获得成就感\u003c/p>\u003c/li>\u003cli>\u003cp>将任务游戏化，有效地将无味的任务变得有趣\u003c/p>\u003c/li>\u003cli>\u003cp>设立奖励，刺激你快速完成任务。\u003c/p>\u003cp>（实际拆解图书为《高效能人士的时间和个人管理法则》）\u003c/p>\u003c/li>\u003c/ul>","explains":"\u003cp>&nbsp; &nbsp; 拖延症已经成为很多人生活中一个极大的困扰，好像什么事不拖上一拖反而不正常了，于是很多工作、学习计划因此不能完成。下次拖延症再犯的时候，不如干脆承认你就是“懒”。\u003c/p>\u003cp>&nbsp; &nbsp; 拖延症不是病，为什么那么多人还非要治？其一，它会让我们的生活丧失秩序感。很多日常琐事都让人感到烦躁，柴米油盐酱醋茶，房租水电信用卡，哪样拖延着不去做，都会让你的生活一团乱；在工作中回邮件、整理文档也让人烦不胜烦，但是拖着不去做，整理难度就会越来越大。其二，拖延的成本太高。每天这么多事，总有一两件是特别不想做的，这类事在我们心里的排序是很靠后的，往往都是拖到不能再拖为止。我最近刚好在看《得到》的经济学专栏，里面说“成本”并不只是我们认为的购买成本，而是你用来交换的\u003cstrong>最大价值\u003c/strong>。拖延的成本也并不是1、2小时的学习时间，而是未来的可能性。\u003c/p>\u003cp>&nbsp; &nbsp; 如何来克服拖延症，作者在拆页中提出了四个建议：\u003c/p>\u003cp>\u003cstrong>&nbsp;1.\u003c/strong>\u003cstrong>设立期限\u003c/strong>。\u003c/p>\u003cp>&nbsp; &nbsp; 在任务的截止日期前，给自己设定一条“时间线”。这会让你聚焦在你能控制的当下，避免“突击式”的完成，提升效率和质量。你可以选择截止日期前一天，也可以选择一天的某个时候之前。\u003c/p>\u003cp>在这里给大家推荐一个app——Forest，比如我想在晚上9点前写完一篇文章，9点就是我给自己设立的期限，我要在7点-9点之间专注写2个小时，才有可能完成。在这段时间里我可以用forest种四棵树，每颗代表30分钟。如果这期间我玩手机的话，树就会死掉。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>\u003cstrong>最难的事情提前做\u003c/strong>。\u003c/p>\u003cp>&nbsp; &nbsp; 把你最不愿意做的事，设立成每天第一个要完成的任务，让它成为拖不下去的事。你甚至可以给自己设定一些仪式感，把最重要的几件事写成便签贴在显示器上，最不想做的排第一，做完一一摘掉。这对强迫症有奇效，就个人而言，我就不愿意在电脑上贴条了。\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong>\u003cstrong>任务游戏化。\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 比较枯燥的任务，不要一味地逼自己，想象自己在升级打怪，而不是单纯的咬牙坚持，那样太消耗意志力了。我们之所以会拖延，还有一个重要的原因是，我们日常所做的很多事缺乏及时的反馈，不知道做到什么程度，也就不容易坚持。游戏化思维的好处是反馈特别及时，你升级了属性就会增加，打不打得过别人也是立竿见影。把游戏化思维引入，有助于任务的完成，可以把任务做适当的分解，完成一个阶段性目标可以给自己一个奖励。\u003c/p>\u003cp>&nbsp; &nbsp; 不知道大家玩没玩过那种单机的小游戏，有很多小关卡和几个大关卡。你不想玩了，刚好和大的关卡差一步，你就会想，玩完这关再说。这个大一点的关卡，就是你的阶段性目标。\u003c/p>\u003cp>\u003cstrong>4.\u003c/strong>\u003cstrong>设置奖励。\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 万维钢曾经提到过一个奖励的方法，制作一个自己的随机奖励盒子，把最近想买又纠结的东西、想看的书和电影、彻底放松一天之类的小愿望写成纸条，完成阶段性任务之后，随即抽一个，这样更能调动人的积极性，毕竟，只是物质奖励很难真正调动人的积极性，因为如果你真正需要或者真正想要，你还是会买，没法起到促进行动的目的。\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp; 最近刚刚结束RIA训练营的学习，最后一周的作业要自己找三个拆页写便签，我就犯了拖延症。要求是周六晚上12点之前交，我晚上9点多才开始写，差不多写完的时候已经将近12点了，困得不行，急急忙忙交上去。这样做的后果是，有很多地方写的不是很好，有的片段我后来干脆重写了一遍。\u003c/p>\u003cp>&nbsp; &nbsp; 我的问题是没有给自己设定一个完成的期限，卡着截止时间来，让自己连修改的时间也没有。也没有提升任务的优先级，而是一直往后拖，放在了吃饭、看书、追猫之后。\u003c/p>\u003cp>&nbsp; &nbsp; 目标：运用四步法克服拖延症，把每天最困难的事完成好\u003c/p>\u003cp>&nbsp; &nbsp; 作为一个要成为拆书家的人，我决定每天写一个便签，但是之前完成度不是很高，通过对这个拆页的学习，我可以重新规划一下自己的计划：\u003c/p>\u003cp>1.\u003cstrong>给自己设定完成期限\u003c/strong>。提前把选好的片段会贴到印象笔记里，每天早上通勤的时候用手机写在印象笔记里写便签，如果没写完或者需要修改也尽量在上班的时候完成，不拖到回家再写。这个时间点就是我给自己设立的期限。\u003c/p>\u003cp>2.\u003cstrong>困难的事情提前做。\u003c/strong>写便签的过程对我来说最难的就是连接自己的经验，也就是写A1，我会把它放在第一个来做，并且给自己增加一点小小的仪式感，每天打开手机的第一件事就是看印象笔记里的拆页，想A1。\u003c/p>\u003cp>3.\u003cstrong>运用游戏化思维。\u003c/strong>我为了贴便签特意买了一块软木板挂墙上，给自己设计一个学习路径，一列是一个主题，贴满一列就换一个红色的大头钉，就算完成了一个阶段性任务，就好像过了一关一样，特别有成就感。\u003c/p>\u003cp>4.\u003cstrong>完成任务后奖励自己。\u003c/strong>完成一周的任务就奖励自己的随机奖励盒子里抽一张。\u003c/p>\u003cp>&nbsp; &nbsp; 反馈：\u003c/p>\u003cp>&nbsp; &nbsp; 截止到今天分享前，我已经运用这个方法有一周多的时间，我在一周内写了7、8个便签，内容来自《搞定》《非暴力沟通》两本书，完成时间基本在早上通勤的时候。抽取的奖励是看电影，准备去看看大家推荐的战狼。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1504181864000,"updated_at":1514795159000,"ria":true},{"id":2781,"topic":"高效能人士的7个习惯之要事第一","learn_goal":"从自己的价值观开始，要事第一，主动选择对自己最重要的事","remark":"在面对多项事务时，你会烦躁吗？\r\n正在写报告，突然来了电话，你是接还是不接呢？\r\n你知道你其实有很多事情都不必做的吗？\r\n《高效能人士的7个习惯》这本书，让你从自己的价值观开始，以要事第一为原则，主动选择对自己最重要的事。","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"徐佳敏","city":"西安"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"大家好，我叫徐佳敏，现在是一名研二的学生，喜欢读书，喜欢旅行，今天跟大家一起分享《高效能人士的7个习惯》这本书。\r\n在跟随我完成本次RIA现场学习后，学习者能够在面对繁杂事务时，会根据自己的目标做取舍，敢于放弃对自己目标无关联的事情，分清什么是重要的，更应该做的。\r\n事件场景：我们在日常工作和学习中，经常会碰到事务繁杂，或者多个紧急事件都碰到一起，尤其是明明自己已经很忙了，忽然再来个电话把自己正在做的事情又打乱，或者我们本来定好这个月要去体检，却被手边杂七杂八的事务搞得脱不开身，我们有时候宁愿刷剧，刷手机，迟迟不想开始那些堆积如山的工作。\r\n提问：我想问一下大家，大家对自己的个人管理做的好吗。包括时间管理和精力管理等等。大家可以回想一下，自己最近有没有类似的情况，刷手机的时候，有没有想过可以减少无意义的事情，任务清单里的事情多到做不完的时候，你心里是怎么想的？有没有想过，清单里的某些事，是可以不做的？（互动）\r\n影响：我们每天只有24小时，能够高效工作的时间也没有很多，如果我们不能够分清事情的轻重缓急，遇到事情，总是想着，先处理那些紧急的事情，而对那些可能暂时看不到结果的事情拖","ratings_count":0,"texts":[{"id":5537,"quote":"\u003cp>【A1】请大家自测\u003c/p>\u003cp>下面，我给大家发张测试题，看看自己的自我管理怎么样，1代表最不符合，6代表最符合，请仔细阅读每一句话，根据自己的实际情况进行打分。\u003c/p>\u003cp>1.如果一天要做八件事，我会疯掉。\u003c/p>\u003cp>2.我总是缺乏自制力，即使有很多事要做，我还是忍不住去刷手机。\u003c/p>\u003cp>3.我总是被突如其来的事务打乱计划。\u003c/p>\u003cp>4.我总是先去处理那些看起来特别紧急的事情。\u003c/p>\u003cp>5.我想有条不紊地做事，却力不从心。\u003c/p>\u003cp>6.我对自己的事务规划不明确。\u003c/p>\u003cp>【I】解释自测题\u003c/p>\u003cp>大家的打分怎么样呢？我们来总结一下，填在这个表里，看看是不是大多数人遇到的情况一样。（在黑板上画表）\u003c/p>\u003cp>6道测试题，如果你有3道题打分都超过3分，那么，你就需要好好学习下时间管理了，分值越高，说明你的自我管理能力还需要提升一下，让自己做事更有效率，越来越接近自己的价值观做事。大家对自己的答案有感触没？\u003c/p>\u003cp>让大家做这个测试题，希望能让我们更清晰地理解我们今天拆解的主题--要事第一。这几个问题，应该是我们大多数人都会面临的实际情况，现在社会，工作压力大，节奏快，即便是学生，平常的事务也很多，面对这样的情况，想要把所有事情做完是不可能的，如何更高效地做事，更高效管理自己的事务呢。\u003c/p>\u003cp>【引导】\u003c/p>\u003cp>在分享今天的内容之前，我们来大概了解一下高效能人士的七个习惯中的前两个习惯：积极主动和以终为始。大家看一下黑板，我们说，七个习惯中的前三个习惯是关于个人的，首先最基础的是积极主动，它是个人管理的基石，积极主动告诉我们，你是创造者，我们要积极主动去创造事情，主动根据自己的价值观去选择对外界刺激回应的方式，而不是消极被动地接受。而第二个习惯以终为始告诉我们以自己的人生目标作为衡量一切的标准，无论发生什么，都遵循这一原则。因为每天都牢记着这些人生目标和价值观，才更能让我们保持积极主动的态度，不受制于外界。有了积极主动和以终为始这两大基础，我们再来看第三个习惯，要事第一。\u003c/p>\u003cp>接下来，先给大家三分钟的时间，大家阅读一下原文片段，然后我们再进一步交流。\u003c/p>\u003cp>\u003cstrong>【原文片段】\u003c/strong>\u003c/p>\u003cp>有效的管理指的就是要事第一，先做最重要的事情。领导者首先要决定的，就是哪些事情是重要的；而作为管理者，就是要将这些重要的事务优先安排。从这个意义上说，自我管理实质就是自律和条理，是对计划的实施。\u003c/p>\u003cp>《成功的普遍共性》一文的作者格雷一直致力于研究所有成功人士身上普遍存在的共性。他发现成功的决定因素并非辛勤的工作、不凡的运气和良好的人际关系，而是另外一个更加重要的因素，那就是习惯三“要事第一”。格雷说：“成功者能为失败者所不能为，纵使并非心甘情愿，但为了理想与目标，仍可以凭毅力克服心理障碍。”\u003c/p>\u003cp>克服这种心理首先要有明确的目标和使命，要有习惯二中所明确的人生方向和价值观，内心要有燃烧的激情，让自己对所有其他不相关的事情大声说“不”。克服这种心理还需要有独立意志，愿意为自己所不愿为之事，能够做到在特定时刻始终坚持自己的既定价值观，不屈服于一时的冲动和欲望。这种能力会让你成为一个诚信的人，让你忠实于自己积极的第一次的创造。\u003c/p>\u003cp>使用下面这张图可以详细阐释第四代时间管理方法的重点。从本质上看，我们对时间的使用方式不外乎以下四种。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>紧迫\u003c/td>\u003ctd>不紧迫\u003c/td>\u003c/tr>\u003ctr>\u003ctd>重要\u003c/td>\u003ctd>\u003cp>1.危机，迫切问题，在限规定时间必须完成的事情\u003c/p>\u003c/td>\u003ctd>2.预防性措施，建立关系，明确新的发展机会，制定计划和休闲\u003c/td>\u003c/tr>\u003ctr>\u003ctd>不重要\u003c/td>\u003ctd>3.接待访客，某些电话，某些信件，某些报告，某些会议，迫切需要解决的事情，公共活动\u003c/td>\u003ctd>4.琐碎忙碌的工作，某些电话，某些信件，消磨时间的活动，令人愉快的活动\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>这张表告诉我们，紧迫意味着必须立即处理，比如电话铃响了，哪怕你正忙得焦头烂额，也要放下手边工作去接听。一般说来，接电话总要优先于私人工作。\u003c/p>\u003cp>紧迫之事通常都显而易见，推拖不得，却不一定很重要。重要性与目标有关，凡有价值、有利于实现个人目标的就是要事。\u003c/p>\u003cp>在时间管理矩阵中，第一类事务既紧迫又重要，需要立即处理，通常被称为“危机”或“问题”。对某些人来说，这类事务会消耗掉大部分的时间和精力，因为他们整天都在处理危机 ，应付各种紧迫任务。但是，如果你过分注重第一类事务，那么它们的范围就会变得越来越大，最终占据你全部的时间和精力。\u003c/p>\u003cp>有些人每天都在应付各种各样的问题，疲于奔命，因此只能借助第四类既不重要也不紧迫的事务来逃避现实，稍微放松一下。在这些人的时间管理矩阵中，他们把90﹪的时间花在第一类事务上，而余下的10﹪中的大部分则用在第四类事务上，用在第二和第三类事务上的时间则少而又少，几乎可以忽略不计。这就是大部分时间精力都用于处理危机的人所过的生活。\u003c/p>\u003cp>还有一些人将大部分时间花在紧迫但并不重要的第三类事务上，却自以为在致力于第一类事务。他们整天忙于应付一些自认为十分重要的紧急事件，殊不知紧迫之事往往只是对别人很重要，对自己就不一定了。\u003c/p>\u003cp>有些人几乎将所有的时间都用在第三和第四类事务上，可以说他们过的是一种不负责任的生活。\u003c/p>\u003cp>高效能人士总是避免陷入第三和第四类事务，因为不论是否紧迫，这些事情都是不重要的，他们还通过花费更多时间在第二类事务上，以期减少第一类事务的数量。\u003c/p>\u003cp>第二类事务包括建立人际关系、撰写使命宣言、规划长期目标，防患于未然等等。人人都知道这些事很重要，却因尚未迫在眉睫，反而避重就轻。\u003c/p>","explains":"\u003cp>现在大家应该对这三个习惯有了一定的了解，\u003c/p>\u003cp>看完这个片段，我们来回顾一下，这段话的关键是什么？它想要告诉我们什么？时间管理的四项限相信大家也有了解过，那么，它的核心是什么？（互动）\u003c/p>\u003cp>（期望答案：要事第一，多做第二类重要不紧急事务，告诉我们，我们的精力有限，要把大多数时间花在对自己真正有用的事情上，时间管理四项限，帮助我们理清自己的核心目标，选择重要的事情，舍弃不重要的事情）\u003c/p>\u003cp>我们每天要面对很多事情，可以肯定的是，不是每件事都值得去做，也不是每件事都非做不可，那如何取舍呢，要事第一，就是把最重要的事情放在第一位，尽量让自己做的更多的事都围绕自己的价值观和自己目前的工作核心。之所以出现要事第一，就是因为我们面对的事务太多，如果不根据自己的价值观进行选择取舍，就会被那些事务搞的焦头烂额。\u003c/p>\u003cp>用要事第一来执行，以原则为基础来安排人生，进行有效的自我管理。\u003c/p>\u003cp>紧急和重要有两个维度，相对来说，我们要更看重重要程度，也就是说，无论紧急与否，我们都更倾向于先做重要的事情，我相信大家对四项限已经很熟悉了，但是我们在日常生活中运用的怎么样呢？对于第二类事务，我们往往因为它不紧急而把它放在一边，对于手边紧迫的事情，我们不管它也许不用做，我们也会去做，第四类事务，相信大家的共通点更多，每天花在刷手机的时间，不算还好，一算吓一跳。\u003c/p>\u003cp>说了这么多，归根结底是什么，根据自己的价值观，对自己来说最重要的事情是什么，也就是四项限中的第二类事务，以第二类事务为生活中心，有助于我们实现自己的人生目标。\u003c/p>\u003cp>举个我自己的例子，上周周天的时候我列了11个待办事项，没有开玩笑啊，我下午还专门数了一遍，我的待办事项是想起一条列一条，一看到那一长串的任务我整个人都懵了，正常情况下，11项任务我是不可能都完成的，而且那天下午还突发占了两个多小时去看了场电影，结果就更别说了，我是怎么做的呢，虽然我知道四项限，但我用的并不好，我就是根据紧急程度来做的，哪个最紧急，哪个待会儿要给老师交，结果到晚上的时候我一看，剩了几个没做的，都是实际上很重要，虽然目前看不到效果的事情，我觉得它不紧急，就舍弃它做了别的事。如果长期这样下去，自己就不会有成长。只有按照重要程度去取舍，把真正重要的事放在首位，才能有真正的进步。\u003c/p>","interaction":"\u003cp>【A3】现在，相信大家对原书拆页的内容有了更深的理解，现在请两个人（或三个人）一个小组一起做个演练，就按照我们开始分的小组。请大家认真听一下要演练的场景：小明是一家创业公司商品部门经理，手底下十几个下属，他每天不仅要回复各个部门的邮件，还要分配自己十几个下属的工作，还要与营销部门商讨策划案，交接发出商品的信息，除此之外，几乎每个下午都要向上级汇报工作，还有不时接到的售后电话，他虽然对这份工作很喜欢，但面对每天这么庞大的工作量，他还是被搞得焦头烂额，他每天下班回去都在想，这样的日子，什么时候是个头啊。对小明来说，他一直想在领导力方面有所提升，好尽快升职，对他来说，现在最重要的是，统筹，分配工作，而不是独揽工作，可是这样下去，怕是没机会了？请大家根据我们今天学到的要事第一，帮小明梳理一下，哪些是对他最重要的，哪些事他可以不做，哪些事可以让下属做，哪些事可以暂时放一放？请大家开始讨论，稍后我们请小伙伴给大家分享一下他们组的讨论结果。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>周老师：\u003c/p>\u003cp>跟领导力提升有关的事情肯定是重要的，那么一些日常的事情可能不重要或不紧急的，这些事情包括制定部门计划，员工工作的细分，甚至日常跟领导的沟通汇报，这是不重要不紧急的，什么是重要紧急的，可能是跟领导力相关，本来是不紧急的但因为他没做，所以可能会被拖成紧急，比如在工作中他需要提前给下属分配工作，但他把这些事情没有提前做好，比如周一开周会的时候才分配，那就变成非常重要紧急了，所以我的目标是什么，根据我的目标来制定我的计划，我的要事是什么，搞清楚我的要事，不把重要不紧急变成紧急，然后做真正目前对我来说最重要的事。\u003c/p>\u003cp>刚刚周老师从分析四项限来跟我们分享小明的现状，很好的用到了我们学到的要事第一，作为经理，我的要事是什么，然后其他不重要的应该怎么办，放在要事后面。\u003c/p>\u003cp>在这里顺便给大家分享一个小贴士：4D工作法\u003c/p>\u003cp>Do it now 立即去做（星标）\u003c/p>\u003cp>Delay计划去做（日程）\u003c/p>\u003cp>Delegate授权去做（确认跟进时间，填进日程）\u003c/p>\u003cp>Do not do it尽量少做或不做（偷着乐吧）\u003c/p>\u003cp>[A2]\u003c/p>\u003cp>今天刚好是周六，给大家布置个任务，回去记录一下自己下一周五天工作时间的待办事项，每一天，当你写下待办事项时，用我们今天学到的要事第一，从重要不重要的维度开始思考，哪件事对我是最重要的，就先做它，如果每天能做三件重要的事，其他的事，要么特别紧急的就先做，要么委托别人做，要么不做，要么推迟，即使完不成也没关系。这样尝试记录一周，看看自己有什么变化。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1496278974000,"updated_at":1496278974000,"ria":true},{"id":2224,"topic":"学习设身处地倾听，避免陷入四种自传式的沟通不良的弊端当中","learn_goal":"顺利通关TF2-4","remark":"《高效能人士的7个习惯》这本书的作者是美国学界的“思想巨匠”史蒂芬•柯维博士，书中讲述了对每个人都适用的7个非常棒的习惯。强调以原则为中心，以品德为基础，要求“由内而外”地实现个人效能和人际效能。","level":"TF2-3","duration":50,"status":0,"type":0,"chaishujia":{"username":"Joyce赵锦","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"哈喽！大家好，我叫赵锦，今天又一次在2-4的现场跟大家见面。我今天跟大家分享的图书是《高效能人士的7个习惯》，听到这本书的时候大家有没有想过，这是一本很棒的书，我第一次拿到这本书的时候就觉得很棒，因为可以改变很多人的很多思路。\r\n这本书的主要F特征：\r\n 《高效能人士的7个习惯》这本书的作者是美国学界的“思想巨匠”史蒂芬•柯维博士，书中讲述了对每个人都适用的7个非常棒的习惯。强调以原则为中心，以品德为基础，要求“由内而外”地实现个人效能和人际效能。\r\nA 优势：\r\n这本书是当今中国最经典、最著名的一部培训教材， 不仅是企业、组织机构，更是个人获得自我提升的人生必修教材，行文非常生动。改变人的思维方式和行为方式。\r\nB 利益：\r\n你有没有遇到一些不好的事情立马被消极的情绪所影响呢？或者有一堆的事情需要完成，可是你不知道如何安排优先次序呢？-----那么，读这本《高效能认识的7个习惯》你就会知道如何改变自己的思维方法，从而改变你的行为。 今天跟大家分享的是设身处地的沟通。","ratings_count":0,"texts":[{"id":4891,"quote":"\u003cp>&nbsp;&nbsp;片段一：\u003c/p>\u003cp>学习目标：\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够在一对一的沟通中首先避免陷入四种自传式的沟通不良的弊端当中。\u003c/p>\u003cp>沟通不良的四大弊病\u003c/p>\u003cp>&nbsp; 自以为是的人有四种反应倾向：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;一、价值判断——对旁人的意见只有接受或不接受。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;二、追根究底——依自己的价值观探查别人隐私。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;三、好为人师——以自己的经验提供忠告。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;四、想当然耳——根据自己的行为与动机衡量别人的行为与动机。\u003c/p>\u003cp>&nbsp; 价值判断令人不能畅所欲言，追根究底则令人无法开诚布公，经常造成亲子关系的一大障碍。\u003c/p>\u003cp>&nbsp; 青少年与朋友讲电话可以扯上一两小时，跟父母却无话可说，或者把家当成吃饭睡觉的旅馆，为什么呢？如果父母只知训斥与批评，孩子岂肯向父母吐真言？\u003c/p>\u003cp>&nbsp; 在无数研讨会中，我曾与成千上万的人讨论这个问题，我发现人们常自以为是，却习焉而不察。无怪乎每次角色扮演时，许多人都意外的发现，自己居然也有这种病。好在只要病情确定，治疗并不难。\u003c/p>\u003cp>片段二：\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003cstrong>\u003cstrong>\u003cstrong>\u003cstrong>学习目标\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/strong>\u003c/strong>\u003c/strong>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003cstrong>\u003cstrong>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够在一对一的沟通中学习设身处地倾听。\u003c/p>\u003c/strong>\u003c/strong>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>正确的沟通方式也就是设身处地的倾听，至少包括四个阶段。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一阶段是复述语句，这至少能使人专心聆听：\u003c/strong>\u003c/p>\u003cp>“上学真是无聊透了！”\u003c/p>\u003cp>“你已受不了了，觉得上学太无聊&quot;\u003c/p>\u003cp>&nbsp;\u003cstrong>第二阶段加入解释，纯用自己的语句表达，但仍用左脑的逻辑思考去理解：\u003c/strong>\u003c/p>\u003cp>“你不想上学了。”\u003c/p>\u003cp>\u003cstrong>第三阶段掺入个人的感觉，右脑发挥作用。此时听者所注意的已不止于言语，也开始体会对方的心情：\u003c/strong>\u003c/p>\u003cp>“你觉得很有挫折感。”\u003c/p>\u003cp>\u003cstrong>第四阶段是既加以解释，又带有感情，左右脑并用：\u003c/strong>\u003c/p>\u003cp>&nbsp;“你对上学有很深的挫折感。”\u003c/p>\u003cp>\u003cstrong>运用第四阶段的方式沟通，不仅能了解对方，更能帮助对\u003c/strong>\u003cstrong>方认清自己，勇于表白。\u003c/strong>\u003c/p>\u003cp>再以前面的例子说明：\u003c/p>\u003cp>“上学真是无聊透了！”（我想引起注意，与人谈谈心事）\u003c/p>\u003cp>“你对上学有很深的挫折感&quot;（对，这正是我的感觉。）\u003c/p>\u003cp>“没错，学校教的东西根本不实用。&quot;\u003c/p>\u003cp>“你觉得读书对你没什么用。”（想想看，我是那么说的吗？）\u003c/p>\u003cp>“对，学校教的不一定对我有用。你看王明，他现在修车技术一流，这才实用。&quot;\u003c/p>\u003cp>“你觉得他的选择正确。”（嗯……）\u003c/p>\u003cp>“嗯，从某个角度看确实如此。现在他收入不错，可是几年后，或许会后悔。”\u003c/p>\u003cp>“你认为将来他会觉得当年作错了决定。”\u003c/p>\u003cp>“一定会的，现在的社会里，教育程度不高会吃亏的。”\u003c/p>\u003cp>“教育很重要。”\u003c/p>\u003cp>“对，如果高中都没毕业，一定找不到工作，也上不了大学。有件事——我真的很担心，你不会告诉妈吧？”\u003c/p>\u003cp>“你不想让妈知道？&quot;\u003c/p>\u003cp>“不是啦，跟她说也无妨，反正她迟早会知道的。今天学校举行阅读能力测验，结果我只有小学程度，可是我已经高二了！&quot;\u003c/p>\u003cp>&nbsp; 儿子终于吐露真言，原来他担心阅读程度不如人。此时才是父亲发挥影响力，提供意见的时刻。不过在开导过程中，依然要注意孩子言谈间所表达的讯息。若是合理的反应不妨顺其自然，但情绪性反应出现时，必须仔细聆听。\u003c/p>\u003cp>“我有个构想，也许你可以上补习班加强阅读能力。”\u003c/p>\u003cp>“我已经打听过了，可是每星期要耗掉好几个晚上！”\u003c/p>\u003cp>&nbsp; 父亲意识到这是情绪性反应，又恢复设身处地的倾听。\u003c/p>\u003cp>“补习的代价太高了。”\u003c/p>\u003cp>“而且我答应同学，晚上另有节目。”\u003c/p>\u003cp>“你不想食言。”\u003c/p>\u003cp>“不过补习如果真的有效，我可以想办法跟同学改期。”\u003c/p>\u003cp>“你其实很想多下点工夫，又担心补习没用。“\u003c/p>\u003cp>“你觉得会有效吗？”\u003c/p>\u003cp>&nbsp; 孩子又恢复了理性，父亲则再次扮演导师的角色。有时候，不待旁人开导，只要能畅所欲言，已足以令人厘清问题，甚至找到答案。\u003c/p>\u003cp>&nbsp;\u003cstrong>心情不好的时候，最需要善解人意的好听众，如果你能适时扮演这种角色，将会惊讶对方毫无保留的程度。但前提是，你必须真心诚意为对方着想，不存私心。有时甚至不必形诸言语，仅仅一分心意就足以感动对方。\u003c/strong>\u003c/p>\u003cp>&nbsp; 对于关系亲密的人，和他分享经验将大有助于沟通：“读了这本书才发现，其实我从未真正聆听你说话，但今后愿尽力而为，纵使一时间不能作得很好，但我确实真心想了解你，也希望你助我一臂之力。“&nbsp;我相信有人会批评，这种倾听方式太耗费时间。起初的确如此，可是一旦进入状况就会如鱼得水。正如医师不能托辞太忙就不经诊断而下处方，沟通也需要投资时间。\u003c/p>","explains":"\u003cp>\u003cstrong>片段一：\u003c/strong>\u003c/p>\u003cp>下面我用自己的话来复述原文片段当中的内容，当我们在听别人讲话时，总是会联系我们自己的经历，因此自以为是的人往往会有4种自传式的回应的倾向：\u003c/p>\u003cp>1.价值判断------对旁人的意见只有接受或不接受\u003c/p>\u003cp>例子：上周陪我妈去买衣服，导购说由于她个子高，穿长款比短款好看，她说：“还是喜欢短的，精干。”\u003c/p>\u003cp>2.追根究底——依自己的价值观探查别人隐私。\u003c/p>\u003cp>例子：有个姊妹跟我聊天说自己平时化妆品用什么什么牌子对皮肤好，衣服买什么什么牌子等，然后我心想，我平时好像没有用化妆品吧，衣服也是没有按哪个牌子买吧。\u003c/p>\u003cp>3.好为人师——以自己的经验提供忠告\u003c/p>\u003cp>例子：有个姊妹最近怀孕了，然后教会里有两个姊妹由于当时怀孕第一胎的时候流产了，所以就告诉这个怀孕的姊妹要卧床休息不能上班了，然后这个孕妇心里各种担忧……\u003c/p>\u003cp>4.想当然耳——根据自己的行为与动机衡量别人的行为与动机\u003c/p>\u003cp>例子：前天在高中同学的微信群里，看到有个同学倾诉自己跟相恋五年的男友最近在闹分手，其中另一个同学紧跟着说自己当初也是……然后，那个倾诉的同学再没有说话……\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003cstrong>不那么做的坏处：\u003c/strong>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>如果我们跟别人沟通时，总自以为是的反应出原文片段当中提到的这四种不良的沟通，会使对方不愿意再跟我们分享，严重时也会影响到我们的关系的。\u003c/p>\u003cp>\u003cstrong>预防学习者异议：\u003c/strong>\u003c/p>\u003cp>在这里需要说明的是，自传式回应也并非是完全错误或者无效的。比如对方确实征询你意见的时候，而且你们俩关系也的确不错，你当然可以“好为人师”的给别人提出你的建议，当你和对方很熟悉，关系很好的时候，这时追根究底的问问“为什么”也没太大问题。\u003c/p>\u003cp>但是，当对方向我们倾述时，对方情绪比较大，想要表达自我时，我们要多倾听，尽量避免这种自传式的回应，好让对方可以畅所欲言。\u003c/p>\u003cp>\u003cstrong>片段二：\u003c/strong>\u003c/p>\u003cp>原文片段中讲到沟通的四个阶段：\u003c/p>\u003cp>1.\u003cstrong>重复\u003c/strong>对方要表达的信息，专心的倾听。\u003c/p>\u003cp>2.\u003cstrong>理解\u003c/strong>对方要表达的内容，且用自己的话\u003cstrong>解释\u003c/strong>。\u003c/p>\u003cp>3.站到对方的角度去\u003cstrong>感受\u003c/strong>她。\u003c/p>\u003cp>4.带有感情的去加以解释对方的情况。\u003c/p>\u003cp>\u003cstrong>（这四个阶段在共同中可以不按顺序）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>举例：\u003c/strong>上周我表姐跟我聊天，提到我姨妈因为身体不好，每次住院的时候都是她全程陪床，其他三个儿女因为忙不能一直待在医院照顾，然而有一次同病房的阿姨在住院期间几个儿女轮流去陪床。我姨妈看着旁边病床的阿姨羡慕的一直嘴上说：“你看你的命那么好呢，你看看你们家孩子多孝顺啊----“然后我表姐当时虽然嘴上没有说什么。但心里还是挺不舒服的。\u003c/p>\u003cp>上周聊天时她正好提到了这个事情：\u003c/p>\u003cp>表姐：“你看你姨妈咋这样儿，每次住院都是我尽心陪着照顾着，她还不满意---”\u003c/p>\u003cp>我：“你是因为她在别人面前那样说你心里不舒服吧？”（复述+感受）\u003c/p>\u003cp>表姐：“我们平时三天两头的过去看她，只要她打电话说不舒服，我再忙都放下手上的事情，赶紧看她去，到头来还是不满意。”\u003c/p>\u003cp>我：“我姨妈在外人面前那样说让你听着感觉像没人管她一样，也是，如果换成我当时在医院，我听了也挺难受的。”（复述+理解）\u003c/p>\u003cp>表姐：“是啊，她这样一说，我都有时候不想去医院陪她了。”\u003c/p>\u003cp>我：“理解理解，心里挺不舒服的，但她一有不舒服，你还不得不去照顾。”（理解+感受）\u003c/p>\u003cp>表姐：“就是就是。”\u003c/p>\u003cp>我：“让你整天这样前前后后陪我姨妈，你也真不容易啊，这次来西安看病咱俩一起陪她去，如果她再这样在外人面前说，那我来跟她聊，你也别太往心里去，她可能也是说着无心吧。”（链接）\u003c/p>\u003cp>表姐：“是啊，她可能上年纪了，常常有自怜的倾向吧。”\u003c/p>\u003cp>------------\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003cstrong>片段一：\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>【A1】\u003c/strong>激活经验（5分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>（显现提问）：回想一下这样的场景，跟配偶讨论孩子的教育问题/跟教会同工一起的沟通/还有跟父母打电话沟通你择偶问题------- &nbsp;在过去一周里，你的沟通不顺利会出现在刚才哪一个情景中呢？\u003cbr>\u003cbr>\u003c/p>\u003cp>拆书家提问：你当时是判断了，还是好为人师了-----这四种当中的哪一种呢？）\u003cbr>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A+：\u003c/strong>如果那个时间段在沟通之前，你学习过今天这四种，那么你会怎么做？\u003cbr>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>任丽娜，跟父母打电话提到择偶问题。在过去一周跟父母打电话陷入到价值判断当中。父母的想法跟自己的有出入，自己用自己的价值判断去判断父母的。\u003c/strong>\u003cstrong>如果发生在学习这个片段之前，她不会用自己的价值去判断父母的，会表示理解父母，父母有对人生的理解和看法，自己也就不会陷入到价值判断当中了。\u003c/strong>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003cstrong>片段二：\u003c/strong>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003cstrong>【A3】\u003cstrong>\u003cstrong>促动参与（10-12分钟）\u003c/strong>\u003c/strong>\u003c/strong>\u003c/strong>\u003cbr>\u003cstrong>拆书家提问设计：\u003c/strong>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;好的，下面有这样一个场景，大家两个人一组来演练一下。背景是你朋友的家人最近经常给她/他安排相亲，使她/他跟父母之间有些矛盾。通过今天学习到的方法，你尽可能的安慰她/他，多倾听。请大家在各自小组先演练，然后请一组上来给大家演练。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>任丽娜：哎呀，我最近都烦死了，我妈给我介绍了好多人。我前天还相亲了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>王娟：你是觉得你父母给你介绍相亲对象，你觉得自己可烦了是吧？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>任丽娜：就是，成天的给我介绍呢，而且有的呢还不是信主的，前天就还相亲了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>王娟:那你现在就是不想相亲吗？\u003c/strong>\u003c/p>\u003cp>任丽娜：倒也不是不想相亲。\u003c/p>\u003cp>王娟:不想让父母这样使劲儿催着自己相亲？\u003c/p>\u003cp>任丽娜：就觉得他们也不要那么着急，我这事自己也上心了。\u003c/p>\u003cp>王娟:爸妈现在还催你，你觉得自己可烦躁了是吗？\u003c/p>\u003cp>任丽娜：对呀，我也很积极的，我又不是不找，前天相亲那个男的可爱玩游戏了，我 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;觉得不喜欢那样的人。\u003c/p>\u003cp>王娟:那父母给你介绍的对象不符合你自己的口味，你现在还是觉得很烦躁？父母给你 &nbsp; &nbsp; &nbsp; &nbsp; 介绍结婚对象----\u003c/p>\u003cp>任丽娜：对啊。\u003c/p>\u003cp>王娟:父母给你介绍的相亲对象，但你有自己的择偶标准----\u003c/p>\u003cp>任丽娜：嗯，嗯\u003c/p>\u003cp>王娟:你有自己的一些标准---\u003c/p>\u003cp>任丽娜：对啊，看着挺好的，但不符合。---------------\u003c/p>\u003cp>王娟:那你有什么标准吗？\u003c/p>\u003cp>任丽娜：不抽烟，有上进心，是一个基督徒，没有不良嗜好。\u003c/p>\u003cp>王娟:那你需要找个有上进心的弟兄，没有不良嗜好。\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003cstrong>\u003cstrong>【A2】催化应用（指向未来）（10-12分钟）\u003c/strong>\u003c/strong>\u003c/strong>\u003cbr>\u003cstrong>\u003c/strong>\u003cstrong>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（分步催化1）&nbsp; &nbsp; 接下来我们来想一下，与家人聊天，向领导汇报工作，跟孩子玩游戏，与教会同工一起配搭服侍⋯⋯&nbsp;你的生活会涉及到哪个情境的沟通？\u003cstrong>\u003cbr>\u003c/strong>\u003cstrong>\u003cbr>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>学习者案例记录：\u003c/strong>\u003cbr>任丽娜：跟同事王娟：也许会跟成为自己未来丈夫的人\u003c/strong>\u003c/p>\u003cp>\u003cstrong>姗姗：妈妈\u003c/strong>\u003c/p>\u003cp>\u003cstrong>忠阳：妻子，客户，潜在客户\u003c/strong>\u003c/p>\u003cp>\u003cstrong>惠媛姐：跟政府部门，跟服务对象-------\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003cstrong>（分步催化2）\u003c/strong>\u003c/strong>（\u003cstrong>请大家思考并想到具体的情景之后\u003c/strong>）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>设想：&nbsp;未来一周，也许你会在某个场合（办公室/学校/教会/家里----）遇见需要沟通的人，然后你会怎样去沟通呢？加工具体的行动步骤，你将如何智慧的沟通，使自己在沟通中学习设身处地的倾听？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.任丽娜：下周一早上开会，会有人迟到。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小王：“哎呀，不好意思不好意思，我迟到了。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>任丽娜：“小王，你迟到了，这一路赶的，心里应该也挺着急的吧？”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.王娟：也许晚上跟相亲博士聊天。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>理科博士：“你要记住，你的第一身份是学生，你是个研究人员，你是高级知识分子，你 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;不要参加那么多活动，你做的那些事情都跟学习没有关系----？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>王娟：“你觉得我参加了这么多活动，我应该把主要精力放到学习上是吗？”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>理科博士：对呀。---------------\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3 .忠阳：接下来某一天跟妻子聊天\u003c/strong>\u003c/p>\u003cp>\u003cstrong>妻子:&quot;气死我了，我妈刚才又说我了。-----“\u003c/strong>\u003c/p>\u003cp>\u003cstrong>忠阳：“哦，你妈把你训了一顿啊，你很生气？--”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>妻子：“幸亏我今天忍了5分钟---”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>忠阳：“治服己心的，强如取城。你太厉害了”---------&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>拆书家反馈：\u003c/strong>\u003c/strong>\u003c/p>\u003cp>刚刚大家都应用了移情沟通的四个阶段，设计了我设计的这段对话，可以看出，虽然是很简单的复述、理解、感受和链接，在实际应用中也并没有那么容易，在应用中我们也要根据对方的回应，及时作出调整。总之是要鼓励对方畅所欲言，有时候只有对方把想说的都说出来了，他自己也自然找到了解决方法。\u003c/p>\u003cp>\u003cstrong>结语：\u003c/strong>\u003c/p>\u003cp>今天我们主要学习了两个知识点，第一个是避免陷入4种自传式回应，第二个是移情聆听的4阶段。总结起来就是，在沟通中，我们要尽量避免以自我为中心，而是多多关注对方，运用复述、理解、感受、链接这样的沟通方式，多倾听，开放式的提问，积极倾听对方的想法、感受，用心理解对方，学会积极倾听别人的想法，而不是急于表达自己的意见和建议。\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1490261001000,"updated_at":1490261200000,"ria":true},{"id":2092,"topic":"责任型授权+","learn_goal":"责任型授权","remark":"","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"张臻凯","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"大家晚上好！我是张臻凯，在大家手上拿的拆页最上面有我的名字，简单拆解记忆就是：日臻完美，达到成功。\r\n 我从事内训管理工作，自己贴的3个标签，首先是小资（有两层含义：一是表达我的生活态度：享受生活，二是大家可以通过标签猜到我的祖籍）；\r\n 第二个标签是好学（希望不断提升自己）；\r\n 最后一个标签是追求圆满（希望做人做事都能不断精进，圆满大成）\r\n 咱们还是按封超老师分的组完成今天的拆书之旅","ratings_count":0,"texts":[],"created_at":1488854058000,"updated_at":1488938493000},{"id":1727,"topic":"要事第一","learn_goal":"要事第一","remark":"","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"张臻凯","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\" 大家晚上好！我是张臻凯，在大家手上拿的拆页最上面有我的名字，简单拆解记忆就是：日臻完美，达到成功。\r\n 我从事内训管理工作，自己贴的3个标签，首先是小资（有两层含义：一是表达我的生活态度：享受生活，二是大家可以通过标签猜到我的祖籍）；\r\n 第二个标签是好学（希望不断提升自己）；\r\n 最后一个标签是追求圆满（希望做人做事都能不断精进，圆满大成）。\"","ratings_count":0,"texts":[{"id":4295,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>若要集中精力与当急的要务，就得排除次要事的牵绊，此时需要有说“不”的勇气。\u003c/p>\u003cp>人各有志，各有优先要务。必要时，应该不卑不亢地拒绝别人，在急迫与重要之间，知道取舍。\u003c/p>\u003cp>我在一所规模很大的大学任师生关系部主任时，曾聘用一位极有才华又独立自主的撰稿人。有一天，有件急事想拜托他。\u003c/p>\u003cp>他说：“你要我做什么都可以，不过请先了解目前的状况”。\u003c/p>\u003cp>他指着墙壁上的工作计划表，显示超过20个计划正在进行，都是我两早就谈妥的。然后他说：“这件事至少要占去几天的时间，你希望我放下或者取消哪个计划来空出时间？”\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; &nbsp; 他的工作效率一流，这也是为什么一有急事我就会找上他，但无法邀请他放下手边的工作，因为比较起来，正在进行的计划更为重要。我只有另请高明了。\u003c/p>","explains":"\u003cp>图书介绍\u003c/p>\u003cp>（学习者场景介绍法）\u003c/p>\u003cp>&nbsp; &nbsp; （事件）有些和他聊天如沐春风，而有些人你知道他是好心，但只要他话一出口，你就恨不得和他绝交或者你和他说话的时候总有种感觉：鸡同鸭讲，无法沟通。（提问）为什么人和人的差别这么大呢？因为不会听话和说话也许你觉得这很容易啊，我们生下来就会听，不到两岁就能背唐诗。其实能良好沟通，是需要技巧，如果具备不仅可以让你拥有个舒心的工作环境，同时还能让你在家里和和美美。（影响）反之，你听不懂别人的话或者和别人无法打通沟通频道，不仅在职场上险象环生，而且在家里也是烽烟四起（解决）本次拆解希望能解决这个问题，拆页选自《成功人士的7个习惯》，FB这本书出版于1900年，经久不衰。这七个习惯分为三个维度，首先让学习者学会提升自己三个方法，而后用有效的方法提升与人合作共赢的三种能力，教会学习者不断更新，内外兼修成为高效能人士。\u003c/p>\u003cp>学习目标：\u003c/p>\u003cp>&nbsp; &nbsp; 在跟随我完成本次RIA现场学习后，希望伙伴学会“1勇敢说不、2围绕中心、3善用碎片化时间”三个原则，并且能合理安排时间，实现“要事第一”的目标。\u003c/p>\u003cp>【A1】请大家自测量表题\u003c/p>\u003cp>那接下来请大家做一个简单的测试，请仔细阅读每个题目并根据实际情况给自己打分，1代表很不符合实际情况，6代表非常符合实际情况。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、我能妥善安排生命中的重要事情 1 2 3 4 &nbsp; 5 6 \u003c/p>\u003cp>2、我能告诉你我五年后的理想 1 2 3 4 &nbsp; 5 6 \u003c/p>\u003cp>3、我有工作授权的规则和方法 1 2 3 4 &nbsp; 5 6 \u003c/p>\u003cp>4、我会把艰难的问题优先处理 1 2 3 4 &nbsp; 5 6 \u003c/p>\u003cp>5、我会定期制定工作、生活的计划（天、周、月、年） 1 2 3 4 5 6 \u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 6、我满意现在的时间方法，有条不紊 1 2 3 4 5 6\u003c/p>\u003cp>【I】解释自测题\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 刚才的小测试是简单判断自己在分配时间是否能抓住自己最重要的事情的习惯。超过25分的小伙伴，说明你在抓住关键事件越能分清轻重，而低于10分的小伙伴的小伙伴，就需要调整自己处理事务的顺序，避免掉入瞎忙的陷阱。\u003c/p>\u003cp>【I】拆书家引导讲解（互动式讲解）\u003c/p>\u003cp>&nbsp; &nbsp; 通过拆页大家可以看出作者推崇撰稿员的“要事第一”的工作排序，同时与上级沟通时的有礼有节，沟通的问题咱不在今天讨论范围内。\u003c/p>\u003cp>&nbsp; &nbsp; （互动）大家能在拆页中找到哪些时间安排的好方法？没错，我们要做到“要事第一”。首先要勇于说不，这里可以有直接回绝，委婉推脱和让对方知难而三种方式，大家看拆页中的撰稿人，对上级要安排工作，首先是表达“你要我做什么都可以，不过请先了解目前的状况”良好态度。然后指向自己的工作计划表，（互动）通过哪些方法让领导另请高明的呢？没错，“委婉推脱结合让对方知难而退”让作者心甘情愿的另请高明了。第二是围绕中心，大家可以通过拆页作者对撰稿人的评价“他的工作效率一流”看出作者对他的认同，其实很简单，就是撰稿人做事时效率和质量双高。那秘诀就是提前安排自己的计划按计划推进，就像撰稿人墙上贴的计划表。大家一定要注意，计划可不是记流水账，而是根据事务的重要程度安排行事历，其他事务的加入，要看重要事情完成程度酌情安排。第三是善用碎片，比如我们要提升英语能力，完全可以利用上下班途中中背单词或者练听力，大家不要小瞧这些碎片时间，可以创造一个个小奇迹。如果我们做到了“勇于说不，围绕中心和善用碎片”相信一定可以慢慢总结出自己的时间管理法则，成为时间的主人。\u003c/p>\u003cp>&nbsp; &nbsp; 大家看到拆页上的撰稿人应该说是要事第一的高手，但其实职场里有许多人是抹不开情面，将自己有限的时间给了别人，而自己的本职工作做得不咋地。这里我举个例子：我曾经有个员工，她的工作是负责薪酬核算和社保、公积金办理等相关工作。可能是因为刚到公司，于是对别人提出的需求比如提取公积金啊，打印社保清单啊都属于来者不拒，按理说应该人缘很好，其实不然。因为谁的事情都是急事，于是她忙的不亦乐乎，但时间有限，帮了这个，耽误那个反而惹得大家觉得他不公平。属于典型的不会拒绝。同时因为干扰因素过多，所以她的本职工作工资核算差错率也很多，每当发薪后的几天，他几乎寝食难安。因为有人来查工资，发现算错了，就有更多的人来查，他的一遍遍解释，一遍遍改错。大家觉得她工资核算那么多错，完全不胜任嘛，可以划入工作没有围绕中心，而她也因为过度劳累和内心焦虑，得了胃出血。每天累得精疲力尽，所有的碎片时间都用来抚慰受伤的心灵和疲惫的身躯，更不不可能实现个人成长。\u003c/p>\u003cp>&nbsp; &nbsp;那我们要做到“要事第一”一定要记得时间安排一定要以重要为中心，首先勇于说不，说不的方法有仨：可以直接拒绝，可以委婉推脱，还可以让对方知难而退。其次要围绕中心，第三是善用碎片。\u003c/p>","interaction":"\u003cp>【A3】促动参与\u003c/p>\u003cp>&nbsp; &nbsp; 马上要元旦了，好不容易放三天，家里老人希望能利用三天出去走走，孩子希望你陪他去海洋世界，配偶希望有自己的小空间，你朋友想约你喝喝茶聊聊天，你老板希望你乘着这三天把17年规划路径拿出来，然后你自己希望能静下心来想想这一年该如何过。请每个组的伙伴按“要事第一”的原则帮自己梳理元旦三天的计划并完成沟通。本环节讨论时间5分钟，之后我们选一个小组伙伴来分享处理方式。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>序号\u003c/td>\u003ctd>对象\u003c/td>\u003ctd>计划\u003c/td>\u003ctd>使用哪条原则\u003c/td>\u003c/tr>\u003ctr>\u003ctd>1\u003c/td>\u003ctd>父母\u003c/td>\u003ctd>希望能利用三天出去走走\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>2\u003c/td>\u003ctd>孩子\u003c/td>\u003ctd>希望你陪他去海洋世界\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>3\u003c/td>\u003ctd>配偶\u003c/td>\u003ctd>希望有自己的小空间\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>4\u003c/td>\u003ctd>好朋友\u003c/td>\u003ctd>想约你一起聚聚（他有个孩子和你孩子同岁的）\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>5\u003c/td>\u003ctd>老板\u003c/td>\u003ctd>完成部门17年规划路径\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>6\u003c/td>\u003ctd>自己\u003c/td>\u003ctd>一年目标如何定\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; 刘丹组：要事包括1、父母；2、孩子；带上父母和孩子一起出去走走；1、空闲时间仔细考虑自己的目标（善用碎片时间）1、好朋友的约会改期；2、老板的要求在最后一天晚上按惯例搭一个框架，上班后约个会讨论具体怎么做。（勇于说不）\u003c/p>\u003cp>&nbsp; &nbsp; 鸿组：意见一：要事包括1、自己一年的目标；2、老板要求的17年规划路径；1父母、2、孩子的出游集中安排一天；3、好朋友的聚会可以安排一个晚餐；4配偶的需求可以安排一个烛光晚餐（委婉说不）\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 意见二：要事1、父母2、孩子3、配偶一起出去，配偶在出去的某个时间安排一个小活动；1、老板17年规划在节前拿出框架，最后一天发老板，约上班当面汇报（委婉说不）2、自己的规划放假前完成，3、好朋友聚会节后安排（勇于说不）\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;感谢两组小伙伴的分享，大家有没发现每个人因为所处环境和定位不同，要事的界定也是不一样的。\u003c/p>\u003cp>【A2】催化应用（4种布置任务法选其一）\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;那请小伙伴思考下，你目前工作、生活中有哪些事情或情况属于忙而无功，正好临近岁末，咱们是不是可以根据要事第一法则，重新梳理年度个人或工作计划。\u003c/p>\u003cp>（结语）希望大家在以后生活中以“要事第一”法则作为定计划的准绳，咱们可以通过将①勇于说不②围绕中心③善用碎片，作为改进计划的方法。让我们的人生更精彩，当回顾往事时可以少点遗憾。我今天的拆解就到这里结束，谢谢大家！\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1483066766000,"updated_at":1483066766000,"ria":true},{"id":1223,"topic":"由内而外改变自己","learn_goal":"做到对能够掌握之事全力以赴，创造“由内而外”的改变","remark":"作者史蒂芬·柯维，他是美国学界的“思想巨匠”，入选“影响美国历史进程的25位人物”，被《时代周刊》评为“人类潜能的导师”。《高效能人士的7个习惯》是当今中国最经典、最著名的一部培训教材。本书不仅是企业、组织机构，更是个人获得自我提升的人生必修教材。书中详细描述了关于人类生存状况,它深深洞察了我们内心所关注的东西。此书中所讲的行为习惯能令人精神振奋、思维活跃。积极主动为自己的人生负责。如果你读了这本书，并刻意培养书中所讲的行为习惯，那么你就是未来的高效能人。","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"Lian","city":"兰州市"},"club":{"name":"兰州金城关分舵","city":"兰州"},"prologue":"大家下午好 ，我是拆书家Lian。今天的拆页选自《高效能人士的7个习惯》。今天我拆解的主题是：“由内而外”的改变，扩大自己的影响圈。完成这次现场RIA学习后，大家能在态度和行为上发生改变。做到对力不能及之事泰然处之，对能够掌握之事则全力以赴。逐渐扩大自己的影响圈。（F）作者史蒂芬·柯维，他是美国学界的“思想巨匠”，被《时代周刊》评为“人类潜能的导师”。书中详细描述了关于人类生存状况,它深深洞察了我们内心所关注的东西，这本书无论对个人还是组织，都非常有用。此书中所讲的行为习惯能令人精神振奋、思维活跃，积极主动为自己过去、现在及未来的行为负责。（A）此书是当今中国最经典、最著名的一部培训教材。本书不仅是企业、组织机构，更是个人获得自我提升的人生必修教材。读者遍及工商业、政府部门、军队、学校以及家庭各个领域。（B）如果你读了这本书，接纳本书所阐释的观念，并刻意培养书中所讲的行为习惯，那么你的自信会得到大幅度的提高！你将更能认清自己的价值观，以及个人独特才干与能耐。秉持自己的信念而活并且内心平和。请大家阅读原文片段：","ratings_count":0,"texts":[{"id":3474,"quote":"\u003cp>《高效能人士的七个习惯》——积极主动\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; “如果”和“我可以”\u003c/p>\u003cp>一个人的关注圈与影响圈可以从他的言谈中看出端倪，与关注圈相关的语句多半带有假设性质。\u003c/p>\u003cp>“要是我的房屋贷款付清了，我就没这么烦心了”\u003c/p>\u003cp>“如果我的老板不这么独断专行……”\u003c/p>\u003cp>“如果孩子肯听话… &nbsp;”\u003c/p>\u003cp>“如果我学历更高…” &nbsp;\u003c/p>\u003cp>“如果我有更多属于自己的时间……”\u003c/p>\u003cp>而与影响圈相关的语句则多半体现了这个人的品德修养，例如“我可以更耐心、更明智、更体贴……\u003c/p>\u003cp>把外在环境视作问题症结的想法本身就成问题，应该说是我们给了外部环境控制自己的权力，这种“由外而内”求变的思维定式，就是以外在环境改变作为个人改变的先决条件。\u003c/p>\u003cp>积极的做法应该是“由内而外”地改变，即先改变个人行为，让自己变得更充实，更具创造力，然后再去施加影响，改变环境。\u003c/p>\u003cp>&nbsp; 《旧约》里有段约瑟（Joseph的故事．约瑟17岁就被兄弟卖到埃及，成为埃及法老的护卫长波提乏(Potiphar)的奴隶。面对同样的遭遇，任何人都难免自怨自艾，并对出卖和奴役自己的人满腔怨愤，但是约瑟却能够积极处世，专心磨炼自己，不久便备受信任，帮助主人打理家事，掌管财产。\u003c/p>\u003cp>后来他遭人污陷，身陷囹图达13年之久，皆因他坚持不肯出卖自己的良心，即便身处这样的困境，他积极的态度依然不改，他从自身做起，时刻想着“我可以”而不是“如果”，化悲愤为动力，没多久就掌管了整座监狱，后来又掌管了整个埃及成为一人（法老）之下，万人之上的大人物。\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导\u003c/p>\u003cp>\u003cstrong>知识补充:什么是关注圈，什么是影响圈？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我们每个人都有自己感兴趣的领域或者不愿意理会的事务。比如我们所关注的健康、子女、工作、事业、金融、核战争、娱乐圈等等。这些都可以被归入“关注圈”。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>关注圈内的事物，有些是可以被掌控的，有些则超出个人能力范围。这些可以被掌控的，就被圈成了一个较小的“影响圈”。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>聚焦影响圈，就不必担忧外界条件，只要从自己做起，对能够掌握的事全力以赴，抱着“我可以更耐心的做……、更明智的去……、更体贴的做……”，的态度，寻求“由内而外”的改变。就可以化阻力为动力，可以不断扩大我们的影响圈，从而使自己能够得到更好的提升。\u003c/p>\u003cp>举个例子:单位换了个新领导，他的工作方法和前任截然相反。前任是干什么都心里有谱，直接命令相关人员按他的要求来完成即可。可是新领导不是这样。他所有的事都要上会，并且每一件事都委派办公室主任全程督查。这样一来，有些科室就不高兴了，我们的业务他插个什么手啊？于是牢骚来了：“有本事自己干去。”“这个没有脑子的领导，会不会当领导啊……”\u003c/p>\u003cp>不满归不满，事情是不是还得干啊？想想带着这样的情绪工作，心情能好吗？肯定不好吧？可是这样的状况你能改变吗？不能吧！反而留给别人“不合作，没有团队意识”的负面影响是吧？\u003c/p>\u003cp>所以我们唯一的策略就是先做好自己分内的事。要有更耐心的态度，更加努力的工作方式，更加积极的配合，高标准的完成任务和目标。努力成为一个好职员。这样是不是得到“高效能团队人员”的标签呢？这种“由内而外”改变自己的行为，不就提高了我们的影响力吗？\u003c/p>\u003cp>【适用范围】今天所讲的影响圈，必须是不受客观条件限制的，适用于自身能力范围内，只要自己付出努力或者改变态度就能做的的领域。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>看过原文的例子和我的例子，大家是不是有这样的想法？\u003c/p>\u003cp>“这种激烈的思维转换并不是人人都能做到的，这是伟人的专利，我想我做不到。”\u003c/p>\u003cp>“只是我改变有什么用呢？没有人认可，遇不到伯乐也是闲的呀！\u003c/p>\u003cp>那么我告诉你:\u003c/p>\u003cp>只要这在我上面所说的范围内的事，就不要否定自己，不要怀疑自己做金子的潜力。\u003c/p>\u003cp>有一句话说的好“你若盛开，清风自来；你若精彩，天自安排！”\u003c/p>\u003cp>永远记住:只要你努力让自己变得更好，你想要的便都会来。如果你一味考虑的是你能得到什么，或者怎样才能得到，反而会适得其反。也就是说，过分注重结果，反而会错失机缘。(尤其指抽象一些的东西，比如事业的成功，爱情的获得等等。)\u003c/p>","interaction":"\u003cp>【A2】分步催化1\u003c/p>\u003cp>通过学习，大家知道了，聚焦影响圈，先改变个人行为，才能实现改变环境的目的。请大家就自己影响圈内的某一件，规划一下具体给如何通过改变自己的行为，来改变环境呢？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者1 &nbsp;：我的影响圈有阅读、拆书、跑步健身\u003c/p>\u003cp>我要做好积极健身，跑步每周坚持3次，一次5km。保证有一个好的身体。还要做高质量的学习者，坚持每周至少读1本书，坚持拆书晋级，提前了解3级拆书家晋级要求，阅读时留意选片段。\u003c/p>\u003cp>学习者2 &nbsp;：我的影响圈有读书学习\u003c/p>\u003cp>曾读到《你远比想象中强大》这本书，要像这本书里讲的一样。从自我做起，改变自己的一些习惯，比如要做到每天7:00起床。先让自己的生活有规律。\u003c/p>\u003cp>【A2】分步催化2\u003c/p>\u003cp>在现实生活中，有多少是我们无法改变，也无能为力的，难道我们任由望城莫及所带来的隐秘伤痛左右我们的情绪吗？答案肯定是: NO!那么，想想我们该怎样去做呢？请大家详细规划一下应用。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者1 ：&nbsp;我正在晋升三级拆书家。进入三级后，我发现准备起来更有挑战性，技能点的要求也更高。我不能决定我能否顺利晋级。但我可以做积极的准备:1、认真阅读三级的技能点要求，并熟记于心；2、在阅读致用类书时，留意合适的片段；3、根据技能点的要求，详细对照手册准备预备表；4、遇到不清楚的地方，及时寻求师父的指导。\u003c/p>\u003cp>学习者2 ：&nbsp;我希望女朋友能欣然接受我的建议，从新疆来到兰州。我打算从一下几个方面去努力，1、多关心她，让我们的关系变得更好；2、多带她去兰州的好地方，多介绍兰州的优势，排除她心中对兰州的偏见；3、在兰州为她解决工作问题，让她消除失去工作的顾虑。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1477820725000,"updated_at":1481172509000,"ria":true},{"id":1093,"topic":"积极主动的言语自我对话，营造外在环境改变自己行事的态度","learn_goal":"完成本次RIA现场学习后，学习者能够改变自己行事的态度","remark":"《高效能人士的7个习惯》是当今中国最经典、最著名的一部培训教材。本书不仅是企业、组织机构，更是个人获得自我提升的人生必修教材。作者史蒂芬·柯维博士，他是美国学界的“思想巨匠”，入选“影响美国历史进程的25位人物”，被《时代周刊》评为“人类潜能的导师”。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"Lian","city":"兰州市"},"club":{"name":"兰州金城关分舵","city":"兰州"},"prologue":"开场： 大家下午好 ，我是拆书家Lian。今天拆解的主题是:用积极主动的语言，营造外在环境。大家完成这次现场RIA学习后，能够用积极主动的语言进行自我对话，营造外在环境，改变自己行事的态度，对自己的人生负责。今天的片段选自《高效能人士的7个习惯》，（F）作者史蒂芬·柯维，他是美国学界的“思想巨匠”，被《时代周刊》评为“人类潜能的导师”。书中详细描述了关于人类生存状况,它深深洞察了我们内心所关注的东西，这本书无论对个人还是组织，都非常有用。此书中所讲的行为习惯能令人精神振奋、思维活跃，积极主动为自己过去、现在及未来的行为负责。（A）此书是当今中国最经典、最著名的一部培训教材。本书不仅是企业、组织机构，更是个人获得自我提升的人生必修教材。读者遍及工商业、政府部门、军队、学校以及家庭各个领域。（B）阅读此书，你就已经开始了一段激动人心的成长历程，如果践行于生活，你就不会再让外在环境影响情绪，可以依据原则及价值观做决定，积极主动调节自己做事的态度，对自己的人生负责。","ratings_count":0,"texts":[{"id":3297,"quote":"\u003cp>第三章：积极主动——聆听自己的语言\u003c/p>\u003cp>我们可以利用自我意识检讨自身的观念，以言语为例，它颇能真切反映—个人对环境的态度。\u003c/p>\u003cp>消极被动的人，言语中往往会暴露出推卸责任的意图，例如：\u003c/p>\u003cp>“我就是这样做事的”我天生这样，这辈子改不掉了\u003c/p>\u003cp>“他把我气疯了”责任不在我，是外界因素控制了我的情绪。\u003c/p>\u003cp>“我根本没时间做”又是处界因素—一时间控制了我\u003c/p>\u003cp>“要是我妻子能更耐心一点就好了。”别人的行为会影响我的效能。\u003c/p>\u003cp>“我只能这样做”意味着迫于环境或他人\u003c/p>\u003cp>消极被动的语言:\u003c/p>\u003cp>我已无能为力。\u003cbr>\u003c/p>\u003cp>我就是这样，\u003c/p>\u003cp>他把我气疯了！\u003c/p>\u003cp>他们不会答应的\u003c/p>\u003cp>我只能这样做\u003c/p>\u003cp>我不能\u003c/p>\u003cp>我不得不\u003c/p>\u003cp>要是……就好了\u003c/p>\u003cp>积极主动的语言:\u003cbr>\u003c/p>\u003cp>试试看有没有其他可能行\u003c/p>\u003cp>我可以选择不同的作风\u003c/p>\u003cp>我可以控制自己的情绪\u003c/p>\u003cp>我可以想出有效的表达方式。\u003c/p>\u003cp>我能选择恰当的回应\u003c/p>\u003cp>我选择\u003c/p>\u003cp>我更愿意\u003c/p>\u003cp>我打算\u003c/p>\u003cp>消极被动的语言源于决定论的思维定式，其本质就是推卸责任。我付不了责任，我无法自由选择回应的方式。\u003c/p>","explains":"\u003cp>【I】在我们的现实生活中，总有这样那样的不如意。我们是怎么做的呢？消极被动的人倾向于把社会当成替罪羊来谴责，如果我老板不是一个刚愎自用的白痴该多好？如果孩子们不那么叛逆该多好？如果那房子不是整天乱得一团糟该多好？如果老婆再体贴点该多好？等等诸如此类的埋怨。如果我们只是用推卸责任的言语，往往会强化宿命论。说者一遍遍被自己洗脑，变得更加自怨自艾，怪罪别人和环境。久而久之，人就会变得颓废，随大流。事实上，任由感觉左右行为是不负责任的做法。\u003c/p>\u003cp>此片段告诉我们:\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;人性的本质是主动而非被动的，人类不仅能针对特定的环境选择回应方式，更能主动创造有利的环境。主动积极的人是改变的催生者，他们扬弃被动的受害者的角色，不埋怨别人，不讲消极被动的语言。而是采用积极主动的语言和自己的内心对话，比如:我可以……我能……我打算……，发挥了人类四项独特的秉赋—自觉、良知、想象力和自主意志，同时以“由内而外”的方式来创造改变，积极面对一切。\u003c/p>\u003cp>如果我们不用积极主动的语言和自己的内心对话，强化自己自主意识和原则。那就只能是任其事情向更遭糕的方向发展，只能导致环境更恶劣，个人更颓废。\u003c/p>\u003cp>举例：有个朋友曾这样抱怨：“我老公现在越来越没有上进心了，每到周末，包包一背，就走了。（驴友）家里啥事也不操心，孩子也不管。工作也不放在心上。我们婚姻真是让我担忧。好像我们已经失去了往日的感觉，我猜我们都已经不再爱对方了。该怎么办呢？”\u003c/p>\u003cp>因为他老公我也比较熟悉。知道这个人原来不是这样的。\u003c/p>\u003cp>我与朋友沟通:\u003c/p>\u003cp>“你问过他是怎么想的吗？” \u003c/p>\u003cp>“他把我都快气疯了，我们现在都很少说话。”\u003c/p>\u003cp>“那你就主动去和他沟通，告诉他这个周末你不要出去了，因为我有事，孩子就由你来带。好吗？”\u003c/p>\u003cp>“我怎么看怎么不顺眼，也懒得说，再说他也不会答应的。”\u003c/p>\u003cp>我提建议给朋友：看你现在这么的不开心，我深表同情。但是，听你的言语都比较消极，行为也很被动，这样放任你俩的关系任其发展，只会越来越糟糕。其实内心深处你还是希望关系能缓和，恢复往日的感觉是吧？建议你积极主动的来应对问题，试着用积极的语言和他交流，比方说:我打算主动和他沟通；我可以控制自己的情绪，多一些聆听，少一些谴责；我要多关注一下他的心情，试着站在他的立场考虑这样做的原因。好吗？\u003c/p>\u003cp>她采纳我的建议。过了一段时间，她对我说：“老公最近好多了，周末出去时，都征求我的意见。前一段时间因为工作调动，有一些不适应。现在都调整的好多了”！\u003c/p>","interaction":"\u003cp>【A1】好，现在我们知道了消极被动的语言只能使事情更糟糕，而积极主动的语言可以营造有利的外环境，有利于解决根本问题。\u003c/p>\u003cp>请大家参照原文两种语言格式，选出近期自己常说的消极被动的语言1-2项，想想对自己有什么不好的影响？大家分组讨论，4分钟后请各小组长分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者1:以前当我有事需要别人帮助才能完成时，如果这件事比较难办。我就会这样想:“他们是不会答应的”，然后这件事情就这样被搁置了。\u003c/p>\u003cp>学习者2:因为我这人性格比较直，在工作中遇到做事出差错的同事，张口就说“你这人做事怎么是这样的？”然后就会收到这样的回应:“我就是这样。”然后我就会这样想:“你为什么会这样讲，我都快被气疯了！”。\u003c/p>\u003cp>学习者3:节前有个很重要的报表必须完成。可是下级不能就是不能按时上报，以致整体工作一延再延。我着急，就给他们打电话，“工作效率这么慢，能不能快点啊？”语气十分强硬。他们说“不是我们效率低，是有原因的，你怎么能这样说？”我说“我就这样。”最后事情没完成。\u003c/p>\u003cp>学习者4:打算请求管理科长同意我们使用教室的白板，用于写字。我想他是不会答应的。其实这是一种推卸责任。\u003c/p>\u003cp>【A1+】进一步激活经验，通过【A】讨论，大家都知道了积极主动的语言可以营造有利的外环境，有利于解决根本问题。那么请大家将上面的问题，改为积极主动的语言，具体应用一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者1：以后我要用积极主动的思维来思考，“试试看吧，也许他们会答应的”，如果我这样去做，就会获得更好的结果。消极被动的语言与积极主动的语言，就同一件事有不同的影响，今后一定要多用积极主动的语言。\u003c/p>\u003cp>学习者2：以后遇到这样的事，我要换个语气，换个交流的方式，改变自己的行为方式和他沟通。如果他还是这样讲，我就知道他这人就这性格，我为什么要让别人的行为来影响自己的情绪？这样转换积极主动的方式，就可以很好的控制自己的情绪。\u003c/p>\u003cp>学习者3：以后我要改变自己的语言，积极主动的语言这样说:“你今天是不是太忙了，报表交晚了。没关系，我等你一会。”\u003c/p>\u003cp>学习者4：我回去要做一个尝试，请求并说服他，或许他会答应的。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":3298,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1476591169000,"updated_at":1481171952000,"ria":true},{"id":737,"topic":"3W1H+TVD法和3W1H+三“谈”法","learn_goal":"让你养成高效能人士的好习惯","remark":"3W1H+TVD法和3W1H+三“谈”法，让你养成高效能人士的好习惯。来自《高效能人士的7个习惯》和《重要的事情说3点》","level":"TF2-4","duration":55,"status":0,"type":0,"chaishujia":{"username":"陈健","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"大家好，我是凝琪，真名陈健，三个标签：转变，计划，行动。现在把大家分为2组，这边的组长林林，这边的组长姜柳，谢谢","ratings_count":0,"texts":[{"id":2353,"quote":null,"explains":"\u003cp>&nbsp; &nbsp;大家都知道，良好的习惯可以让我们在工作和生活中事半功倍。首先什么是习惯？在本拆书页史蒂芬.柯维认为是知识（是什么，为什么），技巧（如何做）和意愿（想要做）相互交叉的结果。请大家看图，要养成习惯这三者缺一不可。即3W1H：1W：willing想要做。2W：what，是什么？ 3W：why，为什么？1H：how,如何做？在这三方面大家应该更想知道如何做？为此我根据做的行动建议把如何做[细化]为：TVD三步法：大家可以记一下：T：tool，即养成习惯的工具或方法。V：value，量化值。D：do，即坚持做，按需调整。具体我们来看看案例，原书给出的是聆听的案例：需要聆听，如何聆听，愿意聆听，（也强调不懂如何做的技巧时不行的）。[根据原书的案例脉络,给出了一个更贴合实际的案例]根据原书的案例脉络，我想到我的一个健身习惯就是这样养成的。这个习惯是每天步行至少6000步。首先我愿意健康（1w，willing想要做），选择健康习惯是步行（2w what是什么），因为我已经年逾50剧烈运用不适合我，医生建议步行（3W why为什么？）。如何做呢？（1H：how）我是按照TVD法做的：1.T：tool，即养成习惯的工具或方法。我选择的是一种工具：计步器 ；2. V：value，量化值,我选择是每天6000步。3.D:do，即坚持做，按需调整。我已经坚持了6个月了，现在每天基本达到了8000步，所以我决定把6000步的目标调整到10000步。在此习惯养成我给大家总结的是3W1H+TVD法。\u003c/p>","interaction":"\u003cp>[A1] 下面请大家想一想在生活或者工作中你有哪些好习惯？是怎么养成的？怎么用我们的3W1H+TVD法养成一个好习惯？小组讨论6分钟，小组长注意组织协调调动组员参与。讨论过后请小伙伴儿分享。\u003c/p>\u003cp>[学习者案例记录]：\u003c/p>\u003cp>全学平：用3W1H+TVD法养成写日记的好习惯。有意愿，我愿意写日记，为了好的工作状态，为了不断的提升。写日记用的是模板，内容很多包括衣食住行感悟，有哪些成功，我的工作，后来把杨老师的复盘也添加进去了。每天往里面填，技巧是每天早上起来就写日记，一写状态就好，一用笔手也在动，脑子也清醒了。坚持做，做了分享到打卡群里面。\u003c/p>\u003cp>拆书家凝琪[总结与反馈]：在全姐的分享中，3W，首先她愿意做（1W），第二确定好习惯写日记（2W），为什么做（3W）因为对她有好处，她上面说了很多，那如何做呢？（1H）：她使用了一个工具T：（询问全）是什么？（全：有道云）V：有个量，每天做，到现在坚持多久了呢？（全：18天了）D：do，坚持做，以后还会增加一些内容还会调整。好这就是我们的3W1H（TVD）法，相信大家对它有了足够的了解，这是我们的第一段。希望大家以后也会经常运用这个方法养成好习惯。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":2354,"quote":null,"explains":"\u003cp>&nbsp; &nbsp; 现在大家看到第二段，第二段来自八幡纰芦史《重要的事情说三点》。\u003c/p>\u003cp>在史蒂芬.柯维《高效能人士的七个习惯》中习惯五就提到了沟通。有效沟通也是高效能人士的好习惯之一。现在我们重点来谈谈3W1H（TVD）法中的T：即养成习惯的工具或方法，上一段我们是直接选用的工具，如：计步器，这段我们采用方法：三“谈”法，它来自八幡纰芦史《重要的事情说三点》，也就是我们把T再细化为1.谈感情2.谈逻辑3.谈利益（三“谈”）。谈感情是为了愿意听，讲逻辑是听得懂，谈利益是愿意做。八幡纰芦史认为这是任何沟通都可以采用的方法,它会带给沟通另一方充实感、创造性和安定感。我曾看到一起这样的案例：老板有事出门电梯里面遇到员工，员工专门等待老板想让老板听他的方案。员工：(老板刚买了一双限量版的世界名牌鞋，老板自己也觉得很酷。)“老板您今天的皮鞋真漂亮”[夸赞拉近感情，谈感情]“真的吗？”老板眼睛发亮，员工：“老板您把公司打理的也很棒”[逻辑递进，谈逻辑]。老板郁闷的说：“这个月的绩效还是输给了隔壁。”员工：“我这里有一个可以让下个月绩效超过隔壁公司的方案，您想不想听一听？”[谈利益]老板：“好，说说看。”员工：“可是估计要占您15分钟的时间，可以吗？” 老板：“李秘书，电话给老张，我有事，请他等等，噢算了，就跟他说抱歉，高尔夫改期了，下次我做东专门给他道歉。”员工计划成功。[强调不这么做的坏处] 如果不这么做，刚开始就上来跟老板说，员工：“老板我这里有个绩效改进方案向您汇报一下？”老板：“你是谁？先向你们部门经理汇报吧。”再好的方案也束之高阁。在我们的案例中，员工很机智的运用3谈法，从夸老板皮靴到夸老板公司，目的是想引出自己的方案。这是一种逻辑递进的方式，最后谈利益让公司翻番，引起了老板的兴趣。所以我在此推荐有效沟通的三“谈”法：1.谈感情-愿意听2.谈逻辑-听得懂3.谈利益-愿意做。[可能会有的争议] 谈逻辑不是要讲一段话或者一个事例吗？其实讲逻辑只是在给论点找论据，能够支撑你的论点就好，可以是一句话也可以是一个案例，故事，也可以是逻辑递进的关系，只要讲的明白听的懂就好。\u003c/p>","interaction":"\u003cp>[A3]现在你如何运用三“谈法”跟一个总是迟到的员工谈话，并帮助他改进。请各小组22配对开始讨论，组长注意组织协调调动组员参与.讨论时间为10分钟，然后请伙伴儿进行角色扮演分享。\u003c/p>\u003cp>[学习者案例分享]：新观摩者1扮演老板，林林扮演员工\u003c/p>\u003cp>老板：小李阿，听说你孩子最近刚刚升入小学，还顺利吗？[谈感情]\u003c/p>\u003cp>员工：还好。\u003c/p>\u003cp>老板：每天上下学谁在接送阿？[逻辑递进，了解是否是因为接送孩子迟到]\u003c/p>\u003cp>员工：家里的老人家。\u003c/p>\u003cp>老板：最近工作上项目进展还顺利吗？[逻辑递进，转到工作上引出后面的话题]\u003c/p>\u003cp>员工：还行吧，只是最近这个项目比较杂事情也比较多，业主的要求也多，然后。。所以我们在下班时候投入的精力也比较多，其他的倒没有什么，老板。\u003c/p>\u003cp>老板：我是看到你们比较努力，可是从交上来的考勤表上看你们部门的考勤比较差这是怎么回事啊？\u003c/p>\u003cp>员工：哦，嗯，主要是我的问题，我确实是每天来的比较晚，也对打卡的事情没有非常重视，因为现在这个项目已经接近尾声了，晚上下班比较晚，如果早上还不睡点懒觉的话，白天精力就不够充沛。\u003c/p>\u003cp>老板：你是挺辛苦的，不过这个项目不是由你一个来完成的，我是希望这个项目接近尾声的时候大家可以团结努力共同做好，而不是看到你迟到，别人也迟到，对吧。看家里的孩子你也能够安排，那能不能以后在考勤上克服一下，等这个项目完成了我们好好出去放松一下？\u003c/p>\u003cp>员工：好的，老板你及时提醒我也是有利于我们这个团队，谢谢老板。\u003c/p>\u003cp>[拆书家凝琪总结和反馈]：开场你是怎么开场的：（新观摩者1：孩子谁接？）那就是谈感情，我周围的伙伴儿一直在表扬你说你逻辑递进递进的好，从家事巧妙的转到工作上，最后利益你们怎么谈的？今天的环境比较吵，可能这边的伙伴儿没有太听得清楚，（新观摩者1：让他明白身处团队，迟到不仅仅是她一个人的事情，她的迟到影响了团队让她感到惭愧），嗯，不错。在这个对话中她们用了我们三谈法：先谈感情再谈逻辑，最后谈利益，达成目标。\u003c/p>\u003cp>[A2]相信大家在生活或者工作中都需要沟通，比如：夫妻吵架，母子因为学业而争执，邻居之间因为阳台的花过界了，员工和员工之间闹误会，今天早上我的一个学生遇到擦刮，对方的责任却要让他赔等等。那么生活或工作中你们遇到需要沟通时你通常是怎么做的？你准备怎么用我们的三“谈”法进行沟通？请大家各自加工一个具体案例，然后分享。小组长注意组织协调调动组员参与。好现在发标签纸了，请大家各自加工。\u003c/p>\u003cp>拆书家凝琪：我观察到一个有趣的现象，那边的伙伴都在埋头认真的写下自己的案例，而这边的伙伴儿却采取22配对的形式组合案例，都很不错哦。我们请一边派一个代表分享一下哈，谢谢。\u003c/p>\u003cp>[学员案例分享1]\u003c/p>\u003cp>杨老师：给商务人士推销衣服\u003c/p>\u003cp>这位先生您真有气质，[拉进关系，谈感情]，您选的这款衣服是最新款的，是欧美大牌设计，老顾客很多都选了多套，上一个顾客一口气就选了三套[服装的特点和优势，谈逻辑]，穿上他凸现您的气质，您要做的事情一定会获得成功[谈利益]。\u003c/p>\u003cp>[学员案例分享2]\u003c/p>\u003cp>姜柳：（我们是讨论的）汽车被擦刮了（对方责任）我们要怎么做？第一从心情上来说，“我们的车子（2人的车子）都被擦了好心疼哦，我想你也不好受吧”[谈感情，从感情上找到一种认同感]。第二，提出三种解决方案“你看现在怎么解决？1.我们叫快处中心2.报保险公司3.你帮我去修车，修好就成”[谈逻辑]。[谈利益]总之，你有空，我很忙，你把我的车子修好就行我也不讹你。\u003c/p>\u003cp>[结束语]谢谢大家的分享，今天我们的拆书页总体体现了习惯养成的3W1H+TVD法。怎么做中着重训练了TVD法，尤其是T：tool, 即养成习惯的工具或方法，在第一段中运用的是工具而在第二段中着重训练了方法：三谈法。希望今后大家能够经常运用这些有效工具，培养好习惯成为高效能人士，让自己的生活和工作都上一个台阶，今天的分享就到这里，谢谢大家。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1471253681000,"updated_at":1471253681000}]};